/// GM1 and its alternates: peak-normalized PCM over the modelled felt damper.
pub(crate) const GM1_VOICING: PianoVoicing = PianoVoicing {
    cal: PianoSampleCal::LegacyNormalized,
    damper: GM0_DAMPER,
};

/// The pre-fix voicing: legacy sample calibration over the legacy FLAT damper.
/// Still correct for GM1 and its alternates (unchanged pending Step 2), and used
/// as the explicit control wherever a test needs the old behaviour reproduced.
#[cfg(test)]
pub(crate) const LEGACY_VOICING: PianoVoicing = PianoVoicing {
    cal: PianoSampleCal::LegacyNormalized,
    damper: LEGACY_DAMPER,
};
const GM0_SAMPLE_GAIN: f32 = 4.00;
const GM0_SAMPLE_FADE: (f32, f32) = (0.18, 0.45);
const GM0_FORTE_LAYER_GAIN: f32 = 0.569;

/// B1 upright make-up gain — see [`PianoSampleCal::B1Upright`] for the derivation
/// and, more importantly, for why the usable window is only about 1.2-1.3 wide.
/// Swept, not guessed: 0.90 leaves the model outrunning the recorded hammer.
const B1_SAMPLE_GAIN: f32 = 1.30;
/// The B1 recording decays faster than the model. Its established bass/mid
/// window preserves the recorded identity; only C♯6+ needs earlier retirement
/// before the much faster treble decay can expose a trough.
const B1_SAMPLE_FADE: (f32, f32) = (0.18, 0.45);
const B1_TREBLE_SAMPLE_FADE: (f32, f32) = (0.12, 0.30);
fn acoustic_piano(key: u8, vel: u8, sr: f32, seed: u32, release_t60: f32) -> Modal {
    let f = key_freq(key);
    let v = vel_amp(vel);
    let bright = 0.55 + 0.40 * (vel as f32 / 127.0);
    let inharm = 0.00045;
    let t1 = (9.0 * (110.0 / f).powf(0.65)).clamp(0.4, 12.0);
    let mut partials = Vec::new();
    for k in 1..=16u32 {
        let kf = k as f32;
        let fk = f * kf * (1.0 + inharm * kf * kf).sqrt();
        if fk > sr * 0.42 {
            break;
        }
        let amp = v * bright.powi(k as i32 - 1) / kf.powf(1.08);
        let t = t1 / (1.0 + 0.6 * (kf - 1.0));
        // prompt sound: decays at the strike rate
        partials.push((fk, amp * 0.85, t));
        if k <= 6 {
            // aftersound: a quiet second stage that sings on much longer —
            // the characteristic double decay of a real piano string
            partials.push((fk * 1.0003, amp * 0.22, t * 2.8));
        }
        if k <= 4 {
            // detuned second string for a gentle unison shimmer
            partials.push((fk * 1.0007, amp * 0.6, t * 0.9));
        }
    }
    let hammer = Biquad::bandpass((f * 9.0).min(3800.0), 1.0, sr);
    Modal::new(
        sr,
        seed,
        &partials,
        (0.30 * v, 0.012, hammer),
        0.0015,
        release_t60,
        0.50,
    )
}

/// GM1/GM3 (round 2): the GM0 grand construction with re-voiced knobs —
/// `bright_add` lifts the per-harmonic brightness base, `hammer_mult`/
/// `hammer_cap` re-tune the strike bandpass, and the unison second string
/// gets its own detune ratio/level/mode count (GM0's shimmer string is
/// 1.0007 at 0.6 for k<=4). `acoustic_piano` itself is untouched so GM0
/// renders byte-identically.
#[allow(clippy::too_many_arguments)]
fn grand_piano_variant(
    key: u8,
    vel: u8,
    sr: f32,
    seed: u32,
    bright_add: f32,
    hammer_mult: f32,
    hammer_cap: f32,
    unison_ratio: f32,
    unison_amp: f32,
    unison_k: u32,
    third_string: bool,
    release_t60: f32,
) -> Modal {
    let f = key_freq(key);
    let v = vel_amp(vel);
    let bright = 0.55 + bright_add + 0.40 * (vel as f32 / 127.0);
    let inharm = 0.00045;
    let t1 = (9.0 * (110.0 / f).powf(0.65)).clamp(0.4, 12.0);
    let mut partials = Vec::new();
    for k in 1..=16u32 {
        let kf = k as f32;
        let fk = f * kf * (1.0 + inharm * kf * kf).sqrt();
        if fk > sr * 0.42 {
            break;
        }
        let amp = v * bright.powi(k as i32 - 1) / kf.powf(1.08);
        let t = t1 / (1.0 + 0.6 * (kf - 1.0));
        partials.push((fk, amp * 0.85, t));
        if k <= 6 {
            partials.push((fk * 1.0003, amp * 0.22, t * 2.8));
        }
        if k <= unison_k {
            partials.push((fk * unison_ratio, amp * unison_amp, t * 0.9));
        }
        if third_string && k <= unison_k {
            // the third string of the trichord, flat of center — the
            // honky-tonk wobble needs both sides of the unison detuned
            partials.push((fk * (2.0 - unison_ratio), amp * unison_amp * 0.8, t * 0.95));
        }
    }
    let hammer = Biquad::bandpass((f * hammer_mult).min(hammer_cap), 1.0, sr);
    Modal::new(
        sr,
        seed,
        &partials,
        (0.30 * v, 0.012, hammer),
        0.0015,
        release_t60,
        0.50,
    )
}

/// GM1 Bright Acoustic (round 2): the same grand, voiced brighter — a
/// higher per-harmonic brightness base and a harder, higher strike band.
fn bright_acoustic_piano(key: u8, vel: u8, sr: f32, seed: u32, release_t60: f32) -> Modal {
    grand_piano_variant(
        key,
        vel,
        sr,
        seed,
        0.12,
        12.0,
        4800.0,
        1.0007,
        0.6,
        4,
        false,
        release_t60,
    )
}

/// GM3 Honky-tonk (round 2): the saloon upright — the unison trichord
/// detuned WIDE (±~12 cents vs the grand's 1.2) and loud on both sides, so
/// held notes beat audibly; a slightly harder tack-hammer band on top.
fn honky_tonk_piano(key: u8, vel: u8, sr: f32, seed: u32) -> Modal {
    // GM3 keeps the flat 0.10 s release its voicing is pinned to: the saloon
    // upright is a deliberately different instrument, and its release window is
    // asserted by `gm0_damper_reaches_gm0_alternates_and_stops_there`.
    grand_piano_variant(
        key, vel, sr, seed, 0.05, 11.0, 4300.0, 1.007, 0.85, 6, true, 0.10,
    )
}

/// GM2 Electric Grand (round 2): the CP-style stage piano — real short
/// strings through a piezo pickup, not a soundboard. Higher inharmonicity
/// (short scale), a faster decay, almost no soundboard aftersound (the
/// pickup hears the string, not the case singing), and a bright glassy
/// strike. Fully modeled: no LA grand-attack layer, no sympathetic bus
/// (is_acoustic_piano excludes 2).
fn electric_grand_piano(key: u8, vel: u8, sr: f32, seed: u32) -> Modal {
    let f = key_freq(key);
    let v = vel_amp(vel);
    let bright = 0.60 + 0.36 * (vel as f32 / 127.0);
    let inharm = 0.0011;
    let t1 = (5.5 * (110.0 / f).powf(0.60)).clamp(0.35, 8.0);
    let mut partials = Vec::new();
    for k in 1..=16u32 {
        let kf = k as f32;
        let fk = f * kf * (1.0 + inharm * kf * kf).sqrt();
        if fk > sr * 0.42 {
            break;
        }
        let amp = v * bright.powi(k as i32 - 1) / kf.powf(0.98);
        let t = t1 / (1.0 + 0.7 * (kf - 1.0));
        partials.push((fk, amp * 0.9, t));
        if k <= 3 {
            // a whisper of aftersound: the plate carries far less than a
            // grand's soundboard
            partials.push((fk * 1.0004, amp * 0.07, t * 2.2));
        }
        if k <= 4 {
            partials.push((fk * 1.0005, amp * 0.5, t * 0.9));
        }
    }
    let hammer = Biquad::bandpass((f * 11.0).min(5600.0), 0.9, sr);
    Modal::new(
        sr,
        seed,
        &partials,
        (0.26 * v, 0.009, hammer),
        0.0012,
        0.12,
        0.52,
    )
}

fn electric_piano_1(key: u8, vel: u8, sr: f32, seed: u32) -> Modal {
    let f = key_freq(key);
    let vn = vel as f32 / 127.0;
    let v = vel_amp(vel);
    let scale = (440.0 / f).powf(0.25).clamp(0.75, 1.5);
    // Column 0 is a RATIO of the key frequency (a Rhodes tine's inharmonic
    // series) — scale by f before handing Modal::new its (freq Hz, amp, T60)
    // rows, exactly as bell()/timpani_partials do. B1 (HLD §2.1): the bare
    // ratios used to be passed as Hz, so every mode oscillated at 1–5 Hz —
    // infrasound — and the voice's only audible output was its noise burst.
    let partials = [
        (1.000, 0.95 * v, 3.6 * scale),
        (1.003, 0.55 * v, 3.1 * scale),
        (2.000, 0.32 * v, 2.1 * scale),
        // Round-3 U5: the Rhodes BARK — the tine/bell partial jumps to
        // ~0.6x the fundamental at onset with a SHORT ring, so a hard
        // strike knocks then blooms into the warm body instead of reading
        // as a clean sine stack (plan 3.2: "GM4 does not bark").
        (2.820, 0.55 * v * (0.4 + 0.8 * vn), 0.45 * scale),
        (3.000, 0.13 * v, 1.3 * scale),
        (5.380, 0.16 * v * (0.4 + 1.0 * vn), 0.30 * scale),
    ]
    .map(|(r, a, t)| (f * r, a, t));
    Modal::new(
        sr,
        seed,
        &partials,
        (
            0.035 * v,
            0.010,
            Biquad::bandpass((f * 7.0).min(5200.0), 0.8, sr),
        ),
        0.002,
        0.22,
        0.56,
    )
    // Round-3 U5: the bark lives in the TINE PARTIAL now (2.82·f0 above),
    // not in shaper saturation — round 2's deep drive (0.6+3.2·vn) was the
    // shared hack that pushed GM4/GM5 together, and at forte its tanh
    // compression ate the raised tine 4× (measured: table ratio 0.73 →
    // rendered 0.177). The pickup still gets a velocity-graded growl, but the
    // drive rises gently enough that it cannot compress the raised tine faster
    // than the mode table grows it.
    .with_pickup_drive(0.7 + 0.6 * vn, 0.3)
}

/// GM 5 (round-3 U5, plan §3.2): a REAL two-operator FM electric piano. A
/// DX-style EP *is* FM — round 2 modeled it as another additive Modal stack
/// with the same pickup shaper as GM 4, which is exactly how the pair
/// re-converged ("GM004/GM005 sound very similar"). Splitting the SYNTHESIS
/// METHOD is what prevents re-convergence: carrier at f0, 1:1 modulator,
/// index = a fast-decaying strike component (the glassy bell attack) over a
/// velocity-scaled RESIDUAL (the sustain keeps its FM sheen instead of
/// collapsing to a sine — measured h-tail/h1 was 0.076 at HEAD). Velocity
/// scales the index, so h4/h1 grows with velocity (M2: the pinned bark test
/// holds for prog 5 structurally — the index stays below Bessel J3's first
/// peak). Deterministic: no rng, no noise — the FM ladder is the voice.
struct FmEp {
    op: FmPair,
    f0: f32,
    sr: f32,
    amp: f32,
    env: f32,
    env_decay: f32,
    idx_sus: f32,
    idx_atk: f32,
    idx_atk_decay: f32,
    att_env: f32,
    att: f32,
    released: bool,
    release_env: f32,
    rel_mul: f32,
}

fn fm_electric_piano(key: u8, vel: u8, sr: f32) -> FmEp {
    let f = key_freq(key);
    let vn = vel as f32 / 127.0;
    let v = 1.04 * vel_amp(vel);
    // piano-like key-scaled decay, a touch longer than the old Modal's body
    let t60 = (2.6 * (440.0 / f).powf(0.25)).clamp(0.8, 5.0);
    FmEp {
        op: FmPair::new(f, 1.0, sr),
        f0: f,
        sr,
        // level-matched to the retired Modal GM5 (measured rms 0.096/0.078/
        // 0.105 at (60,100)/(64,80)/(55,110) over 1 s — the FM voice lands
        // within ~1 dB, verified by the U5 level probe)
        amp: 0.47 * v,
        env: 1.0,
        env_decay: t60_mul(t60, sr),
        idx_sus: 0.35 + 0.85 * vn,
        idx_atk: 0.5 + 1.6 * vn,
        idx_atk_decay: t60_mul(0.10, sr),
        att_env: 0.0,
        att: 1.0 - (-1.0 / (0.002 * sr)).exp(),
        released: false,
        release_env: 1.0,
        rel_mul: t60_mul(0.15, sr),
    }
}

impl Voice for FmEp {
    fn render(&mut self, out: &mut [f32]) -> bool {
        for o in out.iter_mut() {
            let y = self.op.next(self.idx_sus + self.idx_atk);
            if self.att_env < 1.0 {
                self.att_env = (self.att_env + self.att).min(1.0);
            }
            if self.released {
                self.release_env *= self.rel_mul;
            }
            *o += y * self.amp * self.env * self.att_env * self.release_env;
            self.env *= self.env_decay;
            self.idx_atk *= self.idx_atk_decay;
        }
        self.amp * self.env * self.release_env > 2e-5
    }

    fn note_off(&mut self) {
        self.released = true;
    }

    fn released(&self) -> bool {
        self.released
    }

    fn set_pitch(&mut self, mult: f32) {
        self.op.set_freq(self.f0 * mult, self.sr);
    }

    #[cfg(test)]
    fn kind(&self) -> &'static str {
        "FM_EPIANO"
    }
}

/// Bar/tube/bell family, defined by (ratio, amp, T60) tables. Each strike
/// jitters the mode amplitudes a little (nobody hits the same spot twice).
#[allow(clippy::too_many_arguments)]
fn bell(
    key: u8,
    vel: u8,
    sr: f32,
    seed: u32,
    table: &[(f32, f32, f32)],
    noise: (f32, f32, f32, f32), // (amp, T60, filter freq, q)
    attack_s: f32,
    release_t60: f32,
    gain: f32,
) -> Modal {
    let f = key_freq(key);
    let v = vel_amp(vel);
    let mut jrng = Rng::new(seed ^ 0x5F5F_5F5F);
    let partials: Vec<(f32, f32, f32)> = table
        .iter()
        .map(|&(r, a, t)| (f * r, a * v * (1.0 + 0.10 * jrng.white()), t))
        .collect();
    let filt = Biquad::bandpass(noise.2.min(sr * 0.4), noise.3, sr);
    Modal::new(
        sr,
        seed,
        &partials,
        (noise.0 * v, noise.1, filt),
        attack_s,
        release_t60,
        gain,
    )
}

