/// Bank-B GM 114 steel drums: a modal pan note following the timpani
/// pattern — velocity-scaled upper modes with AMP-ONLY jitter. The defining
/// features: a strong octave (2.000x) with a slightly detuned twin (2.018x)
/// that beats at 0.018·f0 (≈ 4.7 Hz at C4), a near-twelfth (3.011x), a soft
/// 10 ms rubber-mallet attack, and a small strike glide (the dent starts
/// ~0.5 st sharp and settles in ~60 ms).
const STEELPAN_B: &[(f32, f32, f32)] = &[
    (1.000, 1.00, 1.4),
    (1.007, 0.45, 1.1),
    (2.000, 0.85, 1.0), // octave twin a — the pan's signature shimmer pair;
    (2.018, 0.30, 1.0), // twin b: NEVER jitter these ratios (beat = Δr·f0).
    // Twin b rings at twin a's T60: both are modes of the same dent, and a
    // faster twin-b decay collapses the beat DEPTH mid-ring (measured: the
    // 4.7 Hz AM line smears into an unreadable 4-6 Hz plateau with 0.8 s).
    (3.011, 0.55, 0.8),
    (4.53, 0.18, 0.5),
    (6.19, 0.08, 0.35),
];
const STEELPAN_B_NOISE: (f32, f32, f32, f32) = (0.06, 0.008, 1200.0, 0.8);
// The strike burst decays with t60 = 8 ms, but `attack_s` ramps the WHOLE voice in
// over 10 ms — so the mallet transient was being gated by its own attack envelope and
// reached only ~12% of its peak. An attack ramp must never outlast the transient it is
// supposed to let through: keep attack_s well under the noise t60 (8 ms).
const STEELPAN_B_ATTACK_S: f32 = 0.003;
const STEELPAN_B_RELEASE_T60: f32 = 0.5;
const STEELPAN_B_GAIN: f32 = 0.31; // level knob: altbank_b114_steel_level_vs_marimba
const STEELPAN_B_STRIKE_RATIO: f32 = 1.0293; // 0.5 st sharp at the strike
const STEELPAN_B_STRIKE_SETTLE_S: f32 = 0.060;
const STEELPAN_B_UPPER_MIN: f32 = 0.55;
const STEELPAN_B_UPPER_VELOCITY_SCALE: f32 = 0.75;
const STEELPAN_B_UPPER_JITTER: f32 = 0.10;

pub(crate) fn steel_drum_b(key: u8, vel: u8, sr: f32, seed: u32) -> Modal {
    let key = fold_key(key, 45, 96);
    let f = key_freq(key);
    let v = vel_amp(vel);
    let vn = vel as f32 / 127.0;
    let upper = STEELPAN_B_UPPER_MIN + STEELPAN_B_UPPER_VELOCITY_SCALE * vn;
    let mut jrng = Rng::new(seed ^ 0x57EE_1DA0);
    // AMP-ONLY jitter: the 2.000/2.018 twin ratios are load-bearing (their
    // difference IS the shimmer beat rate) and are never jittered.
    let partials: Vec<(f32, f32, f32)> = STEELPAN_B
        .iter()
        .map(|&(r, a, t)| {
            let vel_scale = if r >= 2.0 { upper } else { 1.0 };
            let amp = a * v * vel_scale * (1.0 + STEELPAN_B_UPPER_JITTER * jrng.white());
            (f * r, amp, t)
        })
        .collect();
    let mallet = Biquad::bandpass(STEELPAN_B_NOISE.2.min(sr * 0.4), STEELPAN_B_NOISE.3, sr);
    let glide_oct_per_s = (0.5 / 12.0) / STEELPAN_B_STRIKE_SETTLE_S;
    Modal::new(
        sr,
        seed,
        &partials,
        (STEELPAN_B_NOISE.0 * v, STEELPAN_B_NOISE.1, mallet),
        STEELPAN_B_ATTACK_S,
        STEELPAN_B_RELEASE_T60,
        STEELPAN_B_GAIN,
    )
    .with_strike_glide(STEELPAN_B_STRIKE_RATIO, glide_oct_per_s, 1.0)
}

/// CC0-alt GM 14 tam-tam / gong ageng: a deep 65–124 Hz strike whose upper
/// modes BLOOM in over 0.3–0.7 s (slower when struck softly) and ring
/// 6–15 s, under a short bright splash. Routed ONLY from `altbank::make`
/// (CC0 != 0 on a GM 14 channel) — the default bank keeps tubular bells.
const TAMTAM: &[(f32, f32, f32)] = &[
    (1.000, 1.00, 12.0),
    (1.483, 0.75, 10.5),
    (2.090, 0.55, 9.5), // twin a — the bloom group starts here (idx 2)
    (2.132, 0.45, 9.0), // twin b: 0.042·f0 shimmer beat inside the bloom
    (2.980, 0.40, 8.0),
    (3.820, 0.30, 7.5),
    (4.760, 0.22, 6.5),
    (5.890, 0.15, 6.0),
    (7.240, 0.10, 5.0),
    (8.710, 0.07, 4.5),
];
const TAMTAM_BLOOM_FROM: usize = 2;
const TAMTAM_NOISE_AMP: f32 = 0.55;
const TAMTAM_NOISE_T60: f32 = 0.12;
const TAMTAM_NOISE_BP: (f32, f32) = (1100.0, 0.6);
const TAMTAM_ATTACK_S: f32 = 0.002;
const TAMTAM_RELEASE_T60: f32 = 3.0;
const TAMTAM_GAIN: f32 = 0.80; // level knob (alt bank only)
const TAMTAM_BLOOM_MAX_S: f32 = 0.7;
const TAMTAM_BLOOM_VEL_S: f32 = 0.4; // bloom_s = 0.7 − 0.4·vn
const TAMTAM_UPPER_MIN: f32 = 0.5;
const TAMTAM_UPPER_VELOCITY_SCALE: f32 = 0.9;
const TAMTAM_UPPER_JITTER: f32 = 0.10;

pub(crate) fn tam_tam(key: u8, vel: u8, sr: f32, seed: u32) -> Modal {
    let k = fold_key(key, 36, 47);
    let f = key_freq(k);
    let v = vel_amp(vel);
    let vn = vel as f32 / 127.0;
    let upper = TAMTAM_UPPER_MIN + TAMTAM_UPPER_VELOCITY_SCALE * vn;
    let mut jrng = Rng::new(seed ^ 0x7A37_A300);
    let partials: Vec<(f32, f32, f32)> = TAMTAM
        .iter()
        .enumerate()
        .map(|(i, &(r, a, t))| {
            let amp = if i >= TAMTAM_BLOOM_FROM {
                a * v * upper * (1.0 + TAMTAM_UPPER_JITTER * jrng.white())
            } else {
                a * v
            };
            (f * r, amp, t)
        })
        .collect();
    let splash = Biquad::bandpass(TAMTAM_NOISE_BP.0.min(sr * 0.4), TAMTAM_NOISE_BP.1, sr);
    let bloom_s = TAMTAM_BLOOM_MAX_S - TAMTAM_BLOOM_VEL_S * vn;
    Modal::new(
        sr,
        seed,
        &partials,
        (TAMTAM_NOISE_AMP * v, TAMTAM_NOISE_T60, splash),
        TAMTAM_ATTACK_S,
        TAMTAM_RELEASE_T60,
        TAMTAM_GAIN,
    )
    .with_mode_bloom(TAMTAM_BLOOM_FROM, bloom_s)
}

// ---------------------------------------------------------------------------
// Pluck (extended Karplus-Strong)
// ---------------------------------------------------------------------------

#[derive(Clone, Copy)]
pub struct MwahSpec {
    pub start_hz: f32,
    pub bloom_hz: f32,
    pub q: f32,
    pub bloom_s: f32,
    pub decay_s: f32,
    pub gain: f32,
}

struct Mwah {
    spec: MwahSpec,
    low: Biquad,
    high: Biquad,
    follower: f32,
    attack_k: f32,
    release_k: f32,
}

impl Mwah {
    const FOLLOWER_SCALE: f32 = 8.0;
    const HIGH_BLOOM_GAIN: f32 = 2.2;

    fn new(spec: MwahSpec, sr: f32) -> Self {
        Mwah {
            spec,
            low: Biquad::bandpass(spec.start_hz, spec.q, sr),
            high: Biquad::bandpass(spec.bloom_hz, spec.q, sr),
            follower: 0.0,
            attack_k: 1.0 - (-1.0 / (0.006 * sr)).exp(),
            release_k: 1.0 - (-1.0 / (0.055 * sr)).exp(),
        }
    }

    fn tick(&mut self, x: f32, t: u32, sr: f32) -> f32 {
        let target = x.abs();
        let k = if target > self.follower {
            self.attack_k
        } else {
            self.release_k
        };
        self.follower += k * (target - self.follower);

        let t_s = t as f32 / sr;
        let u = (t_s / self.spec.bloom_s.max(0.001)).clamp(0.0, 1.0);
        let smooth = u * u * (3.0 - 2.0 * u);
        let open = smooth * smooth * smooth * smooth * smooth;

        let age = (t_s - self.spec.bloom_s).max(0.0);
        let decay = 10f32.powf(-3.0 * age / self.spec.decay_s.max(0.01));
        let follow = (self.follower * Self::FOLLOWER_SCALE).min(1.0);
        let low = self.low.process(x);
        let high = self.high.process(x);
        let opened = low * (1.0 - open) + high * open * Self::HIGH_BLOOM_GAIN;
        opened * self.spec.gain * open * decay * follow
    }
}

/// Sitar jawari bridge (GM 104): an envelope-tracking one-sided contact
/// nonlinearity INSIDE the KS feedback loop. The wide curved bridge grazes
/// the string once per period, flattening the spectral envelope and pumping
/// energy from the fundamental into high partials on EVERY round trip — so
/// the buzz decays with the note instead of as its square (the refuted
/// memoryless-waveshaper behaviour: relative 3rd-harmonic ∝ A², −2 dB of
/// buzz per −1 dB of decay). The contact height is a RATIO of the tracked
/// signal envelope, which makes the map homogeneous of degree 1: the buzz
/// character is level-invariant all the way down the decay.
///
/// Boundedness: the contact map is pointwise nonexpansive, |J(s)| ≤ |s| for
/// every input and every internal state (a reflected sample never lands
/// further from zero than it came in — proof at `Jawari::process`). The
/// jawari therefore only
/// REMOVES energy from the loop; the linear contraction analysis
/// (`coupled_loop_margin_holds`: (loop_gain·|H_damp|)² + k² < 1) remains a
/// valid upper bound and the string still decays to silence — no runaway,
/// no limit cycle. The spectral flattening is redistribution within a
/// shrinking energy budget, not gain.
#[derive(Clone, Copy)]
pub struct JawariSpec {
    /// Contact height at note start, as a fraction of the tracked envelope
    /// (lower = deeper contact = more buzz).
    pub ratio_start: f32,
    /// Contact height after the slow sweep settles — the sitar's spectral
    /// evolution over the decay (the contact point migrating on the curve).
    pub ratio_end: f32,
    /// Time constant (s) of the ratio glide from start to end.
    pub sweep_s: f32,
    /// Coefficient of restitution 0..1: the fraction of the beyond-bridge
    /// excursion REFLECTED back off the bridge (0 = the string sticks,
    /// 1 = a lossless bounce).
    pub restitution: f32,
    /// One-sided delay modulation: while the string is in contact it wraps
    /// onto the curved bridge and SHORTENS by up to this fraction of the
    /// loop delay. This leg is what actually sustains the HIGH partials —
    /// a delay shift is a phase shift proportional to frequency, so the
    /// n-th partial sees n× the modulation index and the spectral envelope
    /// flattens. (Measured: amplitude-domain contact alone — clip OR fold —
    /// moves energy into h1–h4 and leaves everything above h6 decaying
    /// exactly like plain KS.)
    pub wrap: f32,
    /// Envelope-follower release time constant (s); attack is instant.
    pub follow_s: f32,
}

/// Attack-only string/fret contact for slap-bass gestures (GM 36/37).
///
/// The KS loop stores a travelling-wave amplitude, not a literal fretboard
/// displacement sample. The contact therefore acts as a one-sided junction on
/// that travelling wave during the onset: while the vertical motion exceeds the
/// clearance threshold it reflects part of the excursion and briefly shortens
/// the effective loop. That is the same bounded mechanism as `Jawari`, but
/// gated to the slap attack instead of riding the whole sustain.
#[derive(Clone, Copy)]
pub struct FretContactSpec {
    pub vel_floor: f32,
    pub threshold: f32,
    pub restitution: f32,
    pub wrap: f32,
    pub duration_s: f32,
    pub horiz: f32,
    pub vert: f32,
}

/// Excitation model for a plucked voice (natural-pluck redesign HLD §2).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ExcModel {
    /// The historic flat, peak-normalized comb-filtered noise burst. Every
    /// preset defaults to this, so an un-migrated preset is bit-identical.
    Legacy,
    /// Harmonic-domain build: a deterministic natural-rolloff backbone
    /// (|sin(kπβ)|/k^s · pick-LP magnitude) blended in the energy domain with
    /// the comb noise, then normalized on the SUSTAIN BAND — a gentler, less
    /// front-loaded attack that does not re-level the instrument (§2, G7).
    Shaped,
}

/// The ceiling, in dB/s, on how much of a plucked note's decay the in-loop
/// damper is allowed to contribute at the fundamental (KILN-00042).
///
/// The damper is a FIXED-cutoff one-pole inside the KS loop, so its loss per
/// round trip is ≈ ½(f/fc)² and the loop makes f trips per second: left alone
/// its share of the decay grows as **f³**, which is why an unmitigated preset's
/// top octave dies 5–14x faster than its bottom while both reference synths sit
/// at 1.7–1.8x. Capping that share turns the damper back into what it should be
/// — a timbre control — and leaves the musical register tilt to the `t60`
/// key-scale, which is exact and directly authored.
///
/// 1.5 dB/s keeps the damper subordinate: at the top of the register the median
/// preset's `t60` term is ~28 dB/s, so this is a ~5 % perturbation. The value is
/// forgiving — the derived anchor goes as its cube root, so doubling it moves
/// every anchor only 26 %.
pub const KS_DAMP_BUDGET: f32 = 0.30;

/// KILN-00048: the normalized velocity at which the KS loop damper corner is
/// anchored. String damping is a property of the string, the bridge and the
/// air — NOT of how hard the string is plucked — so the in-loop damper corner
/// (which is applied once per round trip, `f` trips/s, and therefore sets a
/// decay RATE) must be velocity-INDEPENDENT: pinned at this preset velocity so
/// decay rate is a function of pitch and `t60` alone. The velocity→brightness
/// the damper used to supply is transferred onto the excitation (a once-applied
/// spectrum). Anchoring at vel 100 (rather than 1.0) makes every vel-100 render
/// bit-identical to the pre-decouple synth: `vn == vn_anchor` there, so the
/// same IEEE f32 corner is computed. `vn_anchor` folds in `vel_sense` exactly
/// as `vn` does, so the compressed presets stay bit-identical at vel 100 too.
pub(crate) const KS_ANCHOR_VN: f32 = 100.0 / 127.0;

/// KILN-00048: exponent γ on the excitation `pick_lp` velocity-transfer factor.
/// The velocity→brightness factor `t` removed from the loop damper is applied
/// ONCE across the excitation path (see `Pluck::new`): it goes onto `pick_lp`,
/// and only the share the pick floor truncates spills onto `out_lp`. At γ=δ=1
/// the total excitation-corner product = exactly one `t`, so the first-order
/// velocity→timbre tilt (what the centroid oracle and the K-weighted LUFS slope
/// respond to) is preserved for EVERY preset — single-filter (STEEL/NYLON) and
/// dual-filter (koto/shamisen) alike. NB the first cut of this fix applied `t`
/// to pick AND out independently (t², an extra factor of `t` of pp darkening);
/// that over-darkened the dual-filter presets and is the bug the shortfall
/// routing corrects. Raise γ to recover more ff/pp contrast if the damper's
/// removed *compounding* term proves load-bearing (calibrated by
/// `velocity_opens_pluck_timbre`, not guessed).
pub(crate) const KS_EXC_VEL_TRANSFER: f32 = 1.0;

/// KILN-00048: exponent δ on the FLOOR-TRUNCATED share of the transfer that
/// spills onto `out_lp`. The wound basses' `pick_lp` is floor-pinned at pp, so
/// their pp darkening cannot ride the pick and must come from `out_lp` — that
/// spilled share is what this scales. Separate knob from γ so the basses can be
/// tuned without touching the unfloored presets (where the spill is ~nil).
pub(crate) const KS_OUT_VEL_TRANSFER: f32 = 1.0;

/// KILN-00048 item 4: the pitch-relative pp excitation floor coefficient. An
/// absolute 300 Hz `pick_lp` floor is pitch-blind — in the koto's register it
/// lets a soft note collapse to a near-sine (300 Hz ≈ 1.15·f0 at key 60), which
/// the held damper makes near-immortal and which flattens the windowed velocity
/// law past the [1.5, 2.35] compensation bound. Flooring `pick_lp` at `c·f0`
/// instead keeps a pp pluck off the pure fundamental. CAPPED at the no-transfer
/// pick, so it can only ever undo the decouple's *transfer* darkening — never
/// re-voice the preset's own authored darkness — which keeps every vel-100
/// render bit-identical (there the cap equals the pick). Generic physics, but
/// measurably inert for every current preset except koto.
pub(crate) const KS_PICK_F0_FLOOR: f32 = 2.2;

/// How a `Pluck` preset holds its in-loop damper open at high keys.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum DamperHold {
    /// No hold: the damper corner stays at `bright` and its share of the decay
    /// grows as f³. Only for voices deliberately voiced around that collapse.
    Off,
    /// Hold the damper's decay share inside [`KS_DAMP_BUDGET`] of the preset's
    /// OWN authored `t60` loss, by growing the corner above the frequency where
    /// this preset would otherwise exceed that budget.
    ///
    /// Since that share is ≈ 4.343·f³/fc², holding it constant means the corner
    /// must grow as f^1.5 — the *unique* exponent that flattens a per-second
    /// loss, because the per-trip loss has to fall as 1/f to cancel the trip
    /// rate. The budget is RELATIVE, not absolute: an absolute ceiling makes the
    /// required corner independent of `bright` (it cancels exactly), so every
    /// preset converges on one damper curve and their timbres stop differing.
    /// Bounding the damper against each preset's own `t60` loss instead means the
    /// hold engages only where the damper has become a pathological share of that
    /// preset's decay — late for a short, bright voice, early for a dark ringing
    /// one — so identity survives.
    ///
    /// Below the anchor the note is bit-identical to `Off` (the hold clamps at
    /// 1). Above ~key 72 the corner saturates the `sr·0.45` limit and the f³
    /// cliff slowly resumes — accepted, and the same ceiling for every preset
    /// because the bright-dependence cancels.
    Derived,
}

impl DamperHold {
    /// The smallest damper corner that keeps the damper's decay contribution
    /// inside its budget at `f`: [`KS_DAMP_BUDGET`] of the preset's OWN authored
    /// `t60` loss, `t60_dbps` = 60/t60 for this note.
    ///
    /// From 4.343·f³/fc² ≤ ρ·A, so `fc_min = f·√(4.343·f / (ρ·A))`. Shared with
    /// the oracle so implementation and expectation cannot drift.
    pub(crate) fn min_corner(f: f32, t60_dbps: f32) -> f32 {
        f * (4.343 * f / (KS_DAMP_BUDGET * t60_dbps.max(1e-6))).sqrt()
    }
    /// Multiplier on the damper corner for a note ringing at `f`.
    ///
    /// `bright` is the preset's STATIC post-wound corner — deliberately not
    /// the velocity-scaled one, so that the crossover sits at a fixed place
    /// per key and velocity still opens the damper the way it always did.
    /// Always ≥ 1.
    fn corner_scale(self, f: f32, bright: f32, t60_dbps: f32) -> f32 {
        match self {
            DamperHold::Off => 1.0,
            DamperHold::Derived => (Self::min_corner(f, t60_dbps) / bright).max(1.0),
        }
    }
}

pub struct PluckPreset {
    pub t60: f32, // decay at 220 Hz
    /// Key-scaling exponent for the authored t60: `t60 * (220 Hz / f)^exp`.
    /// The historic pluck family law is 0.55; GM7 clavinet flattens it to match
    /// the General MIDI reference idiom instead of a physical short-string collapse.
    pub t60_key_exp: f32,
    pub bright: f32,  // loop damping cutoff
    pub pick_lp: f32, // excitation lowpass
    pub pos: f32,     // pick position (0..0.5)
    /// Minimum fundamental deposit of the INITIAL pluck burst, as a fraction of the
    /// burst peak `v` (0 = off = every preset unchanged). One period of comb-filtered
    /// noise has a Rayleigh-random h1 (~18 dB spread per note/seed); a weak-h1 draw lets
    /// the undamped low-mid octave dominate by up to +20 dB — an intermittent "an-octave-
    /// up" tell. Tops the burst's h1 up in phase to this floor (the `TREM_H1_FLOOR`
    /// restrike fix, now on the initial pluck too). Set on the harp; others opt in.
    pub h1_floor: f32,
    pub amp: f32,
    pub attack_s: f32,
    pub rel_t60: f32,
    pub body: &'static [(f32, f32, f32)], // (freq, q, gain dB) peak EQs
    pub out_lp: f32,                      // 0 = none
    // Magnetic pickup position comb (0 = acoustic). NOTE the ×2 convention:
    // the comb delay is 2·pickup·period, so the field is HALF the physical
    // sensing fraction — 0.11 senses at ~0.22 of the string (a neck pickup),
    // 0.05 near the bridge.
    pub pickup: f32,
    pub sub: f32, // envelope-locked fundamental sine (0 = none)
    // The bass "kick": gain of a deep lowpassed-noise thump fired at note-on
    // (KICK_LP_HZ / KICK_T60_S), summed in parallel like the stop thump. Models
    // the broadband LOW attack thud of a real finger bass through an amp —
    // measured on the MU-80 (XG) as strong 20-80 Hz onset energy (centroid
    // ~100 Hz) that our modelled voice lacked. Lowpassed deep so it adds low
    // punch but never a click. 0 = none; only the electric basses author it, so
    // every other preset is bit-identical.
    pub kick: f32,
    pub cab_lp: f32, // clean-amp cab rolloff, 0 = none (HLD G2)
    // --- HLD family B: parallel one-shot transients ---
    pub click: f32,            // pick/slap onset hardness (0 = none)
    pub click_hp: f32,         // click filter corner
    pub click_post: bool,      // false: knocks the body (pre-EQ); true: post-out
    pub attack_noise: f32,     // finger/fret noise level (0 = none, post-out)
    pub stop_thump: f32,       // release thud level (0 = none, armed by note_off)
    pub sub_shape: (f32, f32), // sub waveshaper (2f, 3f) amounts (MUTED grit / B5)
    pub sub_ramp: u32,         // sub fade-in samples
    pub grit: bool,            // per-voice soft-clip (MUTED palm chug, G4)
    pub buzz: f32,             // envelope-normalized yarn/fret contact buzz (round-3 U1)
    pub wound_all: bool,       // K4: wound full-range (bass family) vs key-split (guitars)
    pub wound_key_split: bool, // when false, non-bass presets skip the guitar split
    /// High-key damper hold — see [`DamperHold`]. `Derived` (the default)
    /// caps the in-loop damper's contribution to the decay at
    /// [`KS_DAMP_BUDGET`] of its authored decay, which stops the "E6 dies in 100 ms"
    /// cliff (KILN-00042).
    pub damper_hold: DamperHold,
    pub harmonic: bool, // prog-31 flageolet: loop retuned and node-filtered (G7)
    pub mwah: Option<MwahSpec>, // fretless vocal formant bloom (GM 35)
    // --- v0.12 second-polarization "course" voicing (GM 15 dulcimer) ---
    // The vertical KS loop's detune, decay and damping relative to the
    // horizontal one, and the h/v mix. DEFAULTS carry the exact literals the
    // code used to hardcode (1.0013 / 0.42 / 1.15 / (0.74, 0.26)), so every
    // pre-existing preset is bit-identical; the dulcimer re-voices the pair
    // as a true double course (wider detune, near-equal decay and mix).
    pub course_detune: f32,
    pub course_t60: f32,
    pub course_bright: f32,
    pub course_mix: (f32, f32),
    // Cross-injection strength between the two loops. DEFAULTS keep the old
    // hardcoded K_COUPLE (same-string polarization coupling). A double COURSE
    // is two separate strings that meet only at the bridge — an order weaker;
    // full-strength skew coupling splits the pair's normal modes by
    // ~k·f0/π Hz, which would bury the course's slow tuning beat.
    pub course_couple: f32,
    // --- v0.15 electric-guitar v2 ---
    // Magnetic-pickup coil resonance (Hz, Q): one resonant lowpass after the
    // position comb — the RLC peak-then-12 dB/oct that reads "electric"
    // (Paiva/Pakarinen/Välimäki, JAES 2012). (0, 0) = no pickup circuit.
    pub pickup_rlc: (f32, f32),
    // E-bow/sustainer hold level as a fraction of the note's early reference
    // level (0 = none): once a HELD note decays to this fraction, a
    // band-limited SATURATING driver at each loop's fundamental latches on
    // and holds it there — supercritical small-signal gain, amplitude pinned
    // by the soft limiter (Sullivan 1990's stabilized feedback). Release
    // drops the driver instantly and the string decays as ever.
    pub sustain: f32,
    // --- v0.16 sitar/banjo (GM 104/105) ---
    // Sitar bridge contact inside the KS loop (None = plain string); see
    // `JawariSpec` for the model and its boundedness argument.
    pub jawari: Option<JawariSpec>,
    // Attack-only string/fret collision for GM 36/37 slap/pop. None keeps every
    // non-slap preset on the old plain-KS path.
    pub fret_contact: Option<FretContactSpec>,
    // Banjo drum-head modes: (freq Hz, Q, linear gain) parallel bandpass
    // resonators driven by the string+pick signal and summed before the
    // body EQ — the tensioned mylar head the bridge stands on. Empty = no
    // membrane (every non-banjo preset).
    pub membrane: &'static [(f32, f32, f32)],
    // --- v0.16 voice-quality overhaul §2.10 ---
    // Velocity sensitivity, 0..=1. At 1.0 (every pre-existing preset) the
    // exact historic velocity laws apply, bit-for-bit. Below 1.0 the key
    // velocity is compressed toward the top of its range before EVERY
    // velocity law (level, loop/pick brightness, click) — the harpsichord's
    // jack plectrum displaces the string the same distance however hard the
    // key falls, so its loudness spread must stay nearly flat.
    pub vel_sense: f32,
    // TREM: whether a fast same-key restrike may re-pick this string as a
    // tremolo stroke (engine gate TREM1). True for hand-picked strings
    // (guitars, basses, dulcimer, sitar, banjo — tremolo/roll/jhala are the
    // idiom); FALSE for the mechanically-damped keyboard machines
    // (harpsichord jack, clavinet yarn strip), whose fast repeats must keep
    // articulating.
    pub trem: bool,
    // --- natural-pluck redesign §2: Shaped excitation (opt-in) ---
    /// Legacy (default → bit-identical) or Shaped. Only the migrated presets set Shaped.
    pub exc_model: ExcModel,
    /// Shaped backbone slope s (1/k^s = −6.02·s dB/oct): finger ~2.0, picked ~1.3–1.5.
    pub slope: f32,
    /// Shaped noise-mix ρ (energy-domain): finger 0.20, picked 0.30.
    pub noise_mix: f32,
    /// Per-preset sustain-band trim, dB (≤ ±1.5; beyond = Tripwire 1). 0 = none.
    pub exc_trim: f32,
    #[cfg(test)]
    pub name: &'static str, // oracle-36 routing discriminant (test-only)
}

