/// One Karplus-Strong delay loop on a fractional-tap delay line, so its
/// pitch can *move* while ringing (bends, slides, hammer-ons, vibrato).
/// The in-loop damper's phase delay is compensated in the delay length,
/// so the string tunes accurately; retuning glides over a few ms.
struct KsLoop {
    dl: DelayLine,
    delay: f32,
    target: f32,
    max_delay: f32, // V4/INT-4: the line's safe capacity (tap margin held back)
    glide_k: f32,
    damp: OnePole,
    loop_gain: f32,
    bright: f32,
    t60: f32,
    sr: f32,
    // guitar v2 sustainer driver (None unless the preset authors `sustain`)
    drv: Option<SusDrv>,
    /// K3 polarization coupling this loop is half of, 0 when uncoupled. The
    /// e-bow drive is sized from the string's per-trip DEFICIT, and a coupled
    /// pair loses less per trip than either loop alone (|λ| = sqrt(a² + k²) > a),
    /// so the deficit has to be taken against the pair or the driver over-pushes
    /// — by a pitch-dependent amount, which tilts the hold (MM-BUG-KILN-00155).
    k_couple: f32,
    // sitar jawari bridge contact (None unless the preset authors `jawari`)
    jaw: Option<Jawari>,
    // slap/pop fretboard contact (None unless the preset authors `fret_contact`)
    fret: Option<FretContact>,
}

/// The jawari runtime (see `JawariSpec` for the model). All state is driven
/// by the loop signal itself: the follower decays with the string, so the
/// contact height h = ratio·follower shrinks with the note and the map stays
/// scale-invariant down to silence. No random draws, no external energy.
struct Jawari {
    fol: f32,   // envelope follower (instant attack, one-pole release)
    fol_k: f32, // follower release coefficient
    ratio: f32, // current contact ratio, glides ratio → ratio_end
    ratio_end: f32,
    ratio_k: f32, // per-sample glide coefficient
    rest: f32,    // coefficient of restitution, clamped to [0, 1]
    wrap: f32,    // delay-shortening fraction while in contact, in [0, 0.05]
    depth: f32,   // last sample's normalized contact depth, 0..1
}

/// Attack-bounded fret collision runtime for slap bass. It is deliberately
/// passive: the collision target is a convex blend between the incoming sample
/// and a one-sided reflection whose magnitude never exceeds the original.
struct FretContact {
    age: u32,
    until: u32,
    strength: f32,
    threshold: f32,
    rest: f32,
    wrap: f32,
    fol: f32,
    fol_k: f32,
    depth: f32,
}

impl Jawari {
    fn new(spec: &JawariSpec, sr: f32) -> Self {
        Jawari {
            fol: 0.0,
            fol_k: 1.0 - (-1.0 / (spec.follow_s.max(1e-4) * sr)).exp(),
            ratio: spec.ratio_start,
            ratio_end: spec.ratio_end,
            ratio_k: 1.0 - (-1.0 / (spec.sweep_s.max(1e-3) * sr)).exp(),
            // the clamps make passivity/boundedness unconditional by
            // construction, whatever a future preset writes
            rest: spec.restitution.clamp(0.0, 1.0),
            wrap: spec.wrap.clamp(0.0, 0.05),
            depth: 0.0,
        }
    }

    /// One-sided reflecting bridge contact. For s ≥ −h the sample passes
    /// untouched; a sample beyond the bridge (s < −h ≤ 0, excursion
    /// e = −(s+h) > 0) bounces back with restitution r:
    ///     J(s) = −h + r·e.
    ///
    /// Passivity (|J(s)| ≤ |s| for EVERY input and EVERY state):
    /// |s| = h + e. If J(s) ≤ 0 then |J(s)| = h − r·e ≤ h ≤ |s|; if
    /// J(s) > 0 then |J(s)| = r·e − h ≤ e ≤ |s| (r ≤ 1). The map never
    /// moves a sample further from zero than it came in, so it can only
    /// remove energy from the feedback loop — the buzz is redistribution
    /// of a shrinking budget, never gain.
    #[inline]
    fn process(&mut self, s: f32) -> f32 {
        let a = s.abs();
        if a > self.fol {
            self.fol = a; // instant attack
        } else {
            self.fol += self.fol_k * (a - self.fol);
            if self.fol < 1e-24 {
                self.fol = 0.0; // denormal flush
            }
        }
        self.ratio += self.ratio_k * (self.ratio_end - self.ratio);
        let h = self.ratio * self.fol;
        if s < -h {
            let e = -(s + h);
            // normalized contact depth drives next sample's bridge wrap;
            // kept PROPORTIONAL (rarely saturating): a smooth per-period
            // delay-mod pulse spreads energy up the harmonic comb, where a
            // saturated square gate was measured to dump it into h1–h4
            self.depth = (e / (0.5 * self.fol + 1e-20)).min(1.0);
            e * self.rest - h
        } else {
            self.depth = 0.0;
            s
        }
    }
}

impl FretContact {
    fn new(spec: &FretContactSpec, vn: f32, sr: f32, lane: f32) -> Option<Self> {
        let over = ((vn - spec.vel_floor) / (1.0 - spec.vel_floor).max(1e-6)).clamp(0.0, 1.0);
        let strength = (lane * over * over).clamp(0.0, 1.0);
        (strength > 0.0).then(|| FretContact {
            age: 0,
            until: (spec.duration_s.max(0.0) * sr) as u32,
            strength,
            threshold: spec.threshold.clamp(0.05, 0.98),
            rest: spec.restitution.clamp(0.0, 1.0),
            wrap: spec.wrap.clamp(0.0, 0.05),
            fol: 0.0,
            fol_k: 1.0 - (-1.0 / (0.004 * sr)).exp(),
            depth: 0.0,
        })
    }

    #[inline]
    fn tap(&self, delay: f32) -> f32 {
        if self.age < self.until && self.depth > 0.0 {
            (delay - self.depth * self.wrap * delay).max(2.0)
        } else {
            delay
        }
    }

    #[inline]
    fn process(&mut self, s: f32) -> f32 {
        if self.age >= self.until {
            self.depth = 0.0;
            self.age = self.age.saturating_add(1);
            return s;
        }
        self.age += 1;

        let a = s.abs();
        if a > self.fol {
            self.fol = a;
        } else {
            self.fol += self.fol_k * (a - self.fol);
            if self.fol < 1e-24 {
                self.fol = 0.0;
            }
        }

        let h = self.threshold * self.fol;
        if s < -h {
            let e = -(s + h);
            let reflected = e * self.rest - h;
            self.depth = self.strength * (e / (0.5 * self.fol + 1e-20)).min(1.0);
            s + self.strength * (reflected - s)
        } else {
            self.depth = 0.0;
            s
        }
    }
}

/// The e-bow driver (guitar v2 HLD §3.D): a resonant bandpass at the loop
/// fundamental feeding back through a soft limiter. The small-signal
/// round-trip gain at f0 is deliberately slightly supercritical
/// (SUS_K_OVER x the loop's per-trip deficit); the SATURATOR pins the
/// amplitude — Sullivan 1990's
/// stabilized feedback. Every other mode sees only the bandpass skirt (zero
/// at DC) and stays contracting, and the energy input is hard-bounded by
/// k·l per sample no matter how the constants are mis-tuned.
struct SusDrv {
    bp: Biquad,
    k_max: f32,  // headroom clamp, min across the current glide's endpoints
    k: f32,      // current drive (0 until the voice's hold latch engages)
    l: f32,      // saturator knee (set at latch time from the reference)
    h_last: f32, // headroom at the previous retune's center (glide endpoint)
}

/// Guitar v2 sustainer constants (HLD §3.D): driver bandpass Q, the
/// small-signal round-trip target at the fundamental, the absolute drive
/// cap, the saturator knee as a fraction of the hold level, and the ramp.
const SUS_BP_Q: f32 = 4.0;
// k = 1.45×deficit: constant supercriticality RATIO.
//
// Was 1.18 while the K3 coupling read its partner one sample stale
// (MM-BUG-KILN-00155). That lag was mildly GENERATIVE — the defect that let a
// high nylon note run away also quietly fed the e-bow, so a smaller drive
// reached the hold in time. With the coupling made lag-free the loop is a true
// contraction again and the driver has to supply that energy itself, so the
// ratio rises to keep the measured settle time (key 64 reaches its hold by
// ~5 s, against ~4 s before; `sustain_holds_high_notes` is the gate).
const SUS_K_OVER: f32 = 1.45;
const SUS_K_MAX: f32 = 0.12;
const SUS_L_SCALE: f32 = 0.7;
const SUS_RAMP_S: f32 = 0.060; // drive engage ramp

// KILN-00049 output-controller bounds. The −26 dB cut covers the reported
// key-88 overshoot (about 21 dB above target) with margin; the +12 dB boost
// prevents a silent/broken projection from turning into unbounded make-up gain.
const SUS_OUT_GAIN_MIN: f32 = 0.05;
const SUS_OUT_GAIN_MAX: f32 = 4.0;
const SUS_OUT_GAIN_TAU_S: f32 = 0.050;

impl KsLoop {
    /// Loop delay (in samples) for frequency `f`, compensating the damper's
    /// phase delay and the one-sample write→read latency.
    fn delay_for(f: f32, bright: f32, sr: f32) -> f32 {
        let a = 1.0 - (-2.0 * std::f32::consts::PI * (bright / sr).min(0.49)).exp();
        let b = 1.0 - a;
        let w = 2.0 * std::f32::consts::PI * f / sr;
        let d1p = ((b * w.sin()) / (1.0 - b * w.cos())).atan() / w;
        (sr / f - d1p - 1.0).max(2.0)
    }

    fn new(f: f32, bright: f32, t60: f32, exc: &[f32], sr: f32) -> Self {
        let target = Self::delay_for(f, bright, sr);
        // room to bend or slur a full octave down
        let mut dl = DelayLine::new((target * 2.2) as usize + 8);
        let n = target.ceil() as usize + 1;
        for i in 0..n {
            dl.push(exc[i % exc.len()]);
        }
        KsLoop {
            dl,
            delay: target,
            target,
            // a wider bend (RPN range 24, deep portamento origins) would
            // silently wrap the ring buffer into garbage — clamp instead:
            // an out-of-range glide pitch-limits (V4/INT-4, oracle 43)
            max_delay: target * 2.2 + 4.0,
            glide_k: 1.0 - (-1.0 / (0.004 * sr)).exp(),
            damp: OnePole::lowpass(bright, sr),
            loop_gain: 10f32.powf(-3.0 / (t60 * f)),
            bright,
            t60,
            sr,
            drv: None,
            // uncoupled until the owner pairs this loop with its partner
            k_couple: 0.0,
            jaw: None,
            fret: None,
        }
    }

    /// |H| of the in-loop OnePole damper at frequency `f` (closed form).
    fn damp_mag(&self, f: f32) -> f32 {
        OnePole::lowpass_mag(self.bright, f, self.sr)
    }

    /// Driver gain at `f`: PROPORTIONALLY supercritical — k = SUS_K_OVER ×
    /// the loop's per-trip deficit at the fundamental (damper included; a
    /// bare scalar cannot hold anything above ~A4, review D1/O1). Keeping
    /// k/deficit constant pins the LOOP equilibrium at the same multiple of the
    /// knee L at every pitch. KILN-00049 separately closes the derived-damper
    /// e-bow's audible level after the pitch-dependent pickup/body projection.
    fn sus_headroom(&self, f: f32) -> f32 {
        let lg = 10f32.powf(-3.0 / (self.t60 * f));
        let a = lg * self.damp_mag(f);
        // Against the PAIR, not this loop alone. K3 couples the two
        // polarizations into the step matrix [[a, k], [-k, a]], whose spectral
        // radius is sqrt(a² + k²) — strictly greater than `a`, so the pair
        // sheds less per trip than the bare loop does. Sizing the drive from
        // `1 - a` therefore over-pushes by k²/2a, and because that error scales
        // with the deficit it lands differently at every pitch, which reads as
        // a hold that tilts across the register instead of sitting flat.
        let a_pair = (a * a + self.k_couple * self.k_couple).sqrt().min(1.0);
        let deficit = 1.0 - a_pair;
        (deficit * SUS_K_OVER).clamp(0.0, SUS_K_MAX)
    }

    /// Arm the e-bow driver (presets with `sustain > 0`); it stays silent
    /// (k = 0) until the voice's hold latch engages.
    fn enable_driver(&mut self, f: f32) {
        let h = self.sus_headroom(f);
        self.drv = Some(SusDrv {
            bp: Biquad::bandpass(f, SUS_BP_Q, self.sr),
            k_max: h,
            k: 0.0,
            l: 0.0,
            h_last: h,
        });
    }

    /// Latch control: `frac` ramps 0→1, `l` is the saturator knee.
    fn set_drive(&mut self, frac: f32, l: f32) {
        if let Some(d) = &mut self.drv {
            d.k = frac * d.k_max;
            d.l = l.max(1e-6);
        }
    }

    fn clear_drive(&mut self) {
        if let Some(d) = &mut self.drv {
            d.k = 0.0;
        }
    }

    /// TREM pick catch: the plectrum grabs the ringing string at a restrike
    /// — scale the standing wave down so the new stroke's displacement
    /// DOMINATES the phase (vector-adding a fresh burst to a comparable
    /// circulating carrier randomly cancels; a real pick re-imposes the
    /// displacement, it does not add to it). g ≤ 1: pure energy removal.
    fn catch_damp(&mut self, g: f32) {
        self.dl.scale(g);
    }

    /// Retune to a new frequency; the ringing energy stays in the string.
    fn retune(&mut self, f: f32) {
        self.target = Self::delay_for(f, self.bright, self.sr).min(self.max_delay);
        self.loop_gain = 10f32.powf(-3.0 / (self.t60 * f));
        if self.drv.is_some() {
            // glide-endpoint minimum (review C3): an upward bend must not
            // borrow the new center's larger headroom while the delay still
            // rings near the old one. h_last is the FRESH endpoint value from
            // the previous retune (not the clamped min - min-ing against the
            // previous clamp would ratchet down forever under vibrato), so
            // one transcendental evaluation per retune suffices.
            let h = self.sus_headroom(f);
            let sr = self.sr;
            if let Some(d) = &mut self.drv {
                d.bp.retune_bandpass(f, SUS_BP_Q, sr);
                d.k_max = h.min(d.h_last);
                d.k = d.k.min(d.k_max);
                d.h_last = h;
            }
        }
    }

    /// G6 release darkening: move the in-loop damper and retune so the
    /// delay keeps compensating the NEW damper's phase — pitch holds while
    /// the string dulls. `f` must be the composed current frequency
    /// (base × harm × bend): the engine keeps writing pitch to released
    /// voices, and a nominal retune would fight it (V4/INT-3).
    fn set_bright(&mut self, bright: f32, f: f32) {
        self.bright = bright;
        self.damp.set_cutoff(bright, self.sr);
        self.retune(f);
    }

    #[inline]
    /// Read half of the loop step: advance the glide and produce this sample's
    /// output.
    ///
    /// The output is a function of the delay line ALONE — it never depends on
    /// what is written back this sample. That is the property the K3 coupling
    /// relies on: a caller driving two coupled polarizations can read BOTH
    /// before writing EITHER, so each plane is coupled to the other's value at
    /// the same instant rather than one sample stale (MM-BUG-KILN-00155).
    fn tick_read(&mut self) -> f32 {
        self.delay += self.glide_k * (self.target - self.delay);
        // K1: cubic-Lagrange tap — linear interpolation lowpasses the loop
        // at fractional delays and dulls short treble strings.
        // Jawari wrap leg: while in contact the string wraps onto the curved
        // bridge and shortens — a one-sided, contact-gated tap shift (same
        // interpolated-tap machinery every bend/glide already uses, clamped
        // to the line's safe range).
        let tap = match &self.jaw {
            Some(j) if j.depth > 0.0 => (self.delay - j.depth * j.wrap * self.delay).max(2.0),
            _ => self.delay,
        };
        let tap = match &self.fret {
            Some(f) => f.tap(tap),
            None => tap,
        };
        let s = self.dl.tap_cubic(tap);
        // slap/pop fret collision: attack-bounded one-sided reflection before
        // damping/feedback, so the contact changes the string rather than only
        // adding an output garnish.
        let s = match &mut self.fret {
            Some(f) => {
                let y = f.process(s);
                if f.age >= f.until {
                    self.fret = None;
                }
                y
            }
            None => s,
        };
        // sitar jawari: the bridge grazes the string INSIDE the loop, every
        // round trip (None compiles to the identical plain-KS path)
        match &mut self.jaw {
            Some(j) => j.process(s),
            None => s,
        }
    }

    /// Write half of the loop step: the e-bow driver, the damper, the loop gain
    /// and the caller's injection go back into the line. `s` must be the value
    /// [`Self::tick_read`] just returned for this loop.
    fn tick_write(&mut self, s: f32, input: f32) {
        // guitar v2 e-bow driver: band-limited saturating feedback at f0.
        // The bandpass runs even at k = 0 so engagement is click-free.
        let fb = match &mut self.drv {
            Some(d) => {
                let b = d.bp.process(s);
                if d.k > 0.0 {
                    d.k * d.l * (b / d.l).tanh()
                } else {
                    0.0
                }
            }
            None => 0.0,
        };
        self.dl
            .push(self.damp.process(s) * self.loop_gain + input + fb);
    }
}

/// K3 polarization coupling strength: strong enough for a measurable
/// secondary rise (oracle 15), weak enough to keep long notes bounded. NOTE
/// (guitar v2 review): the discrete step matrix [[a, k], [−k, a]] has
/// |λ| = sqrt(a² + k²) — skew coupling is only energy-neutral in the
/// continuous-time limit, so boundedness needs a² + k² < 1 with
/// a = loop_gain·|H_damp|; the coupled_loop_margin_holds oracle asserts it
/// across every preset at worst-case jitter.
pub(crate) const K_COUPLE: f32 = 0.02;

/// Bass "kick" decay: the onset noise thump (preset `kick`) rings down with
/// this t60 — a fast punch that lands with the pluck and is gone before the
/// note settles. Short enough to read as a transient PUNCH, not a boomy tail.
const KICK_T60_S: f32 = 0.075;
/// Bass "kick" lowpass corner: the thump is a deep, DARK thud (the MU-80/XG
/// finger-bass onset measures strongest at 20-80 Hz, centroid ~100 Hz). Cutting
/// this low guarantees the thump carries no mid/treble energy — it can add low
/// weight but can never read as the pick "click" Arthur was bothered by.
const KICK_LP_HZ: f32 = 55.0;

/// G6 release-darken targets: while released, each polarization's damper
/// glides toward this floor at control rate (already-dark presets are
/// unaffected — the glide only ever darkens).
const REL_FLOOR_H: f32 = 600.0;
const REL_FLOOR_V: f32 = 700.0;

/// TREM (tremolo restrike): the restruck pick burst's peak relative to a
/// fresh pluck's (tremolo strokes are lighter grazing strokes, and the burst
/// ADDS to a loop that is already ringing rather than initialising a silent
/// one — at 1.0 a low-string tremolo accumulates several dB above a single
/// pluck's attack).
const TREM_RESTRIKE_LEVEL: f32 = 0.7;
/// After a restrike un-releases the voice, the release attenuation rides
/// back up at this T60-style rate (60 dB per this many seconds). The gap
/// between tremolo strokes costs ~12 dB (rel_t60 0.15, ~30 ms gap), so
/// recovery completes in ~8 ms — inside the stroke's own attack, which
/// masks it; instant recovery would be an audible level step.
const TREM_REL_RECOVER_S: f32 = 0.040;
/// Once a voice has taken a tremolo restrike, its note_offs use the
/// preset's release T60 STRETCHED by this factor: mid-run gate-offs are a
/// notation artifact (the pick hand never damps between strokes), and the
/// stock guitar release (0.15 s = 400 dB/s) was measured to carve 12–15 dB
/// troughs into every 30 ms gap — the dominant term of the click-train
/// artifact, bigger than the fresh-spawn restart it accompanied. 8× turns
/// that into ~1.5 dB per gap, while the RUN-END tail still dies in ~1.2 s
/// (a musical ring-off, not an undamped drone).
const TREM_RELEASE_STRETCH: f32 = 8.0;
/// Tremolo carrier hold. At treble keys the one-pole loop damper's
/// MAGNITUDE at f0 dominates the decay (measured: STEEL key 83, vel 55 —
/// damp_mag(f0) = 0.955/trip × ~976 trips/s ≈ −390 dB/s; the fundamental is
/// −45 dB inside 100 ms), so between 75 ms strokes there is nothing left
/// ringing whatever the engine does about voice identity. Compensating
/// loop_gain by 1/|H(f0)| is DC-UNSTABLE (round-trip gain > 1 below f0), so
/// a tremolo-run voice instead engages the existing band-limited SATURATING
/// sustainer (SusDrv — bounded injection, bandpass zero at DC) as the
/// stroke-averaged energy the player's hand keeps feeding the string. The
/// fraction is the hold knee relative to the stroke's spoken level (the
/// same law as the DRIVE preset's e-bow, a touch lower).
const TREM_SUS_FRACTION: f32 = 0.35;
/// The tremolo hold drops this long after the last restrike (an ongoing
/// run restrikes every ≤ ~100 ms and keeps refreshing it): the run has
/// ended, the driver disengages, and the string decays at the stretched
/// release like any ring-off.
const TREM_SUS_DROP_S: f32 = 0.16;
/// The pick-catch at a restrike: the standing wave is scaled by this before
/// the new stroke's burst is injected. The grab makes the NEW displacement
/// own the carrier phase (no stroke-roulette cancellation against the old
/// one) and bounds cross-stroke energy accumulation.
const TREM_CATCH: f32 = 0.35;
/// Minimum fundamental deposit of a restrike burst, as a fraction of the
/// burst's peak. One period of comb-filtered noise has a Rayleigh-random h1
/// coefficient — measured spanning 20 dB stroke-to-stroke, which reads as a
/// stuttering tremolo. A real pick displacement always carries strong h1
/// (the triangle IC's sin(πp) term), so top the burst's h1 up — in phase
/// with its own — to this floor.
const TREM_H1_FLOOR: f32 = 0.5;
// h1-floor register fade (initial pluck): the octave rings undamped only in the low-mid,
// so the floor is needed at G3-C4 and fades out toward C5 (where the loop damps the octave
// and the note is already f0-dominant). Confines the fix to the susceptible register so
// high notes are untouched. (Harp-tuned; only HARP currently sets h1_floor > 0.)
const HARP_FLOOR_LO: f32 = 262.0; // C4 — full floor at/below
const HARP_FLOOR_HI: f32 = 523.0; // C5 — no floor at/above
const REL_DARKEN_K: f32 = 0.010; // per control tick: τ ≈ 36 ms

/// Top a pluck burst's FUNDAMENTAL up to `h1_target` (in phase with its own h1) by adding
/// a cosine at the fundamental period. One period of comb-filtered noise has a Rayleigh-
/// random h1; a weak draw lets the undamped octave dominate. Shared by the tremolo restrike
/// (`TREM_H1_FLOOR`) and the initial pluck (`PluckPreset.h1_floor`). No-op if target ≤ 0 or
/// the burst already clears the floor, so a preset with `h1_floor = 0` is byte-identical.
fn top_up_h1(exc: &mut [f32], h1_target: f32) {
    let n = exc.len();
    if n == 0 || h1_target <= 0.0 {
        return;
    }
    let (mut xr, mut xi) = (0f32, 0f32);
    for (i, &x) in exc.iter().enumerate() {
        let ph = 2.0 * std::f32::consts::PI * i as f32 / n as f32;
        xr += x * ph.cos();
        xi -= x * ph.sin();
    }
    let h1_amp = 2.0 * (xr * xr + xi * xi).sqrt() / n as f32;
    if h1_amp < h1_target {
        let phi = xi.atan2(xr);
        let add = h1_target - h1_amp;
        for (i, x) in exc.iter_mut().enumerate() {
            let ph = 2.0 * std::f32::consts::PI * i as f32 / n as f32 + phi;
            *x += add * ph.cos();
        }
    }
}

/// A touched string node suppresses the ordinary pluck's broadband mode
/// ladder. Keep the historic random burst's phase, but project its displacement
/// onto the sounding loop fundamental. The separate click still carries the
/// brief finger/string contact; the circulating string is the near-sine a
/// flageolet leaves behind.
fn flageolet_excitation(noise: &[f32], peak: f32) -> Vec<f32> {
    let n = noise.len();
    if n == 0 {
        return Vec::new();
    }
    let (mut xr, mut xi) = (0.0f32, 0.0f32);
    for (i, &x) in noise.iter().enumerate() {
        let phase = 2.0 * std::f32::consts::PI * i as f32 / n as f32;
        xr += x * phase.cos();
        xi -= x * phase.sin();
    }
    let start_phase = xi.atan2(xr);
    let mut exc: Vec<f32> = (0..n)
        .map(|i| {
            let phase = 2.0 * std::f32::consts::PI * i as f32 / n as f32 + start_phase;
            peak * phase.cos()
        })
        .collect();
    // A complete sampled cycle is zero-mean analytically; remove float residue
    // so the node-filtered path never seeds a DC mode.
    let mean = exc.iter().sum::<f32>() / n as f32;
    for x in &mut exc {
        *x -= mean;
    }
    exc
}

/// K4 Stage 1 wound-ness: bass strings are wound full-range; guitars cross
/// from wound to plain around G3 (key 55). Pure arithmetic — no allpass
/// (Stage 2 dispersion stays deferred, §7).
pub(crate) fn wound_factor(wound_all: bool, wound_key_split: bool, key: u8) -> f32 {
    if wound_all {
        1.0
    } else if !wound_key_split {
        0.0
    } else {
        ((55.0 - key as f32) / 24.0).clamp(0.0, 1.0)
    }
}

pub struct Pluck {
    // a real string vibrates in two polarizations: one rings on (horizontal),
    // one decays faster and slightly detuned (vertical) — their sum gives the
    // characteristic fast-then-slow decay and a gentle beat
    horiz: KsLoop,
    vert: KsLoop,
    // K3: energy sloshes between the two polarizations (skew-symmetric,
    // same-sample cross-injection — see the coupling site in `render`)
    k_couple: f32,
    course_detune: f32,     // vertical-loop detune ratio (preset course_detune)
    course_mix: (f32, f32), // (horiz, vert) output mix
    base_f: f32,
    bend: f32,
    harm: f32, // G7 flageolet multiple (1.0 = normal), composed into every retune
    pickup: Option<(DelayLine, f32)>, // magnetic pickup position comb
    pickup_rlc: Option<Biquad>, // pickup coil RLC resonance (resonant lowpass)
    // guitar v2 hold latch (§3.D): the raw string mix is watched at control
    // rate; once a HELD note decays to sustain×reference the e-bow drivers
    // ramp in. One-way — never attenuates, release clears it instantly.
    sus_target: f32, // preset `sustain` (0 = feature absent)
    sus_acc: f32,    // per-control-window peak of |string mix|
    sus_env: f32,    // smoothed envelope of the above
    sus_ref: f32,    // reference level captured 20–80 ms post-onset
    // KILN-00049: a derived damper changes the pitch-dependent loop→output
    // projection. Only that e-bow pairing closes its calibration on the audible
    // post-pickup/body signal; tremolo-installed holds keep their historic path.
    sus_out_control: bool,
    sus_out_acc: f32,
    sus_out_env: f32,
    sus_out_ref: f32,
    sus_out_gain: f32,
    sus_hold: bool,
    sus_ramp: f32,
    sus_l: f32,                    // saturator knee, frozen at latch engage
    sus_ref_until: u32,            // reference-capture deadline (re-armed by a slur)
    sub: Option<(Sine, f32, f32)>, // (osc, gain, decay) fundamental weight
    sub_env: f32,
    // The bass "kick": a deep lowpassed-noise thump fired at note-on, summed in
    // parallel (like the stop thump). A real module's bass punch is a broadband
    // LOW attack thud — the pluck displacing the heavy string through the amp —
    // measured on the MU-80 (XG) as strong 20-80 Hz energy at onset, centroid
    // ~100 Hz. Lowpassed deep (KICK_LP_HZ) so it can never read as a click.
    kick_thump: Option<Burst>,
    sub_shape: (f32, f32), // (2f, 3f) waveshaper amounts on the sub
    sub_ramp: u32,
    // HLD family B one-shots, all fed by the voice's own rng
    onset_pre: Option<Burst>,  // pick click / palm chuff — knocks the body
    onset_post: Option<Burst>, // finger noise / slap pop — after the out-LP
    scrape: Option<Burst>,     // tangent scrape when click_post coexists (round-3 U1)
    stop: Option<Burst>,       // release thump, armed by note_off
    mwah: Option<Mwah>,        // fretless vocal formant bloom
    grit: bool,                // MUTED palm soft-clip
    buzz: f32,                 // envelope-normalized contact-snap buzz (round-3 U1)
    buzz_env: f32,             // fast rectifier average the buzz normalizes against
    buzz_k: f32,               // buzz_env one-pole coefficient (~8 ms)
    buzz_hp: Biquad,           // keeps only the bright part of the gated contact
    // banjo drum head: parallel (mode filter, gain) resonators (empty for
    // every preset that authors no `membrane`)
    membrane: Vec<(Biquad, f32)>,
    body: Vec<Biquad>,
    // clean-amp cab (HLD G2): two cascaded biquad lowpasses — one 2nd-order
    // pole pair alone cannot make the −12 dB-vs-one-pole 8 kHz cliff
    // oracle 6 demands
    cab: Option<[Biquad; 2]>,
    out_lp: Option<OnePole>,
    hammer: Vec<f32>, // pending legato excitation, fed into the loops
    hammer_pos: usize,
    rng: Rng,
    pick_lp_hz: f32,
    // TREM restrike state: the spawn stroke's pick position and velocity-law
    // damper cutoffs (h/v), restored — with fresh per-stroke jitter — when a
    // tremolo restrike re-picks a release-darkened string; and the per-sample
    // release_env recovery multiplier for the un-release ramp.
    pos: f32,
    spawn_bright_h: f32,
    spawn_bright_v: f32,
    rel_rec: f32,
    // set by the first restrike: this voice is a tremolo run — its gate-offs
    // take the STRETCHED release (rel_mul_trem), skip the stop thump and the
    // G6 release darkening, and keep the tremolo sustainer driving through
    // the inter-stroke gaps
    trem_hold: bool,
    rel_mul_trem: f32,
    trem_ok: bool,         // preset capability (PluckPreset::trem)
    trem_sus: bool,        // the sustainer was trem-installed (sus_target was 0)
    trem_last_strike: u32, // voice time of the most recent restrike
    trem_drop: u32,        // TREM_SUS_DROP_S in samples
    amp: f32,
    att: f32,
    att_env: f32,
    release_env: f32,
    rel_mul: f32,
    released: bool,
    env: f32,
    t: u32,
    min_life: u32,
    sr: f32,
    #[cfg(test)]
    kind: &'static str,
}

/// Base sustain-band level for the Shaped excitation (§2.4): the h1..h4
/// RMS-amplitude of the burst is normalized to `K_SUS · v · 10^(exc_trim/20)`
/// (v = vel_amp), so the sustain tracks velocity exactly as Legacy did
/// (amplitude ∝ v) — the anti-re-leveling anchor G7 enforces. Because the
/// normalization target is DETERMINISTIC, it also collapses Legacy's ±9 dB
/// Rayleigh-h1 seed spread to ≈0 (G7 seed-spread check).
///
/// TRIPWIRE 1 RESOLUTION (Phase-2 Unit C): the HLD assumed one global K_SUS +
/// per-preset exc_trim ≤ ±1.5 dB. Measured, the 5 migrated presets span 5.4 dB
/// in Legacy sustain-per-excitation-h1h4 (they differ in t60/bright/pick_lp, so
/// the loop projects the same excitation to different sustain loudness). A
/// single global K_SUS therefore CANNOT hold G7 within ±1.5 dB trims. Resolution
/// (preserves the design intent — per-preset loudness parity + deterministic
/// seed collapse): K_SUS is the grid center and each migrated preset carries its
/// own exc_trim to match its HEAD loudness (measured by
/// `print_shaped_loudness_offset`). The trims run wider than ±1.5 dB by design.
const K_SUS: f32 = 0.15;

/// Phase-dispersion knee (HLD §2.4 tripwire-C lever): harmonics up to `k_c` keep
/// their coherent physical-snapshot phase (they carry the fundamental + body
/// colour and must not be smeared); harmonics ABOVE it get a deterministic
/// quadratic (Schroeder) phase so they no longer pile into one sharp rendered
/// attack peak. The lever moves crest/slew ONLY — it is magnitude-invariant.
const SHAPED_K_C: usize = 8;
/// Schroeder-dispersion strength for k>`SHAPED_K_C`. 1.0 = the classic crest-
/// minimizing φ_k = π·k²/n_max. DORMANT at 0.0 (Fable verdict 2026.07.20): the
/// G2 crest overshoot on STEEL/DULCIMER was the pick CLICK, not the backbone
/// (backbone click-free crest 2.90 ≈ FluidR3 natural 2.99) — dispersion moves no
/// observable here and only perturbs the render, so it stays off. Kept as the
/// HLD's sanctioned lever should the click-free backbone crest (G2c) ever trip.
const SHAPED_DISP: f32 = 0.0;

/// Fable click de-impulsify (2026.07.20): the pick CLICK — not the backbone —
/// drove the Shaped attack crest over the natural band, because the redesign
/// lowered the excitation-body RMS (the gentling) while the fixed-peak click
/// held. Shaped presets therefore SPREAD the 3 ms click to `CLICK_T60_SHAPED`
/// with a `CLICK_RISE_S` raised-cosine attack, and energy-compensate the gain by
/// √(legacy_t60/new_t60) so the output PEAK drops (crest → FluidR3 natural ~3) at
/// CONSTANT band energy — sparkle-neutral, and G7-safe because it stays inside the
/// attack window (−60 dB well before the 50 ms sustain window). Legacy presets
/// keep the 3 ms decay-from-peak, bit-identical.
const CLICK_T60_LEGACY: f32 = 0.003;
const CLICK_T60_SHAPED: f32 = 0.010;
const CLICK_RISE_S: f32 = 0.0015;

/// (t60, attack-rise seconds, energy-compensated gain) for a preset's pick click.
fn click_shape(p: &PluckPreset) -> (f32, f32, f32) {
    if p.exc_model == ExcModel::Shaped {
        (
            CLICK_T60_SHAPED,
            CLICK_RISE_S,
            p.click * (CLICK_T60_LEGACY / CLICK_T60_SHAPED).sqrt(),
        )
    } else {
        (CLICK_T60_LEGACY, 0.0, p.click)
    }
}

/// Amplitude of harmonic `k` in a one-period buffer (bin `k` of the N-point
/// DFT), normalized so a unit sine at that bin reads ≈ 1.0. For the buffer
/// f0 = sr/N, so k·f0 lands exactly on bin k — no leakage.
fn dft_bin_mag(buf: &[f32], k: usize) -> f32 {
    let n = buf.len();
    if n == 0 {
        return 0.0;
    }
    let step = std::f32::consts::TAU * k as f32 / n as f32;
    let (mut re, mut im) = (0f32, 0f32);
    for (i, &x) in buf.iter().enumerate() {
        let ph = step * i as f32;
        re += x * ph.cos();
        im -= x * ph.sin();
    }
    (re * re + im * im).sqrt() / (n as f32 / 2.0)
}

/// The Shaped excitation (natural-pluck HLD §2). Builds a deterministic harmonic
/// backbone — weight `|sin(kπβ)|/k^s · P(k·f0)` (β = jittered pick position, s =
/// finger↔pick slope, P = the same velocity/wound-scaled pick-LP magnitude, so
/// the velocity→brightness and wound laws survive), physical phases (φ₁=0,
/// φ_{k≥2}=±0.4 rad), amplitude jitter for k≥2 only (h1 deterministic) — then
/// blends it in the ENERGY domain with the existing comb noise and normalizes on
/// the SUSTAIN BAND (h1..h4 RMS-amp = k_sus·v, NOT the peak). Result: a sharp but
/// far less front-loaded attack that cannot re-level the instrument (G7).
#[allow(clippy::too_many_arguments)]
fn shaped_excitation(
    exc_len: usize,
    beta: f32,
    slope: f32,
    noise_mix: f32,
    pick_lp: f32,
    noise: &[f32],
    v: f32,
    exc_trim_db: f32,
    k_sus: f32,
    sr: f32,
    disp: f32,
    rng: &mut Rng,
) -> Vec<f32> {
    let n = exc_len.max(4);
    let f0 = sr / n as f32;
    let n_max = ((0.45 * n as f32) as usize).max(1);
    // deterministic harmonic backbone
    let mut bb = vec![0f32; n];
    for k in 1..=n_max {
        let fk = k as f32 * f0;
        if fk >= 0.45 * sr {
            break;
        }
        let comb = (std::f32::consts::PI * k as f32 * beta).sin().abs();
        let p_mag = 1.0 / (1.0 + (fk / pick_lp).powi(2)).sqrt();
        let mut w = comb / (k as f32).powf(slope) * p_mag;
        // φ₁=0 & h1 deterministic; k≥2 get amplitude + phase jitter
        let mut phi = if k == 1 {
            0.0
        } else {
            w *= 1.0 + 0.25 * rng.white();
            0.4 * rng.white()
        };
        // HLD §2.4 tripwire-C lever: deterministic Schroeder quadratic phase for
        // k>k_c decorrelates the high partials so they no longer sum to one sharp
        // peak — lowers crest/slew while each partial keeps its EXACT DFT-bin
        // amplitude (magnitude-invariant: level/tilt/att-sus/G7 bit-unaffected).
        if k > SHAPED_K_C {
            phi += disp * std::f32::consts::PI * (k * k) as f32 / n_max as f32;
        }
        let step = std::f32::consts::TAU * k as f32 / n as f32;
        for (i, s) in bb.iter_mut().enumerate() {
            *s += w * (step * i as f32 + phi).sin();
        }
    }
    // zero-mean (exact sines are already ≈0; enforce against float drift)
    let mean = bb.iter().sum::<f32>() / n as f32;
    for x in &mut bb {
        *x -= mean;
    }
    // energy-domain blend: each component to unit RMS, then √(1−ρ)·bb + √ρ·noise
    let unit_rms = |buf: &mut [f32]| {
        let r = (buf.iter().map(|&x| x * x).sum::<f32>() / buf.len() as f32)
            .sqrt()
            .max(1e-9);
        for x in buf.iter_mut() {
            *x /= r;
        }
    };
    unit_rms(&mut bb);
    let mut noise_n = noise.to_vec();
    unit_rms(&mut noise_n);
    let (a, b) = ((1.0 - noise_mix).sqrt(), noise_mix.sqrt());
    let mut exc: Vec<f32> = (0..n).map(|i| a * bb[i] + b * noise_n[i]).collect();
    // zero-mean the blend — the noise component carries residual DC (G10). Bin 0
    // only, so h1..h4 (the sustain band) are untouched.
    let mean = exc.iter().sum::<f32>() / n as f32;
    for x in &mut exc {
        *x -= mean;
    }
    // sustain-band amplitude normalization: h1..h4 RMS-amp = k_sus·v (∝ v, so the
    // velocity level law is preserved — §4 "level unchanged"; G7 verifies).
    let h_amp = (1..=4)
        .map(|k| {
            let m = dft_bin_mag(&exc, k);
            0.5 * m * m
        })
        .sum::<f32>()
        .sqrt()
        .max(1e-9);
    let scale = (k_sus * v / h_amp) * 10f32.powf(exc_trim_db / 20.0);
    for x in &mut exc {
        *x *= scale;
    }
    // NO peak guard. LEVEL is a contract — the sustain-band normalization above is
    // exact and nothing downstream may rescale the buffer (HLD amendment 2026.07.20,
    // Fable). A post-normalization rescale is crest-dependent (key/velocity-varying)
    // and PROVABLY makes exc_trim a no-op when it engages — it was the PICK bug.
    // Crest/clipping is an ENVELOPE bounded at the render by G2 (crest) + G5 (slew);
    // if a preset's crest runs high, the lever is deterministic phase dispersion for
    // k>k_c (magnitude-domain-invariant), never a runtime rescale.
    exc
}

impl Pluck {
    pub fn new(p: &PluckPreset, key: u8, vel: u8, sr: f32, seed: u32) -> Self {
        let mut rng = Rng::new(seed);
        // §2.10 vel_sense: a near-velocity-insensitive preset (HARPSICHORD)
        // compresses the key velocity toward the top of the range before the
        // global velocity law. This is how real GM hardware splits one global
        // curve from per-patch sensitivity, and it is the ONLY sanctioned way
        // to give a voice a shallower response — never a level floor, which
        // is not a power law at all (see `dsp::vel_amp`).
        // Both branches must square: `vn * vn` here is exactly what `vel_amp`
        // computes, just on the compressed velocity.
        // One shared definition (`dsp::vel_sense_norm`), so the sampled LA onset in
        // `sampler.rs` can apply the SAME compression this model does instead of a
        // second copy that drifts from it (MM-BUG-KILN-00030).
        let vn = vel_sense_norm(vel as f32 / 127.0, p.vel_sense);
        let v = vn * vn;
        // round-robin variation: no two picks land identically
        let pos = (p.pos * (1.0 + 0.15 * rng.white())).clamp(0.06, 0.45);
        // velocity→timbre law (HLD family A, G3/B1), DECOUPLED from decay
        // (KILN-00048). A harder pick opens the EXCITATION (`pick_lp`, `out_lp`
        // — each applied ONCE, so they set a spectrum), NOT the loop damper
        // corner (applied `f` trips/s, so it sets a decay RATE). The loop corner
        // is therefore anchored at the vel-100 value per preset (`v_anchor`),
        // making decay rate a function of pitch and `t60` alone; the
        // velocity→brightness the damper used to supply is transferred onto the
        // excitation via `t` — the exact factor removed from the loop,
        // normalized to 1.0 at the anchor. At vel 100 `vn == vn_anchor`, so `t`
        // is exactly 1 and every corner is bit-identical to the pre-decouple
        // synth. rng draw order (pos → bright-jitter → t60-jitter) is preserved.
        let vn_anchor = vel_sense_norm(KS_ANCHOR_VN, p.vel_sense);
        let v_timbre = 0.22 + 0.98 * vn; // the old velocity→corner factor
        let v_anchor = 0.22 + 0.98 * vn_anchor; // …evaluated at the anchor velocity
        let t = v_timbre / v_anchor; // velocity-transfer factor, ≡ 1.0 at vel 100
        let bright = (p.bright * v_anchor * (1.0 + 0.08 * rng.white())).min(sr * 0.45);
        let t60_base = p.t60 * (1.0 + 0.10 * rng.white());
        // K4 Stage 1: wound strings are darker — the windings damp both the ring
        // (loop damper) and the pick transient. `wound` is a pure function of
        // preset + key; hoisted here because the single-application transfer
        // below needs it (and the corner/t60 use it later).
        let wound = wound_factor(p.wound_all, p.wound_key_split, key);
        // KILN-00048 SINGLE-APPLICATION transfer (Fable mid-flight correction).
        // The velocity→brightness factor `t` removed from the loop damper must be
        // applied ONCE across the excitation path, not once per filter. Route it
        // onto `pick_lp`; only the share the 300 Hz floor TRUNCATES spills onto
        // `out_lp`. Applying `t` to BOTH (the first cut of this fix) darkened the
        // dual-filter presets — koto/shamisen, where pick_lp AND out_lp are both
        // active and neither floored — by t², over-flattening their windowed
        // velocity law (the census witness). STEEL/NYLON (no out_lp) and the
        // floor-pinned wound basses are unaffected either way; this keeps the
        // corner product = a single `t` for EVERY preset. At vel 100 `t` = 1 and
        // the pick clears the floor, so both corners are bit-identical.
        let pick_base = p.pick_lp * (0.10 + 1.30 * vn) * (1.0 - 0.42 * wound);
        let tg = t.powf(KS_EXC_VEL_TRANSFER);
        let pick_want = pick_base * tg;
        // out_lp carries ONLY the t-share the 300 Hz floor TRUNCATED. The
        // DENOMINATOR is floored at 300 too (Fable review): a pre-decouple clip —
        // the dark wound basses, whose no-transfer pp pick already sits below 300
        // and was VOICED around that — must not be double-counted onto out_lp.
        // Unfloored → delivered = t → out unscaled (single application); fully
        // floored → delivered = 1 → out ×t (the wound-bass behaviour they were
        // voiced against); partial → only the truncated share. `t` = 1 at vel 100
        // makes both ratios 1, so every corner stays bit-identical there.
        let delivered_t = pick_want.max(300.0) / pick_base.max(300.0);
        let out_lp = p.out_lp * (0.30 + 0.95 * vn) * (tg / delivered_t).powf(KS_OUT_VEL_TRANSFER);
        // (The 200 pre-wound floor the old code carried was dead code:
        // 200·(1−0.42w) ≤ 200 < 300, so the 300 post-wound floor always subsumed
        // it.) KILN-00048 item 4 pitch-relative floor: capped at the no-transfer
        // pick so it is vel-100-inert and can only undo the transfer's darkening;
        // its c·f0 truncation is deliberately NOT routed to out_lp (routing it
        // would re-darken the very spectrum this floor exists to protect).
        let pick_lp = pick_want
            .max((KS_PICK_F0_FLOOR * key_freq(key)).min(pick_base))
            .max(300.0);

        // G7 flageolet: the loop itself resonates at the touched harmonic —
        // 2f below E4, 3f from E4 up (natural-harmonic playability); the
        // multiple is persistent state composed into every retune (V4/INT-2)
        let harm = if p.harmonic {
            if key < 64 {
                2.0
            } else {
                3.0
            }
        } else {
            1.0
        };
        let note_f = key_freq(key);
        let f = note_f * harm; // the frequency the LOOP rings at
        let period = sr / f;
        // The high-key damper hold (see `DamperHold`): the corner grows as
        // f^1.5 above the crossover, holding the damper's dB/s share at
        // within KS_DAMP_BUDGET of the authored t60 loss instead of letting it run
        // away as f³ (KILN-00042).
        // `corner_scale` clamps at 1, so every key below the crossover stays
        // bit-identical; the explicit re-clamp is needed HERE because this line
        // historically only ever reduced bright (wound) and so carried no .min —
        // the hold multiplies UP (review I-M1).
        // The crossover is derived from the preset's STATIC corner (post-wound,
        // PRE-velocity). Deriving it from the velocity-scaled corner instead
        // makes the damper loss velocity-INDEPENDENT above the crossover, which
        // silently deletes the velocity→timbre law for high notes — a harder
        // pick would no longer open the damper — and measurably bends six
        // programs off the k=2 square law. Keeping it static preserves both
        // laws: the hold's reach shrinking at low velocity is the documented,
        // canary-pinned behaviour (see the vel-40 canary in the tests).
        let wound_bright = bright * (1.0 - 0.30 * wound);
        let t60 =
            (t60_base * (220.0 / f).powf(p.t60_key_exp)).clamp(0.25, 14.0) * (1.0 - 0.12 * wound);
        // The budget is relative to THIS preset's authored decay, so t60 must be
        // known first. Static (pre-velocity, pre-jitter) for the same reason the
        // corner is: the crossover must not move with velocity.
        let t60_static =
            (p.t60 * (220.0 / f).powf(p.t60_key_exp)).clamp(0.25, 14.0) * (1.0 - 0.12 * wound);
        let hold =
            p.damper_hold
                .corner_scale(f, p.bright * (1.0 - 0.30 * wound), 60.0 / t60_static);
        let bright = (wound_bright * hold).min(sr * 0.45).max(300.0);

        // excitation: filtered noise burst with a pick-position comb.
        // (K2's deterministic triangle IC was BUILT AND REVERTED: the
        // displacement picture (sin(nπp)/n²) buries every pluck under its
        // fundamental, and the bridge-force picture re-levels the whole
        // instrument — both destabilised ten oracles including a v0.7
        // regression. The noise burst already carries the attack character
        // and per-note variation; K2 is deferred pending a listen-driven
        // re-design. The velocity- and wound-scaled pick_lp levers stay.)
        let exc_len = (period as usize).max(4);
        let mut lp = OnePole::lowpass(pick_lp, sr);
        // §2.10: a velocity-flattened preset (vel_sense < 1) draws its burst
        // from a FIXED stream — a harpsichord jack is a machine: the same
        // quill plucks the same point with the same displacement every time,
        // so per-note loudness must not ride round-robin noise luck (the
        // peak-normalized random burst's loop-projected energy varies ±1.5 dB
        // across seeds, swamping the flattened velocity law the GM6 loudness
        // oracle pins). Per-note variation survives in the pos/bright/t60
        // jitters and the sub phase, all still drawn from the note's rng.
        let mut fixed_rng;
        let exc_rng = if p.vel_sense >= 1.0 {
            &mut rng
        } else {
            fixed_rng = Rng::new(0x6A0C_9111);
            &mut fixed_rng
        };
        let raw: Vec<f32> = (0..exc_len).map(|_| lp.process(exc_rng.white())).collect();
        let comb = ((exc_len as f32 * pos) as usize).max(1);
        // The comb-filtered noise burst — the historic excitation, and the noise
        // component of the Shaped blend.
        let noise: Vec<f32> = (0..exc_len)
            .map(|i| raw[i] - 0.9 * raw[(i + comb) % exc_len])
            .collect();
        let mut exc: Vec<f32> = if p.harmonic {
            flageolet_excitation(&noise, v)
        } else {
            match p.exc_model {
                // Legacy: peak-normalize to v (bit-identical to the historic path —
                // no extra rng draws, so every un-migrated preset is unchanged).
                ExcModel::Legacy => {
                    let mut e = noise;
                    let peak = e.iter().fold(0f32, |m, &x| m.max(x.abs())).max(1e-6);
                    for x in &mut e {
                        *x *= v / peak;
                    }
                    e
                }
                // Shaped: the natural-rolloff harmonic build, sustain-band normalized.
                ExcModel::Shaped => shaped_excitation(
                    exc_len,
                    pos,
                    p.slope,
                    p.noise_mix,
                    pick_lp,
                    &noise,
                    v,
                    p.exc_trim,
                    K_SUS,
                    sr,
                    SHAPED_DISP,
                    exc_rng,
                ),
            }
        };
        // Floor the initial burst's fundamental (harp fix; inert at h1_floor = 0). Guards
        // against a weak-h1 Rayleigh draw letting the octave dominate — see `top_up_h1`.
        // Faded out above C4 (the octave-hollow is a low-mid phenomenon), so high notes —
        // already f0-dominant with a damped octave — are untouched.
        let floor_reg = 1.0 - smoothstep(HARP_FLOOR_LO, HARP_FLOOR_HI, f);
        top_up_h1(&mut exc, p.h1_floor * v * floor_reg);
        let mut horiz = KsLoop::new(f, bright, t60, &exc, sr);
        let mut vert = KsLoop::new(
            f * p.course_detune,
            bright * p.course_bright,
            t60 * p.course_t60,
            &exc,
            sr,
        );
        // the two loops are a K3-coupled pair; each must know the coupling to
        // size its e-bow drive against the PAIR's decay (see `sus_headroom`).
        // Set BEFORE arming the driver, which reads the headroom immediately.
        horiz.k_couple = p.course_couple;
        vert.k_couple = p.course_couple;
        if p.sustain > 0.0 {
            horiz.enable_driver(f);
            vert.enable_driver(f * p.course_detune);
        }
        if let Some(spec) = &p.jawari {
            // both polarizations graze the same bridge
            horiz.jaw = Some(Jawari::new(spec, sr));
            vert.jaw = Some(Jawari::new(spec, sr));
        }
        if let Some(spec) = &p.fret_contact {
            // The fretboard is in the vertical plane. A small horizontal share
            // models bridge/fret coupling, but the weighty contact lives on the
            // vertical polarization and then projects through the existing mix.
            horiz.fret = FretContact::new(spec, vn, sr, spec.horiz);
            vert.fret = FretContact::new(spec, vn, sr, spec.vert);
        }

        Pluck {
            horiz,
            vert,
            k_couple: p.course_couple,
            course_detune: p.course_detune,
            course_mix: p.course_mix,
            base_f: note_f,
            bend: 1.0,
            harm,
            pickup: (p.pickup > 0.0).then(|| {
                // the pickup senses the string a fraction of its length from
                // the bridge: a feedforward comb with a 2·pos·period delay
                let d = 2.0 * p.pickup * period;
                (DelayLine::new(d as usize + 8), d)
            }),
            // the coil circuit: a resonant lowpass — peak at the resonance,
            // 12 dB/oct above it (the RLC that makes a pickup sound electric)
            pickup_rlc: (p.pickup_rlc.0 > 0.0)
                .then(|| Biquad::lowpass(p.pickup_rlc.0, p.pickup_rlc.1, sr)),
            sus_target: p.sustain,
            sus_acc: 0.0,
            sus_env: 0.0,
            sus_ref: 0.0,
            sus_out_control: p.sustain > 0.0 && p.damper_hold == DamperHold::Derived,
            sus_out_acc: 0.0,
            sus_out_env: 0.0,
            sus_out_ref: 0.0,
            sus_out_gain: 1.0,
            sus_hold: false,
            sus_ramp: 0.0,
            sus_l: 0.0,
            sus_ref_until: (0.08 * sr) as u32,
            // B5: random start phase — the sub is part of the string, not a
            // laboratory cosine locked to the pick. Its WEIGHT eases off as
            // velocity rises (a hard pluck is proportionally brighter, not
            // just louder — the last piece of the family-A law).
            sub: (p.sub > 0.0).then(|| {
                (
                    Sine::new(f, sr, rng.white() * std::f32::consts::PI),
                    p.sub * v * (1.25 - 0.5 * vn),
                    t60_mul(t60 * 0.8, sr),
                )
            }),
            sub_env: 0.0,
            // The bass "kick": a deep noise thump fired NOW (at note-on),
            // velocity-scaled so a hard pluck kicks harder, ringing down over
            // ~KICK_T60_S. Inert (None) for every kick-less preset, so those
            // renders stay bit-identical.
            kick_thump: (p.kick > 0.0).then(|| {
                let mut b =
                    Burst::new(Biquad::lowpass(KICK_LP_HZ, 0.9, sr), p.kick, KICK_T60_S, sr);
                b.trigger(0.4 + 0.6 * v);
                b
            }),
            sub_shape: p.sub_shape,
            sub_ramp: p.sub_ramp,
            onset_pre: (p.click > 0.0 && !p.click_post).then(|| {
                // Shaped presets de-impulsify the click (Fable 2026.07.20); Legacy
                // keeps the 3 ms decay-from-peak, bit-identical (rise 0, gain p.click).
                let (t60, rise, gain) = click_shape(p);
                let mut b =
                    Burst::new_ramped(Biquad::highpass(p.click_hp, 0.7, sr), gain, t60, rise, sr);
                // super-linear in velocity: a soft fingerpad barely snaps
                b.trigger(v * vn);
                b
            }),
            onset_post: {
                // slap/pop (click_post) and finger/fret noise share the
                // post-out insertion so the out-LP doesn't swallow them
                if p.click > 0.0 && p.click_post {
                    let (t60, rise, gain) = click_shape(p);
                    let mut b = Burst::new_ramped(
                        Biquad::highpass(p.click_hp, 0.7, sr),
                        gain,
                        t60,
                        rise,
                        sr,
                    );
                    b.trigger(v * vn);
                    Some(b)
                } else if p.attack_noise > 0.0 {
                    let mut b = Burst::new(
                        Biquad::bandpass(2000.0, 0.8, sr),
                        // a soft touch barely scrapes the winding — the
                        // extra vn factor keeps whisper notes from being
                        // mostly finger noise
                        (p.attack_noise * (0.45 + 0.55 * v) * (0.3 + 0.7 * vn)).min(v),
                        0.004,
                        sr,
                    );
                    b.trigger(1.0);
                    Some(b)
                } else {
                    None
                }
            },
            // Round-3 U1 bug A: when click_post AND attack_noise are both set
            // (only CLAVINET), the branch above shadowed the scrape — the
            // tangent contact noise was dead code. It gets its own slot so
            // both one-shots fire; every preset without the combination
            // builds None and renders bit-identically.
            scrape: (p.click > 0.0 && p.click_post && p.attack_noise > 0.0).then(|| {
                let mut b = Burst::new(
                    Biquad::bandpass(2000.0, 0.8, sr),
                    (p.attack_noise * (0.45 + 0.55 * v) * (0.3 + 0.7 * vn)).min(v),
                    0.004,
                    sr,
                );
                b.trigger(1.0);
                b
            }),
            stop: (p.stop_thump > 0.0).then(|| {
                Burst::new(
                    Biquad::lowpass(250.0, 0.7, sr),
                    p.stop_thump * (0.5 + 0.5 * v),
                    0.12,
                    sr,
                )
            }),
            mwah: p.mwah.map(|spec| Mwah::new(spec, sr)),
            grit: p.grit,
            buzz: p.buzz,
            buzz_env: 0.0,
            // ~40 ms: slow enough not to track the waveform WITHIN a low-key
            // period (key 48's period is 7.6 ms — an 8 ms follower rode each
            // cycle and kept n under the contact threshold), fast enough to
            // follow the 0.78 s t60 decay with ~3 dB lag.
            buzz_k: 1.0 - (-1.0 / (0.040 * sr)).exp(),
            buzz_hp: Biquad::highpass(3000.0, 0.7, sr),
            membrane: p
                .membrane
                .iter()
                .map(|&(f, q, g)| (Biquad::bandpass(f, q, sr), g))
                .collect(),
            body: p
                .body
                .iter()
                .map(|&(f, q, g)| Biquad::peak(f, q, g, sr))
                .collect(),
            cab: (p.cab_lp > 0.0).then(|| {
                [
                    Biquad::lowpass(p.cab_lp, 0.75, sr),
                    Biquad::lowpass(p.cab_lp, 0.75, sr),
                ]
            }),
            out_lp: if p.out_lp > 0.0 {
                Some(OnePole::lowpass(out_lp, sr))
            } else {
                None
            },
            hammer: Vec::new(),
            hammer_pos: 0,
            rng,
            pick_lp_hz: pick_lp,
            pos,
            spawn_bright_h: bright,
            spawn_bright_v: bright * p.course_bright,
            rel_rec: 10f32.powf(3.0 / (TREM_REL_RECOVER_S * sr)),
            trem_hold: false,
            rel_mul_trem: t60_mul(p.rel_t60 * TREM_RELEASE_STRETCH, sr),
            trem_ok: p.trem,
            trem_sus: false,
            trem_last_strike: 0,
            trem_drop: (TREM_SUS_DROP_S * sr) as u32,
            amp: p.amp,
            att: if p.attack_s <= 0.0 {
                1.0
            } else {
                1.0 / (p.attack_s * sr)
            },
            att_env: 0.0,
            release_env: 1.0,
            rel_mul: t60_mul(p.rel_t60, sr),
            released: false,
            env: 1.0,
            t: 0,
            min_life: (0.05 * sr) as u32,
            sr,
            #[cfg(test)]
            kind: p.name,
        }
    }

    fn apply_pitch(&mut self) {
        // the flageolet multiple composes into EVERY retune (V4/INT-2) — a
        // CC1/RPN/portamento writer must not collapse the loop back to the
        // fundamental
        let f = self.base_f * self.harm * self.bend;
        self.horiz.retune(f);
        self.vert.retune(f * self.course_detune);
        if let Some((osc, _, _)) = &mut self.sub {
            osc.set_freq(f, self.sr);
        }
    }

    /// KILN-00049: close the e-bow's level loop in the domain the listener hears.
    ///
    /// The driver remains bounded by `sus_headroom`. Once its one-way hold latches,
    /// this controller applies a slow, bounded scalar after the pitch-dependent
    /// pickup/body projection. Unlike changing the saturator knee, it can remove
    /// overshoot without waiting for the eight-second string decay, and it follows
    /// bends or later damper changes without a fitted pitch table.
    fn apply_sustainer_output_gain(&mut self, output: f32) -> f32 {
        if self.sus_target <= 0.0 || self.released {
            return output * self.sus_out_gain;
        }
        self.sus_out_acc = self.sus_out_acc.max(output.abs());
        let now = self.t + 1;
        if now.is_multiple_of(CTRL) {
            self.sus_out_env = self.sus_out_env * 0.9 + self.sus_out_acc * 0.1;
            self.sus_out_acc = 0.0;
            let win = (0.06 * self.sr) as u32;
            if now < self.sus_ref_until {
                if now + win >= self.sus_ref_until {
                    self.sus_out_ref = self.sus_out_ref.max(self.sus_out_env);
                }
            } else if self.sus_hold {
                let target = self.sus_target * self.sus_out_ref;
                let target_gain =
                    (target / self.sus_out_env.max(1e-9)).clamp(SUS_OUT_GAIN_MIN, SUS_OUT_GAIN_MAX);
                // 50 ms: slow beside the waveform/body filters, but fast beside
                // the multi-second hold. Interpolate in log amplitude so equal-dB
                // boosts and cuts converge symmetrically without zipper noise.
                let alpha = (CTRL as f32 / (SUS_OUT_GAIN_TAU_S * self.sr)).min(1.0);
                self.sus_out_gain *= (alpha * (target_gain / self.sus_out_gain).ln()).exp();
            }
        }
        output * self.sus_out_gain
    }
}

impl Voice for Pluck {
    fn render(&mut self, out: &mut [f32]) -> bool {
        for o in out.iter_mut() {
            // pending hammer-on energy trickles into both loops
            let inject = if self.hammer_pos < self.hammer.len() {
                let h = self.hammer[self.hammer_pos];
                self.hammer_pos += 1;
                h
            } else {
                0.0
            };
            // TREM run-end watchdog: an ongoing tremolo restrikes every
            // ≤ ~100 ms; once none has arrived for TREM_SUS_DROP_S the run
            // is over — drop the trem-installed hold and let the string
            // decay (a preset e-bow keeps its own latch semantics).
            if self.trem_sus
                && self.t.is_multiple_of(CTRL)
                && self.t.wrapping_sub(self.trem_last_strike) > self.trem_drop
            {
                self.horiz.clear_drive();
                self.vert.clear_drive();
                self.sus_hold = false;
                self.sus_ramp = 0.0;
                self.sus_target = 0.0;
                self.trem_sus = false;
            }
            // G6: while released, the damper glides darker at control rate;
            // the retune uses the COMPOSED frequency so bends/glides on a
            // released voice keep their pitch (V4/INT-3). A tremolo-run
            // voice (trem_hold) skips the glide: at treble keys the loop
            // period is ~1 ms, so the per-round-trip damper compounds
            // ~1000×/s and the glide kills even the FUNDAMENTAL inside a
            // 30 ms inter-stroke gap — measured as the dominant term of the
            // click-train artifact, above the release envelope itself.
            if self.released && !self.trem_hold && self.t.is_multiple_of(CTRL) {
                let f = self.base_f * self.harm * self.bend;
                let bh = self.horiz.bright;
                if bh > REL_FLOOR_H {
                    self.horiz
                        .set_bright(bh + REL_DARKEN_K * (REL_FLOOR_H - bh), f);
                }
                let bv = self.vert.bright;
                if bv > REL_FLOOR_V {
                    self.vert.set_bright(
                        bv + REL_DARKEN_K * (REL_FLOOR_V - bv),
                        f * self.course_detune,
                    );
                }
            }
            // K3: skew-symmetric polarization coupling — energy sloshes
            // between the planes (the slow secondary bloom of a real string),
            // none is created; each loop remains a contraction.
            //
            // Both planes are READ before either is WRITTEN, so each is coupled
            // to the other's value at this instant. Coupling to the PREVIOUS
            // sample instead (the `h_prev`/`v_prev` form this replaced) is not
            // the step matrix [[a, k], [-k, a]] that `coupled_loop_margin_holds`
            // proves bounded: the one-sample lag adds a 2π/D phase error per
            // round trip, and at short delays (D ≲ 25 samples, i.e. above about
            // key 92) that error turned the rotation net-GENERATIVE. A held
            // nylon note at key 96 grew without bound to ~2e6 in 40 s
            // (MM-BUG-KILN-00155). D shrinks with pitch, which is why only the
            // top of the register blew up while the closed-form margin — which
            // models the lag-free matrix — kept reporting a² + k² ≈ 0.99.
            let hc = self.horiz.tick_read();
            let vc = self.vert.tick_read();
            self.horiz.tick_write(hc, inject + self.k_couple * vc);
            self.vert.tick_write(vc, inject * 0.7 - self.k_couple * hc);
            let mut y = self.course_mix.0 * hc + self.course_mix.1 * vc;
            // guitar v2 hold latch (§3.D): watch the RAW string mix — before
            // the onset click (which never enters the loops) and the pickup
            // chain — capture an early reference, and once a held note has
            // decayed to sustain×reference, ramp the e-bow drivers in.
            if self.sus_target > 0.0 {
                self.sus_acc = self.sus_acc.max(y.abs());
                if !self.released && self.t.is_multiple_of(CTRL) {
                    self.sus_env = self.sus_env * 0.9 + self.sus_acc * 0.1;
                    self.sus_acc = 0.0;
                    // the reference is the note's SPOKEN level: 20-80 ms —
                    // late enough to skip the click, early enough that a
                    // fast-crashing high note (E6 is gone by 100 ms) still
                    // registers its real voice
                    // the reference window is the 60 ms ending at
                    // sus_ref_until; a slur RE-ARMS it (review C4), so a soft
                    // slurred note references ITS own spoken level instead of
                    // holding at a previous loud note's
                    let win = (0.06 * self.sr) as u32;
                    if self.t < self.sus_ref_until {
                        if self.t + win >= self.sus_ref_until {
                            self.sus_ref = self.sus_ref.max(self.sus_env);
                        }
                    } else {
                        let target = self.sus_target * self.sus_ref;
                        if !self.sus_hold && self.sus_env <= target {
                            self.sus_hold = true;
                            // the knee places the hold level; frozen at
                            // engage (the beat makes the instantaneous
                            // envelope an unreliable snapshot — target is
                            // the calibrated quantity)
                            self.sus_l = SUS_L_SCALE * target.max(1e-9);
                        }
                        if self.sus_hold {
                            self.sus_ramp =
                                (self.sus_ramp + CTRL as f32 / (SUS_RAMP_S * self.sr)).min(1.0);
                            // with k a constant multiple of the deficit, the
                            // equilibrium sits at the same multiple of the
                            // knee at every pitch
                            self.horiz.set_drive(self.sus_ramp, self.sus_l);
                            self.vert.set_drive(self.sus_ramp, self.sus_l);
                        }
                    }
                }
            }
            if self.grit {
                // palm-mute chug: the palm+pick+amp chain compresses (G4)
                y = (y * 2.0).tanh() * 0.5;
            }
            if self.buzz > 0.0 {
                // Yarn/fret contact buzz (round-3 U1 bug B): while the string
                // swings past the contact threshold — the top of every cycle —
                // the fret/yarn contact brightens the string itself. Gating
                // the signal by that condition and keeping only the highpassed
                // part injects a pitch-locked splatter whose hard gate edges
                // re-pump the highs every period (the sitar-jawari physics).
                // The threshold reads the signal NORMALIZED against a
                // fast-tracked (~8 ms) envelope, so the RELATIVE buzz level
                // survives the whole decay instead of dying at twice the
                // note's rate — the refuted memoryless-grit property (a smooth
                // waveshaper on a dark sustain cannot make real HF: measured,
                // cubic moved the sustain HF fraction only 0.063→0.076, and a
                // 1-sample snap train was energy-starved at −38 dB).
                // Deterministic (no rng draw — every other preset's stream is
                // untouched) and feedforward → BIBO-stable. Pre-pickup: fret
                // contact IS string motion, so it passes the position comb,
                // the coil resonance and the body like the rest of the string.
                self.buzz_env += (y.abs() - self.buzz_env) * self.buzz_k;
                let n = y / (self.buzz_env * 1.6).max(1e-6);
                // 0.45: a near-sine sustain peaks at n ≈ 0.98 minus the
                // follower's decay lag (~30 % on this t60) — 0.45 keeps the
                // contact engaged for the top third of every swing all the
                // way down the decay, which is the whole point of the fix.
                let gated = if n > 0.45 { y } else { 0.0 };
                // ×8 make-up drive: the >3 kHz content of the gate edges is
                // intrinsically ~−32 dB re the string (measured), so the
                // stage brings preset buzz ≈ 0.2 to an audible ~−14 dB
                // relative buzz. One knob (the preset's `buzz`) → EAR list.
                y += self.buzz * 8.0 * self.buzz_hp.process(gated);
            }
            if let Some((dl, d)) = &mut self.pickup {
                dl.push(y);
                y = (y - dl.tap(*d)) * 0.75;
            }
            if let Some(rlc) = &mut self.pickup_rlc {
                // pickup coil resonance, directly after the position comb
                // (string → position/aperture → coil circuit)
                y = rlc.process(y);
            }
            if let Some(b) = &mut self.onset_pre {
                // the pick click knocks the body: summed before the body EQ.
                // §2.13 verified: this burst is BODY/contact noise, NOT string
                // motion — the pick's effect on the string is the `exc` burst
                // injected into the KS loops above, which already passes the
                // pickup comb + coil. A magnetic pickup cannot sense a body
                // knock, so summing it post-pickup is the CORRECT order; do
                // not "fix" it by moving it before the comb.
                y += b.tick(&mut self.rng);
            }
            if !self.membrane.is_empty() {
                // banjo head: the bridge drives the membrane modes — the
                // pick's broadband knock rings them (the thunk) and the
                // string keeps feeding them (the honk). Parallel feedforward
                // resonators: BIBO-stable, decays with its drive.
                let mut m = 0.0;
                for (mode, g) in &mut self.membrane {
                    m += mode.process(y) * *g;
                }
                y += m;
            }
            for b in &mut self.body {
                y = b.process(y);
            }
            if let Some(cab) = &mut self.cab {
                for c in cab.iter_mut() {
                    y = c.process(y);
                }
            }
            let mwah_tap = y;
            if let Some(lp) = &mut self.out_lp {
                y = lp.process(y);
            }
            if let Some(mwah) = &mut self.mwah {
                y += mwah.tick(mwah_tap, self.t, self.sr);
            }
            if let Some((osc, gain, decay)) = &mut self.sub {
                // the fundamental's weight, decaying with the string
                if self.t < self.sub_ramp {
                    self.sub_env = (self.sub_env + 1.0 / self.sub_ramp as f32).min(1.0);
                }
                let s = osc.next();
                // DC-free 2f/3f enrichment (G4 thud / B5): s²−½ = −½cos2x,
                // ¾s−s³ = ¼sin3x — clean even/odd harmonics of a unit sine
                let (a2, a3) = self.sub_shape;
                let shaped = s + a2 * (s * s - 0.5) + a3 * (0.75 * s - s * s * s);
                y += shaped * *gain * self.sub_env;
                self.sub_env *= *decay;
            }
            if self.att_env < 1.0 {
                self.att_env = (self.att_env + self.att).min(1.0);
            }
            if self.released {
                self.release_env *= self.rel_mul;
            } else if self.release_env < 1.0 {
                // TREM: a restrike un-released this voice mid-release-decay;
                // ride the attenuation back up smoothly under the stroke's
                // own attack (this branch is unreachable unless retrigger()
                // ran — released is never cleared anywhere else, so every
                // pre-existing render is bit-identical).
                self.release_env = (self.release_env * self.rel_rec).min(1.0);
            }
            let mut y = y * self.amp * self.att_env * self.release_env;
            if self.sus_out_control {
                y = self.apply_sustainer_output_gain(y);
            }
            if let Some(b) = &mut self.onset_post {
                // slap pop / finger noise, after the out-LP AND outside the
                // attack ramp — the finger contact happens at t=0 even when
                // the string itself speaks slowly (fretless/upright)
                y += b.tick(&mut self.rng) * self.amp;
            }
            if let Some(b) = &mut self.scrape {
                // the tangent scrape coexists with the slap-pop click
                // (round-3 U1 bug A) — same post-out insertion, and it only
                // exists (and draws rng) on presets setting both, so every
                // other preset's stream is untouched
                y += b.tick(&mut self.rng) * self.amp;
            }
            if let Some(b) = &mut self.stop {
                // release thump (armed by note_off): the palm's thud is NOT
                // the string ring, so it does not decay with the release env
                y += b.tick(&mut self.rng) * self.amp;
            }
            if let Some(b) = &mut self.kick_thump {
                // onset "kick": the deep attack thud, in parallel like the stop
                // thump (not string ring, so no release/attack env on it)
                y += b.tick(&mut self.rng) * self.amp;
            }
            self.env = self.env.max(y.abs()) * 0.9995;
            *o += y;
            self.t += 1;
        }
        self.t < self.min_life || self.env > 2e-5
    }

    fn note_off(&mut self) {
        if !self.released && !self.trem_hold {
            if let Some(b) = &mut self.stop {
                // the stop thump fires on the effective release — under
                // CC64/CC66 that is the pedal lift, by design (V4/INT-7)
                b.trigger(1.0);
            }
        }
        if self.trem_hold {
            // TREM: mid-run gate-offs are notation, not damping — the pick
            // hand never stops the string between tremolo strokes. Take the
            // stretched release (and no stop thump 13×/s), and KEEP the
            // tremolo hold driving through the gap; the run-end watchdog in
            // render() drops it TREM_SUS_DROP_S after the last restrike.
            self.rel_mul = self.rel_mul_trem;
            self.released = true;
            return;
        }
        self.released = true;
        // release drops the e-bow instantly: the string decays as ever
        self.horiz.clear_drive();
        self.vert.clear_drive();
    }

    fn released(&self) -> bool {
        self.released
    }

    fn set_pitch(&mut self, mult: f32) {
        self.bend = mult;
        self.apply_pitch();
    }

    fn legato_to(&mut self, key: u8, vel: u8) -> bool {
        // hammer-on / pull-off: retune the ringing string, add a soft tap
        // (the flageolet multiple, if any, is preserved — V4/INT-2)
        self.base_f = key_freq(key);
        self.apply_pitch();
        let v = vel_amp(vel);
        let n = ((self.sr / self.base_f) as usize / 2).max(3);
        let mut lp = OnePole::lowpass((self.pick_lp_hz * 0.5).max(400.0), self.sr);
        self.hammer = (0..n)
            .map(|_| lp.process(self.rng.white()) * v * 0.30)
            .collect();
        self.hammer_pos = 0;
        self.sub_env = self.sub_env.max(0.6 * v);
        self.env = self.env.max(0.3 * v);
        // guitar v2 (review C4): the slurred note is a NEW note to the
        // sustainer — drop the drive, re-arm the reference window, and let
        // the latch re-engage against the slur's own spoken level
        if self.sus_target > 0.0 {
            self.horiz.clear_drive();
            self.vert.clear_drive();
            self.sus_hold = false;
            self.sus_ramp = 0.0;
            self.sus_ref = 0.0;
            if self.sus_out_control {
                self.sus_acc = 0.0;
                self.sus_env = 0.0;
                self.sus_out_acc = 0.0;
                self.sus_out_env = 0.0;
                self.sus_out_ref = 0.0;
                self.sus_out_gain = 1.0;
            }
            self.sus_ref_until = self.t + (0.06 * self.sr) as u32;
        }
        true
    }

    fn retrigger(&mut self, key: u8, vel: u8) -> bool {
        // TREM: a tremolo stroke re-PICKS the still-ringing string. Same
        // pick law as a fresh pluck (pick_lp burst + position comb + contact
        // click) — the ONE difference from a fresh spawn is that the string
        // state carries over: no restart from silence, no second voice
        // decaying underneath, no phase discontinuity. That continuity is
        // what turns 13 strokes/s from a click train into a shimmer.
        if !self.trem_ok {
            return false; // mechanically damped presets: repeats articulate
        }
        self.base_f = key_freq(key);
        self.apply_pitch();
        let v = vel_amp(vel);
        let vn = vel as f32 / 127.0;
        let f = self.base_f * self.harm * self.bend;
        // the release G6 glide darkened the dampers between strokes —
        // restore the spawn stroke's velocity-law cutoffs (fresh per-stroke
        // jitter: no two strokes land identically)
        let bh = (self.spawn_bright_h * (1.0 + 0.08 * self.rng.white())).min(self.sr * 0.45);
        let bv = (self.spawn_bright_v * (1.0 + 0.08 * self.rng.white())).min(self.sr * 0.45);
        self.horiz.set_bright(bh, f);
        self.vert.set_bright(bv, f * self.course_detune);
        // a fresh pick burst, trickled INTO the ringing loops (hammer path)
        let n = ((self.sr / f) as usize).max(4);
        let mut lp = OnePole::lowpass(self.pick_lp_hz, self.sr);
        let raw: Vec<f32> = (0..n).map(|_| lp.process(self.rng.white())).collect();
        let comb = ((n as f32 * self.pos) as usize).max(1);
        let mut exc: Vec<f32> = (0..n).map(|i| raw[i] - 0.9 * raw[(i + comb) % n]).collect();
        let peak = exc.iter().fold(0f32, |m, &x| m.max(x.abs())).max(1e-6);
        let g = v * TREM_RESTRIKE_LEVEL / peak;
        for x in &mut exc {
            *x *= g;
        }
        // guarantee the stroke deposits FUNDAMENTAL (see TREM_H1_FLOOR / top_up_h1)
        top_up_h1(&mut exc, TREM_H1_FLOOR * v * TREM_RESTRIKE_LEVEL);
        // the pick-catch: grab the standing wave so this stroke's
        // displacement owns the string (and the carrier phase)
        self.horiz.catch_damp(TREM_CATCH);
        self.vert.catch_damp(TREM_CATCH);
        self.hammer = exc;
        self.hammer_pos = 0;
        // the plectrum clicks on every stroke (same law as the spawn pick)
        if let Some(b) = &mut self.onset_pre {
            b.trigger(v * vn);
        }
        self.sub_env = self.sub_env.max(0.6 * v);
        self.env = self.env.max(0.3 * v);
        if !self.trem_hold {
            // FIRST restrike: this voice becomes a tremolo run. Install the
            // carrier hold (see TREM_SUS_FRACTION) if the preset has no
            // sustainer of its own, and arm the reference window so the
            // hold level is THIS run's spoken level. Later restrikes must
            // NOT reset any of this — the hold persists across the run.
            if self.sus_target <= 0.0 {
                self.sus_target = TREM_SUS_FRACTION;
                self.trem_sus = true;
                self.horiz.enable_driver(f);
                self.vert.enable_driver(f * self.course_detune);
            } else {
                // a preset e-bow (DRIVE): the restrike is a NEW note to it,
                // exactly as a slur is
                self.horiz.clear_drive();
                self.vert.clear_drive();
            }
            self.sus_hold = false;
            self.sus_ramp = 0.0;
            self.sus_ref = 0.0;
            if self.sus_out_control {
                self.sus_acc = 0.0;
                self.sus_env = 0.0;
                self.sus_out_acc = 0.0;
                self.sus_out_env = 0.0;
                self.sus_out_ref = 0.0;
                self.sus_out_gain = 1.0;
            }
            self.sus_ref_until = self.t + (0.06 * self.sr) as u32;
        }
        self.trem_last_strike = self.t;
        // un-release: the stroke owns the string again; render() ramps the
        // release attenuation back up under the stroke's attack. From here
        // on this voice is a tremolo run: gate-offs damp softly.
        self.released = false;
        self.trem_hold = true;
        true
    }

    #[cfg(test)]
    fn kind(&self) -> &'static str {
        self.kind
    }
}

// ---------------------------------------------------------------------------
// SynthBass (HLD family F, B4) — GM 38/39 are synth basses, not plucked
// strings: saw(s) + sub sine through an envelope-swept resonant lowpass.
// ---------------------------------------------------------------------------

pub struct SynthBass {
    saws: Vec<(BlepSaw, f32)>, // (osc, detune ratio)
    sub: Sine,
    base_f: f32,
    bend: f32,
    amp_env: Adsr,
    filt_env: Adsr,
    filt: Biquad,
    depth: f32, // filter-env sweep depth in Hz
    q: f32,
    t: u32,
    amp: f32,
    sr: f32,
}

impl SynthBass {
    /// program 38 = one saw; 39 = two saws detuned ±8 cents.
    pub fn new(program: u8, key: u8, vel: u8, sr: f32, seed: u32) -> Self {
        let f = key_freq(key);
        let mut rng = Rng::new(seed);
        let vn = vel as f32 / 127.0;
        let detunes: &[f32] = if program == 39 {
            &[0.99538, 1.00463] // ±8 cents
        } else {
            &[1.0]
        };
        let saws = detunes
            .iter()
            .map(|&r| (BlepSaw::new(f * r, sr, rng.white() * 0.5 + 0.5), r))
            .collect();
        SynthBass {
            saws,
            sub: Sine::new(f, sr, rng.white() * std::f32::consts::PI),
            base_f: f,
            bend: 1.0,
            amp_env: Adsr::new(0.004, 0.18, 0.75, 0.08, sr),
            filt_env: Adsr::new(0.003, 0.28, 0.25, 0.10, sr),
            filt: Biquad::lowpass(300.0, 4.0, sr),
            depth: 900.0 + 2600.0 * vn, // velocity opens the sweep
            q: 4.0,
            t: 0,
            amp: 0.44 * vel_amp(vel),
            sr,
        }
    }
}

impl Voice for SynthBass {
    fn render(&mut self, out: &mut [f32]) -> bool {
        for o in out.iter_mut() {
            if self.t.is_multiple_of(CTRL) {
                // envelope-swept resonant filter, state-preserving retune
                let fenv = self.filt_env.next();
                let cut = (300.0 + fenv * self.depth).clamp(80.0, self.sr * 0.4);
                self.filt.retune_lowpass(cut, self.q, self.sr);
            } else {
                self.filt_env.next();
            }
            let mut s = 0.0;
            for (osc, _) in &mut self.saws {
                s += osc.next();
            }
            s /= self.saws.len() as f32;
            s += 0.35 * self.sub.next();
            let y = self.filt.process(s) * self.amp * self.amp_env.next();
            *o += y;
            self.t += 1;
        }
        self.amp_env.alive()
    }

    fn note_off(&mut self) {
        self.amp_env.release();
        self.filt_env.release();
    }

    fn released(&self) -> bool {
        self.amp_env.released()
    }

    fn set_pitch(&mut self, mult: f32) {
        // v0.6/v0.7 bend/vibrato/portamento support (V4/INT-5): the engine
        // writes per block; BlepSaw/Sine retunes are click-free
        self.bend = mult;
        let f = self.base_f * mult;
        for (osc, r) in &mut self.saws {
            osc.set_freq(f * *r, self.sr);
        }
        self.sub.set_freq(f, self.sr);
    }

    // legato_to: default false — a synth bass retriggers (stated, not
    // accidental; V4/B4).

    #[cfg(test)]
    fn kind(&self) -> &'static str {
        "synthbass"
    }
}

// ---------------------------------------------------------------------------
// Organ
// ---------------------------------------------------------------------------

struct Pipe {
    osc: Sine,
    ratio: f32,
    amp: f32,
    active: bool,
}

pub struct Organ {
    harms: Vec<Pipe>,
    env: Adsr,
    trem: Sine,
    trem_depth: f32,
    chiff_amp: f32,
    chiff_decay: f32,
    chiff_filt: Biquad,
    click_amp: f32,
    click_decay: f32,
    click_filt: Biquad,
    // Percussion tab (GM 17 only): a pitched harmonic tap struck at key-on that
    // decays away over the sustained drawbar — the Hammond "Percussion" voice.
    // Inert (`perc_amp == 0.0`) for every other organ program, whose render is
    // then bit-identical (the block is skipped and `perc_osc` never ticks).
    perc_osc: Sine,
    perc_amp: f32,
    perc_decay: f32,
    reed_noise_amp: f32,
    reed_noise_filt: Biquad,
    rng: Rng,
    drive: f32,
    amp: f32,
    base_f: f32,
    bend: f32,
    sr: f32,
}

impl Organ {
    #[allow(clippy::too_many_arguments)]
    fn new(
        key: u8,
        vel: u8,
        sr: f32,
        seed: u32,
        stops: &[(f32, f32)],
        env: Adsr,
        trem_hz: f32,
        trem_depth: f32,
        chiff: f32,
        click: f32,
        drive: f32,
        amp: f32,
    ) -> Self {
        let f = key_freq(key);
        let mut rng = Rng::new(seed);
        let harms = stops
            .iter()
            .filter(|&&(m, _)| f * m < sr * 0.45)
            .map(|&(m, a)| {
                // every pipe speaks at its own level
                let a = a * (1.0 + 0.08 * rng.white());
                Pipe {
                    osc: Sine::new(f * m, sr, rng.white() * std::f32::consts::PI),
                    ratio: m,
                    amp: a,
                    active: true,
                }
            })
            .collect();
        Organ {
            harms,
            env,
            trem: Sine::new(trem_hz, sr, 0.0),
            trem_depth,
            chiff_amp: chiff * vel_amp(vel),
            chiff_decay: t60_mul(0.03, sr),
            chiff_filt: Biquad::bandpass((f * 2.0).min(sr * 0.4), 2.0, sr),
            click_amp: click * vel_amp(vel),
            click_decay: t60_mul(0.004, sr),
            click_filt: Biquad::highpass(2000.0, 0.7, sr),
            perc_osc: Sine::new(f, sr, 0.0),
            perc_amp: 0.0,
            perc_decay: 0.0,
            reed_noise_amp: 0.0,
            reed_noise_filt: Biquad::bandpass((f * 3.0).clamp(240.0, sr * 0.4), 0.8, sr),
            rng,
            drive,
            amp: amp * vel_amp(vel),
            base_f: f,
            bend: 1.0,
            sr,
        }
    }

    fn with_reed_noise(mut self, amp: f32, center_hz: f32, q: f32) -> Self {
        self.reed_noise_amp = amp;
        self.reed_noise_filt = Biquad::bandpass(center_hz.clamp(180.0, self.sr * 0.4), q, self.sr);
        self
    }

    /// The Hammond Percussion tab (GM 17): a pitched harmonic tap at `ratio`×f0,
    /// level `amp` relative to the drawbar fundamental, decaying over `t60`. It
    /// rides the master amp/env like the drawbars, so it is velocity-scaled and
    /// released with the note, but its own exponential decay makes it a one-shot
    /// tap over the held sustain — the "ping" that separates 17 from 16.
    fn with_percussion(mut self, ratio: f32, amp: f32, t60: f32) -> Self {
        let f = (self.base_f * ratio).min(self.sr * 0.45);
        self.perc_osc = Sine::new(f, self.sr, 0.0);
        self.perc_amp = amp;
        self.perc_decay = t60_mul(t60, self.sr);
        self
    }

    // (The PitchScoop machinery that lived here served only the old organ-22
    // harmonica arm; GM 22 is a Reed free-reed voice now — §2.11 — and the
    // Reed owns its scoop natively.)

    fn apply_pitch(&mut self) {
        let pitch = self.bend;
        for pipe in &mut self.harms {
            let f = self.base_f * pipe.ratio * pitch;
            pipe.active = f < self.sr * 0.45;
            if pipe.active {
                pipe.osc.set_freq(f, self.sr);
            }
        }
    }
}

impl Voice for Organ {
    fn render(&mut self, out: &mut [f32]) -> bool {
        for o in out.iter_mut() {
            let mut s = 0.0;
            for pipe in &mut self.harms {
                if pipe.active {
                    s += pipe.amp * pipe.osc.next();
                }
            }
            if self.reed_noise_amp > 1e-6 {
                s += self.reed_noise_filt.process(self.rng.white()) * self.reed_noise_amp;
            }
            if self.chiff_amp > 1e-5 {
                s += self.chiff_filt.process(self.rng.white()) * self.chiff_amp;
                self.chiff_amp *= self.chiff_decay;
            }
            if self.click_amp > 1e-5 {
                s += self.click_filt.process(self.rng.white()) * self.click_amp;
                self.click_amp *= self.click_decay;
            }
            if self.perc_amp > 1e-5 {
                s += self.perc_amp * self.perc_osc.next();
                self.perc_amp *= self.perc_decay;
            }
            if self.drive > 0.0 {
                s = (s * self.drive).tanh() / self.drive;
            }
            let trem = 1.0 + self.trem_depth * self.trem.next();
            *o += s * self.amp * trem * self.env.next();
        }
        self.env.alive()
    }

    fn note_off(&mut self) {
        self.env.release();
    }

    fn released(&self) -> bool {
        self.env.released()
    }

    fn set_pitch(&mut self, mult: f32) {
        self.bend = mult;
        self.apply_pitch();
    }

    fn set_trem(&mut self, rate_hz: f32, depth: f32) {
        // phase-continuous retune; the engine calls this once per block with
        // an inertia-slewed rate, so there is no zipper and no click
        self.trem.set_freq(rate_hz, self.sr);
        self.trem_depth = depth;
    }

    #[cfg(test)]
    fn kind(&self) -> &'static str {
        "organ"
    }
}

struct AccordionReed {
    source: ReedPulse,
    ratio: f32,
    amp: f32,
    drift: Drift,
    wander_ratio: f32,
    wander_amp: f32,
    age: u64,
}

impl AccordionReed {
    fn new(base_f: f32, ratio: f32, amp: f32, width: f32, sr: f32, seed: u32) -> Self {
        let mut rng = Rng::new(seed);
        Self {
            source: ReedPulse::new(
                base_f * ratio,
                sr,
                rng.next_u32() as f32 / u32::MAX as f32,
                width * (1.0 + 0.02 * rng.white()),
            ),
            ratio,
            amp: amp * (1.0 + 0.04 * rng.white()),
            drift: Drift::new(seed ^ 0xA21C_C0ED, 1.4, 360),
            wander_ratio: 1.0,
            wander_amp: 1.0,
            age: 0,
        }
    }

    fn retune(&mut self, base_f: f32, bend: f32, sr: f32) {
        self.source
            .set_freq(base_f * self.ratio * bend * self.wander_ratio, sr);
    }

    #[inline]
    fn next(&mut self, base_f: f32, bend: f32, sr: f32) -> f32 {
        self.age = self.age.saturating_add(1);
        if self.age % 64 == 1 {
            let w = self.drift.next().clamp(-12.0, 12.0);
            self.wander_ratio = 2f32.powf(w / 1200.0);
            self.wander_amp = 10f32.powf(0.12 * w / 20.0);
            self.retune(base_f, bend, sr);
        }
        self.source.next() * self.amp * self.wander_amp
    }
}

struct AccordionAttackMode {
    osc: Sine,
    amp: f32,
}

/// GM21 accordion: modeled French musette free reeds through a compact body
/// filter. This replaces the old H1-H4 sine stack while preserving the three-reed
/// +/-16 cent registration that the musette oracles already pin.
struct MusetteAccordion {
    reeds: [AccordionReed; 3],
    env: Adsr,
    trem: Sine,
    trem_depth: f32,
    body: [Biquad; 5],
    source_lp: Biquad,
    body_hp: Biquad,
    body_lp: Biquad,
    air: Biquad,
    air_amp: f32,
    attack_noise: Biquad,
    attack_modes: [AccordionAttackMode; 4],
    attack_gain: f32,
    attack_decay: f32,
    age: u64,
    rng: Rng,
    amp: f32,
    base_f: f32,
    bend: f32,
    sr: f32,
}

impl MusetteAccordion {
    fn new(key: u8, vel: u8, sr: f32, seed: u32) -> Self {
        let (trem_hz, trem_depth) = organ_trem_base(21);
        let base_f = key_freq(key);
        let reeds = [
            AccordionReed::new(base_f, 1.0, 0.82, 0.34, sr, seed ^ 0x2100_0001),
            AccordionReed::new(
                base_f,
                cent_ratio(-16.0),
                0.52,
                0.32,
                sr,
                seed ^ 0x2100_0002,
            ),
            AccordionReed::new(base_f, cent_ratio(16.0), 0.52, 0.36, sr, seed ^ 0x2100_0003),
        ];
        let body_specs: [(f32, f32, f32); 5] = [
            (520.0, 0.75, 2.5),
            (980.0, 0.85, 5.0),
            (1450.0, 0.75, -2.5),
            (2350.0, 0.95, 4.0),
            (3550.0, 0.80, 2.0),
        ];
        let body = std::array::from_fn(|i| {
            let (freq, q, gain_db) = body_specs[i];
            Biquad::peak(freq.min(sr * 0.42), q, gain_db, sr)
        });
        let high_register = ((key as f32 - 60.0) / 36.0).clamp(0.0, 1.0);
        let low_register = ((60.0 - key as f32) / 36.0).clamp(0.0, 1.0);
        let body_lp =
            (7600.0 + 700.0 * low_register - 2200.0 * high_register).clamp(5200.0, 8300.0);
        let mode_ratios = [14.2, 18.5, 23.7, 29.4];
        let mode_amps = [0.30, 0.24, 0.18, 0.13];
        let mut rng = Rng::new(seed ^ 0xACCD_0021);
        let attack_modes = std::array::from_fn(|i| {
            let f = base_f * mode_ratios[i];
            AccordionAttackMode {
                osc: Sine::new(f.min(sr * 0.45), sr, rng.white() * TAU),
                amp: if f < sr * 0.45 { mode_amps[i] } else { 0.0 },
            }
        });
        Self {
            reeds,
            env: Adsr::new(0.035, 0.08, 0.98, 0.18, sr),
            trem: Sine::new(trem_hz, sr, 0.0),
            trem_depth,
            body,
            source_lp: Biquad::lowpass(350.0, 0.72, sr),
            body_hp: Biquad::highpass(70.0, 0.7, sr),
            body_lp: Biquad::lowpass(body_lp.min(sr * 0.42), 0.75, sr),
            air: Biquad::bandpass((base_f * 5.2).clamp(900.0, 3400.0), 0.65, sr),
            air_amp: 0.012 * (0.45 + 0.55 * vel_ctrl(vel)),
            attack_noise: Biquad::bandpass((base_f * 18.0).clamp(3200.0, 7200.0), 0.75, sr),
            attack_modes,
            attack_gain: 0.55 * (0.35 + 0.65 * vel_ctrl(vel)),
            attack_decay: t60_mul(0.110, sr),
            age: 0,
            rng,
            amp: 0.20 * vel_amp(vel),
            base_f,
            bend: 1.0,
            sr,
        }
    }
}

impl Voice for MusetteAccordion {
    fn render(&mut self, out: &mut [f32]) -> bool {
        for o in out.iter_mut() {
            let t = self.age as f32 / self.sr;
            self.age = self.age.saturating_add(1);
            let mut s = self
                .reeds
                .iter_mut()
                .map(|reed| reed.next(self.base_f, self.bend, self.sr))
                .sum::<f32>();
            s += self.air.process(self.rng.white()) * self.air_amp;
            if self.age % 64 == 1 {
                let open = (t / 0.075).clamp(0.0, 1.0);
                let cutoff = 350.0 + (7600.0 - 350.0) * open * open;
                self.source_lp
                    .retune_lowpass(cutoff.min(self.sr * 0.42), 0.72, self.sr);
            }
            s = self.source_lp.process(s);
            if self.attack_gain > 1e-5 {
                let mut attack = self.attack_noise.process(self.rng.white()) * 0.10;
                for mode in &mut self.attack_modes {
                    attack += mode.osc.next() * mode.amp;
                }
                let attack_ramp = (t / 0.040).clamp(0.0, 1.0).powi(2);
                s += attack * self.attack_gain * attack_ramp;
                self.attack_gain *= self.attack_decay;
            }
            for b in &mut self.body {
                s = b.process(s);
            }
            s = self.body_hp.process(self.body_lp.process(s));
            let trem = 1.0 + self.trem_depth * self.trem.next();
            *o += s * self.amp * trem * self.env.next();
        }
        self.env.alive()
    }

    fn note_off(&mut self) {
        self.env.release();
    }

    fn released(&self) -> bool {
        self.env.released()
    }

    fn set_pitch(&mut self, mult: f32) {
        self.bend = mult.max(0.0001);
        for reed in &mut self.reeds {
            reed.retune(self.base_f, self.bend, self.sr);
        }
    }

    fn set_trem(&mut self, rate_hz: f32, depth: f32) {
        self.trem.set_freq(rate_hz, self.sr);
        self.trem_depth = depth;
    }

    #[cfg(test)]
    fn kind(&self) -> &'static str {
        "accordion"
    }
}

// ---------------------------------------------------------------------------
// GM 19 cathedral organ
// ---------------------------------------------------------------------------

const ORGAN_TABLE_LEN: usize = 1024;
const ORGAN_MAX_SOURCE_HARMONICS: usize = 24;
const ORGAN_MIN_FUNDAMENTAL_HZ: f32 = 12.0;
const ORGAN_MAX_SR_FRACTION: f32 = 0.45;
const ORGAN_FIXED_SEED: u32 = 0xC471_EDA1;
// Reed rasp on the swell (CC11): a chorus reed driven hard *snarls*. When drive
// (from CC11) rises, the reed pipes crossfade from their `steady` table toward a
// harder `driven` table (spectral peak off the fundamental, brighter tail,
// extended to 48 harmonics to fill the 2–8 kHz snarl band that the 24-harmonic
// cap leaves empty for mid keys) and lift in level. Alias-free by construction —
// a band-limited table, never a time-domain nonlinearity. See the reed-rasp HLD.
const ORGAN_MAX_DRIVEN_HARMONICS: usize = 48;
const REED_LIFT_DB: f32 = 8.0; // reed prominence at full drive (reeds-forward)

/// Driven (hard-blown) chorus-reed spectrum, in dB relative to H1. Same
/// key-anchored shape as `organ_harmonic_db` but the peak sits on H2–H4 and the
/// tail falls ~−4 dB/oct (vs −6), which is the perceptual signature of a reed
/// beating fully against its shallot. Register shaping stays in the key anchors
/// only (no fixed-Hz formant), so the table remains a pure function of
/// (family, key, count) and the pitch/pressure path-independence test holds.
fn organ_driven_harmonic_db(key: u8, harmonic: usize) -> f32 {
    if harmonic <= 1 {
        return 0.0;
    }
    let h2 = organ_anchor([3.0, 2.0, 1.0], key);
    let h3 = organ_anchor([2.0, 1.0, 0.0], key);
    let h6 = organ_anchor([-2.0, -3.0, -4.0], key);
    let h = harmonic as f32;
    if harmonic == 2 {
        h2
    } else if harmonic == 3 {
        h3
    } else {
        (h3 + (h6 - h3) * (h / 3.0).log2()).max(-72.0)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum RankFamily {
    OpenWood,
    Principal,
    ChorusReed,
    Mixture,
}

#[derive(Clone, Copy)]
struct RankSpec {
    id: u8,
    ratio: f32,
    family: RankFamily,
    gain: f32,
    sensitivity: f32,
}

fn organ_anchor(values: [f32; 3], key: u8) -> f32 {
    let k = key as f32;
    if k <= 36.0 {
        values[0]
    } else if k < 60.0 {
        values[0] + (values[1] - values[0]) * ((k - 36.0) / 24.0)
    } else if k < 84.0 {
        values[1] + (values[2] - values[1]) * ((k - 60.0) / 24.0)
    } else {
        values[2]
    }
}

fn organ_speech_ms(family: RankFamily, key: u8) -> f32 {
    let (c2, c6) = match family {
        RankFamily::OpenWood => (180.0, 90.0),
        RankFamily::Principal => (90.0, 35.0),
        RankFamily::ChorusReed => (130.0, 60.0),
        RankFamily::Mixture => (55.0, 20.0),
    };
    let t = ((key as f32 - 36.0) / 48.0).clamp(0.0, 1.0);
    c2 + (c6 - c2) * t
}

fn organ_harmonic_db(family: RankFamily, key: u8, harmonic: usize) -> f32 {
    if harmonic <= 1 {
        return 0.0;
    }
    let (h2, h3, h6) = match family {
        RankFamily::OpenWood => (
            organ_anchor([-28.0, -25.0, -22.0], key),
            organ_anchor([-9.0, -8.0, -7.0], key),
            organ_anchor([-40.0, -36.0, -32.0], key),
        ),
        RankFamily::Principal => (
            organ_anchor([-6.0, -5.0, -4.0], key),
            organ_anchor([-11.0, -9.0, -8.0], key),
            organ_anchor([-24.0, -18.0, -15.0], key),
        ),
        RankFamily::ChorusReed => (
            organ_anchor([-2.0, -3.0, -4.0], key),
            organ_anchor([-4.0, -5.0, -6.0], key),
            organ_anchor([-10.0, -11.0, -12.0], key),
        ),
        RankFamily::Mixture => (
            organ_anchor([-7.0, -6.0, -5.0], key),
            organ_anchor([-12.0, -10.0, -9.0], key),
            organ_anchor([-24.0, -20.0, -18.0], key),
        ),
    };
    let h = harmonic as f32;
    if harmonic == 2 {
        h2
    } else if harmonic == 3 {
        h3
    } else {
        // Continue the H3->H6 log-frequency slope above H6. This gives every
        // generated integer harmonic one deterministic value while retaining
        // the signed H1/H2/H3/H6 spectral contract.
        (h3 + (h6 - h3) * (h / 3.0).log2()).max(-72.0)
    }
}

fn organ_speech_tilt_db(family: RankFamily, harmonic: usize) -> f32 {
    match family {
        RankFamily::OpenWood if harmonic >= 3 => -6.0,
        RankFamily::Principal if harmonic >= 3 => 3.0,
        RankFamily::ChorusReed if harmonic >= 2 => 2.0,
        RankFamily::Mixture if harmonic >= 2 => 2.0,
        _ => 0.0,
    }
}

fn cathedral_mixture_ratios(key: u8) -> [f32; 4] {
    match key {
        0..=47 => [6.0, 8.0, 12.0, 16.0],
        48..=59 => [4.0, 6.0, 8.0, 12.0],
        60..=71 => [3.0, 4.0, 6.0, 8.0],
        72..=83 => [2.0, 3.0, 4.0, 6.0],
        _ => [1.5, 2.0, 3.0, 4.0],
    }
}

fn cathedral_registration(key: u8) -> Vec<RankSpec> {
    let mut ranks = Vec::with_capacity(14);
    let mut add = |id, ratio, family, gain, sensitivity| {
        ranks.push(RankSpec {
            id,
            ratio,
            family,
            gain,
            sensitivity,
        });
    };
    add(0, 0.5, RankFamily::Principal, 0.28, 1.0);
    add(1, 1.0, RankFamily::Principal, 0.72, 1.0);
    add(2, 2.0, RankFamily::Principal, 0.34, 1.0);
    add(3, 3.0, RankFamily::Principal, 0.18, 1.0);
    add(4, 4.0, RankFamily::Principal, 0.22, 1.0);
    let mixture = cathedral_mixture_ratios(key);
    let previous = matches!(key, 48 | 60 | 72 | 84).then(|| cathedral_mixture_ratios(key - 1));
    let crossfade_gain = 0.05 * std::f32::consts::FRAC_1_SQRT_2;
    for (i, ratio) in mixture.into_iter().enumerate() {
        let gain = if let Some(old) = previous {
            if old.contains(&ratio) {
                0.05
            } else {
                crossfade_gain
            }
        } else {
            0.05
        };
        add(5 + i as u8, ratio, RankFamily::Mixture, gain, 0.35);
    }
    if let Some(old) = previous {
        if let Some(ratio) = old.into_iter().find(|ratio| !mixture.contains(ratio)) {
            // One old-only rank overlaps the new break for this semitone. ID 14
            // is reserved for that transition pipe so physical identity remains
            // unambiguous without lifting the fourteen-pipe runtime ceiling.
            add(14, ratio, RankFamily::Mixture, crossfade_gain, 0.35);
        }
    }
    add(9, 1.0, RankFamily::ChorusReed, 0.18, 1.2);

    let pedal = ((50.0 - key as f32) / 4.0).clamp(0.0, 1.0);
    if pedal > 0.0 {
        add(10, 0.25, RankFamily::OpenWood, 0.32 * pedal, 0.25);
        add(11, 0.5, RankFamily::Principal, 0.26 * pedal, 0.25);
        add(12, 1.0, RankFamily::Principal, 0.18 * pedal, 0.25);
        // At the first mixture overlap only, omit the quietest doubled pedal
        // colour to leave room for the transition pipe under the 14-rank cap.
        if key != 48 {
            add(13, 0.5, RankFamily::ChorusReed, 0.16 * pedal, 0.25);
        }
    }
    ranks
}

struct RankPipe {
    #[cfg(test)]
    id: u8,
    key: u8,
    ratio: f32,
    family: RankFamily,
    gain: f32,
    sensitivity: f32,
    static_tune: f32,
    #[cfg(test)]
    identity_bits: (u32, u32),
    sr: f32,
    phase: f32,
    phase_inc: f32,
    frequency: f32,
    harmonics: usize,
    active: bool,
    speech: Box<[f32; ORGAN_TABLE_LEN]>,
    steady: Box<[f32; ORGAN_TABLE_LEN]>,
    age: u64,
    attack_samples: f32,
    transition_samples: f32,
    amp_mod: f32,
    // Per-pipe wind-wander: an independent slow random walk (local wind-pressure
    // deviation) that drifts pitch and amplitude together, so this pipe beats
    // against its neighbours on a continuously moving rate rather than the fixed
    // `static_tune` offset. This — not a coherent tremulant — is what makes the
    // additive stack breathe like many real pipes instead of one frozen,
    // "harpsichord-like" oscillator. Ticks at control rate off `age`; never
    // touches `frequency`/`harmonics`, so no table regen and the pinned
    // frequency/bounds tests are unaffected.
    drift: Drift,
    wander_ratio: f32,
    wander_amp: f32,
    // Reed rasp (ChorusReed pipes only). `driven` is the hard-blown table
    // crossfaded in by `blend` (0..1, the CC11-derived drive); `driven_harmonics`
    // caches its count so it regenerates only when the count changes; `drive_gain`
    // is the reed lift. `None`/0.0/1.0 for non-reed pipes and at drive 0 — which
    // is the byte-identical `else` path in `next()`.
    driven: Option<Box<[f32; ORGAN_TABLE_LEN]>>,
    driven_harmonics: usize,
    blend: f32,
    drive_gain: f32,
}

impl RankPipe {
    fn new(spec: RankSpec, key: u8, sr: f32, event_seed: u32) -> Self {
        let stable_seed = ORGAN_FIXED_SEED
            ^ (spec.id as u32).wrapping_mul(0x9E37_79B9)
            ^ (key as u32).wrapping_mul(0x85EB_CA6B);
        let mut stable = Rng::new(stable_seed);
        let tune_cents = stable.white() * 1.5;
        let level = 1.0 + stable.white() * 0.04;
        let attack_var = 1.0 + stable.white() * 0.08;
        // Wander seed + hold jitter are drawn from `stable` AFTER the identity
        // draws above, so (a) they are stable per (rank id, key) and independent
        // of `event_seed` — `pipe_identity_ignores_event_seed` and byte-identical
        // rebuilds both hold — and (b) `tune_cents`/`level`/`attack_var` are
        // untouched. Base hold ~0.45 s at the 64-sample control rate (≈310
        // ticks), jittered ±25% per pipe so the 14 pipes never retarget in
        // lock-step. Depth scales with `sensitivity` (pedals stay stately).
        let wander_seed = stable.next_u32();
        let hold_jitter = stable.white();
        let hold_ticks = (310.0 * (1.0 + 0.25 * hold_jitter)).round().max(1.0) as u32;
        let mut event = Rng::new(event_seed ^ (spec.id as u32).wrapping_mul(0x27D4_EB2D));
        let speech_ms = organ_speech_ms(spec.family, key) * attack_var;
        let mut pipe = Self {
            #[cfg(test)]
            id: spec.id,
            key,
            ratio: spec.ratio,
            family: spec.family,
            gain: spec.gain * level,
            sensitivity: spec.sensitivity,
            static_tune: 2f32.powf(tune_cents / 1200.0),
            #[cfg(test)]
            identity_bits: (tune_cents.to_bits(), level.to_bits()),
            sr,
            phase: event.next_u32() as f32 / u32::MAX as f32 * ORGAN_TABLE_LEN as f32,
            phase_inc: 0.0,
            frequency: 0.0,
            harmonics: 0,
            active: false,
            speech: Box::new([0.0; ORGAN_TABLE_LEN]),
            steady: Box::new([0.0; ORGAN_TABLE_LEN]),
            age: 0,
            attack_samples: (speech_ms * 0.12).clamp(4.0, 22.0) * 0.001 * sr,
            transition_samples: speech_ms * 0.001 * sr,
            amp_mod: 1.0,
            drift: Drift::new(wander_seed, 2.5 * spec.sensitivity, hold_ticks),
            wander_ratio: 1.0,
            wander_amp: 1.0,
            driven: matches!(spec.family, RankFamily::ChorusReed)
                .then(|| Box::new([0.0; ORGAN_TABLE_LEN])),
            driven_harmonics: 0,
            blend: 0.0,
            drive_gain: 1.0,
        };
        pipe.retune(1.0, 0.0, 0.0);
        pipe
    }

    fn regenerate_tables(&mut self, harmonics: usize) {
        self.speech.fill(0.0);
        self.steady.fill(0.0);
        if harmonics == 0 {
            return;
        }
        let mut energy = 0.0;
        let mut amps = Vec::with_capacity(harmonics);
        for harmonic in 1..=harmonics {
            let steady_amp = 10f32.powf(organ_harmonic_db(self.family, self.key, harmonic) / 20.0);
            let speech_amp =
                steady_amp * 10f32.powf(organ_speech_tilt_db(self.family, harmonic) / 20.0);
            energy += steady_amp * steady_amp;
            amps.push((steady_amp, speech_amp));
        }
        let scale = 0.65 / energy.sqrt().max(1e-6);
        for (index, &(steady_amp, speech_amp)) in amps.iter().enumerate() {
            let harmonic = index + 1;
            let mut osc = Sine::new(harmonic as f32, ORGAN_TABLE_LEN as f32, 0.0);
            for i in 0..ORGAN_TABLE_LEN {
                let s = osc.next() * scale;
                self.steady[i] += s * steady_amp;
                self.speech[i] += s * speech_amp;
            }
        }
    }

    /// Build the hard-blown reed table (ChorusReed pipes only), normalized to its
    /// own energy exactly like `steady`, so crossfading `steady`→`driven` changes
    /// timbre only — loudness is the separate `drive_gain` lift.
    fn regenerate_driven(&mut self, harmonics: usize) {
        let key = self.key;
        let Some(driven) = self.driven.as_mut() else {
            return;
        };
        driven.fill(0.0);
        if harmonics == 0 {
            return;
        }
        let mut energy = 0.0;
        let mut amps = Vec::with_capacity(harmonics);
        for harmonic in 1..=harmonics {
            let amp = 10f32.powf(organ_driven_harmonic_db(key, harmonic) / 20.0);
            energy += amp * amp;
            amps.push(amp);
        }
        let scale = 0.65 / energy.sqrt().max(1e-6);
        for (index, &amp) in amps.iter().enumerate() {
            let mut osc = Sine::new((index + 1) as f32, ORGAN_TABLE_LEN as f32, 0.0);
            for slot in driven.iter_mut() {
                *slot += osc.next() * scale * amp;
            }
        }
    }

    fn retune(&mut self, performance_pitch: f32, pressure: f32, trem: f32) {
        let wind_cents = -5.0 * pressure.clamp(0.0, 1.0) * self.sensitivity;
        let trem_cents = 3.0 * trem.clamp(-1.0, 1.0) * self.sensitivity;
        let frequency = key_freq(self.key)
            * self.ratio
            * self.static_tune
            * performance_pitch.max(0.0001)
            * 2f32.powf((wind_cents + trem_cents) / 1200.0);
        let max_hz = self.sr * ORGAN_MAX_SR_FRACTION;
        let harmonics = if frequency >= ORGAN_MIN_FUNDAMENTAL_HZ && frequency < max_hz {
            ORGAN_MAX_SOURCE_HARMONICS.min((max_hz / frequency).floor() as usize)
        } else {
            0
        };
        if harmonics != self.harmonics {
            self.regenerate_tables(harmonics);
            self.harmonics = harmonics;
        }
        // Reed pipes also carry a hard-blown `driven` table extended to 48
        // harmonics (fills the 2–8 kHz snarl band). Same alias law, higher
        // ceiling; cache its own count so it regenerates only when it changes,
        // independently of the 24-harmonic steady count.
        if self.driven.is_some() {
            let driven_h = if frequency >= ORGAN_MIN_FUNDAMENTAL_HZ && frequency < max_hz {
                ORGAN_MAX_DRIVEN_HARMONICS.min((max_hz / frequency).floor() as usize)
            } else {
                0
            };
            if driven_h != self.driven_harmonics {
                self.regenerate_driven(driven_h);
                self.driven_harmonics = driven_h;
            }
        }
        self.frequency = frequency;
        self.phase_inc = frequency * ORGAN_TABLE_LEN as f32 / self.sr;
        self.active = harmonics > 0;
        let amp_db = -1.5 * pressure.clamp(0.0, 1.0) * self.sensitivity
            + 0.30 * trem.clamp(-1.0, 1.0) * self.sensitivity;
        self.amp_mod = 10f32.powf(amp_db / 20.0);
    }

    #[inline]
    fn next(&mut self) -> f32 {
        self.age = self.age.saturating_add(1);
        if !self.active {
            return 0.0;
        }
        // Advance the wind-wander at a 64-sample control rate (~689 Hz). The walk
        // value is in cents; convert to a pitch ratio and a co-signed amplitude
        // trim (+0.4 dB per +2.5 cents). Keyed off `age`, this is independent of
        // the caller's block size, so voice unit renders (which call render()
        // once on the whole buffer, never retune) see the wander too.
        if self.age % 64 == 1 {
            let w = self.drift.next().clamp(-60.0, 60.0);
            self.wander_ratio = 2f32.powf(w / 1200.0);
            self.wander_amp = 10f32.powf(0.16 * w / 20.0);
        }
        let i0 = self.phase as usize & (ORGAN_TABLE_LEN - 1);
        let i1 = (i0 + 1) & (ORGAN_TABLE_LEN - 1);
        let frac = self.phase - self.phase.floor();
        let speech = self.speech[i0] + (self.speech[i1] - self.speech[i0]) * frac;
        let steady = self.steady[i0] + (self.steady[i1] - self.steady[i0]) * frac;
        // Reed rasp: under swell drive, harden `steady` toward the `driven` table
        // (same phase accumulator, so the wander detunes both coherently). At
        // blend 0 — every non-reed pipe, and every reed with the swell shut — this
        // is bit-for-bit the original `steady`, and the drive_gain multiply below
        // is skipped: that is the opt-in byte-identity guarantee.
        let body = if self.blend > 0.0 {
            match &self.driven {
                Some(driven) => {
                    let driven_val = driven[i0] + (driven[i1] - driven[i0]) * frac;
                    steady + (driven_val - steady) * self.blend
                }
                None => steady,
            }
        } else {
            steady
        };
        self.phase += self.phase_inc * self.wander_ratio;
        self.phase = self.phase.rem_euclid(ORGAN_TABLE_LEN as f32);
        let speech_mix = (self.age as f32 / self.transition_samples.max(1.0)).min(1.0);
        let attack = (self.age as f32 / self.attack_samples.max(1.0)).min(1.0);
        let reed_overshoot = if self.family == RankFamily::ChorusReed {
            1.0 + 0.15 * (1.0 - self.age as f32 / (0.015 * self.sr)).max(0.0)
        } else {
            1.0
        };
        let out = (speech + (body - speech) * speech_mix)
            * attack
            * reed_overshoot
            * self.gain
            * self.amp_mod
            * self.wander_amp;
        if self.blend > 0.0 {
            out * self.drive_gain
        } else {
            out
        }
    }
}

pub struct CathedralOrgan {
    pipes: Vec<RankPipe>,
    performance_pitch: f32,
    pressure: f32,
    trem: f32,
    norm: f32,
    output_hp: Biquad,
    chiff_filter: Biquad,
    chiff_rng: Rng,
    chiff_amp: f32,
    chiff_decay: f32,
    released: bool,
    release_gain: f32,
    release_step: f32,
}

impl CathedralOrgan {
    fn new(key: u8, vel: u8, sr: f32, event_seed: u32) -> Self {
        let pipes: Vec<_> = cathedral_registration(key)
            .into_iter()
            .map(|spec| RankPipe::new(spec, key, sr, event_seed))
            .collect();
        debug_assert!(pipes.len() <= 14);
        let energy = pipes.iter().map(|p| p.gain * p.gain).sum::<f32>().sqrt();
        // The extra old/new pipe pair at a mixture break is correlated rather
        // than noise-like, so the generic root-sum-square normaliser trims a
        // fraction too much. This measured half-percent correction keeps the
        // audible semitone crossfade inside the 2 dB level contract.
        let break_compensation = if matches!(key, 48 | 60 | 72 | 84) {
            1.005
        } else {
            1.0
        };
        Self {
            pipes,
            performance_pitch: 1.0,
            pressure: 0.0,
            trem: 0.0,
            norm: 0.28 / energy.max(0.1) * break_compensation,
            output_hp: Biquad::highpass(10.0, 0.707, sr),
            chiff_filter: Biquad::bandpass(2_200.0, 0.8, sr),
            chiff_rng: Rng::new(event_seed ^ 0xC41F_F123),
            // TIMBRE, not level — exempt from the k=2 law (HLD velocity-law §2.4).
            // Onset chiff colour at 0.012 scale; its level contribution is negligible.
            chiff_amp: 0.012 * (0.35 + 0.65 * vel_ctrl(vel)),
            chiff_decay: t60_mul(0.045, sr),
            released: false,
            release_gain: 1.0,
            release_step: 1.0 / (0.10 * sr).max(1.0),
        }
    }

    fn retune(&mut self) {
        for pipe in &mut self.pipes {
            pipe.retune(self.performance_pitch, self.pressure, self.trem);
        }
    }

    #[cfg(test)]
    fn debug_pipe_identity(&self) -> Vec<(u8, u32, u32)> {
        self.pipes
            .iter()
            .map(|pipe| (pipe.id, pipe.identity_bits.0, pipe.identity_bits.1))
            .collect()
    }

    #[cfg(test)]
    fn debug_composed_frequencies(&self) -> Vec<u32> {
        self.pipes
            .iter()
            .map(|pipe| pipe.frequency.to_bits())
            .collect()
    }

    #[cfg(test)]
    fn debug_all_pipe_bounds_hold(&self) -> bool {
        self.pipes.len() <= 14
            && self.pipes.iter().all(|pipe| {
                (!pipe.active
                    || (pipe.frequency >= ORGAN_MIN_FUNDAMENTAL_HZ
                        && pipe.frequency * pipe.harmonics as f32
                            <= pipe.sr * ORGAN_MAX_SR_FRACTION + 0.01))
                    // The 48-harmonic driven reed table obeys the same Nyquist law.
                    && pipe.frequency * pipe.driven_harmonics as f32
                        <= pipe.sr * ORGAN_MAX_SR_FRACTION + 0.01
            })
    }
}

impl Voice for CathedralOrgan {
    fn render(&mut self, out: &mut [f32]) -> bool {
        for sample in out.iter_mut() {
            let mut organ = self.pipes.iter_mut().map(RankPipe::next).sum::<f32>();
            if self.chiff_amp > 1e-6 {
                organ += self.chiff_filter.process(self.chiff_rng.white()) * self.chiff_amp;
                self.chiff_amp *= self.chiff_decay;
            }
            if self.released {
                self.release_gain = (self.release_gain - self.release_step).max(0.0);
            }
            *sample += self
                .output_hp
                .process(organ * self.norm * self.release_gain);
        }
        self.release_gain > 0.0
    }

    fn note_off(&mut self) {
        self.released = true;
    }

    fn released(&self) -> bool {
        self.released
    }

    fn set_pitch(&mut self, mult: f32) {
        self.performance_pitch = mult.max(0.0001);
        self.retune();
    }

    fn set_organ_pressure(&mut self, pressure: f32, trem: f32) {
        self.pressure = pressure.clamp(0.0, 1.0);
        self.trem = trem.clamp(-1.0, 1.0);
        self.retune();
    }

    fn set_organ_swell(&mut self, drive: f32) {
        let d = drive.clamp(0.0, 1.0);
        // Reed-only: the reeds harden toward `driven` and lift; the flues are left
        // to the wind-pressure model. Does NOT call `retune()` — no table regen.
        let gain = 10f32.powf(REED_LIFT_DB * d / 20.0);
        for pipe in &mut self.pipes {
            if pipe.family == RankFamily::ChorusReed {
                pipe.blend = d;
                pipe.drive_gain = gain;
            }
        }
    }

    #[cfg(test)]
    fn kind(&self) -> &'static str {
        "cathedral-organ"
    }
}

/// Base tremulant/musette AM (rate Hz, depth) for the organ programs. The
/// engine only morphs GM16-19 from these values toward Leslie-fast; the
/// musette accordions keep their built-in motion. (GM 22 no longer routes
/// here — it is a Reed free-reed voice, §2.11, with CC1 as pitch vibrato.)
pub fn organ_trem_base(program: u8) -> (f32, f32) {
    match program {
        18 => (6.5, 0.10),
        16 | 17 => (5.5, 0.06),
        20 => (4.2, 0.0),
        // Round-3 U7 (plan §3.4): the accordions' COHERENT global tremolo is
        // removed (depth 0) — it was the "musette" oracle cheat (a single AM on
        // every harmonic in lock-step). Real musette shimmer is per-harmonic
        // reed BEATING (detuned reed pairs on each harmonic, so the beat rate
        // scales with h), now carried by the stops table itself. The rate is
        // kept for the engine's Leslie-morph plumbing but the depth is inert.
        21 => (5.0, 0.0),
        23 => (5.8, 0.0),
        _ => (4.2, 0.04),
    }
}

fn cent_ratio(cents: f32) -> f32 {
    2f32.powf(cents / 1200.0)
}

fn organ(program: u8, key: u8, vel: u8, sr: f32, seed: u32) -> Organ {
    let (trem_hz, trem_depth) = organ_trem_base(program);
    let f = key_freq(key);
    match program {
        18 => Organ::new(
            key,
            vel,
            sr,
            seed,
            &[
                (0.5, 0.6),
                (1.0, 1.0),
                (1.5, 0.55),
                (2.0, 0.5),
                (3.0, 0.25),
                (4.0, 0.15),
            ],
            Adsr::new(0.005, 0.05, 1.0, 0.10, sr),
            trem_hz,
            trem_depth,
            0.10,
            0.09,
            1.8,
            0.32,
        ),
        16 => Organ::new(
            key,
            vel,
            sr,
            seed,
            &[
                (0.5, 0.5),
                (1.0, 1.0),
                (1.5, 0.35),
                (2.0, 0.35),
                (3.0, 0.12),
                (4.0, 0.08),
            ],
            Adsr::new(0.01, 0.05, 1.0, 0.15, sr),
            trem_hz,
            trem_depth,
            0.08,
            0.09,
            0.0,
            0.32,
        ),
        // 17 percussive organ: the Percussion tab drops the 4' drawbar and thins
        // the upper drawbars, and a 3rd-harmonic tap pings at key-on and decays
        // over the sustained tone — the identity 16 lacks. Louder key click too.
        17 => Organ::new(
            key,
            vel,
            sr,
            seed,
            &[
                (0.5, 0.55),
                (1.0, 1.0),
                (1.5, 0.25),
                (2.0, 0.30),
                (3.0, 0.06),
            ],
            Adsr::new(0.01, 0.05, 1.0, 0.15, sr),
            trem_hz,
            trem_depth,
            0.08,
            0.14,
            0.0,
            0.32,
        )
        .with_percussion(3.0, 0.55, 0.22),
        19 => Organ::new(
            key,
            vel,
            sr,
            seed,
            &[
                (0.5, 0.5),
                (1.0, 1.0),
                (2.0, 0.62),
                (3.0, 0.28),
                (4.0, 0.42),
                (6.0, 0.16),
                (8.0, 0.18),
            ],
            Adsr::new(0.06, 0.10, 0.92, 0.25, sr),
            trem_hz,
            trem_depth,
            0.20,
            0.09,
            0.0,
            0.32,
        ),
        // 20 reed organ (harmonium/Lowrey): a FREE reed radiates an INTEGER
        // harmonic series. The old additive table carried a full half-integer
        // ladder (1.5/2.5/3.5/4.5f) — perfect-fifth "quint" partials that
        // painted an audible parallel fifth (medieval-organum ghost) on every
        // note (flagged in the Tubular Bells reference render at 0:07). Those
        // quints were the WRONG realization of a right idea: a free reed IS
        // less pure than the church organ. Integer harmonics only now; the
        // reed's inharmonic CHARACTER is re-realized PHYSICALLY as broadband
        // reed BUZZ — turbulent air rasping past the vibrating tongue, not a
        // pitched mutation rank — which keeps the off-harmonic residual that
        // distinguishes it from GM19 WITHOUT any pitched fifth. Wider, louder,
        // slightly lower-centred noise than before so it spans the 1.5–4.5f
        // band the free-reed-character oracle samples.
        20 => Organ::new(
            key,
            vel,
            sr,
            seed,
            &[
                (1.0, 1.0),
                (2.0, 0.38),
                (3.0, 0.22),
                (4.0, 0.13),
                (5.0, 0.07),
            ],
            Adsr::new(0.095, 0.08, 0.96, 0.22, sr),
            trem_hz,
            trem_depth,
            0.0,
            0.0,
            0.0,
            0.30,
        )
        .with_reed_noise(0.05, (f * 3.0).clamp(600.0, 2400.0), 0.7),
        // 22 harmonica moved to the Reed free-reed voice (§2.11) — see
        // HARMONICA in the ReedPreset table.
        // Round-3 U7 (plan §3.4): a DRIER, sharper bandoneon/tango box. HEAD
        // had it BACKWARDS — a WIDER musette (±22 c) than the GM21 accordion
        // (±16 c). A bandoneon is a drier double-reed: NARROWER detune (±9 c),
        // QUIETER side reeds (~0.46× the centre vs GM21's 0.63×), and the
        // musette confined to H1/H2 — H3/H4 stay single sines (drier top).
        23 => Organ::new(
            key,
            vel,
            sr,
            seed,
            &[
                (1.0, 0.90),
                (cent_ratio(-9.0), 0.41),
                (cent_ratio(9.0), 0.41),
                (2.0, 0.26),
                (2.0 * cent_ratio(-9.0), 0.11),
                (2.0 * cent_ratio(9.0), 0.11),
                (3.0, 0.12),
                (4.0, 0.06),
            ],
            Adsr::new(0.040, 0.07, 0.98, 0.18, sr),
            trem_hz,
            trem_depth,
            0.0,
            0.0,
            0.0,
            0.21,
        )
        .with_reed_noise(0.020, (f * 3.5).clamp(750.0, 2600.0), 0.75),
        _ => unreachable!("organ() only handles GM16-20 and 23"),
    }
}

/// Frozen pre-cathedral GM19 voice for the non-zero CC0 compatibility bank.
pub(crate) fn legacy_church_organ(key: u8, vel: u8, sr: f32, seed: u32) -> Box<dyn Voice> {
    Box::new(organ(19, key, vel, sr, seed))
}

/// GM19 CC0=2 alt bank: the restored cathedral pipe-organ voice (a second
/// church-organ colour alongside the default Leslie drawbar). See [`CathedralOrgan`].
pub(crate) fn cathedral_organ(key: u8, vel: u8, sr: f32, seed: u32) -> Box<dyn Voice> {
    Box::new(CathedralOrgan::new(key, vel, sr, seed))
}

// ---------------------------------------------------------------------------
// SawStack (strings / choir / pads)
// ---------------------------------------------------------------------------

/// Oscillator shape for a `SawStack` layer. Saw for strings/choir/pads and
/// most leads; Pulse (band-limited square) for the square-lead class.
#[derive(Clone, Copy)]
enum Wave {
    Saw,
    Pulse(f32), // duty cycle
}

/// A layer's oscillator — a thin enum so the render loop stays branch-cheap and
/// the `Saw` arm is numerically identical to a bare `BlepSaw`.
enum LayerOsc {
    Saw(BlepSaw),
    Pulse(BlepPulse),
}

impl LayerOsc {
    #[inline]
    fn next(&mut self) -> f32 {
        match self {
            LayerOsc::Saw(o) => o.next(),
            LayerOsc::Pulse(o) => o.next(),
        }
    }

    #[inline]
    fn set_freq(&mut self, freq: f32, sr: f32) {
        match self {
            LayerOsc::Saw(o) => o.set_freq(freq, sr),
            LayerOsc::Pulse(o) => o.set_freq(freq, sr),
        }
    }
}

struct Layer {
    osc: LayerOsc,
    ratio: f32,
    /// Amplitude relative to a stock layer. 1.0 everywhere except an authored
    /// interval layer (GM 86 fifth / GM 87 sub) — `x × 1.0` is exact in f32,
    /// so existing callers render byte-identically.
    gain: f32,
    vib_phase: f32,
    vib_rate: f32, // Hz — every player's wobble is their own
    drift: Drift,
}

enum StackFilter {
    Lp(Biquad),
    /// Vocal formants that morph from a closed schwa into the vowel over the
    /// first ~150 ms of the note ("mm-ah").
    Formant {
        bands: [Biquad; 3],
        gains: [f32; 3],
        cur: [f32; 3],
        tgt: [f32; 3],
        qs: [f32; 3],
    },
}

pub struct SawStack {
    layers: Vec<Layer>,
    /// Σ layer gains — the layer-sum normalizer. Equals `layers.len() as f32`
    /// for every caller without an authored interval layer (all gains 1.0), so
    /// the historical `s / len` normalization is reproduced bit-exactly.
    gain_norm: f32,
    base_f: f32,
    bend: f32, // channel pitch multiplier (bend / fine-tune / aftertouch vibrato)
    filt: StackFilter,
    vowel_morph_start: Option<[f32; 3]>,
    env: Adsr,
    vib_depth: f32,
    vib_delay: u32,
    breath: f32,
    breath_attack: f32,
    breath_attack_k: f32,
    /// Optional model-owned crescendo `(start, end, target gain)` in samples.
    /// GM49 uses it after the shared sampled onset has handed over; `None`
    /// keeps every other stack on the historical render path.
    post_handover_swell: Option<(u32, u32, f32)>,
    rng: Rng,
    sweep: Option<(f32, f32, f32, f32)>, // (lfo phase, rate Hz, base cutoff, octaves)
    sweep_q: f32,
    // Divide-down string machine (synth strings 50/51): one shared BBD chorus
    // LFO — (phase, rate Hz, ± pitch depth) — read by every layer at its own
    // fixed phase offset, so the ensemble motion is *correlated*, unlike each
    // player's independent `drift`. `None` for every other caller; its per-layer
    // contribution is then exactly `+ 0.0`, so those renders are bit-identical.
    chorus: Option<(f32, f32, f32)>,
    // One-shot filter envelope (synth pads 88/90/92/93): a note-synchronous
    // MONOTONE cutoff trajectory the free-running `sweep` LFO cannot make — a
    // bright onset decaying into a warm bed (`fenv` starts >1) or a slow swell
    // opening into the sound (`fenv` starts <1). `fenv` is the live cutoff
    // multiplier, relaxing toward 1.0 by `fenv_k` per control tick; `base_cut`
    // is the design cutoff used when there is no `sweep`. Inert (`fenv_k == 0.0`,
    // `fenv == 1.0`) for every other caller, whose cutoff is then `× 1.0` — bit-
    // identical. `fenv_k` is built at `sr / CTRL` (control rate), NOT `sr`.
    fenv: f32,
    fenv_k: f32,
    base_cut: f32,
    t: u32,
    amp: f32,
    sr: f32,
    legato_enabled: bool, // strings/choir/leads slur on CC68; pads re-attack
    // Post-filter tanh drive (GM 84 charang, MM-REQ-KILN-00021). 0.0 for every
    // other caller, and the render loop tests `> 0.0` OUTSIDE the multiply, so
    // those renders are bit-identical. Placed AFTER the filter on purpose: a
    // shaper before the tone control has its new harmonics filtered straight
    // back off, which is the opposite of what an overdriven lead sounds like.
    drive: f32,
    /// Make-up divisor `tanh(drive · x_nom) / x_nom`, giving the stage unity
    /// gain at the level the voice actually runs at (`LEAD84_NOMINAL`), so
    /// engaging the drive changes the wave's SHAPE without stepping its
    /// loudness.
    drive_norm: f32,
    /// Broadband make-up for the formant bank, `1.0` for every voice that does not
    /// use one. Three bandpasses pass far less energy than the lowpass they
    /// replace, so a formant voice needs its level restored at the point the bank
    /// is summed — the same principle as `drive_norm`, applied to a different
    /// stage. `1.0` is an exact identity under IEEE-754, so every non-formant
    /// render stays bit-identical.
    formant_makeup: f32,
}

impl SawStack {
    /// Saw-oscillator constructor (strings / choir / pads). Delegates to
    /// `new_wave` with `Wave::Saw`; kept as the stable entry point so those
    /// callers are byte-identical.
    #[allow(clippy::too_many_arguments)]
    fn new(
        key: u8,
        vel: u8,
        sr: f32,
        seed: u32,
        n_osc: usize,
        detune: f32,
        drift_depth: f32,
        filt: StackFilter,
        env: Adsr,
        vib: (f32, f32, f32), // (hz, depth, delay s)
        breath: f32,
        sweep: Option<(f32, f32, f32)>, // (rate, base, octaves)
        sweep_q: f32,
        amp: f32,
    ) -> Self {
        Self::new_wave(
            key,
            vel,
            sr,
            seed,
            n_osc,
            detune,
            drift_depth,
            filt,
            env,
            vib,
            breath,
            sweep,
            sweep_q,
            amp,
            Wave::Saw,
        )
    }

    /// Full constructor with a selectable oscillator shape. The per-layer RNG
    /// draw order (osc phase, then `vib_phase`, then `vib_rate`) is identical to
    /// the historical saw path — load-bearing for byte-identity — so the phase
    /// is drawn once before the wave match and both arms consume it the same way.
    #[allow(clippy::too_many_arguments)]
    fn new_wave(
        key: u8,
        vel: u8,
        sr: f32,
        seed: u32,
        n_osc: usize,
        detune: f32,
        drift_depth: f32,
        filt: StackFilter,
        env: Adsr,
        vib: (f32, f32, f32), // (hz, depth, delay s)
        breath: f32,
        sweep: Option<(f32, f32, f32)>, // (rate, base, octaves)
        sweep_q: f32,
        amp: f32,
        wave: Wave,
    ) -> Self {
        let f = key_freq(key);
        let mut rng = Rng::new(seed);
        let layers = (0..n_osc)
            .map(|i| {
                let spread = if n_osc > 1 {
                    (i as f32 / (n_osc - 1) as f32) * 2.0 - 1.0
                } else {
                    0.0
                };
                let layer_f = f * (1.0 + detune * spread);
                let phase = rng.white() * 0.5 + 0.5;
                let osc = match wave {
                    Wave::Saw => LayerOsc::Saw(BlepSaw::new(layer_f, sr, phase)),
                    Wave::Pulse(duty) => LayerOsc::Pulse(BlepPulse::new(layer_f, sr, phase, duty)),
                };
                Layer {
                    osc,
                    ratio: 1.0 + detune * spread,
                    gain: 1.0,
                    vib_phase: rng.white() * std::f32::consts::PI,
                    vib_rate: vib.0 * (1.0 + 0.15 * rng.white()),
                    drift: Drift::new(seed ^ (0x1234 + i as u32 * 977), drift_depth, 2800),
                }
            })
            .collect();
        let sweep_phase = rng.white() * std::f32::consts::PI;
        SawStack {
            layers,
            gain_norm: n_osc as f32,
            base_f: f,
            bend: 1.0,
            filt,
            vowel_morph_start: None,
            drive: 0.0,
            drive_norm: 1.0,
            formant_makeup: 1.0,
            env,
            vib_depth: vib.1,
            vib_delay: (vib.2 * sr) as u32,
            breath,
            breath_attack: 0.0,
            breath_attack_k: 0.0,
            post_handover_swell: None,
            rng,
            sweep: sweep.map(|(rate, base, oct)| (sweep_phase, rate, base, oct)),
            sweep_q,
            chorus: None,
            fenv: 1.0,
            fenv_k: 0.0,
            base_cut: 0.0,
            t: 0,
            amp: amp * vel_amp(vel),
            sr,
            legato_enabled: false,
        }
    }

    /// Turn this stack into a divide-down string machine: replace the layers'
    /// independent detune drift with one shared BBD chorus LFO. Fixed start
    /// phase (0.0) keeps the render deterministic; the per-layer phase offsets
    /// applied in `control_tick` supply the ensemble width.
    fn with_chorus(mut self, rate_hz: f32, depth: f32) -> Self {
        self.chorus = Some((0.0, rate_hz, depth));
        self
    }

    /// Arm the one-shot filter envelope (synth pads). The cutoff starts at
    /// `start_mult × base` and relaxes toward `base` with time constant `t60`.
    /// `base_cut` is the design cutoff, used when the stack has no `sweep` (with
    /// a sweep, the LFO already supplies the moving base and `base_cut` is
    /// ignored). The relax coefficient is built at the CONTROL rate `sr / CTRL`,
    /// because `control_tick` runs once per `CTRL` samples — the exact trap that
    /// was MM-BUG-KILN-00003 for the flute vibrato.
    fn with_fenv(mut self, start_mult: f32, t60: f32, base_cut: f32) -> Self {
        if t60 > 0.0 {
            self.fenv = start_mult;
            self.fenv_k = t60_mul(t60, self.sr / CTRL as f32);
            self.base_cut = base_cut;
        }
        self
    }

    /// Add a one-shot excess-air transient above the sustained breath bed.
    /// Inert by default; acoustic strings use it for the noisy bow catch.
    fn with_breath_attack(mut self, amount: f32, t60: f32) -> Self {
        self.breath_attack = amount.max(0.0);
        self.breath_attack_k = if t60 > 0.0 {
            t60_mul(t60, self.sr)
        } else {
            0.0
        };
        self
    }

    /// Add a gradual section crescendo after an onset layer has handed over.
    fn with_post_handover_swell(mut self, start_s: f32, end_s: f32, target_gain: f32) -> Self {
        let start = (start_s.max(0.0) * self.sr) as u32;
        let end = (end_s.max(start_s + 0.001) * self.sr) as u32;
        self.post_handover_swell = Some((start, end, target_gain.max(1.0)));
        self
    }

    /// Push one authored interval layer (GM 86's parallel fifth, GM 87's
    /// sub-octave) at `ratio` × the written pitch and `gain` relative to a
    /// stock layer. It joins `layers` AFTER normal construction with its own
    /// salted RNG, so every existing caller's draw sequence — and render —
    /// stays byte-identical. The layer rides the shared env/filter and the
    /// `base_f · ratio · bend` retune in `control_tick`, so pitch bend, the
    /// engine's CC1 vibrato and CC68 legato keep the interval locked
    /// (MM-REQ-KILN-00019 / MM-REQ-KILN-00020).
    #[allow(clippy::too_many_arguments)]
    fn push_interval_layer(
        &mut self,
        wave: Wave,
        ratio: f32,
        gain: f32,
        drift_depth: f32,
        seed: u32,
    ) {
        let mut rng = Rng::new(seed ^ 0x51B1_A7E5); // salt: decorrelated from the stack rng
        let layer_f = self.base_f * ratio;
        let phase = rng.white() * 0.5 + 0.5;
        let osc = match wave {
            Wave::Saw => LayerOsc::Saw(BlepSaw::new(layer_f, self.sr, phase)),
            Wave::Pulse(duty) => LayerOsc::Pulse(BlepPulse::new(layer_f, self.sr, phase, duty)),
        };
        let idx = self.layers.len() as u32;
        self.layers.push(Layer {
            osc,
            ratio,
            gain,
            vib_phase: rng.white() * std::f32::consts::PI,
            vib_rate: 0.0, // leads carry no always-on vibrato; CC1 rides the bend
            drift: Drift::new(seed ^ (0x1234 + idx * 977), drift_depth, 2800),
        });
        self.gain_norm += gain;
    }

    fn control_tick(&mut self) {
        let ramp = if self.t > self.vib_delay {
            (((self.t - self.vib_delay) as f32) / self.sr).min(1.0)
        } else {
            0.0
        };
        let sr = self.sr;
        // Advance the shared BBD chorus LFO once per control tick (string
        // machines only). Every layer then reads it at a fixed phase offset for
        // a *correlated* ensemble motion. `None` → `cmod == 0.0` below, so every
        // other caller's frequency is unchanged to the bit.
        let chorus = if let Some((phase, rate, depth)) = &mut self.chorus {
            *phase += TAU * *rate * CTRL as f32 / sr;
            Some((*phase, *depth))
        } else {
            None
        };
        let n = self.layers.len() as f32;
        for (i, layer) in self.layers.iter_mut().enumerate() {
            layer.vib_phase += TAU * layer.vib_rate * CTRL as f32 / sr;
            let vib = if ramp > 0.0 && self.vib_depth > 0.0 {
                self.vib_depth * ramp * layer.vib_phase.sin()
            } else {
                0.0
            };
            let drift = layer.drift.next();
            let cmod = match chorus {
                Some((phase, depth)) => depth * (phase + i as f32 * TAU / n).sin(),
                None => 0.0,
            };
            layer.osc.set_freq(
                self.base_f * layer.ratio * self.bend * (1.0 + vib + drift + cmod),
                sr,
            );
        }
        match &mut self.filt {
            StackFilter::Formant {
                bands,
                cur,
                tgt,
                qs,
                ..
            } => {
                for i in 0..3 {
                    if (tgt[i] - cur[i]).abs() > 1.0 {
                        cur[i] += 0.045 * (tgt[i] - cur[i]);
                        bands[i].retune_bandpass(cur[i], qs[i], sr);
                    }
                }
            }
            StackFilter::Lp(b) => {
                // Relax the one-shot filter envelope toward 1.0 (inert unless a
                // pad armed it; `fenv_k == 0.0` leaves `fenv` at exactly 1.0).
                if self.fenv_k > 0.0 {
                    self.fenv = 1.0 + (self.fenv - 1.0) * self.fenv_k;
                }
                // Retune only when there is motion to apply: a sweep, or a live
                // filter envelope. A caller with neither (strings/leads/other
                // pads) skips this exactly as before — bit-identical. A swept
                // caller with `fenv` inert computes today's cutoff, then `× 1.0`.
                if self.sweep.is_some() || self.fenv_k > 0.0 {
                    let cut = if let Some((phase, rate, base, oct)) = &mut self.sweep {
                        *phase += TAU * *rate * CTRL as f32 / sr;
                        *base * 2f32.powf(*oct * 0.5 * (phase.sin() + 1.0))
                    } else {
                        self.base_cut
                    };
                    b.retune_lowpass((cut * self.fenv).min(sr * 0.4), self.sweep_q, sr);
                }
            }
        }
    }
}

impl Voice for SawStack {
    fn render(&mut self, out: &mut [f32]) -> bool {
        for o in out.iter_mut() {
            if self.t.is_multiple_of(CTRL) {
                self.control_tick();
            }
            let mut s = 0.0;
            for layer in &mut self.layers {
                s += layer.osc.next() * layer.gain;
            }
            s /= self.gain_norm;
            let breath = self.breath + self.breath_attack;
            if breath > 0.0 {
                s += self.rng.white() * breath;
                self.breath_attack *= self.breath_attack_k;
            }
            s = match &mut self.filt {
                StackFilter::Lp(b) => b.process(s),
                StackFilter::Formant { bands, gains, .. } => {
                    let mut y = 0.0;
                    for (b, g) in bands.iter_mut().zip(gains.iter()) {
                        y += b.process(s) * *g;
                    }
                    y * self.formant_makeup
                }
            };
            if self.drive > 0.0 {
                s = (s * self.drive).tanh() / self.drive_norm;
            }
            let env = self.env.next();
            if let Some((start, end, target)) = self.post_handover_swell {
                let progress =
                    (self.t.saturating_sub(start) as f32 / (end - start) as f32).min(1.0);
                let swell = 1.0 + (target - 1.0) * progress;
                *o += s * self.amp * env * swell;
            } else {
                *o += s * self.amp * env;
            }
            self.t += 1;
        }
        self.env.alive()
    }

    fn note_off(&mut self) {
        self.env.release();
    }

    fn released(&self) -> bool {
        self.env.released()
    }

    fn set_pitch(&mut self, mult: f32) {
        // applied at control rate on top of each layer's detune/vibrato/drift
        self.bend = mult;
    }

    fn legato_to(&mut self, key: u8, _vel: u8) -> bool {
        // A slur just retunes the base frequency; the layers pick it up on the
        // next control tick and the envelope keeps running (no fresh attack).
        if !self.legato_enabled {
            return false;
        }
        self.base_f = key_freq(key);
        true
    }

    fn set_vowel(&mut self, freqs: [f32; 3], qs: [f32; 3], gains: [f32; 3]) {
        if let StackFilter::Formant {
            tgt,
            qs: q,
            gains: g,
            ..
        } = &mut self.filt
        {
            *tgt = freqs;
            *q = qs;
            *g = gains;
        } else if let Some(start) = self.vowel_morph_start.take() {
            self.filt = StackFilter::Formant {
                bands: [
                    Biquad::bandpass(start[0], qs[0], self.sr),
                    Biquad::bandpass(start[1], qs[1], self.sr),
                    Biquad::bandpass(start[2], qs[2], self.sr),
                ],
                gains,
                cur: start,
                tgt: freqs,
                qs,
            };
        }
    }

    #[cfg(test)]
    fn kind(&self) -> &'static str {
        "sawstack"
    }
}

/// Soft notes speak slower: scale an attack time by velocity.
fn vel_attack(base: f32, vel: u8) -> f32 {
    base * (1.45 - 0.65 * (vel as f32 / 127.0))
}

fn strings(program: u8, key: u8, vel: u8, sr: f32, seed: u32) -> SawStack {
    let slow = program == 49;
    let cutoff = if slow { 3200.0 } else { 4200.0 };
    // (excess bow-air level, T60): the fast section catches over its ~70 ms
    // attack; the slow section's rosin noise follows its post-handover swell.
    let bow_catch = if slow { (0.55, 0.70) } else { (0.24, 0.35) };
    let mut s = SawStack::new(
        key,
        vel,
        sr,
        seed,
        5,
        0.007,
        0.0035,
        StackFilter::Lp(Biquad::lowpass(cutoff, 0.7, sr)),
        if slow {
            Adsr::new(vel_attack(0.45, vel), 0.3, 0.85, 0.8, sr)
        } else {
            Adsr::new(vel_attack(0.07, vel), 0.3, 0.85, 0.35, sr)
        },
        (5.1, 0.003, 0.22),
        // Round-2: a small bow-noise breath bed. A bare 5-saw detuned stack is
        // near-perfectly periodic and reads as "synthy"; the sample layer only owns
        // the onset (zeroed after 0.40 s), so the sustain needs its own aperiodic bow
        // "air". Summed pre-filter, so it becomes filtered bow-hiss under the section.
        0.025,
        None,
        0.7,
        0.22,
    )
    .with_breath_attack(bow_catch.0, bow_catch.1);
    if slow {
        s.push_interval_layer(Wave::Saw, 2.0, 0.75, 0.0025, seed ^ 0x49A5);
        s = s.with_post_handover_swell(0.40, 2.50, 3.75);
    }
    s.legato_enabled = true;
    s
}

/// Synth Strings 1/2 (GM 50/51) — a *divide-down string machine* (Solina idiom),
/// deliberately NOT the acoustic section `strings()` renders for 48/49. A string
/// machine has no players: its ensemble comes from one shared BBD chorus (via
/// [`SawStack::with_chorus`]), so per-player `drift` and vibrato are OFF and the
/// width is entirely correlated. 51 is the lush/slow variant — wider, more
/// layers, slower & deeper chorus, darker and slower to swell. Tier D: no sample
/// layer (the `make` dispatch routes 50/51 straight here, model-only).
fn synth_strings(program: u8, key: u8, vel: u8, sr: f32, seed: u32) -> SawStack {
    let lush = program == 51;
    let (n_osc, detune, cutoff, q) = if lush {
        (6, 0.014, 2400.0, 0.8)
    } else {
        (5, 0.010, 3000.0, 0.9)
    };
    let (attack, decay, sustain, release) = if lush {
        (0.25, 0.5, 0.92, 0.9)
    } else {
        (0.10, 0.4, 0.90, 0.5)
    };
    let (chorus_hz, chorus_depth) = if lush { (0.45, 0.0026) } else { (0.75, 0.0015) };
    let mut s = SawStack::new(
        key,
        vel,
        sr,
        seed,
        n_osc,
        detune,
        0.0, // no independent per-player drift — the machine's motion is the chorus
        StackFilter::Lp(Biquad::lowpass(cutoff, q, sr)),
        Adsr::new(vel_attack(attack, vel), decay, sustain, release, sr),
        (0.0, 0.0, 0.0), // no per-player vibrato
        0.0,             // no breath bed
        None,            // no filter sweep
        q,
        0.24,
    )
    .with_chorus(chorus_hz, chorus_depth);
    s.legato_enabled = true;
    s
}

// ---------------------------------------------------------------------------
// ChoirV2 (GM 52-54) — formant engine v2 (HLD option C, 2026.07.10)
//
// A dedicated choir voice, deliberately NOT built on `SawStack`: the stack is
// shared by strings (48-51), pads and leads, so every choir-v2 behaviour lives
// in this choir-scoped struct and the shared families render bit-identically.
//
// Design (per the signed-off HLD):
//  - per-singer saw sources in four SATB section pairs, each pair with its own
//    intonation lean, pitch scatter, drift and decorrelated delayed vibrato;
//  - an upgraded 5-band tract per section: three CC70-morphable vowel formants
//    plus a fixed singer's-formant cluster (~2.9/3.25 kHz), with per-section
//    formant scatter so the four tracts never line up exactly;
//  - breath noise injected pre-tract (vowel-coloured) — a one-shot onset puff
//    plus a low sustained air floor;
//  - a soft consonant onset generalised from the alt-bank `hum_hold` prior
//    art: the vowel morph holds at a closed schwa, the mouth then opens (level
//    lift + brightening lowpass);
//  - CC70 vowel sequences keep working through the existing `set_vowel` path
//    (the engine's 3-band anchors drive the vowel formants; the singer's
//    cluster shades with the third band's gain, so "mm" closes it too).
// ---------------------------------------------------------------------------

/// One SATB section's ensemble character. Cents are relative to written pitch.
struct Ch2Section {
    off_cents: f32,        // systematic intonation lean
    scatter_cents: f32,    // ± uniform per-note draw
    drift: f32,            // Drift depth
    vib_rate_mul: f32,     // × 4.6 Hz base
    vib_depth_mul: f32,    // × 0.006 base
    vib_delay: (f32, f32), // s, per-singer uniform draw range
    reg: (u8, u8),         // full-weight key range
}

/// S, A, T, B. Offsets ≤ 6 cents keep the cluster centre on pitch; scatter
/// grows toward the low voices; vibrato slows and shallows toward the basses.
const CH2_SECTIONS: [Ch2Section; 4] = [
    Ch2Section {
        off_cents: 3.0,
        scatter_cents: 4.0,
        drift: 0.0035,
        vib_rate_mul: 1.12,
        vib_depth_mul: 1.00,
        vib_delay: (0.20, 0.55),
        reg: (60, 84),
    },
    Ch2Section {
        off_cents: -2.0,
        scatter_cents: 6.0,
        drift: 0.0040,
        vib_rate_mul: 0.97,
        vib_depth_mul: 0.95,
        vib_delay: (0.30, 0.60),
        reg: (53, 74),
    },
    Ch2Section {
        off_cents: 5.0,
        scatter_cents: 8.0,
        drift: 0.0045,
        vib_rate_mul: 1.05,
        vib_depth_mul: 0.90,
        vib_delay: (0.28, 0.58),
        reg: (47, 69),
    },
    Ch2Section {
        off_cents: -6.0,
        scatter_cents: 10.0,
        drift: 0.0055,
        vib_rate_mul: 0.85,
        vib_depth_mul: 0.70,
        vib_delay: (0.35, 0.80),
        reg: (36, 62),
    },
];

const CH2_SCHWA: [f32; 3] = [500.0, 1400.0, 2400.0]; // closed-mouth onset vowel
const CH2_MORPH: f32 = 0.045; // vowel slew per control tick
/// Singer's-formant cluster: (Hz, Q) — the trained-voice "ring" at 2.8-3.2 kHz.
const CH2_SF: [(f32, f32); 2] = [(2900.0, 5.0), (3250.0, 6.0)];
const CH2_FSCAT: f32 = 0.03; // ± per-section formant-frequency scatter
const CH2_REG_FADE: f32 = 7.0; // semitones of gain fade outside a section reg
const CH2_REG_FLOOR: f32 = 0.25; // a section never fully mutes
const CH2_HUM_GAIN: f32 = 0.45; // closed-lips level (−6.9 dB)
const CH2_MOUTH_RATE: f32 = 0.030; // mouth-open slew per control tick
const CH2_HUM_LP: (f32, f32) = (900.0, 3400.0); // closed→open lowpass cutoff Hz
const CH2_BREATH_T60: f32 = 0.09; // onset breath decay, seconds
const CH2_BREATH_SUS: f32 = 0.008; // sustained air floor (pre-tract)
/// Klatt-style voicing (chest) branch — round 2 "thin, no body": the tract
/// is a parallel bandpass bank whose lowest band is F1, so a note below F1
/// had NO sung fundamental (−24 dB at A2). A lowpassed copy of the dry
/// pre-tract source runs in parallel and restores it; the 2-pole corner
/// keeps the branch to chest register (the vowel identity stays with the
/// formants). Per-program gain below (the ooh is the most
/// fundamental-dominant vowel).
const CH2_CHEST_LP_HZ: f32 = 580.0;
/// Output level, calibrated so the sustained RMS sits in the v1 choir's
/// 0.03-0.07 window across the keyboard (measured before the swap).
const CH2_AMP: f32 = 1.55;

/// Section register weight: 1.0 inside `reg`, fading linearly to
/// `CH2_REG_FLOOR` over `CH2_REG_FADE` semitones outside it.
fn ch2_reg_weight(key: u8, reg: (u8, u8)) -> f32 {
    let d = if key < reg.0 {
        (reg.0 - key) as f32
    } else if key > reg.1 {
        (key - reg.1) as f32
    } else {
        0.0
    };
    if d <= 0.0 {
        1.0
    } else {
        let t = (d / CH2_REG_FADE).min(1.0);
        1.0 - (1.0 - CH2_REG_FLOOR) * t
    }
}

/// One singer: a detuned/drifting saw with their own delayed vibrato.
struct Ch2Singer {
    osc: BlepSaw,
    ratio: f32,
    vib_phase: f32,
    vib_rate: f32,  // Hz
    vib_depth: f32, // fractional pitch deviation
    vib_delay: u32, // samples before the wobble starts
    vib_ramp_s: f32,
    drift: Drift,
    gain: f32, // register/section weight (mean-renormalised to 1)
}

/// One section's vocal tract: 3 vowel formants + the 2-band singer's cluster,
/// each centre scattered by the section's own `fscat` multipliers.
struct Ch2Tract {
    bands: [Biquad; 5],
    fscat: [f32; 5],
}

pub struct ChoirV2 {
    singers: Vec<Ch2Singer>, // 8: [S,S,A,A,T,T,B,B]
    tracts: [Ch2Tract; 4],   // singer pair i uses tract i/2
    // shared vowel morph state (per-tract scatter applied at retune)
    cur: [f32; 3],
    tgt: [f32; 3],
    qs: [f32; 3],
    vgains: [f32; 3],
    sf_gains: [f32; 2],
    sf_ref_g3: f32, // program-default third-band gain: the cluster's open point
    sf_open: f32,   // slewless cluster shade = (vgains[2]/sf_ref_g3).min(1.3)
    base_f: f32,
    bend: f32,
    env: Adsr,
    breath_env: f32, // one-shot onset puff (decays)
    breath_mul: f32,
    hum_hold: u32, // samples: vowel morph frozen, mouth closed
    mouth: f32,    // 0 closed → 1 open
    hum_lp: OnePole,
    chest_lp: Biquad, // Klatt voicing branch: lowpassed dry pre-tract copy
    chest_gain: f32,
    rng: Rng,
    t: u32,
    amp: f32,
    sr: f32,
}

fn choir(program: u8, key: u8, vel: u8, sr: f32, seed: u32) -> ChoirV2 {
    use std::f32::consts::PI;
    let f = key_freq(key);
    let vn = vel as f32 / 127.0;
    let mut rng = Rng::new(seed);

    // Per-program vowel target, onset multipliers and cluster gains. 54
    // ("synth voice") finally splits from 53 with a brighter "eh" and a
    // uniform (non-SATB) scatter — a stack of synth voices, not a room.
    // Last two columns (round 2, chest branch): chest_gain — the Klatt
    // voicing bypass level — and amp_mul, the output re-trim that holds the
    // sustained level inside the strings-continuity window after the chest
    // energy lands (the h1-vs-peak oracle is amp-invariant, so the trim
    // never buries the restored fundamental).
    let (tgt, vgains, sf_gains, hold_mul, br_mul, chest_gain, amp_mul): (
        [f32; 3],
        [f32; 3],
        [f32; 2],
        f32,
        f32,
        f32,
        f32,
    ) = match program {
        52 => (
            [660.0, 1120.0, 2500.0],
            [1.0, 0.45, 0.15],
            [0.20, 0.09],
            1.0,
            1.0,
            0.45,
            0.75,
        ), // aah — the one vowel SC-55 gives a real singer's formant (cluster
        // 8-13x above the 4.1 kHz band); keep it. vgains[2]=0.15 is the F3 gain
        // AND the CC70 cluster-open reference (sf_ref_g3) — kept off the floor so
        // the CC70 vowel morph still differentiates mm (0.10→0.67) from ah
        // (0.35→1.3); the brightness lives in the mouth cutoff + cluster, not F3.
        53 => (
            [330.0, 870.0, 2300.0],
            [1.0, 0.45, 0.12],
            [0.06, 0.03],
            1.25,
            0.7,
            0.50,
            0.44,
        ), // ooh — the most fundamental-dominant vowel; SC-55 gives it no
        // singer's-formant ring, so the cluster is trimmed near-off
        _ => (
            [400.0, 900.0, 1800.0],
            [1.0, 0.28, 0.08],
            [0.04, 0.02],
            0.5,
            1.3,
            0.42,
            0.70,
        ), // eh/synth voice — SC-55 renders GM54 the dark, flat voice (centroid
           // ~640-790 across the register); low F2, trimmed cluster + light chest
           // hold the fundamental and keep it dark
    };
    let qs = [9.0, 10.0, 9.0];
    let uniform = program == 54;

    let mut singers: Vec<Ch2Singer> = Vec::with_capacity(8);
    for i in 0..8u32 {
        let sec = &CH2_SECTIONS[(i / 2) as usize];
        let (cents, rate_mul, depth_mul, dlo, dhi, drift, gain) = if uniform {
            (rng.white() * 12.0, 1.0, 1.0, 0.30, 0.70, 0.0040, 1.0)
        } else {
            let (dlo, dhi) = sec.vib_delay;
            (
                sec.off_cents + rng.white() * sec.scatter_cents,
                sec.vib_rate_mul,
                sec.vib_depth_mul,
                dlo,
                dhi,
                sec.drift,
                ch2_reg_weight(key, sec.reg),
            )
        };
        let ratio = 2f32.powf(cents / 1200.0);
        let phase = rng.white() * 0.5 + 0.5;
        let vib_phase = rng.white() * PI;
        let vib_rate = 4.6 * rate_mul * (1.0 + 0.15 * rng.white());
        let vib_delay_s = dlo + (dhi - dlo) * (rng.white() * 0.5 + 0.5);
        let vib_ramp_s = 0.5 + 0.7 * (rng.white() * 0.5 + 0.5); // 0.5-1.2 s
        singers.push(Ch2Singer {
            osc: BlepSaw::new(f * ratio, sr, phase),
            ratio,
            vib_phase,
            vib_rate,
            vib_depth: 0.006 * depth_mul,
            vib_delay: (vib_delay_s * sr) as u32,
            vib_ramp_s,
            drift: Drift::new(seed ^ (0x2C41 + i * 977), drift, 2800),
            gain,
        });
    }
    // Renormalise the mean singer gain to 1 so register weighting reshapes the
    // section balance without moving the overall level across the keyboard.
    let sum: f32 = singers.iter().map(|s| s.gain).sum();
    if sum > 0.0 {
        let k = singers.len() as f32 / sum;
        for s in &mut singers {
            s.gain *= k;
        }
    }

    // Four tracts, each with its own ±CH2_FSCAT formant scatter. Built at the
    // closed schwa; the morph retunes the vowel bands toward `tgt`.
    let tracts = std::array::from_fn(|_| {
        let mut fscat = [1.0f32; 5];
        for m in &mut fscat {
            *m = 1.0 + CH2_FSCAT * rng.white();
        }
        let bands = std::array::from_fn(|k| {
            if k < 3 {
                Biquad::bandpass(CH2_SCHWA[k] * fscat[k], qs[k], sr)
            } else {
                let (sf, sq) = CH2_SF[k - 3];
                Biquad::bandpass(sf * fscat[k], sq, sr)
            }
        });
        Ch2Tract { bands, fscat }
    });

    // Soft consonant onset (generalised hum_hold): velocity shortens the hold,
    // the program scales it; the onset puff is shaped by the tract it feeds.
    let hum_hold_s = 0.11 * (1.3 - 0.6 * vn) * hold_mul;
    let breath0 = 0.10 * (0.3 + 0.7 * vn) * br_mul;

    ChoirV2 {
        singers,
        tracts,
        cur: CH2_SCHWA,
        tgt,
        qs,
        vgains,
        sf_gains,
        sf_ref_g3: vgains[2],
        sf_open: 1.0,
        base_f: f,
        bend: 1.0,
        env: Adsr::new(vel_attack(0.28, vel), 0.3, 0.9, 0.4, sr),
        breath_env: breath0,
        breath_mul: t60_mul(CH2_BREATH_T60, sr),
        hum_hold: (hum_hold_s * sr) as u32,
        mouth: 0.0,
        hum_lp: OnePole::lowpass(CH2_HUM_LP.0, sr),
        chest_lp: Biquad::lowpass(CH2_CHEST_LP_HZ, 0.6, sr),
        chest_gain,
        rng,
        t: 0,
        amp: CH2_AMP * amp_mul * vel_amp(vel),
        sr,
    }
}

impl ChoirV2 {
    fn control_tick(&mut self) {
        let sr = self.sr;
        let t = self.t;
        // per-singer delayed/ramped vibrato + drift
        for s in &mut self.singers {
            s.vib_phase += TAU * s.vib_rate * CTRL as f32 / sr;
            let ramp = if t > s.vib_delay {
                (((t - s.vib_delay) as f32) / sr / s.vib_ramp_s).min(1.0)
            } else {
                0.0
            };
            let vib = if ramp > 0.0 {
                s.vib_depth * ramp * s.vib_phase.sin()
            } else {
                0.0
            };
            let drift = s.drift.next();
            s.osc
                .set_freq(self.base_f * s.ratio * self.bend * (1.0 + vib + drift), sr);
        }
        // vowel morph — frozen at the schwa during the consonant hold
        if t >= self.hum_hold {
            for i in 0..3 {
                if (self.tgt[i] - self.cur[i]).abs() > 1.0 {
                    self.cur[i] += CH2_MORPH * (self.tgt[i] - self.cur[i]);
                    for tr in &mut self.tracts {
                        tr.bands[i].retune_bandpass(self.cur[i] * tr.fscat[i], self.qs[i], sr);
                    }
                }
            }
            self.mouth += CH2_MOUTH_RATE * (1.0 - self.mouth);
        }
        // singer's-formant cluster shade: closed vowels ("mm") mute the ring
        self.sf_open = (self.vgains[2] / self.sf_ref_g3.max(1e-3)).min(1.3);
        // closed-lips lowpass opens with the mouth
        let cut = CH2_HUM_LP.0 + (CH2_HUM_LP.1 - CH2_HUM_LP.0) * self.mouth * self.mouth;
        self.hum_lp.set_cutoff(cut, sr);
    }
}

#[cfg(test)]
impl ChoirV2 {
    /// CH2-O5 structural accessors: per-singer vibrato rates (Hz) and onset
    /// delays (samples) — the decorrelation that makes ensemble shimmer.
    fn singer_vib_rates(&self) -> Vec<f32> {
        self.singers.iter().map(|s| s.vib_rate).collect()
    }
    fn singer_vib_delays(&self) -> Vec<u32> {
        self.singers.iter().map(|s| s.vib_delay).collect()
    }
}

impl Voice for ChoirV2 {
    fn render(&mut self, out: &mut [f32]) -> bool {
        for o in out.iter_mut() {
            if self.t.is_multiple_of(CTRL) {
                self.control_tick();
            }
            let breath_now = CH2_BREATH_SUS + self.breath_env;
            let mut s = 0.0;
            let mut dry = 0.0;
            for (sec, tr) in self.tracts.iter_mut().enumerate() {
                // section pair summed pre-tract, breath injected pre-tract so
                // the air is vowel-coloured, decorrelated across sections
                let a = &mut self.singers[sec * 2];
                let mut x = a.osc.next() * a.gain;
                let b = &mut self.singers[sec * 2 + 1];
                x += b.osc.next() * b.gain;
                x += self.rng.white() * breath_now;
                dry += x;
                let mut y = 0.0;
                for k in 0..3 {
                    y += tr.bands[k].process(x) * self.vgains[k];
                }
                for k in 0..2 {
                    y += tr.bands[3 + k].process(x) * self.sf_gains[k] * self.sf_open;
                }
                s += y;
            }
            s /= self.singers.len() as f32;
            // Klatt voicing branch: the sung fundamental in parallel with the
            // formant bank (which has no band below F1). Runs through the same
            // mouth/lips chain below, so a closed hum stays closed. Gated so a
            // zero-gain program (54) renders bit-identically to pre-chest.
            if self.chest_gain > 0.0 {
                s += self.chest_lp.process(dry / self.singers.len() as f32) * self.chest_gain;
            }
            s = self.hum_lp.process(s);
            s *= CH2_HUM_GAIN + (1.0 - CH2_HUM_GAIN) * self.mouth;
            self.breath_env *= self.breath_mul;
            *o += s * self.amp * self.env.next();
            self.t += 1;
        }
        self.env.alive()
    }

    fn note_off(&mut self) {
        self.env.release();
    }

    fn released(&self) -> bool {
        self.env.released()
    }

    fn set_pitch(&mut self, mult: f32) {
        self.bend = mult;
    }

    fn legato_to(&mut self, key: u8, _vel: u8) -> bool {
        // a melisma: the ringing choir retunes on one vowel — no fresh
        // consonant, breath puff or attack
        self.base_f = key_freq(key);
        true
    }

    fn set_vowel(&mut self, freqs: [f32; 3], qs: [f32; 3], gains: [f32; 3]) {
        self.tgt = freqs;
        self.qs = qs;
        self.vgains = gains;
    }

    #[cfg(test)]
    fn kind(&self) -> &'static str {
        "choir2"
    }
}

/// GM synth pads (88-95). Each of the eight is a distinct identity over the
/// shared `SawStack` (Stage 2 of the stages-2-5 HLD). Two are FROZEN bit-for-bit
/// because they carry almost all committed pad usage — 89 warm (19 albums) and 95
/// sweep (8) — and the moving six each get an identity axis the base pad lacked,
/// chiefly the one-shot filter envelope (`with_fenv`). The FX-family aliases
/// 97/99/103 (base pad) and 101 (dispatched as `pad(95)`) fall through to the
/// frozen arms until Stage 3 gives the FX family its own voice.
/// Transverse mode ratios of an ideal free-free BAR — the glockenspiel /
/// tubular-bell series (1 : 2.756 : 5.404 : 8.933). GM 93's inharmonic layers
/// (MM-REQ-KILN-00023). Mode 4 is left out: at C4 it lands at 2.3 kHz, above the
/// preset's 1600 Hz cutoff, so it would cost a layer to buy almost nothing.
const PAD93_BAR_MODE_2: f32 = 2.756;
const PAD93_BAR_MODE_3: f32 = 5.404;

fn pad(program: u8, key: u8, vel: u8, sr: f32, seed: u32) -> SawStack {
    match program {
        // 95 sweep — FROZEN. The sweep IS the instrument (1.8 octaves of slow
        // resonant travel). Verbatim from the pre-Stage-2 voice.
        95 => SawStack::new(
            key,
            vel,
            sr,
            seed,
            5,
            0.010,
            0.0030,
            StackFilter::Lp(Biquad::lowpass(900.0, 1.1, sr)),
            Adsr::new(0.9, 0.5, 1.0, 1.8, sr),
            (0.0, 0.0, 0.0),
            0.0,
            Some((0.07, 350.0, 1.8)),
            1.1,
            0.42,
        ),
        // 88 new age — a STRUCK pad: a bright resonant onset decaying into a soft
        // dark bed (fenv 5.0 -> 1.0 over a 900 Hz base). The only pad with an
        // onset *event*; unreachable without the filter envelope.
        88 => SawStack::new(
            key,
            vel,
            sr,
            seed,
            5,
            0.008,
            0.0030,
            StackFilter::Lp(Biquad::lowpass(900.0, 1.4, sr)),
            Adsr::new(0.25, 0.5, 1.0, 1.5, sr),
            (0.0, 0.0, 0.0),
            0.0,
            None,
            1.4,
            0.42,
        )
        .with_fenv(5.0, 0.45, 900.0),
        // 90 polysynth — the pad that PLAYS: an order-of-magnitude faster attack
        // than 89, wide audible detune, short release (chords must clear). A
        // light bright-onset fenv — the classic "pluck into pad".
        90 => SawStack::new(
            key,
            vel,
            sr,
            seed,
            7,
            0.020,
            0.0025,
            StackFilter::Lp(Biquad::lowpass(3200.0, 1.0, sr)),
            Adsr::new(0.08, 0.35, 0.85, 0.5, sr),
            (0.0, 0.0, 0.0),
            0.0,
            None,
            1.0,
            0.36,
        )
        .with_fenv(2.2, 0.30, 3200.0),
        // 91 choir — FORMANTS by default (a sung "aah", not a filtered saw): the
        // family's one purely-spectral identity. Static vowel (cur == tgt, so
        // control_tick does not morph); CC70 still retargets via set_vowel. A
        // slow delayed per-layer vibrato is the singers' wobble.
        91 => {
            let freqs = [660.0, 1120.0, 2600.0];
            let qs = [9.0, 10.0, 9.0];
            let gains = [1.0, 0.55, 0.28];
            SawStack::new(
                key,
                vel,
                sr,
                seed,
                5,
                0.008,
                0.0040,
                StackFilter::Formant {
                    bands: [
                        Biquad::bandpass(freqs[0], qs[0], sr),
                        Biquad::bandpass(freqs[1], qs[1], sr),
                        Biquad::bandpass(freqs[2], qs[2], sr),
                    ],
                    gains,
                    cur: freqs,
                    tgt: freqs,
                    qs,
                },
                Adsr::new(0.7, 0.5, 1.0, 1.6, sr),
                (4.6, 0.004, 0.35),
                0.0,
                None,
                0.7,
                1.5,
            )
        }
        // 92 bowed — NO onset: the filter opens *with* the amplitude over ~1.5 s,
        // like a bow taking the string. The inverse fenv (starts at 0.30× the
        // cutoff and rises). No sweep — a wobble would fight the swell.
        92 => SawStack::new(
            key,
            vel,
            sr,
            seed,
            5,
            0.006,
            0.0035,
            StackFilter::Lp(Biquad::lowpass(2000.0, 2.2, sr)),
            Adsr::new(1.6, 0.8, 1.0, 2.2, sr),
            (3.6, 0.0025, 0.9),
            0.0,
            None,
            2.2,
            0.44,
        )
        .with_fenv(0.30, 1.4, 2000.0),
        // 93 metallic — a resonant CLANG with GENUINELY INHARMONIC partials
        // (MM-REQ-KILN-00003's sibling, MM-REQ-KILN-00023). A narrow pulse
        // (even-rich, buzzy) under a self-resonant lowpass (Q 6.5) that clangs on
        // the fenv onset and shimmers via a fast shallow sweep — and, on top of
        // that harmonic body, two oscillator layers tuned to NON-integer ratios.
        //
        // The ratios are physics, not taste: 1 : 2.756 : 5.404 are the transverse
        // mode frequencies of an ideal free-free BAR (the glockenspiel / tubular-
        // bell series), which is why struck metal reads as metal and not as a
        // pitched pipe. Laying them in as interval layers — the same
        // `push_interval_layer` machinery the 86 fifth and 87 sub-octave use —
        // keeps the voice a SUSTAINING pad, which a `Modal` bell (the route the
        // old comment here proposed) could not: a Modal rings and decays, and
        // GM 93 has to hold under a held key.
        //
        // Gains sit under the harmonic body on purpose: the brief is "metallic
        // pad", so the written pitch must stay the tonal centre and the
        // inharmonic modes colour it. Distinct seeds keep the two layers'
        // phase/drift decorrelated (`push_interval_layer` salts from the seed it
        // is given, so passing the same one twice would start both in step).
        93 => {
            let mut s = SawStack::new_wave(
                key,
                vel,
                sr,
                seed,
                4,
                0.014,
                0.0030,
                StackFilter::Lp(Biquad::lowpass(1600.0, 6.5, sr)),
                Adsr::new(0.15, 0.6, 0.8, 1.0, sr),
                (0.0, 0.0, 0.0),
                0.0,
                Some((0.9, 1600.0, 0.35)),
                6.5,
                0.26,
                Wave::Pulse(0.22),
            )
            .with_fenv(4.0, 0.18, 1600.0);
            s.push_interval_layer(Wave::Pulse(0.22), PAD93_BAR_MODE_2, 0.45, 0.0030, seed);
            s.push_interval_layer(
                Wave::Pulse(0.22),
                PAD93_BAR_MODE_3,
                0.30,
                0.0030,
                seed ^ 0x9E37_79B9,
            );
            s
        }
        // 94 halo — AIR: a soft tonal core almost buried in a *swept band of
        // noise*. The only pad where noise is first-class; injected pre-filter,
        // so the sweep shapes the noise band as much as the tone (free shimmer).
        94 => SawStack::new(
            key,
            vel,
            sr,
            seed,
            5,
            0.012,
            0.0045,
            StackFilter::Lp(Biquad::lowpass(700.0, 2.4, sr)),
            Adsr::new(0.9, 0.6, 1.0, 2.0, sr),
            (0.0, 0.0, 0.0),
            0.40,
            Some((0.19, 700.0, 1.6)),
            2.4,
            0.34,
        ),
        // 89 warm — FROZEN (19 albums): the reference pad, its identity is
        // negative space. Also the fall-through for the FX-family base-pad
        // aliases 97/99/103. Verbatim from the pre-Stage-2 else branch (which set
        // no vowel for these — 91 is now its own formant arm above).
        _ => SawStack::new(
            key,
            vel,
            sr,
            seed,
            5,
            0.010,
            0.0030,
            StackFilter::Lp(Biquad::lowpass(1400.0, 0.6, sr)),
            Adsr::new(0.6, 0.5, 1.0, 1.4, sr),
            (0.0, 0.0, 0.0),
            0.0,
            Some((0.13, 1100.0, 0.5)),
            0.7,
            0.42,
        ),
    }
}

/// GM 85's vowel, given as a POSITION in the shared CC70 vowel bank rather than
/// as its own copy of the formant numbers: 84.0 is the bank's "ah" anchor
/// (`engine::VOWEL_ANCHORS`). Deriving it means a retune of the vowel table
/// moves the choir and the voice lead together, instead of leaving a second
/// hand-maintained table to drift (MM-REQ-KILN-00022).
const LEAD85_VOWEL_CC: f32 = 84.0;

/// GM 84's tanh drive depth (MM-REQ-KILN-00021). The charang is defined by a
/// driven, edgy character, which no cutoff setting can produce: a filter can
/// only REMOVE harmonics, and the patch's identity is harmonics that are not in
/// the oscillator at all. Engineering gut-feel — this box has no ears; the
/// oracle asserts that a nonlinearity is present and that it does not alias,
/// not that the amount is tasteful.
const LEAD84_DRIVE: f32 = 3.0;

/// The shaper's OPERATING POINT: the input amplitude at which the drive stage
/// has exactly unity gain, `tanh(drive·x)/x = 1`. It is what keeps the drive a
/// TIMBRE control rather than a volume knob.
///
/// SOLVED, not guessed. The stage's RMS gain on this voice measures 1.918x, so
/// the value is the root of `tanh(LEAD84_DRIVE · x) / x = 1.918`, which lands at
/// 0.46 — nearer the waveform's peak than its RMS, because a tanh's compression
/// is dominated by the peaks it flattens. Change `LEAD84_DRIVE` and this must be
/// re-solved; LD-O2(c) fails if the two drift apart.
///
/// Both obvious normalisations move the level instead of the timbre, which is
/// why neither is used: dividing by `tanh(drive)` maps full scale to full scale,
/// but this voice never approaches full scale, so the stage runs at nearly its
/// 3x small-signal gain and the patch jumps +5.7 dB; dividing by `drive` (unity
/// small-signal) leaves the compression uncompensated, about -3.8 dB. A patch
/// that got 5.7 dB louder would pass an "it sounds edgier" ear test for entirely
/// the wrong reason — and would unbalance the five album tracks that play GM 84.
const LEAD84_NOMINAL: f32 = 0.46;

/// Broadband make-up for GM 85's vocal formant bank, in dB.
///
/// `ec8bfd7` replaced GM 85's velocity-tracked lowpass with three vocal formant
/// bandpasses and landed them WITHOUT compensating for how much less broadband
/// energy a narrow bandpass bank passes. GM 85 lost 16.0 dB and fell out of the
/// M-CAL anchor cohort (MM-BUG-KILN-00108). Its sibling GM 84, in that same
/// commit, did get its make-up — see `LEAD84_NOMINAL` directly above.
///
/// 16.0 dB is measured, not fitted. The 2026.07.25 closed-loop re-derive put the
/// fall at 16.08 dB against a Roland SC-55mkII and 15.95 dB against a Yamaha
/// S-YXG50 — two independent references agreeing to 0.13 dB. Restoring exactly
/// that returns GM 85 to the level BOTH references had already blessed before the
/// re-voicing, which is a stronger target than any family median.
///
/// A RESIDUAL TILT IS LEFT IN, deliberately. The loss is register-dependent
/// (-17.2 dB at key 40 against -6.6 dB at key 84, measured against GM 84), because
/// vocal formants sit at ABSOLUTE frequencies and do not transpose with the note —
/// which is what makes a formant read as a voice rather than a filter sweep. A real
/// singer has that tilt too. Flattening it would need a pitch-tracking gain, which
/// is a voicing decision, not a regression fix; see MM-BUG-KILN-00108.
const LEAD85_FORMANT_MAKEUP_DB: f32 = 16.0;

/// Per-program voicing for the GM synth leads (80-87). Kept to the cheap knobs
/// the SawStack already exposes, plus the two per-program identities that could
/// not be reached that way: 84's drive and 85's formants.
struct LeadSpec {
    wave: Wave,
    n_osc: usize,
    detune: f32,
    cutoff: f32,
    q: f32,
    breath: f32,
    /// Authored interval layer: (frequency ratio vs the written pitch, gain
    /// relative to a stock layer); `(0.0, 0.0)` = none. GM 86 authors the
    /// parallel fifth (MM-REQ-KILN-00019), GM 87 the sub-octave
    /// (MM-REQ-KILN-00020). Amounts are engineering gut-feel — this box has
    /// no ears; the oracles assert presence and tracking, not taste.
    interval: (f32, f32),
    /// Position in the shared CC70 vowel bank whose formants REPLACE this
    /// program's lowpass. `None` = the plain velocity-tracked lowpass (every
    /// lead but 85). GM 85 is "Lead 6 (voice)", so its defining character is
    /// spectral, not a filter setting (MM-REQ-KILN-00022).
    vowel_cc: Option<f32>,
    /// tanh drive depth applied AFTER the filter (0.0 = a clean lead). GM 84
    /// ("charang") is the driven patch of the family (MM-REQ-KILN-00021); every
    /// other lead passes 0.0 and its render is bit-identical (the render loop
    /// branches on `> 0.0` outside the multiply).
    drive: f32,
}

const LEADS: [LeadSpec; 8] = [
    // 80 square lead — hollow, focused pulse
    LeadSpec {
        wave: Wave::Pulse(0.5),
        n_osc: 2,
        detune: 0.004,
        cutoff: 3400.0,
        q: 1.0,
        breath: 0.0,
        interval: (0.0, 0.0),
        vowel_cc: None,
        drive: 0.0,
    },
    // 81 saw lead — the classic (the one used by albums)
    LeadSpec {
        wave: Wave::Saw,
        n_osc: 3,
        detune: 0.006,
        cutoff: 3000.0,
        q: 1.1,
        breath: 0.0,
        interval: (0.0, 0.0),
        vowel_cc: None,
        drive: 0.0,
    },
    // 82 calliope — rounder pulse, breathy, no detune
    LeadSpec {
        wave: Wave::Pulse(0.5),
        n_osc: 1,
        detune: 0.0,
        cutoff: 2200.0,
        q: 0.8,
        breath: 0.015,
        interval: (0.0, 0.0),
        vowel_cc: None,
        drive: 0.0,
    },
    // 83 chiff — airy saw
    LeadSpec {
        wave: Wave::Saw,
        n_osc: 2,
        detune: 0.005,
        cutoff: 2800.0,
        q: 1.0,
        breath: 0.05,
        interval: (0.0, 0.0),
        vowel_cc: None,
        drive: 0.0,
    },
    // 84 charang — brightest, edgiest saw
    LeadSpec {
        wave: Wave::Saw,
        n_osc: 3,
        detune: 0.012,
        cutoff: 4200.0,
        q: 1.4,
        breath: 0.0,
        interval: (0.0, 0.0),
        vowel_cc: None,
        drive: LEAD84_DRIVE,
    },
    // 85 voice lead — softer, breathy saw
    LeadSpec {
        wave: Wave::Saw,
        n_osc: 3,
        detune: 0.008,
        cutoff: 2500.0,
        q: 1.2,
        breath: 0.02,
        interval: (0.0, 0.0),
        vowel_cc: Some(LEAD85_VOWEL_CC),
        drive: 0.0,
    },
    // 86 fifths — saw pair + an authored parallel-fifth layer at 2^(7/12)
    // (MM-REQ-KILN-00019); the fifth sits just under unison gain so the
    // written pitch stays the tonal centre
    LeadSpec {
        wave: Wave::Saw,
        n_osc: 2,
        detune: 0.006,
        cutoff: 3000.0,
        q: 1.1,
        breath: 0.0,
        interval: (1.498_307, 0.85),
        vowel_cc: None,
        drive: 0.0,
    },
    // 87 bass+lead — darker saw + an envelope-locked sub-octave bass layer
    // (MM-REQ-KILN-00020); the sub rides the same env/filter as the lead.
    // Gain 0.55 not 0.90: at 0.90 the sub was the DOMINANT spectral line and
    // o_pitch_melodic_programs_model correctly read the patch an octave low —
    // the req wants bass UNDER the lead, so the lead must stay the voice.
    LeadSpec {
        wave: Wave::Saw,
        n_osc: 2,
        detune: 0.005,
        cutoff: 2400.0,
        q: 1.0,
        breath: 0.0,
        interval: (0.5, 0.55),
        vowel_cc: None,
        drive: 0.0,
    },
];

/// GM synth leads (80-87): a `SawStack` voiced for a lead — fast
/// velocity-tracked attack, short release, a velocity-tracked filter, and a
/// pulse oscillator for the square-lead class. CC1 vibrato and CC68 legato come
/// from the engine; `legato_enabled` opts this instance into slurs.
fn lead(program: u8, key: u8, vel: u8, sr: f32, seed: u32) -> SawStack {
    let spec = &LEADS[(program - 80) as usize];
    // TIMBRE, not level — exempt from the k=2 law (HLD velocity-law §2.4). This is a
    // filter CUTOFF: velocity opens the lead's brightness. Folding it as if it were a
    // level floor would silently turn a timbre control into a gain.
    let cutoff = (spec.cutoff * (0.55 + 0.45 * vel_ctrl(vel))).min(sr * 0.45);
    // GM 85 (voice) speaks through a vocal formant bank instead of the lowpass:
    // "Lead 6 (voice)" is a SPECTRAL identity — three resonant bands at the
    // vowel's formants — which no cutoff setting on a saw can imitate
    // (MM-REQ-KILN-00022). Every other lead keeps the velocity-tracked lowpass.
    //
    // `cur` is left at `tgt`, so the bank is static from the first sample, the
    // way choir 91 does it: the "mm-ah" onset morph belongs to a sung entry, and
    // a lead has to speak immediately. Velocity still tracks amplitude and the
    // ADSR; it no longer opens a cutoff on this one program, because there is no
    // cutoff to open — the formants ARE the timbre.
    let filt = match spec.vowel_cc {
        Some(pos) => {
            let (freqs, qs, gains) = crate::engine::vowel_at(pos);
            StackFilter::Formant {
                bands: [
                    Biquad::bandpass(freqs[0], qs[0], sr),
                    Biquad::bandpass(freqs[1], qs[1], sr),
                    Biquad::bandpass(freqs[2], qs[2], sr),
                ],
                gains,
                cur: freqs,
                tgt: freqs,
                qs,
            }
        }
        None => StackFilter::Lp(Biquad::lowpass(cutoff, spec.q, sr)),
    };
    let mut s = SawStack::new_wave(
        key,
        vel,
        sr,
        seed,
        spec.n_osc,
        spec.detune,
        0.002, // light per-layer drift — leads sit tighter than pads
        filt,
        Adsr::new(vel_attack(0.010, vel), 0.06, 0.82, 0.10, sr),
        (0.0, 0.0, 0.0), // no always-on vibrato — CC1 mod wheel provides it
        spec.breath,
        None, // no filter sweep (that stays a pad feature)
        spec.q,
        0.50,
        spec.wave,
    );
    s.legato_enabled = true;
    if spec.vowel_cc.is_some() {
        s.formant_makeup = 10f32.powf(LEAD85_FORMANT_MAKEUP_DB / 20.0);
    }
    if spec.drive > 0.0 {
        s.drive = spec.drive;
        s.drive_norm = (spec.drive * LEAD84_NOMINAL).tanh() / LEAD84_NOMINAL;
    }
    if spec.interval.0 > 0.0 {
        s.push_interval_layer(spec.wave, spec.interval.0, spec.interval.1, 0.002, seed);
    }
    s
}

// ---------------------------------------------------------------------------
// Wind — the GM pipe / flue family (72-79)
// ---------------------------------------------------------------------------
// Air-jet (edge-tone) instruments. ONE voice + a per-program preset table — the
// shape the Reed family (64-71) proved. The key move: **bore class lives in the
// DATA, not in code.** A stopped pipe (pan flute) is a preset whose EVEN
// harmonic slots are 0.0; a Helmholtz vessel (bottle / ocarina / whistle) is a
// preset whose ladder is one weak entry. One mechanism (an amplitude table),
// eight identities — so `render` carries no per-instrument branch.
//
// Design + oracle spec: see the WD-O suite in `mod tests` and
// `wrk_docs/2026.07.11 - HLD - woodwind and synthwide LA synthesis ...` §7.1.
// This voice needs nothing from the engine beyond set_pitch / legato_to.
// ---------------------------------------------------------------------------

const WD_SCOOP_K: f32 = 0.05; // onset-scoop settle per control tick
/// Velocity normal at which the preset table reads DIRECTLY off the render
/// (`bright` == 1.0 at vel 100, mid-register) — so the table is the spectrum.
const WD_VN0: f32 = 100.0 / 127.0;
/// Partials above this fraction of `sr` are gated off rather than folded.
const WD_ALIAS_LIM: f32 = 0.44;

// --- Stage 1 (round-3 feedback): the breath flutter ------------------------
// The sustain breath rode a ±50% AM LOCKED to the pitch vibrato (4.5-5.5 Hz).
// That sits on the ~4 Hz fluctuation-strength peak (Fastl/Zwicker) and, on the
// loud-breath pipes (pan flute / bottle / shakuhachi), reads as the "shaking
// sshsshssh" of round-3 feedback. Replace it with a shallow, slow, DECORRELATED
// flutter — a control-rate LFO off the pitch vibrato and off the 4 Hz peak, so
// the breath drifts naturally instead of pulsing. WD_FLUTTER_HZ = 2.0 sits well
// clear of the 4.5-5.5 Hz pitch-vib rate (and, being a near-pure sine, carries
// negligible energy at its 4.0 Hz 2nd harmonic), so the breath-AM oracle cleanly
// separates the two. Built from a SEPARATE rng (seed ^ SALT) so
// `self.rng` — the render-loop noise stream — keeps its exact draw sequence:
// the WD-O5 differential seam and every wind's underlying noise are untouched;
// only the AM envelope moves. Zero-mean, so the MEAN breath level is unchanged.
const WD_FLUTTER_HZ: f32 = 2.0;
const WD_FLUTTER_DEPTH: f32 = 0.12; // was 0.5 on the pitch-vib LFO
const WD_FLUTTER_JIT: f32 = 0.08; // per-note rate jitter (matches the vib LFO)
const WD_FLUTTER_SALT: u32 = 0xF107_7E45; // decorrelate the flutter rng from self.rng

// --- WD9 (§2.8.5.2-3): the flue blowing-pressure law -----------------------
// The RD9 law verbatim (`RD_P_VEL`/`RD_P_VEL_EXP`/`RD_P_ENV`/`RD_P_SMOOTH_S`/
// `RD_P_AUTH_SPAN` are shared, not copied, so reed and flue pressure cannot
// drift apart): p = clamp(vel_floor + env·speak + authored CC2/CC11), smoothed
// ~15 ms at CTRL rate. `bright` and `vel_air` — spawn-fixed before WD9 — now
// track p. Honesty scoping (§2.8.2): on today's albums only the vel floor
// moves, so this is note-to-note velocity brightening plus onset speak;
// within-note breathing is authored-content only.

/// p at vel ≈ 100, mid-register sustain — the anchor at which the preset
/// table reads directly off the render (the flue analogue of `bright` == 1.0
/// at `WD_VN0`). Provenance: RD9 law at vel 100, sustain 0.92:
/// 0.06 + 0.845·(100/127)^1.5 + 0.11·0.92 = 0.7515.
const WD_P_ANCHOR: f32 = 0.7515;
/// Maps (p − anchor) onto the old (vn − WD_VN0) span so the vel-127 end of
/// the ladder lands where the accepted spawn law put it: at vel 127,
/// p − anchor = 0.2485 and vn − WD_VN0 = 1 − 100/127 = 0.2126.
const WD_P_GAIN: f32 = (1.0 - WD_VN0) / 0.2485;
/// `vel_air` in p-coordinates: air(p) = WD_AIR.0 + WD_AIR.1·p², anchored so
/// air(WD_P_ANCHOR) = 1.001 = the old 0.35 + 1.05·vn² at vel 100 — harder
/// blowing stays amplitude-quadratic in the driving signal (turbulence grows
/// super-linearly with jet speed), now within the note as well as across it.
const WD_AIR: (f32, f32) = (0.35, 1.1526);

// --- WD10 (§2.8.5.1): the split onset chiff --------------------------------
// Before the split the single f0-tracked breath bandpass fed BOTH the
// sustained bed AND the onset chiff, so the chiff could not be the broadband
// edge-tone burst a flue attack actually is. The chiff now has its own
// highpassed white burst (the Reed/Pluck `onset_post` precedent), independent
// of the bed.

/// Edge-tone burst highpass floor (Hz); per-note the cutoff is
/// max(floor, 1.2·f0) so the "tuh" always sits above the fundamental.
const WD_CHIFF_HP_HZ: f32 = 1800.0;
/// Broadband-burst level normalisation: a Q-0.7 highpass passes ~0.55 of
/// white RMS where the old narrowband bed bandpass passed ~0.20 (pan flute at
/// its WD-O8 probe key), so 0.36 keeps the preset `chiff` table meaning what
/// it always meant. Verified against WD-O8's absolute floors.
const WD_CHIFF_NORM: f32 = 0.36;

// --- WD11 (§2.8.5.4): the GM 76 Helmholtz resonator ------------------------
/// Resonator Q: ring τ = Q/(π·f0) ⇒ T60 ≈ 0.54 s at range bottom (key 48),
/// 0.17 s at mid — a bottle's short "boop" tail, pinned by WD-O12.
const WD_HELM_Q: f32 = 32.0;
/// Whisper-of-tone scale on the sine bank: the additive core drops to a
/// pitch anchor (~25 % of steady energy) and the filtered jet becomes the
/// PRIMARY source — the topology fix. (The old voice was ~99 % sine.)
const WD_HELM_TONE: f32 = 0.52;
/// Excitation gain anchor. The constant-peak-gain bandpass emits
/// noise RMS ∝ √(f0/Q), so the drive carries √(Q·sr/f0) — the §2.8.5.4 gain
/// normalisation across keys (pinned by WD-O13) — times this level trim
/// (measured: re-anchors the steady render at vel 100 mid-key to the
/// pre-Helmholtz bottle level, WD-O11's +0.2 dB vs flute).
const WD_HELM_DRIVE: f32 = 0.52;
/// Broadband jet spill (the "airier" of the pressure leg): gain on the
/// shaped jet mixed straight into the output (× breath·air), growing with p
/// as (lo + span·p, ≈ 1.0 at the anchor) — harder blowing spills more jet
/// noise past the resonance. Level trim measured at the WD-O13 probe.
const WD_HELM_SPILL: f32 = 1.59;
const WD_HELM_SPILL_P: (f32, f32) = (0.25, 1.0);
/// Excitation-shaping one-pole cutoff = f0·(lo + span·p): harder blowing
/// widens the excitation band (the "slightly wider" of the pressure leg).
const WD_HELM_LP: (f32, f32) = (1.5, 2.5);
/// Ring-follower floor: the voice stays alive until the resonator's own
/// ring (tracked by a peak follower) falls below this — the §2.8.5.4
/// released()/alive bookkeeping that keeps the ring from truncating.
const WD_HELM_RING_FLOOR: f32 = 1e-4;

/// A GM pipe program's fixed voicing. All-`pub`, const-constructible.
pub struct WindPreset {
    /// h2..h7 amplitudes relative to h1 = 1.0, at `bright` = 1. The bore class:
    /// stopped pipe zeroes the evens; a vessel keeps one weak entry.
    pub harm: [f32; 6],
    pub vel_bright: f32, // velocity → spectral tilt slope (recorder ≈ 0: it can't be blown open)
    pub reg_dark: f32,   // register → spectral tilt slope (top of range purifies)
    pub breath: f32,     // sustain breath-bed level (through the tracked bandpass)
    pub breath_f: f32,   // bed centre as a MULTIPLE of f0 (vessels sit on f0; pipes above it)
    pub breath_q: f32,   // bed Q (pan-flute halo 0.8 … whistle 4.0 focused)
    pub breath_hi: f32,  // >8 kHz noise shelf (shakuhachi muraiki); 0.0 = filter not built
    pub chiff: f32,      // onset chiff level (× vn × vel_amp — super-linear, Reed convention)
    pub chiff_t60: f32,  // chiff decay
    pub vib: (f32, f32, f32), // (rate Hz, depth, delay s)
    pub attack: f32,     // Adsr attack base (vel_attack-scaled)
    pub release: f32,
    pub scoop: f32,      // onset pitch multiplier start
    pub range: (u8, u8), // MIDI keys for register normalisation
    pub amp: f32,
    /// WD11 (§2.8.5.4): the voice is ONE high-Q resonance excited by breath
    /// (blown bottle), not a harmonic pipe — `breath` becomes the resonator
    /// drive, the sine bank drops to a whisper, and the standard bed is
    /// replaced by the resonator + jet spill.
    pub helmholtz: bool,
    #[cfg(test)]
    pub name: &'static str, // diagnostic label (kind() is always "wind")
}

