/// GM pipe program → its voicing. Anything outside 72..=79 falls back to the flute.
pub fn wind(program: u8) -> &'static WindPreset {
    match program {
        72 => &PICCOLO,
        74 => &RECORDER,
        75 => &PAN_FLUTE,
        76 => &BLOWN_BOTTLE,
        77 => &SHAKUHACHI,
        78 => &WHISTLE,
        79 => &OCARINA,
        _ => &FLUTE,
    }
}

/// WD11 (§2.8.5.4): the GM 76 Helmholtz resonator — real state, so it can
/// ring past release. A constant-peak-gain two-pole bandpass at the sounding
/// f0 (retuned at CTRL with bend/scoop/vib) driven by shaped breath noise as
/// the voice's primary source, plus a broadband jet spill.
struct Helm {
    res: Biquad,     // THE bottle: high-Q bandpass at the sounding pitch
    exc_lp: OnePole, // excitation shaping — cutoff widens with pressure
    drive: f32,      // CTRL-computed excitation gain (key-normalised)
    spill: f32,      // CTRL-computed broadband spill gain
    ring: f32,       // |resonator out| peak follower (alive bookkeeping)
    ring_mul: f32,
}

pub struct Wind {
    osc: [Sine; 7], // h1..h7 (index i renders harmonic i+1)
    amps: [f32; 7], // amps[0] = 1.0 (fundamental); zero slots are never ticked
    // WD9: the preset's spectral law, kept live so the amps retune with
    // pressure at CTRL rate (they were spawn-fixed before §2.8.5).
    harm: [f32; 6],
    vel_bright: f32,
    reg_term: f32,   // reg_dark·(reg − 0.5), fixed per note
    dead: [bool; 7], // alias-gated slots — never resurrected by a retune
    base_f: f32,
    bend: f32,
    scoop: f32, // pitch multiplier settling toward 1.0
    breath_filt: Biquad,
    breath_base: f32, // preset.breath (the WD-O5 differential seam zeroes this)
    breath_amp: f32,  // CTRL-computed: breath_base · air(p)
    hi_filt: Option<Biquad>, // >8 kHz muraiki shelf (shakuhachi only)
    hi_base: f32,
    hi_amp: f32,
    chiff_filt: Biquad, // WD10: the broadband edge-tone burst's own highpass
    chiff_amp: f32,
    chiff_decay: f32,
    helm: Option<Helm>, // WD11: GM 76 only
    // WD9 pressure state (the RD9 law: vel floor + env speak + authored)
    vn: f32,
    p_auth: f32,
    p_sm: f32,
    p_k: f32,
    last_env: f32,
    env: Adsr,
    vib: Sine,
    vib_depth: f32,
    vib_delay: u32,
    vib_val: f32,
    flutter: Sine,    // slow breath-flutter LFO, decorrelated from the pitch vib
    flutter_val: f32, // control-rate flutter value in ~[-1, 1]
    rng: Rng,
    t: u32,
    amp: f32,
    sr: f32,
}

impl Wind {
    fn from_preset(preset: &WindPreset, key: u8, vel: u8, sr: f32, seed: u32) -> Self {
        let f = key_freq(key);
        let vn = vel as f32 / 127.0;
        let mut rng = Rng::new(seed);
        // Register position: 0 at range bottom, 1 at top (out-of-range clamps).
        let (lo, hi) = preset.range;
        let reg = ((key as f32 - lo as f32) / (hi as f32 - lo as f32).max(1.0)).clamp(0.0, 1.0);
        // WD9: blowing pressure at spawn — the RD9 vel floor (env starts at
        // 0; authored CC2/CC11 arrives via set_breath before the first
        // render on authored channels, and the ~15 ms smoother absorbs it).
        let p0 = RD_P_VEL.0 + RD_P_VEL.1 * vn.powf(RD_P_VEL_EXP);
        let reg_term = preset.reg_dark * (reg - 0.5);
        // The spectral-tilt scalar, now in p-coordinates (WD9): normalised so
        // bright == 1.0 at vel 100 mid-register SUSTAIN (p = WD_P_ANCHOR) —
        // i.e. the preset table IS the spectrum at the oracle probe. Harder
        // blowing opens the timbre; the top of the range purifies it.
        let bright = wd_bright(preset.vel_bright, reg_term, p0);

        // Partial amplitudes: upper partials scale super-linearly with `bright`.
        let mut amps = [0.0f32; 7];
        amps[0] = 1.0;
        for (i, a) in amps.iter_mut().enumerate().skip(1) {
            *a = preset.harm[i - 1] * bright.powi(i as i32);
        }
        // Alias gate: a partial above 0.44·sr is silenced, never folded. (0.44
        // leaves headroom for a ±2-semitone bend: 0.44 × 1.122 = 0.494 < Nyquist.)
        // The gate is a one-way MASK: a CTRL-rate pressure retune (WD9) or a
        // downward slur must never resurrect a gated slot.
        let lim = WD_ALIAS_LIM * sr;
        let mut dead = [false; 7];
        for (i, a) in amps.iter_mut().enumerate() {
            if (i + 1) as f32 * f > lim {
                *a = 0.0;
                dead[i] = true;
            }
        }
        // One phase draw per SLOT (even silent ones) so the RNG stream stays
        // aligned across presets with different partial counts — the WD-O5
        // breath-differential seam depends on that.
        let osc = std::array::from_fn(|i| {
            Sine::new(f * (i + 1) as f32, sr, rng.white() * std::f32::consts::PI)
        });

        // Breath bed: a bandpass tracking f0, placed and shaped per bore.
        // Amplitude-quadratic in the pressure (WD9; was vn-quadratic at
        // spawn only) — turbulent noise grows super-linearly with jet speed,
        // so hard blowing is airier and soft playing purer, now within the
        // note as well as across notes.
        let air = WD_AIR.0 + WD_AIR.1 * p0 * p0;
        // WD11: the Helmholtz path replaces the additive-core fake for GM 76.
        let helm = preset.helmholtz.then(|| Helm {
            res: Biquad::bandpass(f.min(sr * 0.4), WD_HELM_Q, sr),
            exc_lp: OnePole::lowpass(f * (WD_HELM_LP.0 + WD_HELM_LP.1 * p0), sr),
            drive: preset.breath * air * (WD_HELM_Q * sr / f).sqrt() * WD_HELM_DRIVE,
            spill: preset.breath
                * air
                * WD_HELM_SPILL
                * (WD_HELM_SPILL_P.0 + WD_HELM_SPILL_P.1 * p0),
            ring: 0.0,
            ring_mul: t60_mul(0.1, sr),
        });
        if helm.is_some() {
            // the sine bank drops to a pitch-anchor whisper
            for a in amps.iter_mut() {
                *a *= WD_HELM_TONE;
            }
        }
        let vibr = preset.vib;
        Wind {
            osc,
            amps,
            harm: preset.harm,
            vel_bright: preset.vel_bright,
            reg_term,
            dead,
            base_f: f,
            bend: 1.0,
            scoop: preset.scoop,
            breath_filt: Biquad::bandpass((preset.breath_f * f).min(sr * 0.4), preset.breath_q, sr),
            breath_base: preset.breath,
            breath_amp: preset.breath * air,
            hi_filt: (preset.breath_hi > 0.0).then(|| Biquad::highpass(8000.0, 0.7, sr)),
            hi_base: preset.breath_hi,
            hi_amp: preset.breath_hi * air,
            chiff_filt: Biquad::highpass(WD_CHIFF_HP_HZ.max(1.2 * f).min(sr * 0.35), 0.7, sr),
            chiff_amp: preset.chiff * vn * vel_amp(vel),
            chiff_decay: t60_mul(preset.chiff_t60, sr),
            helm,
            vn,
            p_auth: 0.0,
            p_sm: p0,
            p_k: 1.0 - (-(CTRL as f32) / (RD_P_SMOOTH_S * sr)).exp(),
            last_env: 0.0,
            env: Adsr::new(
                vel_attack(preset.attack, vel),
                0.05,
                0.92,
                preset.release,
                sr,
            ),
            vib: control_lfo(vibr.0, 0.08, &mut rng, sr),
            vib_depth: vibr.1,
            vib_delay: (vibr.2 * sr) as u32,
            vib_val: 0.0,
            // A SEPARATE throwaway rng so the flutter draws nothing from `self.rng`
            // (the render-loop noise stream stays byte-for-byte aligned — see the
            // WD_FLUTTER_* header and the WD-O5 differential seam).
            flutter: control_lfo(
                WD_FLUTTER_HZ,
                WD_FLUTTER_JIT,
                &mut Rng::new(seed ^ WD_FLUTTER_SALT),
                sr,
            ),
            flutter_val: 0.0,
            rng,
            t: 0,
            amp: preset.amp * vel_amp(vel),
            sr,
        }
    }
}

/// WD9: the flue spectral-tilt scalar in p-coordinates. `WD_P_GAIN` maps the
/// pressure span back onto the accepted (vn − WD_VN0) span, so the vel-127
/// end of the ladder lands where the old spawn law put it and the clamp
/// rails are unchanged.
fn wd_bright(vel_bright: f32, reg_term: f32, p: f32) -> f32 {
    (1.0 + vel_bright * WD_P_GAIN * (p - WD_P_ANCHOR) - reg_term).clamp(0.55, 1.20)
}

impl Voice for Wind {
    fn render(&mut self, out: &mut [f32]) -> bool {
        for o in out.iter_mut() {
            if self.t.is_multiple_of(CTRL) {
                self.scoop += WD_SCOOP_K * (1.0 - self.scoop);
                let v = self.vib.next();
                self.vib_val = v;
                self.flutter_val = self.flutter.next();
                let vib = if self.t > self.vib_delay {
                    let ramp = ((self.t - self.vib_delay) as f32 / (0.2 * self.sr)).min(1.0);
                    self.vib_depth * ramp * v
                } else {
                    0.0
                };
                let f = self.base_f * self.bend * self.scoop * (1.0 + vib);
                for (i, osc) in self.osc.iter_mut().enumerate() {
                    if self.amps[i] > 0.0 {
                        osc.set_freq(f * (i + 1) as f32, self.sr);
                    }
                }
                // WD9 blowing pressure: vel floor + env "speaking" term +
                // authored CC2/CC11 delta — the RD9 law — smoothed ~15 ms.
                let target = (RD_P_VEL.0
                    + RD_P_VEL.1 * self.vn.powf(RD_P_VEL_EXP)
                    + RD_P_ENV * self.last_env
                    + self.p_auth)
                    .clamp(0.0, 1.0);
                self.p_sm += self.p_k * (target - self.p_sm);
                let p = self.p_sm;
                // WD9 tilt: the per-partial amps — spawn-fixed before
                // §2.8.5 — retune from pressure. The alias mask is one-way.
                let bright = wd_bright(self.vel_bright, self.reg_term, p);
                let tone = if self.helm.is_some() {
                    WD_HELM_TONE
                } else {
                    1.0
                };
                for (i, a) in self.amps.iter_mut().enumerate().skip(1) {
                    if !self.dead[i] {
                        *a = self.harm[i - 1] * bright.powi(i as i32) * tone;
                    }
                }
                // WD9 air: the bed level tracks pressure (was vn² at spawn)
                let air = WD_AIR.0 + WD_AIR.1 * p * p;
                self.breath_amp = self.breath_base * air;
                self.hi_amp = self.hi_base * air;
                // WD11: retune the resonator with the sounding pitch and
                // track the pressure leg (louder/airier/slightly wider)
                if let Some(h) = self.helm.as_mut() {
                    h.res
                        .retune_bandpass(f.min(self.sr * 0.4), WD_HELM_Q, self.sr);
                    h.exc_lp
                        .set_cutoff(f * (WD_HELM_LP.0 + WD_HELM_LP.1 * p), self.sr);
                    h.drive = self.breath_base
                        * air
                        * (WD_HELM_Q * self.sr / f.max(1.0)).sqrt()
                        * WD_HELM_DRIVE;
                    h.spill = self.breath_base
                        * air
                        * WD_HELM_SPILL
                        * (WD_HELM_SPILL_P.0 + WD_HELM_SPILL_P.1 * p);
                }
            }
            let mut s = 0.0;
            for (i, osc) in self.osc.iter_mut().enumerate() {
                if self.amps[i] > 0.0 {
                    s += self.amps[i] * osc.next();
                }
            }
            let e = self.env.next();
            self.last_env = e;
            // The breath rides a shallow, slow flutter DECORRELATED from the pitch
            // vibrato — natural air drift, not the deep vib-locked pulse that read as
            // "shaking sshsshssh" on the loud-breath pipes. See the WD_FLUTTER_* header.
            let breath_mod = 1.0 + WD_FLUTTER_DEPTH * self.flutter_val;
            // WD11: on the Helmholtz path the first noise draw IS the jet —
            // shaped, driven through the resonator (excitation dies with the
            // envelope; the resonator state rings on past it), plus spill.
            // The draw count per sample is unchanged, keeping the WD-O5
            // differential seams aligned. `helm_out` is added OUTSIDE the
            // envelope product below — killing the ring with e would
            // re-truncate exactly what the topology fix exists to keep.
            let mut helm_out = 0.0;
            if let Some(h) = self.helm.as_mut() {
                let jet = h.exc_lp.process(self.rng.white()) * e * breath_mod;
                let r = h.res.process(jet * h.drive);
                h.ring = r.abs().max(h.ring * h.ring_mul);
                helm_out = r + jet * h.spill;
            } else {
                let noise = self.breath_filt.process(self.rng.white());
                s += noise * self.breath_amp * e * breath_mod;
            }
            // The second RNG draw is gated on the FILTER, not on hi_amp, so a test
            // that zeroes hi_amp keeps this stream aligned with its twin.
            if let Some(hf) = self.hi_filt.as_mut() {
                s += hf.process(self.rng.white()) * self.hi_amp * e * breath_mod;
            }
            // The chiff sits OUTSIDE the envelope (the Reed/Brass onset convention):
            // a fresh attack spits at t=0 while the envelope is still ramping. Inside
            // it, the old flute's chiff was largely swallowed by its own 50 ms attack.
            // WD10: its source is a dedicated broadband highpassed burst (own RNG
            // draw, unconditional — stream alignment), no longer the bed bandpass.
            let burst = self.chiff_filt.process(self.rng.white());
            let chiff = burst * WD_CHIFF_NORM * self.chiff_amp * self.amp;
            self.chiff_amp *= self.chiff_decay;
            *o += (s * e + helm_out) * self.amp + chiff;
            self.t += 1;
        }
        // WD11: the resonator keeps the voice alive until its ring fades
        self.env.alive()
            || self
                .helm
                .as_ref()
                .is_some_and(|h| h.ring > WD_HELM_RING_FLOOR)
    }

    fn note_off(&mut self) {
        self.env.release();
    }

    fn released(&self) -> bool {
        self.env.released()
    }

    fn set_pitch(&mut self, mult: f32) {
        self.bend = mult;
    }

    fn set_breath(&mut self, pressure: f32, _growl: f32) {
        // WD9 authored seam (§2.8.5.3, the RD9 mirror): the engine feeds
        // √(expr·breath) — CC11 × CC2, neutral 1.0 — ONLY on flue channels
        // that have authored one of them, so an unauthored channel renders
        // controller-identically to before. Authored breath carves DOWNWARD
        // from the velocity anchor (GM expression semantics); the ~15 ms
        // smoother de-zippers the steps. Growl has no flue consumer.
        self.p_auth = RD_P_AUTH_SPAN * (pressure.clamp(0.0, 1.0) - 1.0);
    }

    fn legato_to(&mut self, key: u8, _vel: u8) -> bool {
        // slur: glide from the old pitch via the scoop, keep the air moving
        let new_f = key_freq(key);
        self.scoop = (self.base_f * self.scoop / new_f).clamp(0.85, 1.18);
        self.base_f = new_f;
        self.chiff_amp = 0.0;
        // An upward slur sheds partials that would now alias — a one-way
        // mask, so the WD9 pressure retune can never resurrect them.
        let lim = WD_ALIAS_LIM * self.sr;
        for (i, a) in self.amps.iter_mut().enumerate() {
            if (i + 1) as f32 * new_f > lim {
                *a = 0.0;
                self.dead[i] = true;
            }
        }
        true
    }

    #[cfg(test)]
    fn kind(&self) -> &'static str {
        "wind"
    }
}

// ---------------------------------------------------------------------------
// Bowed solo strings (GM 40-44 / 110)
// ---------------------------------------------------------------------------

const BODY_VIOLIN: [(f32, f32, f32); 3] =
    [(280.0, 1.2, 5.0), (610.0, 1.8, 4.0), (1350.0, 1.5, 3.0)];
const BODY_VIOLA: [(f32, f32, f32); 3] = [(220.0, 1.3, 7.5), (475.0, 1.8, 4.0), (1200.0, 1.6, 3.5)];
const BODY_CELLO: [(f32, f32, f32); 3] = [(105.0, 1.1, 5.5), (220.0, 1.5, 4.5), (650.0, 1.4, 3.5)];
const BODY_CONTRABASS: [(f32, f32, f32); 3] =
    [(62.0, 1.0, 2.5), (115.0, 1.3, 7.5), (380.0, 1.4, 3.0)];

#[derive(Clone, Copy)]
struct BowedPreset {
    body: &'static [(f32, f32, f32); 3],
    press_lo: f32,
    press_span: f32,
    vib_rate: f32,
    vib_depth: f32,
    attack_s: f32,
    bite: f32,
    amp_trim: f32,
    tremolo: bool,
}

const BOWED_VIOLIN: BowedPreset = BowedPreset {
    body: &BODY_VIOLIN,
    press_lo: 900.0,
    press_span: 5200.0,
    vib_rate: 5.3,
    vib_depth: 0.0045,
    attack_s: 0.070,
    bite: 0.100,
    amp_trim: 1.0,
    tremolo: false,
};

fn bowed_preset(program: u8) -> BowedPreset {
    match program {
        41 => BowedPreset {
            body: &BODY_VIOLA,
            press_lo: 800.0,
            press_span: 4200.0,
            vib_rate: 5.1,
            attack_s: 0.090,
            bite: 0.095,
            amp_trim: 0.98,
            ..BOWED_VIOLIN
        },
        42 => BowedPreset {
            body: &BODY_CELLO,
            press_lo: 600.0,
            press_span: 2900.0,
            vib_rate: 4.8,
            attack_s: 0.105,
            bite: 0.090,
            ..BOWED_VIOLIN
        },
        43 => BowedPreset {
            body: &BODY_CONTRABASS,
            press_lo: 350.0,
            press_span: 1700.0,
            vib_rate: 4.2,
            vib_depth: 0.0038,
            attack_s: 0.125,
            bite: 0.085,
            amp_trim: 0.85,
            ..BOWED_VIOLIN
        },
        44 => BowedPreset {
            tremolo: true,
            ..BOWED_VIOLIN
        },
        110 => BowedPreset {
            press_lo: 1800.0,
            press_span: 7000.0,
            vib_rate: 5.6,
            attack_s: 0.052,
            bite: 0.230,
            ..BOWED_VIOLIN
        },
        _ => BOWED_VIOLIN,
    }
}

const BOW_TREM_RATE_LO_HZ: f32 = 6.0;
const BOW_TREM_RATE_VEL_HZ: f32 = 3.0;
const BOW_TREM_DEPTH_LO: f32 = 0.50;
const BOW_TREM_DEPTH_VEL: f32 = 0.15;
const BOW_TREM_BITE_S: f32 = 0.018;
const BOW_TREM_JITTER: f32 = 0.06;
const BOW_TREM_AMP_JITTER: f32 = 0.10;

const PIZZ: PluckPreset = PluckPreset {
    #[cfg(test)]
    name: "PIZZ",
    // Phase-2 Shaped, FINGER slope (steeper → less harsh). Pizzicato stays SHORT
    // (t60 unchanged); the goal is a gentler attack, not a lower att/sus ratio.
    exc_model: ExcModel::Shaped,
    slope: 2.0,
    noise_mix: 0.20,
    exc_trim: 3.16,
    t60: 0.9,
    bright: 2600.0,
    pick_lp: 1600.0,
    pos: 0.30,
    amp: 0.58,
    rel_t60: 0.10,
    body: &BODY_VIOLIN,
    click: 0.6,
    click_hp: 900.0,
    attack_noise: 0.25,
    stop_thump: 0.5,
    ..DEFAULTS
};

pub struct Bowed {
    saw: BlepSaw,
    base_f: f32,
    bend: f32,
    scoop: f32,
    body: [Biquad; 3],
    lp: OnePole, // bow-pressure brightness: opens with the envelope
    press_lo: f32,
    press_span: f32,
    env: Adsr,
    vib: Sine,
    vib_depth: f32,
    vib_delay: u32,
    #[cfg(test)]
    vib_val: f32,
    bite: f32,
    trem_rate: f32,
    trem_rate_cur: f32,
    trem_phase: f32,
    trem_depth: f32,
    trem_stroke_gain: f32,
    trem_gain: f32,
    trem_bite_until: u32,
    rng: Rng,
    t: u32,
    attack_samples: u32,
    last_env: f32,
    amp: f32,
    sr: f32,
}

impl Bowed {
    fn new(program: u8, key: u8, vel: u8, sr: f32, seed: u32) -> Self {
        let f = key_freq(key);
        let mut rng = Rng::new(seed);
        let preset = bowed_preset(program);
        let vn = vel as f32 / 127.0;
        let attack = vel_attack(preset.attack_s, vel);
        let (trem_rate, trem_depth) = if preset.tremolo {
            (
                BOW_TREM_RATE_LO_HZ + BOW_TREM_RATE_VEL_HZ * vn,
                BOW_TREM_DEPTH_LO + BOW_TREM_DEPTH_VEL * vn,
            )
        } else {
            (0.0, 0.0)
        };
        Bowed {
            saw: BlepSaw::new(f * 0.975, sr, rng.white() * 0.5 + 0.5),
            base_f: f,
            bend: 1.0,
            scoop: 0.975 + 0.008 * vn,
            body: [
                Biquad::peak(preset.body[0].0, preset.body[0].1, preset.body[0].2, sr),
                Biquad::peak(preset.body[1].0, preset.body[1].1, preset.body[1].2, sr),
                Biquad::peak(preset.body[2].0, preset.body[2].1, preset.body[2].2, sr),
            ],
            lp: OnePole::lowpass(1400.0, sr),
            press_lo: preset.press_lo,
            press_span: preset.press_span,
            env: Adsr::new(attack, 0.2, 0.9, 0.18, sr),
            vib: control_lfo(preset.vib_rate, 0.1, &mut rng, sr),
            vib_depth: preset.vib_depth,
            vib_delay: (0.22 * sr) as u32,
            #[cfg(test)]
            vib_val: 0.0,
            bite: preset.bite,
            trem_rate,
            trem_rate_cur: trem_rate,
            trem_phase: 0.0,
            trem_depth,
            trem_stroke_gain: 1.0,
            trem_gain: 1.0,
            trem_bite_until: 0,
            rng,
            t: 0,
            attack_samples: (attack * sr) as u32,
            last_env: 0.0,
            amp: 0.40 * vel_amp(vel) * preset.amp_trim,
            sr,
        }
    }
}

impl Voice for Bowed {
    fn render(&mut self, out: &mut [f32]) -> bool {
        for o in out.iter_mut() {
            if self.t.is_multiple_of(CTRL) {
                self.scoop += 0.03 * (1.0 - self.scoop);
                let v = self.vib.next();
                #[cfg(test)]
                {
                    self.vib_val = v;
                }
                let vib = if self.t > self.vib_delay {
                    let ramp = ((self.t - self.vib_delay) as f32 / (0.2 * self.sr)).min(1.0);
                    self.vib_depth * ramp * v
                } else {
                    0.0
                };
                self.saw
                    .set_freq(self.base_f * self.bend * self.scoop * (1.0 + vib), self.sr);
                // More bow pressure opens each instrument's brightness ceiling.
                self.lp
                    .set_cutoff(self.press_lo + self.press_span * self.last_env, self.sr);
                if self.trem_rate > 0.0 {
                    self.trem_phase += self.trem_rate_cur * CTRL as f32 / self.sr;
                    if self.trem_phase >= 1.0 {
                        self.trem_phase -= 1.0;
                        self.trem_bite_until = self.t + (BOW_TREM_BITE_S * self.sr) as u32;
                        self.trem_stroke_gain = 1.0 + BOW_TREM_AMP_JITTER * self.rng.white();
                        self.trem_rate_cur =
                            self.trem_rate * (1.0 + BOW_TREM_JITTER * self.rng.white());
                    }
                    let c = (std::f32::consts::TAU * self.trem_phase).cos();
                    self.trem_gain = self.trem_stroke_gain
                        * ((1.0 - self.trem_depth) + self.trem_depth * 0.5 * (1.0 - c));
                }
            }
            let e = self.env.next();
            self.last_env = e;
            // bow noise: loud while the bow bites, quieter once the string speaks
            let noise_amp = if self.t < self.attack_samples * 2 || self.t < self.trem_bite_until {
                self.bite
            } else {
                0.028
            };
            let mut s = self.saw.next() + self.rng.white() * noise_amp * e;
            for b in &mut self.body {
                s = b.process(s);
            }
            s = self.lp.process(s);
            *o += s * self.amp * e * self.trem_gain;
            self.t += 1;
        }
        self.env.alive()
    }

    fn note_off(&mut self) {
        self.env.release();
    }

    fn released(&self) -> bool {
        self.env.released()
    }

    fn set_pitch(&mut self, mult: f32) {
        self.bend = mult;
    }

    fn legato_to(&mut self, key: u8, _vel: u8) -> bool {
        // one bow, new finger: glide over via the scoop, no fresh bite
        let new_f = key_freq(key);
        self.scoop = (self.base_f * self.scoop / new_f).clamp(0.85, 1.18);
        self.base_f = new_f;
        true
    }

    #[cfg(test)]
    fn kind(&self) -> &'static str {
        "bowed"
    }
}

// ---------------------------------------------------------------------------
// BowedString (GM 43 contrabass) — a bowed-string digital waveguide
// ---------------------------------------------------------------------------

/// A bowed string as a *physical model*: a delay-line waveguide split at the
/// bow into a bridge-side and a nut-side section, driven every sample by a
/// nonlinear stick-slip bow-friction interaction (the McIntyre–Woodhouse–
/// Schumacher / Smith / STK lineage).
///
/// Why this and not the shared `Bowed` (saw + static body EQ): a saw through a
/// fixed EQ is, at 65 Hz, a static harmonic stack — it reads as a buzzy
/// "transformer hum", and no amount of EQ makes it an instrument, because an
/// instrument's identity is in the *time domain*. Here every partial comes
/// from one coupled oscillator locked to the fundamental, so the tone fuses by
/// construction, and the stick-slip nonlinearity gives it the living,
/// slightly-irregular motion a static spectrum cannot fake. Contrabass-only
/// (default GM 43); the Codex per-program `Bowed` set is the CC0 alt bank.
pub struct BowedString {
    bridge: DelayLine, // bow -> bridge -> bow section
    neck: DelayLine,   // bow -> nut -> bow section
    bridge_delay: f32,
    neck_delay: f32,
    beta: f32, // bow position as a fraction of the speaking length
    base_f: f32,
    bend: f32,
    refl: OnePole,     // bridge reflection filter: string losses (darkens)
    body: [Biquad; 3], // the instrument body's broad low resonances
    dc_x1: f32,        // DC blocker state (bowed loops accumulate DC)
    dc_y1: f32,
    env: Adsr,                 // bow pressure/velocity envelope (the onset + release)
    max_vel: f32,              // bow speed (loudness / brightness)
    slope: f32,                // bow force: narrows the friction curve (brighter/scratchier)
    source_energy: f32,        // slow intrinsic post-body level estimate for low-string AGC
    source_follow_k: f32,      // sample-rate-correct coefficient for `source_energy`
    level_gain: f32,           // slow, bounded residual low-string normalization
    level_target: Option<f32>, // calibrated intrinsic RMS; None leaves other voices bit-exact
    level_fade_start: u32,     // normalization handover start, in samples
    level_fade_end: u32,       // normalization handover end, in samples
    vib: Sine,                 // pitch vibrato
    vib_depth: f32,            //
    vib_delay: u32,            // vibrato onset delay
    grit: Biquad,              // bow-hair / rosin noise band (bandpass)
    contact_noise: f32,        // broadband noise radiated straight from the contact
    bow_noise: f32,            // per-note grit level — no two bows are identical
    scratch: f32,              // decaying attack "catch" intensity (the bite before the tone)
    scratch_k: f32,            // its per-sample decay
    drift: Drift,              // slow human pitch wander (intonation is never dead-steady)
    amp_follow: f32,           // output magnitude follower, for the release tail
    refl_sustain: f32,         // bridge-filter cutoff while bowed (register brightness)
    loop_comp: f32,            // loop-latency tuning compensation, in samples
    out_lp: Option<OnePole>,   // post-output darkening (cello de-buzz); None = flat
    rng: Rng,
    t: u32,
    amp: f32,
    sr: f32,
}

/// The stick-slip friction characteristic (STK `BowTable`): the fraction of the
/// bow/string differential velocity that the bow imparts to the string. Near
/// zero differential the bow *sticks* (coefficient saturates at 1, string moves
/// with the bow); past a force-dependent threshold it *slips* (coefficient
/// falls off), and the alternation of the two is what makes a string speak.
#[inline]
fn bow_friction(delta_v: f32, slope: f32) -> f32 {
    let s = (delta_v * slope).abs() + 0.75;
    let s2 = s * s;
    (1.0 / (s2 * s2)).min(1.0) // (|Δv·slope| + 0.75)^-4, clamped to the stick region
}

/// The lowest pitch [`BowedString::set_freq`] will ever tune to. It floors `f` at this
/// value, so `sr / BOW_MIN_HZ` is the longest loop either delay line can be asked for —
/// including under a downward pitch bend, which drives `set_freq` per sample.
const BOW_MIN_HZ: f32 = 20.0;

/// How long a bowed-waveguide delay line must be at `sr` to hold its `share` of the
/// longest loop `set_freq` can request.
///
/// Sized from the SAME arithmetic `set_freq` uses, because a literal cannot be right at
/// more than one sample rate: the loop needs ~`sr / f` samples, so doubling the rate
/// doubles the requirement. The old fixed `DelayLine::new(320)` / `new(1600)` held C1 at
/// 44.1 kHz (~1349 samples) but not at 96 kHz (~2936), and `DelayLine::tap` then walked
/// off the front of the buffer — a debug panic, and a silent wrong-sample read in release
/// (MM-BUG-KILN-00074).
///
/// `loop_comp` is deliberately not subtracted: it only ever shortens the delay, so
/// ignoring it keeps this a safe upper bound. `+ 2` covers `tap`'s two-point
/// interpolated read, which reaches one sample further back than the delay itself.
fn bow_line_len(sr: f32, share: f32) -> usize {
    ((sr / BOW_MIN_HZ) * share).ceil() as usize + 2
}

/// One bowed instrument's voicing of the shared waveguide.
///
/// Was a 6-tuple while only the cello and contrabass existed; the violin family
/// (GM 40/41/110) adds a fourth and fifth arm and two more per-program levers
/// (`beta`, the bow-force ceiling), at which point positional fields stop being
/// readable. Same values, named.
#[derive(Clone, Copy)]
struct StringVoicing {
    /// Body resonances: air/Helmholtz, main wood mode, broad arco presence.
    body_f: [f32; 3],
    /// In-loop bridge damping — string loss, and the voice's brightness ceiling.
    refl_sustain: f32,
    /// Output gain before the velocity law. Was `amp_base` + `amp_span`, only
    /// ever consumed as their sum — one number wearing two names, which made
    /// every new voicing invent a split that changed nothing.
    amp: f32,
    /// Post-output darkening; 0.0 leaves the voice flat.
    out_lp_hz: f32,
    /// Loop-latency tuning compensation, in samples. MEASURED, never guessed.
    loop_comp: f32,
    /// Bow position as a fraction of the speaking length.
    beta: f32,
    /// Bow-force ceiling: full force below `slope_hi_key`, falling linearly to
    /// `slope_hi` at `top_key` (this instrument's highest note). See
    /// `bow_force_ceiling`.
    slope_hi: f32,
    slope_hi_key: u8,
    top_key: u8,
    vib_rate: f32,
    vib_base: f32,
    vib_span: f32,
    vib_floor: f32,
    /// Attack-catch and bow-grit multiplier — how hard the bow bites.
    ///
    /// The saw-based `Bowed` carried this per program (its `bite` field: 0.230
    /// for the fiddle against 0.100 for the violin) and the waveguide had no
    /// equivalent, so on migration GM110 inherited the violin's onset exactly and
    /// stopped being a fiddle. A fiddle IS a violin played with more bite; that
    /// difference is its whole GM identity, and it belongs in the voicing.
    bite: f32,
    /// Bow-hair noise radiated DIRECTLY from the bow/string contact, rather than
    /// coupled through the string loop, as a fraction of the note's amplitude.
    ///
    /// The saw-based `Bowed` added its `bite` broadband, straight into the signal;
    /// the waveguide's grit instead goes through a bandpass INTO the loop, where
    /// the reflection filter and body damp it. That is why raising `bite` or
    /// moving `grit_hz` barely touched the fiddle's early-HF signature
    /// (`sweep_fiddle_brightness_levers`: 1.02x, against the 1.10x its identity
    /// oracle requires), while the two loop-brightness levers saturated near
    /// 1.08x even taken to absurd values.
    ///
    /// Not all bow noise couples through the string — some radiates from the
    /// contact point directly, and that component is broadband and undamped by
    /// the body. Modelling it gives the voicing an honest bite lever.
    ///
    /// Deliberately ZERO for every voicing except the fiddle, so the four
    /// pre-existing programs render bit-identically to before this field existed.
    contact_noise: f32,
    /// Bow-hair fluctuation band, as (base Hz, span Hz); the per-note draw lands
    /// somewhere inside it.
    ///
    /// This — not `bite` — is what makes a bow sound scrapier, because the grit
    /// is BANDPASSED here before it reaches the string. Raising `bite` alone adds
    /// energy inside the band, so it lifts the voice's total level as much as its
    /// brightness; the fiddle needs the noise to move UP the spectrum, which is
    /// also what a rosinier bow physically does.
    grit_hz: (f32, f32),
}

/// Register-dependent voicing: one waveguide, retuned per instrument. The cello
/// sits ~an octave above the contrabass, and the violin family two above that,
/// so body resonances, string brightness and output level all move with the
/// instrument.
///
/// `loop_comp` compensates the in-loop reflection filter plus structural
/// latency — ~4 samples the bare `sr/f` never subtracts. Uncompensated, a string
/// renders progressively flat with pitch (≈ −5 cents at E1 but −31/−45 cents at
/// the C4/G4 the ear notices). Every value here is MEASURED, never guessed
/// (lesson 2026.07.11), because the reflection filter's phase delay moves with
/// its cutoff — so each `refl_sustain` carries its own `loop_comp`:
///
/// * cello 3.85 (refl 2600) — the original autocorrelation sweep;
/// * contrabass 4.52 (refl 2200) — `measure_bowedstring_loop_latency`, HLD §2.4;
/// * violin family (refl 3900/3500/4200) — `fit_violin_family_loop_comp`.
///
/// `beta` near 1/7 avoids locking onto a low mode; 0.127 mode-locked cello and
/// bass keys 46–50 onto a higher one (MM-BUG-KILN-00012). The violin family
/// needs its own value: at 0.140 it carries a dead note at key 90 and a crippled
/// key 91, mapped by `map_bowedstring_bow_force_ceiling`.
fn string_voicing(program: u8) -> StringVoicing {
    const CELLO: StringVoicing = StringVoicing {
        body_f: [110.0, 230.0, 500.0],
        refl_sustain: 2600.0,
        // Written as the SUM, not as 1.18: in f32 those differ by 1.2e-7
        // (0.36 + 0.82 = 1.18000007, the literal 1.18 = 1.17999995), and that is
        // enough to change every sample of a cello render. Const arithmetic is
        // evaluated with the same f32 semantics, so this reproduces the exact bits
        // the pre-refactor `amp_base + amp_span` produced.
        amp: 0.36 + 0.82,
        out_lp_hz: 2600.0,
        loop_comp: 3.85,
        beta: 0.140,
        // The cello's top two tones (D5/E5) lock an octave up whenever the
        // per-note bow force draws near the top of its range — pre-existing, and
        // caught by bowed_string_cello_holds_register once that gate started
        // using engine-realistic seeds. A ceiling over the last few semitones is
        // the targeted fix; retuning its `beta` would disturb the whole voice and
        // the 46–50 wolf fix that depends on 0.140.
        slope_hi: 2.55,
        slope_hi_key: 72,
        top_key: 76,
        vib_rate: 5.2,
        vib_base: 0.0055,
        vib_span: 0.0055,
        vib_floor: 0.12,
        bite: 1.0,               // the pre-existing draw, unscaled
        contact_noise: 0.0,      // no direct path: bit-identical to before
        grit_hz: (500.0, 800.0), // the pre-existing 500-1300 Hz band
    };
    const CONTRABASS: StringVoicing = StringVoicing {
        body_f: [70.0, 180.0, 700.0],
        refl_sustain: 2200.0,
        amp: 0.55 + 1.25, // same reasoning; this pair happens to be exact
        out_lp_hz: 1800.0,
        loop_comp: 4.52,
        vib_rate: 4.2,
        vib_base: 0.0050,
        vib_span: 0.0050,
        vib_floor: 0.10,
        // Clean across its whole range at full bow force, so no ceiling — but
        // `top_key` must still be its own, or it would inherit the cello's 76
        // and taper a range it does not have.
        slope_hi: 2.9,
        slope_hi_key: 255,
        top_key: 64,
        ..CELLO
    };
    // The violin family. Body frequencies follow the same air / main-wood /
    // broad-presence roles as the low strings: the violin's Helmholtz A0 near
    // 280 Hz, its B1+ corpus mode near 560, and the broad "bridge hill" near
    // 2200 that gives arco its presence. The viola's sit a fourth or so below.
    const VIOLIN: StringVoicing = StringVoicing {
        body_f: [280.0, 560.0, 2200.0],
        refl_sustain: 3900.0,
        // MEASURED by fit_violin_family_level_match: the median sustain level
        // must match the saw-based `Bowed` this replaces, or every album mixed
        // against the old voice shifts balance under it.
        amp: 1.11,
        out_lp_hz: 5200.0,
        loop_comp: 3.16, // MEASURED at beta 0.170, fit_violin_family_loop_comp (sd 0.044)
        // MEASURED by sweep_violin_family_beta. At the low strings' 0.140 the
        // violin family carries a dead note at key 90 and a crippled key 91.
        // The clean window is 0.168–0.176 (one pinhole at 0.172); 0.170 sits
        // clear of both edges, and degradation past 0.178 is steep.
        beta: 0.170,
        // No bow-force ceiling: at beta 0.170 the violin family holds its
        // fundamental across its whole register at FULL bow force. An earlier
        // draft carried a ceiling here too; the calibration test proved it never
        // fired, so it went rather than sit unexercised.
        slope_hi: 2.9,
        slope_hi_key: 255,
        top_key: 100,
        vib_rate: 5.7,
        // Gentler than the low strings' in ratio terms, on purpose. This is the
        // ALWAYS-ON baseline under every note; CC1 is the authored expressive
        // control and needs headroom above it. At 0.0060+0.0060 the autonomous
        // excursion measured 34 cents pk-pk and CC1 could only lift it 1.87x,
        // which is a wobble the player cannot get out from under.
        vib_base: 0.0048,
        vib_span: 0.0048,
        vib_floor: 0.12, // LA_VIOLIN fades 0.12 -> 0.38: wait for the handover
        bite: 1.0,
        contact_noise: 0.0,
        grit_hz: (500.0, 800.0),
    };
    match program {
        42 => CELLO,
        40 => VIOLIN,
        41 => StringVoicing {
            body_f: [220.0, 475.0, 1800.0],
            refl_sustain: 3500.0,
            amp: 1.117, // MEASURED, fit_violin_family_level_match
            out_lp_hz: 4400.0,
            loop_comp: 3.36, // MEASURED at beta 0.170 (sd 0.035)
            top_key: 88,
            vib_rate: 5.4,
            ..VIOLIN
        },
        // GM 110 fiddle: the same instrument as the violin, played brighter and
        // with more bite — a faster, shallower vibrato and a higher brightness
        // ceiling. Its sampled onset hands over earlier (LA_FIDDLE fades
        // 0.08 -> 0.28), so the model's vibrato may start earlier too.
        110 => StringVoicing {
            refl_sustain: 4200.0,
            // 5800 left the fiddle's SUSTAIN within 1.03x of the violin's once the
            // attack scratch had decayed, and its identity oracle wants >= 1.05x on
            // both sides of the sample handover. Raised post-loop rather than via
            // `refl_sustain`, which would shift the reflection filter's phase delay
            // and invalidate the measured `loop_comp`.
            out_lp_hz: 8200.0,
            loop_comp: 3.07, // MEASURED at beta 0.170 (sd 0.032)
            amp: 0.98,       // MEASURED — already level-matched, unlike 40/41
            top_key: 89,
            vib_rate: 6.1,
            vib_base: 0.0035,
            vib_span: 0.0035,
            vib_floor: 0.11, // tracks LA_FIDDLE's fade start
            // The fiddle's defining difference from GM40. Pinned by
            // `default_bowed_body_bands_and_fiddle_identity`, which requires its
            // first 80 ms to be at least 1.10x the violin's above 2.5 kHz — so the
            // grit band has to STRADDLE 2.5 kHz, not merely get louder below it.
            bite: 1.4,
            // MEASURED by sweep_fiddle_brightness_levers. 0.3 reached only 1.03x
            // and the two loop-brightness levers saturate near 1.08x even taken to
            // absurd values; 1.0 lands at 1.16x, clear of the 1.10x bar without
            // becoming hiss. Chosen over `bite` (which reaches 1.24x at 5.0)
            // because it is purely additive at the output and cannot perturb the
            // loop dynamics, where `bite` feeds `slope_eff` and could destabilise.
            contact_noise: 1.0,
            grit_hz: (1900.0, 1700.0), // 1.9-3.6 kHz: a rosinier, brighter scrape
            ..VIOLIN
        },
        // The `_` arm is the contrabass, matching the pre-refactor tuple `match`
        // exactly. Keeping it that way is what makes this refactor a no-op for
        // the two shipping programs.
        _ => CONTRABASS,
    }
}

/// The highest bow force a voicing may draw at `key`.
///
/// Below `slope_hi_key` the full 2.2…2.9 range is available. Above it the
/// ceiling falls linearly to `slope_hi` by the top of the register, because a
/// hard bow in a short loop drives the waveguide off its fundamental. The taper
/// is deliberately monotone even though the measured failures are not (keys
/// 81–83 take full force while 77–79 do not): the failures are discrete
/// mode-crossing resonances, and a ceiling that dips back up between them would
/// encode the measurement's grid rather than the physics.
fn bow_force_ceiling(v: &StringVoicing, key: u8) -> Option<f32> {
    if key < v.slope_hi_key || v.top_key <= v.slope_hi_key {
        return None;
    }
    let lo = v.slope_hi_key as f32;
    let t = ((key as f32 - lo) / (v.top_key as f32 - lo)).clamp(0.0, 1.0);
    Some(2.9 + (v.slope_hi - 2.9) * t)
}

fn bowed_string_controls(
    program: u8,
    key: u8,
    vel: u8,
    natural_slope: f32,
    voicing: &StringVoicing,
) -> (f32, f32) {
    let control = vel_ctrl(vel);
    if !matches!(program, 42 | 43) {
        return (0.03 + 0.22 * control, natural_slope);
    }

    // MM-BUG-KILN-00029: low strings used to run bow speed from 0.03 to 0.25
    // while independently drawing force over 2.2..2.9. Full-compass measurement
    // found unstable pockets in that rectangle (142 of the regression draws).
    // Move both physical controls together through the measured playable region:
    // speed still opens with velocity, while force converges toward a stable
    // middle pressure. The cello's established high-register force ceiling stays
    // authoritative. This is deliberately not the rejected one-dimensional clamp.
    let speed = 0.100 + 0.050 * control;
    let cap = bow_force_ceiling(voicing, key).unwrap_or(2.9);
    let stable_force = 2.60f32.min(cap);
    // By v96 the measured high-velocity region needs the stable force itself,
    // not merely a partial move toward it: GM43 key 31 still octave-locked at
    // v100 with slope 2.553, while 2.60 held across every tested speed and seed.
    let pressure_mix = (control / vel_ctrl(96)).min(1.0);
    let slope = natural_slope + (stable_force - natural_slope) * pressure_mix;
    (speed, slope)
}

fn bowed_string_level_target(program: u8) -> Option<f32> {
    match program {
        // Median intrinsic steady-state RMS after the joint control map, measured
        // over each full compass, ten velocities and four engine-realistic seeds.
        42 => Some(0.286),
        43 => Some(0.259),
        _ => None,
    }
}

impl BowedString {
    fn new(program: u8, key: u8, vel: u8, sr: f32, seed: u32) -> Self {
        let f = key_freq(key);
        let mut rng = Rng::new(seed);
        let voicing = string_voicing(program);
        let StringVoicing {
            body_f,
            refl_sustain,
            amp,
            out_lp_hz,
            loop_comp,
            beta,
            ..
        } = voicing;
        // Per-note character: the seed varies per voice (the engine's spawn
        // counter), so drawing the bow's force, grit, scratch and vibrato here
        // makes every stroke its own — the fix for "each note sounds the same".
        let u = |r: &mut Rng| r.white() * 0.5 + 0.5;
        // Bow force / pressure this stroke, capped by what this pitch can take.
        // Bowing hard in a SHORT loop drives the waveguide off its fundamental
        // (`map_bowedstring_bow_force_ceiling`). Only the cello needs the cap:
        // its top two tones lock an octave up under a hard bow, and unlike the
        // violin family it cannot be cured by moving `beta`, because 0.140 is
        // what holds its own 46–50 wolf band. Real players press less hard high
        // on a string anyway, so the ceiling is physically right where it bites.
        // `None` keeps the ORIGINAL expression, character for character. Writing
        // the unrestricted case as `2.2 + (2.9 - 2.2) * u` looks equivalent and is
        // not: in f32, 2.9 - 2.2 is 0.70000005 and 0.7 is 0.69999999. Six parts in
        // 10^8 of bow force, fed into a chaotic stick-slip loop, is enough to
        // change every sample of the render — it moved two cello-only albums that
        // this change must not touch, and the render-diff inventory caught it.
        let natural_slope = match bow_force_ceiling(&voicing, key) {
            None => 2.2 + 0.7 * u(&mut rng),
            Some(hi) => 2.2 + (hi - 2.2) * u(&mut rng),
        };
        let (max_vel, slope) = bowed_string_controls(program, key, vel, natural_slope, &voicing);
        let level_target = bowed_string_level_target(program);
        let bow_noise = (0.05 + 0.06 * u(&mut rng)) * voicing.bite; // how gritty this stroke is
                                                                    // the sampled arco bite now owns the onset, so the model's own synth
                                                                    // scratch is dialled right back — just a hint under the sample.
        let scratch = (0.08 + 0.10 * u(&mut rng)) * voicing.bite;
        // B3 (MM-BUG-KILN-00004, HLD §2.3): render advances this LFO once per
        // CTRL samples, so it must be BUILT at sr/CTRL — control_lfo() is the
        // one constructor that makes the 16×-slow idiom bug impossible. Base
        // rates are per-program: cello 5.2 Hz (its OWN deeper-voicing value - real
        // cello vibrato is ~5.5-6.5 Hz, so the old 4.8 read as a slow wobble; it no
        // longer mirrors a Bowed preset), contrabass 4.2 Hz (still matching its
        // demoted CC0 alt-bank Bowed preset, and the slow-bass idiom). The 42/43
        // vibrato oracle (default_bowed_natural_vibrato_runs_at_named_rate) is the
        // single source of truth - its per-program nominals track these two literals.
        // The violin family adds its own rates: violin 5.7 Hz and fiddle 6.1 Hz
        // (fiddle idiom is faster and shallower), viola 5.4 Hz.
        let vib = control_lfo(voicing.vib_rate, 0.10, &mut rng, sr);
        // Natural arco vibrato, deepened ~3.4x from the old shared 0.0016+0.0016*u
        // (~2.8-5.5 c peak, far shallower than a real cello/bass). Per-program: cello
        // 0.0055+0.0055*u ~ 9.5-19 c peak (5.2 Hz); contrabass 0.0050+0.0050*u ~
        // 8.6-17 c peak (4.2 Hz). GM43's onset is the VSCO Solo Contrabass SusNV
        // (NON-vibrato) sample, so the model owns 100% of the bass vibrato and need
        // not stay shallow to dodge a double-vibrato. GM42's onset (Bigcat sus) may
        // carry mild baked vibrato but fades out by ~0.40 s, so the cello floor
        // (0.12 s) waits for that fade to START (LA_CELLO fades 0.13->0.40 s) before
        // the model wobble ramps in. The bass floor (0.10 s) is earlier: no sample
        // vibrato to fight, and it gives short bass notes the vibrato the old 0.16 s
        // floor denied them.
        let vib_depth = voicing.vib_base + voicing.vib_span * u(&mut rng);
        let vib_onset = (voicing.vib_floor + 0.24 * u(&mut rng)) * sr;
        let grit_hz = voicing.grit_hz.0 + voicing.grit_hz.1 * u(&mut rng);
        let mut s = BowedString {
            bridge: DelayLine::new(bow_line_len(sr, beta)),
            neck: DelayLine::new(bow_line_len(sr, 1.0 - beta)),
            bridge_delay: 1.0,
            neck_delay: 1.0,
            beta,
            base_f: f,
            bend: 1.0,
            // string loss: wound bass strings are quite lossy up top -> darker,
            // and this is what lets the note decay once the bow lifts.
            refl: OnePole::lowpass(refl_sustain, sr),
            body: [
                Biquad::peak(body_f[0], 0.7, 3.0, sr), // the big body/air resonance
                Biquad::peak(body_f[1], 0.7, 2.0, sr), // main wood mode
                Biquad::peak(body_f[2], 0.5, 1.5, sr), // broad arco "presence"
            ],
            dc_x1: 0.0,
            dc_y1: 0.0,
            // soft notes speak slower: a longer bow onset at low velocity
            env: Adsr::new(vel_attack(0.05, vel), 0.1, 0.9, 0.18, sr),
            // Bow SPEED drives brightness (a harder note is a faster bow, so it
            // is brighter — real bowing): quiet pedal ~dark, collision ~bright.
            // TIMBRE, not level — exempt from the k=2 law (HLD velocity-law §2.4).
            // Bow SPEED, per the comment above: it drives brightness, not gain.
            max_vel,
            slope,
            source_energy: level_target.map_or(0.0, |target| target * target),
            // 80 ms source meter: slow enough to ignore individual stick-slip
            // periods, fast enough to settle before the model owns the LA sustain.
            source_follow_k: (-1.0 / (0.080 * sr)).exp(),
            level_gain: 1.0,
            level_target,
            level_fade_start: (0.30 * sr) as u32,
            level_fade_end: (0.55 * sr) as u32,
            vib,
            vib_depth,
            vib_delay: vib_onset as u32,
            grit: Biquad::bandpass(grit_hz.min(sr * 0.40), 0.8, sr),
            contact_noise: voicing.contact_noise,
            bow_noise,
            scratch,
            // the catch decays over ~45-70 ms into the settled tone
            scratch_k: (-1.0 / (0.055 * sr)).exp(),
            drift: Drift::new(seed ^ 0x2BED_51CE, 0.0018, (0.05 * sr / CTRL as f32) as u32),
            amp_follow: 1.0,
            rng,
            t: 0,
            // Loudness is a velocity-scaled output gain: the self-oscillating
            // limit-cycle amplitude barely tracks velocity, so the dynamic level
            // is applied here. Level-matched to the old contrabass so the album
            // mix balance holds (~0.11 at the quiet pedal, ~0.18 riff/collision).
            amp: amp * vel_amp(vel),
            refl_sustain,
            loop_comp,
            out_lp: if out_lp_hz > 0.0 {
                Some(OnePole::lowpass(out_lp_hz, sr))
            } else {
                None
            },
            sr,
        };
        s.set_freq(f);
        s
    }

    fn set_freq(&mut self, f: f32) {
        // total loop delay = one period, minus the measured loop latency
        // (structural read/write plus the in-loop reflection filter's phase
        // delay — ≈ 4 samples for both programs); split at the bow into the
        // two sections. Compensating this is what keeps the higher register
        // in tune.
        // The `BOW_MIN_HZ` floor is what bounds the loop length, and `bow_line_len` sizes
        // the two delay lines from the same constant. Keep them coupled: lowering this
        // floor without regrowing the lines re-creates MM-BUG-KILN-00074.
        let total = (self.sr / f.max(BOW_MIN_HZ) - self.loop_comp).max(8.0);
        self.bridge_delay = (total * self.beta).max(1.0);
        self.neck_delay = (total * (1.0 - self.beta)).max(1.0);
    }
}

impl Voice for BowedString {
    fn render(&mut self, out: &mut [f32]) -> bool {
        for o in out.iter_mut() {
            if self.t.is_multiple_of(CTRL) {
                let vib = if self.t > self.vib_delay {
                    let ramp = ((self.t - self.vib_delay) as f32 / (0.25 * self.sr)).min(1.0);
                    self.vib_depth * ramp * self.vib.next()
                } else {
                    self.vib.next();
                    0.0
                };
                let drift = self.drift.next();
                self.set_freq(self.base_f * self.bend * (1.0 + vib) * (1.0 + drift));
                // the bow lifts on release: the loop loses its energy source and
                // the string damps faster (darker) as it decays.
                let refl_hz = if self.env.released() {
                    900.0
                } else {
                    self.refl_sustain
                };
                self.refl.set_cutoff(refl_hz, self.sr);
            }
            let e = self.env.next();
            // the bow "catch": a scratchy bite at the onset that decays into the
            // settled tone. This transient — not the steady state — is the single
            // strongest "this is a bow, not an oscillator" cue.
            self.scratch *= self.scratch_k;
            // Bow-hair micro-fluctuation. The critical point (the fix for the
            // "hiss bolted on top"): this perturbs the bow VELOCITY — the INPUT to
            // the friction nonlinearity — so it jitters the stick-slip timing and
            // emerges as grain phase-locked to the string, NOT a noise signal added
            // after the fact. Stronger at the catch, easing into the settled tone.
            let bow_n = self.grit.process(self.rng.white());
            let noise_amt = self.bow_noise * (0.6 + 7.0 * self.scratch);
            // the catch also presses harder — more slip, scratchier — then eases.
            let slope_eff = self.slope * (1.0 + 1.3 * self.scratch);
            let bow_vel = self.max_vel * e * (1.0 + noise_amt * bow_n);
            // loop loss: enough per-period loss that the limit-cycle amplitude
            // is set by the balance of bow energy in vs loss out — that is what
            // makes loudness track bow SPEED (dynamics). Heavier once released so
            // the note actually stops within the tail.
            let loss = if self.env.released() { 0.70 } else { 0.95 };

            let bridge_out = self.bridge.tap(self.bridge_delay);
            let neck_out = self.neck.tap(self.neck_delay);
            // terminations invert; the bridge also filters (string loss) and loses.
            let bridge_refl = -self.refl.process(bridge_out) * loss;
            let nut_refl = -neck_out;
            let string_vel = bridge_refl + nut_refl;
            let delta_v = bow_vel - string_vel;
            // the string is driven purely by the friction — the noise is already
            // inside `bow_vel`, so its grain is shaped by the string, not layered on.
            let excite = delta_v * bow_friction(delta_v, slope_eff);
            self.neck.push(bridge_refl + excite);
            self.bridge.push(nut_refl + excite);

            // pick up the motion at the bridge, colour it with the body, block DC.
            let mut y = bridge_out;
            for b in &mut self.body {
                y = b.process(y);
            }
            if let Some(lp) = &mut self.out_lp {
                y = lp.process(y); // cello de-buzz; None for the bass
            }
            // Direct contact radiation: broadband, gated by the same catch envelope
            // as the scratch, so it is an ATTACK phenomenon that decays into the
            // settled tone rather than a constant hiss. Placed after the body and
            // output filters because this component never passes through them.
            if self.contact_noise > 0.0 {
                y += self.contact_noise * self.scratch * self.rng.white() * e;
            }
            let hp = y - self.dc_x1 + 0.9985 * self.dc_y1;
            self.dc_x1 = y;
            self.dc_y1 = hp;
            let mut levelled = hp;
            if let Some(target) = self.level_target {
                self.source_energy = self.source_energy * self.source_follow_k
                    + hp * hp * (1.0 - self.source_follow_k);
                if self.t.is_multiple_of(CTRL) && !self.env.released() {
                    let measured = self.source_energy.max(1e-12).sqrt();
                    let desired = (target / measured).clamp(0.60, 1.70);
                    // `desired` inherits the 80 ms meter's slew. Applying that
                    // already-smoothed value directly avoids a second lag that
                    // misses late-settling limit cycles.
                    self.level_gain = desired;
                }
                // Preserve the sampled/modelled bow catch. The correction fades in
                // only as the LA attack hands the note to the waveguide.
                let mix = if self.t <= self.level_fade_start {
                    0.0
                } else if self.t >= self.level_fade_end {
                    1.0
                } else {
                    (self.t - self.level_fade_start) as f32
                        / (self.level_fade_end - self.level_fade_start) as f32
                };
                levelled *= 1.0 + (self.level_gain - 1.0) * mix;
            }
            let sample = (levelled * self.amp).clamp(-1.5, 1.5);
            *o += sample;
            self.amp_follow = self.amp_follow * 0.9997 + sample.abs() * 0.0003;
            self.t += 1;
        }
        // alive while the bow is on, or while the string is still ringing down.
        self.env.alive() || self.amp_follow > 3.0e-4
    }

    fn note_off(&mut self) {
        self.env.release();
    }

    fn released(&self) -> bool {
        self.env.released()
    }

    fn set_pitch(&mut self, mult: f32) {
        self.bend = mult;
    }

    fn legato_to(&mut self, key: u8, _vel: u8) -> bool {
        // one bow-stroke, new stopped pitch: retune the string, keep it ringing.
        self.base_f = key_freq(key);
        true
    }

    #[cfg(test)]
    fn kind(&self) -> &'static str {
        "bowedstring"
    }
}

// ---------------------------------------------------------------------------
// Factory
// ---------------------------------------------------------------------------

/// LA layering (sampled attack + modeled sustain) — level-matched to the
/// models by the `la_level_continuity` test.
const LA_VIOLIN: (f32, (f32, f32)) = (0.30, (0.12, 0.38));
/// GM 110 fiddle: still the quickest handover of the bowed family — a fiddle
/// attack is more percussive than a violin's — but no longer the saw-era
/// 0.08 -> 0.28. A waveguide takes time to build its limit cycle, so a fade that
/// finished while the model was still speaking left a 1.72x RMS step in the
/// middle of the handover. Every other waveguide program already hands over
/// later for exactly this reason (contrabass 0.16 -> 0.46, cello 0.13 -> 0.40).
const LA_FIDDLE: (f32, (f32, f32)) = (0.32, (0.11, 0.34));
/// GM 43 contrabass: a real cello-section arco *bite* over the waveguide
/// sustain — the bow-catch is what the physical model fakes worst, so the
/// sample owns the onset. A slightly longer handover than the violin: a bass
/// bow speaks slower. Gain tuned by ear (Arthur): a restrained bite.
const LA_CONTRABASS: (f32, (f32, f32)) = (0.29, (0.16, 0.46));
// GM 32-35 alternate-bank bass onset (MM-BUG-KILN-00085): additive, not a
// replacement crossfade. The modeled bass stays live from sample zero and the
// CC0 sample is a short transient overlay tapering out by 150 ms.
const LA_BASS_FADE: (f32, f32) = (0.0, 0.15);
// 2^(5/12), inclusive.
const LA_BASS_MAX_UP_RATIO: f32 = 1.334_839_8;
// Each recording/model pair needs its own additive trim: one shared 0.20 mix
// left the quieter pizz and pick attacks below the bank reachability floor,
// while raising all four together would over-layer the louder finger take.
const LA_PIZZBASS: (f32, (f32, f32)) = (0.40 * 0.65, LA_BASS_FADE);
const LA_FINGERBASS: (f32, (f32, f32)) = (0.42 * 0.30, LA_BASS_FADE);
const LA_PICKBASS: (f32, (f32, f32)) = (0.42 * 0.50, LA_BASS_FADE);
const LA_FRETLESS: (f32, (f32, f32)) = (0.42 * 0.46, LA_BASS_FADE);
// GM 4 Rhodes tine / 10 music box comb / 15 hammered dulcimer: real Freesound onsets over the
// modeled voices. The sample carries the strike/pluck attack; the model keeps the body/decay.
// Ear-tunable.
const LA_RHODES: (f32, (f32, f32)) = (0.45, (0.05, 0.35));
const LA_MUSICBOX: (f32, (f32, f32)) = (0.50, (0.05, 0.30));
const LA_DULCIMER: (f32, (f32, f32)) = (0.45, (0.05, 0.30));
