pub(crate) struct BagpipeDrone {
    tenor1: ReedPulse,
    tenor2: ReedPulse,
    bass: ReedPulse,
    norm: (f32, f32, f32),
    lp: OnePole,
    env: Adsr,
    amp: f32,
}

impl BagpipeDrone {
    /// The Highland drone stack: two tenors at the drone pitch (detuned
    /// against each other → the slow beat) plus one bass an octave below.
    /// Spawned by a low drone-control note it sounds AT that pitch; spawned
    /// by a chanter note the tenors sit an octave below it. Velocity is
    /// ignored: bag pressure is constant.
    fn new(key: u8, _vel: u8, sr: f32, seed: u32) -> Self {
        let mut rng = Rng::new(seed ^ 0xBA60_0001);
        let tenor_f = if key <= BAGPIPE_DRONE_CONTROL_MAX {
            key_freq(key)
        } else {
            key_freq(key) * 0.5
        };
        let bass_f = tenor_f * 0.5;
        let norm = |width: f32| 0.5 / (width * (1.0 - width)).sqrt();
        let w1 = BAGPIPE_DRONE_WIDTH * (1.0 + 0.015 * rng.white());
        let w2 = BAGPIPE_DRONE_WIDTH * (1.0 + 0.015 * rng.white());
        let w3 = BAGPIPE_DRONE_WIDTH * (1.0 + 0.015 * rng.white());
        BagpipeDrone {
            tenor1: ReedPulse::new(
                tenor_f * (1.0 + BAGPIPE_TENOR_DETUNE),
                sr,
                rng.white() * 0.5 + 0.5,
                w1,
            ),
            tenor2: ReedPulse::new(
                tenor_f * (1.0 - BAGPIPE_TENOR_DETUNE),
                sr,
                rng.white() * 0.5 + 0.5,
                w2,
            ),
            bass: ReedPulse::new(bass_f, sr, rng.white() * 0.5 + 0.5, w3),
            norm: (norm(w1), norm(w2), norm(w3)),
            lp: OnePole::lowpass(2600.0, sr),
            // Constant-pressure sustain (1.0, no decay dip); the release is
            // the bag emptying at the authored stop / engine hang release.
            env: Adsr::new(0.050, 0.0, 1.0, 0.22, sr),
            amp: BAGPIPE_DRONE_AMP,
        }
    }
}

impl Voice for BagpipeDrone {
    fn render(&mut self, out: &mut [f32]) -> bool {
        for o in out.iter_mut() {
            let e = self.env.next();
            let s = self.tenor1.next() * self.norm.0 * BAGPIPE_DRONE_MIX.0
                + self.tenor2.next() * self.norm.1 * BAGPIPE_DRONE_MIX.1
                + self.bass.next() * self.norm.2 * BAGPIPE_DRONE_MIX.2;
            *o += self.lp.process(s) * self.amp * e;
        }
        self.env.alive()
    }

    fn note_off(&mut self) {
        self.env.release();
    }

    fn released(&self) -> bool {
        self.env.released()
    }

    #[cfg(test)]
    fn kind(&self) -> &'static str {
        "reed"
    }
}

pub(crate) fn bagpipe_drone(key: u8, vel: u8, sr: f32, seed: u32) -> BagpipeDrone {
    BagpipeDrone::new(key, vel, sr, seed)
}

/// The SAMPLED drone stack (HLD 2026.07.17): the real G-pipe's bass + tenor,
/// each a looped recording repitched to track the chanter's key. Mirrors the
/// modeled `BagpipeDrone`'s bass+tenor structure — but from real recordings, so
/// there is NO tenor-pair beat (a real G-pipe has one tenor; BP-O2's beat is a
/// model-only property, kept on the alt bank). `tenor_f` follows the same
/// drone-control branch as the model: a control note (key <= MAX) sounds the
/// tenor AT its pitch, else an octave below the chanter.
pub(crate) struct BagpipeDroneSampled {
    bass: crate::sampler::LoopVoice,
    tenor: crate::sampler::LoopVoice,
}

impl BagpipeDroneSampled {
    fn new(key: u8, sr: f32) -> Self {
        let tenor_f = if key <= BAGPIPE_DRONE_CONTROL_MAX {
            key_freq(key)
        } else {
            key_freq(key) * 0.5
        };
        let g = crate::sampler::BAGPIPE_DRONE_GAIN;
        BagpipeDroneSampled {
            // Fixed, distinct drift seeds: the drones are per-channel
            // singletons, so a note seed adds nothing — these just decorrelate
            // the two drones' read-rate walks (MM-REQ-KILN-00026).
            bass: crate::sampler::LoopVoice::new(
                crate::sampler::drone_g2_bank(),
                tenor_f * 0.5,
                sr,
                g,
                0.050,
                0.22,
                0x0D20_0E01,
                "bagpipe_drone",
            ),
            tenor: crate::sampler::LoopVoice::new(
                crate::sampler::drone_g3_bank(),
                tenor_f,
                sr,
                g,
                0.050,
                0.22,
                0x0D20_0E02,
                "bagpipe_drone",
            ),
        }
    }
}

impl Voice for BagpipeDroneSampled {
    fn render(&mut self, out: &mut [f32]) -> bool {
        // both loops add into `out`; alive if EITHER is (they release in lockstep)
        let a = self.bass.render(out);
        let b = self.tenor.render(out);
        a || b
    }

    fn note_off(&mut self) {
        self.bass.note_off();
        self.tenor.note_off();
    }

    fn released(&self) -> bool {
        // released only when BOTH are (they note_off together, so this is exact)
        self.bass.released() && self.tenor.released()
    }

    #[cfg(test)]
    fn kind(&self) -> &'static str {
        "reed"
    }
}

pub(crate) fn bagpipe_drone_sampled(key: u8, sr: f32) -> BagpipeDroneSampled {
    BagpipeDroneSampled::new(key, sr)
}

/// RD10 (§2.8.4) — the sax rasp stage state. Runs the source chain (pulse →
/// leaky integrator → bias-tanh → decimation cliff) at `m`× the output rate;
/// the owning `Reed` constructs its `ReedPulse` at `osr` when this stage is
/// live. Bypassed voices never build one (`rasp: None`), keeping their hot
/// path identical to the filter-only voice.
struct ReedRasp {
    m: u32,   // oversampling factor (shipped: RD_RASP_OVER; A-MEAS runs 2/4/8)
    osr: f32, // m · sr
    #[cfg(test)]
    w: f32, // post-jitter duty (kept for the A-MEAS test-seam rebuild)
    int_a: f32, // leaky-integrator coefficient at osr (~18 Hz corner)
    int_z: f32, // integrator state (the raw tent)
    tg_k: f32, // tent normalisation: tent_g = f · tg_k lands the tent at ±1
    tent_g: f32, // current tent gain (retuned at CTRL with the composed f)
    bias: f32, // b = 2w−1 — the g→∞ limit duty equals w (see RD10 header)
    g0: f32,  // drive at p = 0
    g_span: f32, // drive slope: g = (g0 + g_span·p)·derate(f)
    g: f32,   // current drive (CTRL-rate; p is already T-N1 smoothed)
    dc_ref: f32, // closed-form mean of tanh(g(x+b)), x ~ U[−1,1]
    norm: f32, // closed-form 0.5/rms — keeps the RD8 source-RMS anchor
    noise_base: f32, // turbulence rms at tent scale (breath-scaled preset frac)
    k_noise: f32, // per-CTRL gain: lowpassed white → rms noise_base·(1+span·growl)
    nlp_a: f32, // turbulence lowpass coefficient (0.30·f0 at osr)
    nlp_z: f32, // turbulence lowpass state
    white: f32, // held white draw (one per OUTPUT sample, m-invariant voicing)
    growl_tgt: f32, // authored growl (set_breath arg 2); 0 until authored
    growl_sm: f32, // smoothed growl (shares the RD9 p_k time constant)
    decim: [Biquad; 2], // m×→1× decimation cliff (BR1 idiom, at osr)
    dcb: Biquad, // 20 Hz output highpass — the T-N2 DC guard (at sr)
    #[cfg(test)]
    derate_force: Option<f32>, // A-MEAS-ALIAS seam: pin the derate to measure raw g
}

impl ReedRasp {
    fn new(m: u32, sr: f32, f: f32, width: f32, spec: (f32, f32, f32), noise_base: f32) -> Self {
        let osr = sr * m as f32;
        let int_a = 1.0 - (-2.0 * std::f32::consts::PI * RD_RASP_INT_HZ / osr).exp();
        ReedRasp {
            m,
            osr,
            #[cfg(test)]
            w: width,
            int_a,
            int_z: 0.0,
            // tent pp ≈ int_a·osr·w(1−w)/f (linear-segment integration of the
            // duty-w two-level pulse), so f·tg_k normalises the tent to ±1
            tg_k: 2.0 / (int_a * osr * width * (1.0 - width)),
            tent_g: 0.0, // set by the first set_drive (t = 0 is a CTRL tick)
            bias: 2.0 * width - 1.0,
            g0: spec.0,
            g_span: spec.1,
            g: spec.0,
            dc_ref: 0.0,
            norm: 1.0,
            noise_base,
            k_noise: 0.0,
            nlp_a: 0.0,
            nlp_z: 0.0,
            white: 0.0,
            growl_tgt: 0.0,
            growl_sm: 0.0,
            decim: [
                Biquad::lowpass(RD_RASP_DECIM_HZ, 0.8, osr),
                Biquad::lowpass(RD_RASP_DECIM_HZ, 0.8, osr),
            ],
            dcb: Biquad::highpass(RD_RASP_HP_F0 * f, 0.7, sr),
            #[cfg(test)]
            derate_force: None,
        }
    }

    /// CTRL-rate operating point: drive from pressure (with the measured
    /// high-f0 derate), tent/turbulence retunes, and the closed-form
    /// dc_ref/norm. Each tent segment is linear and spans [−1, +1], so the
    /// tent's level distribution is uniform (exact for the ideal tent):
    ///   dc_ref = ½∫tanh(g(x+b))dx = (lncosh(g(1+b)) − lncosh(g(1−b)))/(2g)
    ///   E[y²]  = 1 − (tanh(g(1+b)) + tanh(g(1−b)))/(2g)
    /// and norm = 0.5/√(E[y²] − dc_ref²) holds the source at the RD8 0.5-RMS
    /// anchor across the whole drive range (level rides the amp envelope, not g).
    fn set_drive(&mut self, p: f32, f: f32) {
        #[allow(unused_mut)]
        let mut der = 1.0 - (1.0 - RD_RASP_F0_FLOOR) * smoothstep(RD_RASP_F0_LO, RD_RASP_F0_HI, f);
        #[cfg(test)]
        if let Some(d) = self.derate_force {
            der = d;
        }
        self.g = (self.g0 + self.g_span * p) * der;
        self.tent_g = f * self.tg_k;
        // sub-fundamental guard rides the composed f (legato/bend-safe)
        self.dcb
            .retune_highpass(RD_RASP_HP_F0 * f, 0.7, self.osr / self.m as f32);
        // turbulence band: lowpass the held white at 0.30·f0, renormalised so
        // its rms is noise_base·p⁴·(1+growl span) at tent scale regardless of
        // f/m. Round 2 ("all sound distorted from mezzo-forte up"): the
        // window is now QUARTIC in pressure, was p². The p² law left a vel-96
        // note with ~0.5× the ff skirt energy — the rasp barely distinguished
        // mf from ff — and gating the DRIVE instead is a dead end: the skirt
        // transfer saturates in g while a g-knee moves the honk band-winner
        // (breaks P5) and dents the P2 ramp. Only the noise INTENSITY is
        // gated, so the harmonic path (drive, tent, honk, tilt) is untouched
        // at every pressure — P2/P5/P3 see identical harmonic input, ff is
        // bit-identical (window(1) = 1), and the mf skirt drops directly with
        // the window (reed_sax_rasp_blooms_with_pressure).
        self.nlp_a = 1.0 - (-2.0 * std::f32::consts::PI * (RD_RASP_NLP_F0 * f) / self.osr).exp();
        let n_eff =
            self.noise_base * (p * p) * (p * p) * (1.0 + RD_RASP_GROWL_SPAN * self.growl_sm);
        let a = self.nlp_a as f64;
        // one-pole on white: var_out = a/(2−a)·var_in; uniform ±1 has var 1/3
        let lp_rms = (a / (2.0 - a) / 3.0).sqrt().max(1e-9);
        self.k_noise = (n_eff as f64 / lp_rms) as f32;
        let (g, b) = (self.g as f64, self.bias as f64);
        let dc = (lncosh(g * (1.0 + b)) - lncosh(g * (1.0 - b))) / (2.0 * g);
        let e2 = 1.0 - ((g * (1.0 + b)).tanh() + (g * (1.0 - b)).tanh()) / (2.0 * g);
        self.dc_ref = dc as f32;
        self.norm = 0.5 / ((e2 - dc * dc).max(1e-12).sqrt() as f32);
    }

    /// One osr sub-step: integrate the pulse to the tent, inject the
    /// turbulence INTO the shaper input (that is where breath physically
    /// enters — the saturating transfer intermodulates it into skirts), shape,
    /// re-anchor, and run the decimation cliff. Caller keeps the last
    /// (aligned) sample of each m-group.
    #[inline]
    fn step(&mut self, pulse: f32) -> f32 {
        self.int_z += self.int_a * (pulse - self.int_z);
        let tent = self.int_z * self.tent_g;
        self.nlp_z += self.nlp_a * (self.white - self.nlp_z);
        let x = tent + self.nlp_z * self.k_noise + self.bias;
        let mut v = ((self.g * x).tanh() - self.dc_ref) * self.norm;
        for d in self.decim.iter_mut() {
            v = d.process(v);
        }
        v
    }
}

#[cfg(test)]
impl Reed {
    /// A-MEAS-ALIAS seam (§3.1): rebuild the rasp stage at oversampling
    /// factor `m` (fresh state, identical voicing), optionally pinning the
    /// high-f0 drive derate — so the same worst case runs at 2×/4×/8×,
    /// underated and derated, against the 8× reference.
    fn rasp_reover(&mut self, m: u32, derate_force: Option<f32>) {
        let r = self
            .rasp
            .as_ref()
            .expect("rasp_reover on a filter-only reed");
        let mut nr = ReedRasp::new(
            m,
            self.sr,
            self.base_f,
            r.w,
            (r.g0, r.g_span, 0.0),
            r.noise_base,
        );
        nr.derate_force = derate_force;
        nr.growl_tgt = r.growl_tgt;
        self.rasp = Some(nr);
        self.osc.set_freq(self.base_f, self.sr * m as f32);
    }
}

// RD11 cone-fill: the four saxes are CONICAL bores (a complete harmonic series),
// but the model is a symmetric duty-`w` rectangle whose sinc null guts h3 and whose
// upper-mid is thin. This is a parallel additive bank of upper partials only
// (n = 3..8, NO h1/h2 — ferro's fundamental and h2 are already at/above SC-55, so
// adding a full saw would inflate them and DRAG the centroid down). Pure sines below
// Nyquist ⇒ alias-free and DC-free by construction; downstream of and parallel to the
// rasp ⇒ the `bias = 2w−1` identity is untouched. Depths are per-preset (`cone`); the
// weights taper gently so h3 fills strongly while the highs keep the centroid up.
const CONE_N0: u32 = 3; // first partial (h3 — the duty null)
const CONE_WEIGHTS: [f32; 6] = [1.0, 0.9, 0.7, 0.55, 0.45, 0.4]; // n = 3,4,5,6,7,8

struct ConeResidual {
    partials: [Sine; 6],
    gain: [f32; 6], // CONE_WEIGHTS in-band, 0 above Nyquist (set at retune); amp applied in next()
    amp: f32,       // per-preset `cone` scale
}

impl ConeResidual {
    fn new(f: f32, sr: f32, cone: f32) -> Self {
        let partials = std::array::from_fn(|i| Sine::new(f * (CONE_N0 + i as u32) as f32, sr, 0.0));
        let mut cr = ConeResidual {
            partials,
            gain: [0.0; 6],
            amp: cone,
        };
        cr.set_freq(f, sr);
        cr
    }

    /// Retune every partial to n·f (following bend/scoop/vibrato); mute (gain 0) any
    /// that would exceed Nyquist so the bank never aliases.
    fn set_freq(&mut self, f: f32, sr: f32) {
        for (i, s) in self.partials.iter_mut().enumerate() {
            let fp = f * (CONE_N0 + i as u32) as f32;
            self.gain[i] = if fp < sr * 0.45 {
                s.set_freq(fp, sr);
                CONE_WEIGHTS[i]
            } else {
                0.0
            };
        }
    }

    /// Σ gain·sin(2π·n·φ), scaled by the preset depth. Advances every partial (phase
    /// continuity) regardless of its gate; `amp = 0` makes the whole bank a bit-exact
    /// no-op (the cone-on/off differential seam).
    #[inline]
    fn next(&mut self) -> f32 {
        let mut y = 0.0;
        for (i, s) in self.partials.iter_mut().enumerate() {
            y += self.gain[i] * s.next();
        }
        y * self.amp
    }
}

pub struct Reed {
    osc: ReedPulse,
    osc_norm: f32, // RD8 equal-RMS-across-widths source gain
    formants: [Biquad; 3],
    // RD2 slot designs (jittered Hz, Q, TABLE gain dB): the honk retunes the
    // live biquads from these at CTRL rate, scaling gain dB by (α + β·p).
    fdesign: [(f32, f32, f32); 3],
    tilt: Biquad,           // RD3 pressure tilt — low-Q 12 dB/oct lowpass at f0·N(p)
    rasp: Option<ReedRasp>, // RD10 §2.8.4 sax rasp stage (None = filter-only bypass)
    cone_res: Option<ConeResidual>, // RD11 Stage-2 cone-fill (saxes only; None = untouched)
    n_lo: f32,
    n_hi: f32,
    p_auth: f32, // RD9 authored CC2/CC11 delta (0 until set_breath; ≤ 0)
    p_sm: f32,   // RD9 smoothed pressure (T-N1 zipper guard)
    p_k: f32,    // RD9 one-pole coefficient at CTRL rate
    base_f: f32,
    bend: f32,
    scoop: f32,
    scoop_k: f32, // RD6 per-CTRL-tick scoop settle (preset)
    breath_filt: Biquad,
    breath: f32, // RD5 register-scaled sustain breath level
    chiff_amp: f32,
    chiff_decay: f32,
    env: Adsr,
    last_env: f32,
    vib: Sine,
    vib_depth: f32,
    vib_delay: u32,
    vib_val: f32,
    rng: Rng,
    t: u32,
    vn: f32,
    amp: f32,
    sr: f32,
}

impl Reed {
    /// Parametric constructor (the RD-O8a `breath = 0` differential test seam
    /// constructs through it; `reed()` is a thin lookup-then-`from_preset`).
    fn from_preset(preset: &ReedPreset, key: u8, vel: u8, sr: f32, seed: u32) -> Self {
        let f = key_freq(key);
        let vn = vel as f32 / 127.0;
        let mut rng = Rng::new(seed);
        // RD3 register position: 0 at range bottom, 1 at top (out-of-range clamps)
        let (lo, hi) = preset.range;
        let reg = ((key as f32 - lo as f32) / (hi as f32 - lo as f32).max(1.0)).clamp(0.0, 1.0);
        // RD1 duty: interpolate bottom→top width, then ±2% per-note jitter
        let w0 = preset.width + (preset.width_hi - preset.width) * reg;
        let width = w0 * (1.0 + 0.02 * rng.white());
        // RD8 equal-RMS source normalisation (raw pulse RMS = √(w(1−w)))
        let osc_norm = 0.5 / (width * (1.0 - width)).sqrt();
        // RD9 pressure at spawn: vel_floor only (env starts at 0; authored
        // CC2/CC11 arrives via set_breath before the first render on
        // authored channels, and the ~15 ms smoother absorbs the step).
        let p0 = RD_P_VEL.0 + RD_P_VEL.1 * vn.powf(RD_P_VEL_EXP);
        // RD2 fixed formant bank (±2% freq jitter), gains scaled by the honk
        // law at the spawn pressure. A 0 dB slot is a pass-through, but must
        // NOT be built at f = 0 (as the §5 table marks inert slots): a 0 Hz
        // peak lands a DOUBLE POLE on z = 1 (DC) — a marginally-stable
        // integrator that accumulates float rounding into a slow DC drift. A
        // benign mid-band frequency keeps the (still-identity) filter's poles
        // inside the unit circle so rounding decays instead of accumulating.
        let fdesign = preset.formants.map(|(ff, q, g)| {
            let j = 1.0 + 0.02 * rng.white(); // one jitter draw per slot (stable RNG stream)
            ((ff * j).min(sr * 0.4), q, g)
        });
        let gmul0 = RD_FORM_ALPHA + RD_FORM_BETA * p0;
        let formants = fdesign.map(|(ff, q, g)| {
            if g == 0.0 {
                Biquad::peak(sr * 0.25, 1.0, 0.0, sr)
            } else {
                Biquad::peak(ff, q, g * gmul0, sr)
            }
        });
        // RD3 tilt at the spawn pressure, in harmonic-count coordinates
        let cut0 = (f * preset.n_lo * (preset.n_hi / preset.n_lo).powf(p0))
            .clamp(RD_TILT_FLOOR_HZ, sr * 0.4);
        let tilt = Biquad::lowpass(cut0, RD_TILT_Q, sr);
        // RD5 breath: register-scaled (low notes breathier — the sax subtone),
        // through a bandpass at the upper reed-hiss band (Wind idiom, tamer Q)
        let breath = preset.breath * (1.3 - 0.6 * reg);
        let breath_filt = Biquad::bandpass((2.5 * f).min(5000.0).min(sr * 0.4), 1.2, sr);
        let vibr = preset.vib;
        // RD10: the sax rasp stage — built only where the preset asks for it,
        // so filter-only reeds keep a rasp-free hot path AND an unchanged rng
        // draw order. The turbulence rms scales with the REGISTER-scaled
        // breath (low notes growl more, and the RD-O8a breath=0 seam kills it
        // for the clean-lattice oracles).
        let rasp = if preset.rasp.1 > 0.0 {
            Some(ReedRasp::new(
                RD_RASP_OVER,
                sr,
                f,
                width,
                preset.rasp,
                preset.rasp.2 * breath / RD_RASP_BREATH_REF,
            ))
        } else {
            None
        };
        let osc_sr = rasp.as_ref().map_or(sr, |r| r.osr);
        Reed {
            osc: ReedPulse::new(f, osc_sr, rng.white() * 0.5 + 0.5, width),
            osc_norm,
            formants,
            fdesign,
            tilt,
            rasp,
            // RD11 cone-fill: built only for the conical saxes (cone > 0). No self.rng
            // draw (partial phases are deterministic 0), so the reed's rng stream — and
            // every non-sax reed's render — is byte-identical.
            cone_res: (preset.cone > 0.0).then(|| ConeResidual::new(f, sr, preset.cone)),
            n_lo: preset.n_lo,
            n_hi: preset.n_hi,
            p_auth: 0.0,
            p_sm: p0,
            p_k: 1.0 - (-(CTRL as f32) / (RD_P_SMOOTH_S * sr)).exp(),
            base_f: f,
            bend: 1.0,
            scoop: preset.scoop,
            scoop_k: preset.scoop_k,
            breath_filt,
            breath,
            chiff_amp: RD_CHIFF_AMP * vn * vel_amp(vel),
            chiff_decay: t60_mul(RD_CHIFF_T60, sr),
            env: Adsr::new(
                vel_attack(preset.attack, vel),
                0.06,
                0.90,
                preset.release,
                sr,
            ),
            last_env: 0.0,
            vib: control_lfo(vibr.0, 0.08, &mut rng, sr),
            vib_depth: vibr.1,
            vib_delay: (vibr.2 * sr) as u32,
            vib_val: 0.0,
            rng,
            t: 0,
            vn,
            amp: preset.amp * vel_amp(vel),
            sr,
        }
    }
}

impl Voice for Reed {
    fn render(&mut self, out: &mut [f32]) -> bool {
        for o in out.iter_mut() {
            if self.t.is_multiple_of(CTRL) {
                // RD6 scoop settle + RD7 vibrato, composed into the retune so the
                // engine's per-block bend/CC1 writers cannot snap them back
                self.scoop += self.scoop_k * (1.0 - self.scoop);
                let v = self.vib.next();
                self.vib_val = v;
                let vib = if self.t > self.vib_delay {
                    let ramp = ((self.t - self.vib_delay) as f32 / (0.2 * self.sr)).min(1.0);
                    self.vib_depth * ramp * v
                } else {
                    0.0
                };
                let f = self.base_f * self.bend * self.scoop * (1.0 + vib);
                // RD10: a live rasp stage runs the source at m× the output
                // rate, so the pulse retunes against osr, not sr
                let osc_sr = self.rasp.as_ref().map_or(self.sr, |r| r.osr);
                self.osc.set_freq(f, osc_sr);
                // RD11 cone-fill: the residual is parallel to the rasp OUTPUT, so it
                // retunes against sr (not osr), following the same composed pitch.
                if let Some(cr) = &mut self.cone_res {
                    cr.set_freq(f, self.sr);
                }
                // RD9 blowing pressure: vel floor + env "speaking" term +
                // authored CC2/CC11 delta, smoothed ~15 ms (T-N1)
                let target = (RD_P_VEL.0
                    + RD_P_VEL.1 * self.vn.powf(RD_P_VEL_EXP)
                    + RD_P_ENV * self.last_env
                    + self.p_auth)
                    .clamp(0.0, 1.0);
                self.p_sm += self.p_k * (target - self.p_sm);
                let p = self.p_sm;
                // RD3 tilt: "speak N(p) harmonics" means the same thing at
                // every key — harmonic-count, not absolute Hz (§2.8.2)
                let cut = (f * self.n_lo * (self.n_hi / self.n_lo).powf(p))
                    .clamp(RD_TILT_FLOOR_HZ, self.sr * 0.4);
                self.tilt.retune_lowpass(cut, RD_TILT_Q, self.sr);
                // RD2 honk: pressure drives the slot GAINS only — the centres
                // and Qs never move, so nothing can read as a filter sweep
                let gmul = RD_FORM_ALPHA + RD_FORM_BETA * p;
                for (b, &(ff, q, g)) in self.formants.iter_mut().zip(&self.fdesign) {
                    if g != 0.0 {
                        b.retune_peak(ff, q, g * gmul, self.sr);
                    }
                }
                // RD10: drive from pressure (§2.8.4 "g = g0 + g_press·p"),
                // growl smoothed on the same T-N1 time constant as p
                if let Some(r) = &mut self.rasp {
                    r.growl_sm += self.p_k * (r.growl_tgt - r.growl_sm);
                    r.set_drive(p, f);
                }
            }
            // RD1 band-limited pulse; RD10 shapes it (its closed-form norm
            // holds the RD8 0.5-RMS anchor), the bypass applies RD8 directly
            let mut s = if let Some(r) = &mut self.rasp {
                r.white = self.rng.white();
                let mut y = 0.0;
                for _ in 0..r.m {
                    y = r.step(self.osc.next());
                }
                r.dcb.process(y)
            } else {
                self.osc.next() * self.osc_norm
            };
            // RD11 cone-fill: sum the parallel upper-harmonic residual (saxes only) so
            // the formant bank + tilt then shape it with the pulse. Downstream of the
            // rasp/bias-tanh chain ⇒ `bias = 2w−1` untouched; h1/h2 absent ⇒ the hot
            // fundamental/h2 untouched and the centroid not dragged.
            if let Some(cr) = &mut self.cone_res {
                s += cr.next();
            }
            // RD2 fixed formant bank (pressure-gained above)
            for b in &mut self.formants {
                s = b.process(s);
            }
            // RD3 pressure-tilt lowpass (12 dB/oct, no resonance)
            s = self.tilt.process(s);
            let e = self.env.next();
            self.last_env = e;
            // RD5 breath (rides the vibrato) — a quiet, envelope-scaled sustain
            // hiss, post-LP; and a one-shot tongue chiff sharing the same filter.
            // NB: the Wind voice decoupled this from the vibrato (round-3 flutter,
            // see WD_FLUTTER_*); the reed keeps the coupling — no sax "shaking"
            // complaint, and the reed breath (0.4×) is quieter — a conscious deferral.
            let breath_mod = 1.0 + 0.4 * self.vib_val;
            let noise = self.breath_filt.process(self.rng.white());
            s += noise * self.breath * e * breath_mod;
            // The tongue chiff is added OUTSIDE the amp envelope (the Brass/Pluck
            // onset_post precedent, voices.rs:2552) so it "spits" at t=0 even
            // while the amp envelope is still ramping in — a hard-tongued forte
            // attack spits, a soft entrance barely speaks. A slur kills it.
            let chiff = noise * self.chiff_amp * self.amp;
            self.chiff_amp *= self.chiff_decay;
            *o += s * self.amp * e + chiff;
            self.t += 1;
        }
        self.env.alive()
    }

    fn note_off(&mut self) {
        self.env.release();
    }

    fn released(&self) -> bool {
        self.env.released()
    }

    fn set_pitch(&mut self, mult: f32) {
        self.bend = mult;
    }

    fn set_breath(&mut self, pressure: f32, growl: f32) {
        // RD9 authored seam (§2.8.3 item 4, the Brass BR9 mirror): the engine
        // feeds √(expr·breath) — CC11 × CC2, neutral 1.0 — ONLY on channels
        // that have authored one of them, so an unauthored channel renders
        // controller-identically to before. Authored breath carves DOWNWARD
        // from the velocity anchor (CC2/CC11 at max = the vel-set voicing,
        // GM expression semantics); the ~15 ms smoother de-zippers the steps.
        // `growl` (aftertouch) scales the RD10 turbulence fraction — the
        // §2.8.4 growl seam. Inert until authored, and a no-op on the
        // filter-only reeds (no rasp stage to feed).
        self.p_auth = RD_P_AUTH_SPAN * (pressure.clamp(0.0, 1.0) - 1.0);
        if let Some(r) = &mut self.rasp {
            r.growl_tgt = growl.clamp(0.0, 1.0);
        }
    }

    fn legato_to(&mut self, key: u8, _vel: u8) -> bool {
        // RD6 slur: glide from the old pitch via the scoop, keep the air moving,
        // and kill the tongue chiff — one breath across several fingered notes
        let new_f = key_freq(key);
        self.scoop = (self.base_f * self.scoop / new_f).clamp(0.85, 1.18);
        self.base_f = new_f;
        self.chiff_amp = 0.0;
        true
    }

    #[cfg(test)]
    fn kind(&self) -> &'static str {
        "reed"
    }
}

fn reed(program: u8, key: u8, vel: u8, sr: f32, seed: u32) -> Reed {
    let preset: &'static ReedPreset = match program {
        22 => &HARMONICA,
        64 => &SOP_SAX,
        65 => &ALTO_SAX,
        66 => &TENOR_SAX,
        67 => &BARI_SAX,
        68 => &OBOE,
        69 => &ENGLISH_HORN,
        70 => &BASSOON,
        71 => &CLARINET,
        109 => &BAGPIPE,
        111 => &SHANAI,
        _ => &CLARINET,
    };
    let mut v = Reed::from_preset(preset, key, vel, sr, seed);
    if program == 109 {
        // A Highland chanter is a constant-pressure double reed fed by the
        // bag: NO dynamics (velocity is ignored — amplitude, brightness and
        // envelope are fixed), NO tongue chiff (articulation is grace-note
        // pitch flicks, not tonguing), no onset scoop, no vibrato mechanism.
        // Post-construct overrides so `from_preset` — and every sax / oboe /
        // clarinet voice built through it, and their RNG draw order — is
        // untouched (the bagpipe audition fix must not move the saxes).
        v.amp = preset.amp;
        // Fixed reed brightness: pin the pressure input to a constant bag
        // pressure (not breath). The §2.8.3 reed model has no RD4 tanh drive
        // any more — brightness is the pressure-swept tilt + formant honk, both
        // driven by `p` — so a fixed `vn` plus the flat sustain-1.0 envelope
        // below give a constant `p` and hence a constant, velocity-independent
        // timbre. (The old `v.drive = 1 + drive_vn·0.82` line retired with the
        // tanh; BP-O1 still guards the constant-amplitude chanter.)
        v.vn = 0.82;
        v.env = Adsr::new(0.010, 0.0, 1.0, preset.release, sr);
        v.chiff_amp = 0.0;
        v.scoop = 1.0;
        v.vib_depth = 0.0;
    }
    v
}

// ---------------------------------------------------------------------------
// Brass (GM 56–63) — the v0.9 flagship. An isolated sustaining voice adjacent
// to Wind/Bowed (§3.1): per-player lip-valve saws (2× oversampled), ONE
// loudness scalar driving both the lip lowpass and the per-player
// bias-referenced tanh (BR1/BR2), bore peak EQ + first-order bell shelf (BR3),
// straight-mute transmission (BR4), scoop/slur (BR5), breath+tongue chiff
// (BR6), section scatter (BR7), the synth-brass resonant sweep (BR8), the
// CC11 breath + aftertouch growl seam (BR9/BR10), and a DC guard (BR11).
// ---------------------------------------------------------------------------

const BR_DECIM_HZ: f32 = 13_500.0; // BR1 2× decimation cliff (Q 0.8, at sr2)
const BR_BITE_T60: f32 = 0.06; // BR2 tongue over-blow decay
const BR_ONSET_RAMP_S: f32 = 0.015; // BR7 late-entry smoothstep ramp
const BR_H_EXP: f32 = 1.4; // BR2 cutoff-law convexity
const BR_BLOOM_A: f32 = 0.25; // BR2 brightness-bloom attack (the "waa")
const BR_L_VEL: (f32, f32) = (0.10, 0.90); // BR2 timbre-law velocity floor/span
const BR_GROWL_HZ: f32 = 30.0; // BR10 flutter-tongue rate
const BR_GROWL_AM: f32 = 0.35; // BR10 flutter AM depth
const BR_GROWL_DRIVE: f32 = 1.6; // BR10 growl → shaper-index bite
const BR_GROWL_BRIGHT: f32 = 1.00; // BR10 growl → lip/output brightness (so the bite radiates)
const BR_K_MAX: f32 = 3.2; // BR1/BR2/BR10 composed-drive ceiling (alias cap)
const BR_GROWL_SLEW: f32 = 0.05; // BR9 growl_cur de-zipper slew (τ ≈ 7 ms)
const BR_SCOOP_CLAMP: (f32, f32) = (0.85, 1.19); // BR5 slur glide origin bounds
const BR_PRESS_FLOOR: (f32, f32) = (0.30, 0.70); // BR9 CC11=0 is dark, not dead

// BR-LB living-breath (Stage 2, solo naturals 56-60): a shallow, zero-mean, APERIODIC
// value-noise wander of the `l` timbre scalar so the sustain breathes instead of freezing.
// Because fc/kws/cascade/out_lp all ride `l`, one fold-in moves the whole timbre coherently.
// Depth is the one ear-tunable knob (out_oct=4.2 makes out_lp very sensitive → keep it small).
const BR_BREATH_DEPTH: f32 = 0.025; // fractional L modulation depth (first-cut; A/B-tunable)
const BR_BREATH_HOLD_S: f32 = 0.22; // value-noise mean segment (dominant ~2.3 Hz, sub-4 Hz peak)
const BR_BREATH_RAMP: (f32, f32) = (0.15, 0.40); // fade-in window (s): the onset stays bit-exact
                                                 // BR17 ordinary natural bodies settle before the 0.3 s timbre-hold window.
                                                 // Tuba waits for its LA handover because its stronger formants expose that seam.
const BR_BODY_RAMP: (f32, f32) = (0.12, 0.25);
const BR_TUBA_BODY_RAMP: (f32, f32) = (0.32, 0.45);
const BR_BREATH_SALT: u32 = 0x8BEA_7401; // throwaway-rng seed offset (never draws from self.rng)

// BR12 — progressive-steepening cascade (the "rasp"/cuivré). A real brass note
// "brasses up" when pushed: the pressure wave steepens toward a shock as it
// travels the bore, cascading energy into a slow-rolloff high-harmonic tail whose
// centroid climbs super-linearly with loudness. The single BR1 lip valve, driven
// linearly by L and capped at BR_K_MAX for aliasing, has a rolloff too fast for
// that tearing edge. BR12 adds a SECOND mild bias-tanh stage — a discrete analog
// of cumulative bore steepening — blended in by an amount that (a) blooms with
// loudness above a threshold (gated on `bright`, which spans ~0.3..1.0 in sustain
// and >1 only under authored growl — so mp stays clean and forte/ff/growl rip),
// (b) scales per-program by a brassiness constant B (trombone/trumpet rip, horn/
// tuba barely), and (c) derates at high f0 so the alias floor (BR-O11) holds at
// 2×. Naturals 56–61 only; the synth path (62/63, near-linear, no oversampling)
// never reads it. This is the FORK-A change: it reshapes the harmonic rolloff
// within the existing 2× envelope, it does NOT raise the drive past BR_K_MAX.
const BR_CASCADE_MAX: f32 = 1.0; // max morph toward the two-stage cascade (full rip)
const BR_CASCADE_SPLIT: f32 = 0.6; // stage-1 drive reduction at full cascade (the split)
const BR_CASCADE_K2: f32 = 2.6; // stage-2 shaper index (the second knee)
const BR_CASCADE_BIAS2: f32 = 0.55; // stage-2 bias fraction (less even, more buzz)
const BR_CASCADE_RADIATE: f32 = 1.2; // BR12 out_lp cutoff opening at full cascade (lets rasp radiate)
const BR_CASCADE_LO: f32 = 0.62; // bright below which no rasp (mp stays clean)
const BR_CASCADE_HI: f32 = 1.02; // bright at which the rasp is fully open (ff/growl)
const BR_CASCADE_F0: f32 = 440.0; // f0 (Hz) above which the rasp derates (alias guard)
                                  // BR13 ADAA (first-order antiderivative anti-aliasing on the rasp shaper) lifts
                                  // the sinc-suppressed alias floor by ≥29 dB at the worst BR-O11 guard bin, so the
                                  // high-f0 derate no longer has to gut the top-register rasp. Raised 0.06→0.60,
                                  // oracle-set: BR-O11b (F#6, the worst case) holds the fold-back a full 6 dB under
                                  // the 0.03 ceiling at this floor. The f0-dependent derate LAW is kept as margin.
const BR_CASCADE_F0_FLOOR: f32 = 0.30; // top-octave rasp lift (was a flat 0.06 pre-ADAA; see HLD §4)
                                       // BR13: the floor is applied ONLY to the top octave, ramped in over this band, so
                                       // it lifts F#6-and-up (where ADAA gives alias headroom) WITHOUT clamping the
                                       // mildly-derated upper-mid (A5≈880, B5≈988) up — over-driving those aliases under
                                       // growl and busts BR-O11. Below LIFT_LO the natural quartic derate stands alone.
const BR_CASCADE_LIFT_LO: f32 = 900.0; // Hz: below this the lift is inert (A5 keeps its natural rasp)
const BR_CASCADE_LIFT_HI: f32 = 1100.0; // Hz: above this the full lift applies (C6 and up)

/// Smoothstep 0→1 over [e0, e1]; flat outside. Used to gate the BR12 rasp on
/// loudness so it blooms in over forte rather than switching on.
#[inline]
fn smoothstep(e0: f32, e1: f32, x: f32) -> f32 {
    let t = ((x - e0) / (e1 - e0)).clamp(0.0, 1.0);
    t * t * (3.0 - 2.0 * t)
}

/// BR1 bias-referenced tanh lip valve. Normalisation `÷ tanh(0.9·k)` keeps the
/// positive peak ~k-invariant so the law changes *slope*, not loudness; the
/// bias term breaks odd symmetry so even harmonics appear (asymmetric flow).
#[inline]
fn brass_valve(x: f32, k: f32, b: f32) -> f32 {
    ((x * k + b).tanh() - b.tanh()) / (0.9 * k).tanh()
}

// --- BR13: first-order antiderivative anti-aliasing (ADAA) for the rasp ------
// See `wrk_docs/2026.07.11 - HLD - brass ADAA antialiasing`. First-order ADAA
// replaces the memoryless shaper f(x[n]) with the boxcar-filtered continuous
// model (F(x1)-F(x0))/(x1-x0), F=∫f — a sinc(f/sr2) prefilter with zeros at every
// multiple of sr2, i.e. exactly where the audible aliases are born. Applied
// STAGE-WISE (each bias-tanh separately, then the morph is a linear mix, which
// commutes with ADAA), so no composite antiderivative is needed. All math in f64
// (the divided difference is ill-conditioned near x1≈x0); audio stays f32.
const BR_ADAA_H: f64 = 1.0e-4; // |Δx| below which the DD cancels → midpoint fallback

/// Numerically stable ln cosh: |u| − ln2 + ln1p(e^(−2|u|)). Exact for all |u|
/// (the naive `cosh(u).ln()` overflows for |u| ≳ 20 even in f64).
#[inline]
fn lncosh(u: f64) -> f64 {
    let a = u.abs();
    a - std::f64::consts::LN_2 + (-2.0 * a).exp().ln_1p()
}

/// One bias-referenced tanh valve in f64 (mirrors `brass_valve`, the shaper the
/// antiderivative below integrates).
#[inline]
fn brass_valve_f64(x: f64, k: f64, b: f64) -> f64 {
    ((x * k + b).tanh() - b.tanh()) / (0.9 * k).tanh()
}

/// Antiderivative F of `brass_valve_f64`: ∫tanh(kx+b)dx = (1/k)lncosh(kx+b),
/// ∫tanh(b)dx = x·tanh(b), both ÷ the same tanh(0.9k) normaliser.
#[inline]
fn brass_valve_antideriv(x: f64, k: f64, b: f64) -> f64 {
    (lncosh(k * x + b) / k - x * b.tanh()) / (0.9 * k).tanh()
}

/// First-order ADAA of one bias valve over the step x0→x1. Divided difference of
/// the antiderivative, with a midpoint fallback when |Δx| < BR_ADAA_H to dodge the
/// catastrophic cancellation of `(F(x1)-F(x0))/(x1-x0)`. At the seam the two
/// branches agree to ~3e-9 (f64), far below f32 output quantisation, so the
/// switch is spectrally inert. F is recomputed each call with the CURRENT (k,b) —
/// never cached — because a cached F(x0) from ramped parameters is meaningless.
#[inline]
fn brass_valve_adaa(x1: f64, x0: f64, k: f64, b: f64) -> f64 {
    let dx = x1 - x0;
    if dx.abs() < BR_ADAA_H {
        brass_valve_f64(0.5 * (x0 + x1), k, b)
    } else {
        (brass_valve_antideriv(x1, k, b) - brass_valve_antideriv(x0, k, b)) / dx
    }
}

/// One BrassPlayer per human player: solo programs run 1, section 61 runs 3,
/// synth 62/63 run 5. (Skeleton: candidate B.)
struct BrassPlayer {
    saw: BlepSaw,       // lip source (natural: at sr2; synth: at sr)
    detune: f32,        // fixed per-player ratio (sections/synth)
    onset: u32,         // output samples of silence before this player speaks (BR7)
    lip_lp: OnePole,    // BR2 envelope-tracked lip-closure lowpass
    decim: [Biquad; 2], // BR1 2×→1× decimation cliff (natural only)
    vib_phase: f32,     // BR7 per-player autonomous vibrato (sections/synth)
    vib_rate: f32,
    drift: Drift, // BR7 random-walk pitch instability
    scoop: f32,   // BR5 per-player pitch mult settling toward 1.0
    scoop_k: f32, // BR5 per-player settle rate (jittered ±15% in sections)
    // BR13 ADAA state (natural path): previous sr2 sample fed to the shaper, and
    // the previous ADAA outputs of the single valve and the cascade's stage 1.
    // All zero at note-on — every valve maps 0→0, so x_prev=0 seeds exactly.
    x_prev: f64,
    s_prev: f64,
    u_prev: f64,
}

impl BrassPlayer {
    /// BR13: anti-aliased rasp for one sr2 sub-step. `x` is the lip_lp output
    /// (the shaper input). Mirrors `brass_rasp` but every bias-tanh is run through
    /// first-order ADAA, and the `single` branch carries a matching half-sample
    /// alignment average so the linear single↔cascade morph never combs (both
    /// paths land at 1.0-sample group delay). See the HLD §2/§4.
    #[inline]
    fn rasp_adaa(&mut self, x: f32, k: f32, b: f32, cascade_amt: f32) -> f32 {
        let (k, b, x) = (k as f64, b as f64, x as f64);
        let s = brass_valve_adaa(x, self.x_prev, k, b);
        let s_align = 0.5 * (s + self.s_prev); // +0.5-sample delay to match the cascade
        let y = if cascade_amt > 0.0 {
            let a = cascade_amt as f64;
            let k1 = k * (1.0 - BR_CASCADE_SPLIT as f64 * a);
            let u = brass_valve_adaa(x, self.x_prev, k1, b);
            let c = brass_valve_adaa(
                u,
                self.u_prev,
                BR_CASCADE_K2 as f64,
                b * BR_CASCADE_BIAS2 as f64,
            );
            self.u_prev = u;
            s_align + a * (c - s_align)
        } else {
            // Cascade dormant: keep u_prev tracking stage 1's static output so the
            // first sample after cascade_amt lifts off 0 has no seeding transient.
            self.u_prev = brass_valve_f64(x, k, b);
            s_align
        };
        self.x_prev = x;
        self.s_prev = s;
        y as f32
    }
}

pub struct BrassSpec {
    pub players: usize,
    pub detune_cents: f32,    // full spread; players spread linearly
    pub onset_scatter_s: f32, // per-player random onset in [0, this]; player 0 = 0
    pub scoop0: f32,
    pub scoop_k: f32, // BR5
    pub h_min: f32,
    pub h_max: f32, // BR2 lip cutoff, multiples of f0
    pub k_min: f32,
    pub k_max: f32,
    pub bias: f32,                       // BR1/BR2 law
    pub brassiness: f32, // BR12 rasp/cuivré readiness (0 = no cascade; ~1 = rips easily)
    pub bore: [(f32, f32, f32); 2], // BR3 (Hz, Q, dB); Hz=0 → skip
    pub body_hp: (f32, f32), // BR17 bell/body radiation HP (Hz, Q); Hz=0 → disabled
    pub body_bore: [(f32, f32, f32); 2], // BR17 hold-only formants; Hz=0 → skip
    pub body_lp_base: f32, // BR17 hold-only L-driven LP; 0 → disabled
    pub body_gain: f32,  // BR17 level-neutral makeup after body_hp
    pub body_ramp: (f32, f32), // BR17 onset-to-corrected-body crossfade (seconds)
    pub bell_fc: f32,
    pub bell_g: f32, // BR3
    // BR2 output brightness: an L-driven radiated lowpass `out_base·2^(out_oct·L)`
    // (the Bowed env→brightness precedent, voices.rs:1861), so the flagship
    // loudness law reaches the OUTPUT centroid past the fixed bore/bell — the
    // lip lowpass alone is masked by them. out_base=0 → disabled (synth, which
    // owns its own resonant sweep).
    pub out_base: f32,
    pub out_oct: f32,
    pub mute: bool,                                // BR4
    pub synth_sweep: Option<(f32, f32, f32, f32)>, // BR8 (base, vel0, vel_depth, q)
    pub fenv: (f32, f32, f32, f32),                // BR8 synth resonant-sweep envelope (A/D/S/R)
    pub breath: f32,
    pub chiff: f32,                // BR6
    pub env: (f32, f32, f32, f32), // amp A/D/S/R
    pub vib: (f32, f32, f32),      // BR7 (rate, depth, delay); depth=0 → none
    pub drift: f32,
    pub growl: bool, // BR10 aftertouch growl enabled (naturals yes, synth no)
    pub amp: f32,
    #[cfg(test)]
    pub name: &'static str, // kind() string, oracle-36 seam
}

