    /// Guitar block two §3 — the high-key damper hold: HELD-note (no
    /// note_off — release stays G6-governed by design) f0-band decay rate
    /// at the formerly-cliffed keys must sit in the audibly-plucked-but-
    /// ringing band. Estimator per the HLD: ±¼-octave f0 bandpass, frame
    /// RMS at 0.10–0.20 s vs 0.50–0.60 s, seeds {5, 21, 99} averaged.
    /// Pre-fix these read ≈ −62/−333 dB/s (steel 76/88) and −113/−687
    /// (nylon) at vel 100 — E6 died inside 100 ms.
    #[test]
    fn guitar_treble_hold_decay_band() {
        let sr = 44100.0;
        let rate = |prog: u8, key: u8, vel: u8| -> f32 {
            let mut acc = 0.0;
            for seed in [5u32, 21, 99] {
                let mut v = make(prog, key, vel, sr, seed, false);
                let mut buf = vec![0f32; (0.7 * sr) as usize];
                v.render(&mut buf);
                let f0 = key_freq(key);
                let band = |a: f32, b: f32| {
                    crate::testutil::band_rms(
                        &buf[(a * sr) as usize..(b * sr) as usize],
                        sr,
                        f0,
                        2.0, // ~±1/4 octave
                    )
                };
                let (early, late) = (band(0.10, 0.20), band(0.50, 0.60));
                acc += 20.0 * (late / early.max(1e-12)).max(1e-12).log10() / 0.4;
            }
            acc / 3.0
        };
        for (prog, name) in [(25u8, "steel"), (24, "nylon")] {
            for key in [76u8, 88] {
                let r = rate(prog, key, 100);
                // Slow end widened -15 -> -6 for the 2026.07.23 plucked-family t60
                // re-fit: the guitars now ring at the references' rate (nylon/steel
                // t60 3.8/4.5 -> 7.7/7.0), so a high note legitimately decays only
                // ~7-11 dB/s. The band still catches a DEAD note (faster than -80,
                // the pre-KILN-00042 cliff) and a stuck/organ note (slower than -6).
                assert!(
                    (-80.0..=-6.0).contains(&r),
                    "{name} key {key} vel 100: decay {r:.1} dB/s outside the \
                     plucked-but-ringing band [-80, -6]"
                );
            }
        }
        // Vel-40 CANARY: under KILN-00042 alone the corner scaled with velocity so
        // the hold's reach SHRANK at low velocity — the cliff was reduced, not
        // removed (this pinned ≈ −450..−40 dB/s). The 2026.07.23 t60 re-fit
        // (nylon 3.8 → 7.7) removes it at vel 40 too: the note now rings at ≈ −12.6
        // dB/s, in the same plucked-but-ringing band as vel 100. The wide bound still
        // surfaces a regression to the ≈ −1198 pre-fix cliff.
        let r = rate(24, 88, 40);
        assert!(
            (-80.0..=-6.0).contains(&r),
            "nylon key 88 vel 40 canary moved: {r:.1} dB/s (was ≈ −1198 pre-KILN-00042, \
             ≈ −450..−40 under the hold alone; the t60 re-fit rings it at ≈ −12.6)"
        );
    }

    /// KILN-00048: RENDERED decay-rate velocity invariance. The
    /// velocity/damper decouple makes a plucked string's decay RATE a function
    /// of pitch and `t60` alone, never of pluck strength.
    /// `rendered_ks_decay_tilt_holds_across_register` guards the register law's
    /// rendered wiring; THIS guards velocity decoupling through that same loop
    /// path (loop_gain, coupling, the whole KS loop) end-to-end.
    ///
    /// Decay is measured in the SETTLED regime (both windows past 0.45 s, so the
    /// front-loaded early cliff is excluded), band-limited to f0 (and 3·f0) to
    /// remove the "which partials died" confound, and ENERGY-averaged across
    /// seeds BEFORE the log (the per-note ±10 % t60 / ±8 % bright jitter).
    /// `sub`/`kick`/`attack_noise`/`mwah` are stripped on twins: an f0-locked
    /// sine (the sub) with a velocity-weighted amplitude decaying at its OWN rate
    /// would manufacture the exact velocity-dependent f0-band slope this oracle
    /// forbids; the shamisen jawari buzz is level-dependent contact, stripped the
    /// same way. Fail-first: the pre-decouple synth read STEEL key 60 at
    /// 11.9 dB/s (vel 127) vs 20.8 (vel 32) — a 1.75× f0-band spread.
    #[test]
    fn ks_decay_rate_is_velocity_invariant() {
        let strip = |base: &PluckPreset| PluckPreset {
            sub: 0.0,
            kick: 0.0,
            attack_noise: 0.0,
            mwah: None,
            ..*base
        };
        let cases: [(&str, PluckPreset, u8); 6] = [
            ("STEEL", STEEL, 60),
            ("NYLON", NYLON, 60),
            ("BASS", strip(&BASS), 34),
            ("FRETLESS", strip(&FRETLESS), 34),
            ("KOTO", KOTO, 60),
            ("SHAMISEN", strip(&SHAMISEN), 60),
        ];
        for (name, p, key) in &cases {
            for &(harm, k_tol, floor) in &[(1.0f32, 0.15f32, 1.5f32), (3.0, 0.20, 2.5)] {
                let r100 = rendered_ks_decay_rate(p, *key, 100, harm);
                let tol = (k_tol * r100.abs()).max(floor);
                for &vel in &[32u8, 64, 127] {
                    let rv = rendered_ks_decay_rate(p, *key, vel, harm);
                    assert!(
                        (rv - r100).abs() <= tol,
                        "{name} key {key} band×{harm}: decay {rv:.1} dB/s @vel {vel} vs \
                         {r100:.1} @vel 100 — Δ {:.1} > tol {tol:.1}: velocity leaked into decay",
                        (rv - r100).abs()
                    );
                }
            }
        }
    }

    /// Authoring pins (KILN-00042, succeeding guitar block two's review C4):
    /// the hold is derived by default and OFF exactly where a documented
    /// decision says so — nowhere else.
    #[test]
    fn treble_hold_authoring_pins() {
        // Default ON: the f³ collapse is a defect, so presets opt OUT, not in.
        assert_eq!(DEFAULTS.damper_hold, DamperHold::Derived);
        assert_eq!(NYLON.damper_hold, DamperHold::Derived);
        assert_eq!(STEEL.damper_hold, DamperHold::Derived);
        assert_eq!(
            UKULELE.damper_hold,
            DamperHold::Derived,
            "inherits ..NYLON by design"
        );
        // The documented opt-outs, each for a stated reason.
        assert_eq!(
            OUD.damper_hold,
            DamperHold::Off,
            "deliberate voicing (warm dark top) — lifting it is an ear decision"
        );
        assert_eq!(
            HARPSICHORD.damper_hold,
            DamperHold::Off,
            "HARPSICHORD is held out of KILN-00042 while its LA layer remains separately calibrated"
        );

        // ...and NOTHING ELSE is Off. This closes the loophole in the decay-law
        // oracle, which skips `Off` presets by design: without this pin, quietly
        // flipping a preset to `Off` would silently remove it from that oracle's
        // coverage instead of failing anything.
        // sorted so reordering ALL_PLUCK_PRESETS cannot fail this spuriously
        // KILN-00045 reconciled the bass-family held levels and moved BASS/FRETLESS
        // back to the derived hold, so they must no longer appear in this opt-out list.
        // DRIVE_LEAD left this list in KILN-00049: its output-domain sustainer
        // controller now makes the derived hold safe across the full register.
        const EXPECTED_OFF: &[&str] = &["HARPSICHORD", "OUD"];
        let mut actual_off: Vec<&str> = ALL_PLUCK_PRESETS
            .iter()
            .filter(|(_, p)| p.damper_hold == DamperHold::Off)
            .map(|(n, _)| *n)
            .collect();
        actual_off.sort_unstable();
        assert_eq!(
            actual_off, EXPECTED_OFF,
            "the set of damper-hold opt-outs changed. Every opt-out needs a stated \
             reason in the preset AND an entry here — otherwise it drops out of \
             ks_decay_law_holds_across_register unnoticed."
        );
    }

    /// The OUD opt-out proven in the ACTIVE range: a high-key oud render must
    /// be bit-identical to a forced-`Off` twin, AND must genuinely differ from
    /// a `Derived` one. The first half catches an inherited default leaking in;
    /// the second half stops the test going vacuous if `Off` ever became a
    /// no-op. Key-60 ratio tests cannot see either.
    #[test]
    fn oud_high_key_ignores_treble_hold() {
        let sr = 44100.0;
        let twin = PluckPreset {
            damper_hold: DamperHold::Off,
            ..OUD
        };
        let render = |p: &PluckPreset| {
            let mut v = Pluck::new(p, 88, 100, sr, 5);
            let mut buf = vec![0f32; 22050];
            v.render(&mut buf);
            buf
        };
        let (a, b) = (render(&OUD), render(&twin));
        assert!(
            a.iter().zip(&b).all(|(x, y)| x.to_bits() == y.to_bits()),
            "oud high keys must ignore the treble hold"
        );
        // ...and the opt-out must MEAN something: a Derived twin has to differ,
        // or this oracle would pass just as happily on a broken `Off`.
        let derived = render(&PluckPreset {
            damper_hold: DamperHold::Derived,
            ..OUD
        });
        assert!(
            a.iter()
                .zip(&derived)
                .any(|(x, y)| x.to_bits() != y.to_bits()),
            "OUD's Off opt-out is vacuous — a Derived twin renders identically, \
             so this key is not in the hold's active range and the oracle proves nothing"
        );
    }

    /// Guitar-realism HLD §6 (4a) / AC5 — the authored release thump is
    /// present and low-band: same seed, stop_thump on vs off, differential
    /// isolated to the post-note-off window (the same differential pattern
    /// as the pick-click oracle below; note_off never fires in the onset
    /// oracles, so they cannot be confounded).
    ///
    /// Phase-2 RE-BASELINE (Shaped excitation, 2026.07.20): STEEL's thump/ring
    /// bar drops from 0.25 to 0.20; NYLON (Legacy) stays 0.25, bit-exact. This is
    /// NOT a weakened thump — the thump stays PRESENT (differential non-zero) and
    /// LOW-BAND (hf frac 0.081, well under the 0.2 clause). What changed is the
    /// RING it is measured against: STEEL went Shaped, whose slope-1.4 backbone
    /// concentrates energy in the slow-decaying low harmonics, so by the 0.4 s
    /// note-off the string rings ~7.6 dB louder than Legacy (measured key 52:
    /// ring 0.0088 vs 0.0037). The stop_thump injection is unchanged (Legacy,
    /// parallel); its isolated differential even reads slightly LOWER (0.0020 vs
    /// 0.0033) because it now rides a louder signal into the output nonlinearity.
    /// Net: the thump is quieter RELATIVE to a louder ring, so the ratio falls to
    /// 0.229 — still an audible low thud, and 0.20 keeps the present+low-band
    /// guarantee. (STEEL's overall mix level stays in spec — golden_mix ch1.)
    #[test]
    fn guitar_release_thump_speaks_low() {
        let sr = 44100.0;
        for (preset, min_rel) in [(&NYLON, 0.25f32), (&STEEL, 0.20)] {
            let render = |p: &PluckPreset| {
                let mut v = Pluck::new(p, 52, 100, sr, 5);
                let mut pre = vec![0f32; (0.4 * sr) as usize];
                v.render(&mut pre);
                v.note_off();
                let mut post = vec![0f32; (0.15 * sr) as usize];
                v.render(&mut post);
                post
            };
            let quiet = PluckPreset {
                stop_thump: 0.0,
                ..*preset
            };
            let (on, off) = (render(preset), render(&quiet));
            let diff: Vec<f32> = on.iter().zip(&off).map(|(a, b)| a - b).collect();
            let (d, o) = (crate::testutil::rms(&diff), crate::testutil::rms(&off));
            assert!(
                d > min_rel * o,
                "{}: release thump inaudible (diff {d:.6} vs ring {o:.6})",
                preset.name
            );
            let hf = crate::testutil::hp_rms(&diff, sr, 1500.0) / d.max(1e-12);
            assert!(
                hf < 0.2,
                "{}: release thump is not low-band (hf frac {hf:.3})",
                preset.name
            );
        }
    }

    /// Oracle 7 (§5.3 differential): the pick click adds real onset HF —
    /// same seed, same preset, click on vs off.
    #[test]
    fn pick_click_is_audible() {
        let sr = 44100.0;
        let no_click = PluckPreset {
            click: 0.0,
            ..STEEL
        };
        let with = render_pluck(&STEEL, 45, 100, 0.1, 7);
        let without = render_pluck(&no_click, 45, 100, 0.1, 7);
        let onset_hf = |s: &[f32]| {
            crate::testutil::hp_rms(&s[..(0.003 * sr) as usize], sr, 1500.0)
                / crate::testutil::rms(&s[(0.05 * sr) as usize..(0.08 * sr) as usize]).max(1e-9)
        };
        let (w, wo) = (onset_hf(&with), onset_hf(&without));
        // Phase-1 pluck-redesign re-baseline (HLD §7): the STEEL pick click was
        // cut 2.0 -> 0.9 (attack-side taming), so its onset-HF boost over the
        // click-off case shrank from >1.3x to ~1.09x — the flat excitation
        // dominates onset HF until Phase 2 gentles it, so the click is now a
        // smaller (but still real, +9%) onset term. Bar recalibrated 1.3 -> 1.05
        // (RED at no-click = 1.0; GREEN at the shipped 0.9 click = ~1.09). Phase 2
        // widens this margin as the excitation's own onset HF falls.
        assert!(w > 1.05 * wo, "click on {w} vs off {wo}");
        // NYLON's fingernail is softer than STEEL's plectrum
        let nylon = render_pluck(&NYLON, 45, 100, 0.1, 7);
        let no_nylon = render_pluck(
            &PluckPreset {
                click: 0.0,
                ..NYLON
            },
            45,
            100,
            0.1,
            7,
        );
        let gain = |a: f32, b: f32| a / b.max(1e-9);
        assert!(
            gain(onset_hf(&nylon), onset_hf(&no_nylon)) < gain(w, wo),
            "NYLON click should be softer than STEEL's"
        );
    }

    /// Phase-1 (natural-pluck HLD §8): cutting the pick click reduces the ONSET
    /// HF transient — the pick "tick" that reads as fierce — the low-risk first
    /// step before the Phase-2 excitation redesign. The broadband att/sus ratio
    /// is EXCITATION-dominated (the click is a small term there — measured a
    /// <0.1 % move on CLEAN), so the click's effect lives in the onset >1.5 kHz
    /// band. Where the click DOMINATES that band (STEEL 2.0, DRIVE 2.2 — the
    /// loud ch14-family clicks) the reduction is decisive and checked strictly;
    /// where the excitation's own HF dominates (e.g. CLEAN's pick_lp 4500) the
    /// per-cell effect is small and sign-unstable, so the whole set is checked in
    /// AGGREGATE (≥10 % total reduction). (The remaining front-load — the att/sus
    /// fierceness proper — is Phase 2's excitation redesign.)
    #[test]
    fn phase1_click_cut_reduces_onset_hf() {
        let sr = 44100.0;
        let onset_hf = |s: &[f32]| crate::testutil::hp_rms(&s[..(0.005 * sr) as usize], sr, 1500.0);
        // (preset, pre-Phase-1 click value, strict-per-key check?)
        let cases: &[(&PluckPreset, f32, bool)] = &[
            (&STEEL, 2.0, true),
            (&DRIVE, 2.2, true),
            (&CLEAN, 1.8, false),
            (&JAZZ, 1.2, false),
            (&PICK, 1.6, false),
            (&DULCIMER, 1.7, false),
            (&NYLON, 0.9, false),
            (&OUD, 0.8, false),
        ];
        let (mut now_sum, mut loud_sum) = (0.0f32, 0.0f32);
        for &(preset, old_click, strict) in cases {
            assert!(
                preset.click < old_click,
                "{}: Phase-1 must have cut the click below {old_click}",
                preset.name
            );
            let loud = PluckPreset {
                click: old_click,
                ..*preset
            };
            for &key in &[40u8, 52, 64] {
                let now = onset_hf(&render_pluck(preset, key, 100, 0.2, 7));
                let loud_hf = onset_hf(&render_pluck(&loud, key, 100, 0.2, 7));
                now_sum += now;
                loud_sum += loud_hf;
                if strict {
                    assert!(
                        now < loud_hf,
                        "{} key {key}: onset HF {now:.5} not below pre-cut {loud_hf:.5}",
                        preset.name
                    );
                }
            }
        }
        // Aggregate across the whole cut set: the pick-tick energy is meaningfully
        // down (robust to the few excitation-dominated cells). Bar >=5%: the A/B
        // follow-up gave DRIVE a soft onset (attack_s 0.015) that ramps its string
        // front-load in, trimming the click's share of the onset-HF band, so the
        // aggregate click-reduction eased ~10% -> ~9%. 5% stays robustly GREEN while
        // still going RED if the clicks were restored.
        assert!(
            now_sum < 0.95 * loud_sum,
            "total onset HF {now_sum:.4} not >=5% below pre-cut {loud_sum:.4}"
        );
    }

    /// Oracle 8 (§5.1): SLAP's first 3 ms carry ≥3× the >3 kHz energy of
    /// fingered BASS at the same low key, and the fundamental stays E1.
    #[test]
    fn slap_transient_and_pitch() {
        let sr = 44100.0;
        let slap = render_pluck(&SLAP, 28, 110, 0.6, 7);
        let bass = render_pluck(&BASS, 28, 110, 0.6, 7);
        let onset = |s: &[f32]| crate::testutil::hp_rms(&s[..(0.003 * sr) as usize], sr, 3000.0);
        assert!(
            onset(&slap) >= 3.0 * onset(&bass),
            "slap onset {} vs bass {}",
            onset(&slap),
            onset(&bass)
        );
        let f = crate::testutil::peak_locate(&slap[(0.1 * sr) as usize..], sr, 35.0, 50.0);
        assert!((f - 41.2).abs() < 4.0, "slap fundamental {f} Hz");
    }

    /// MM-BUG-KILN-00016: GM36/37 must get their slap/pop identity from a
    /// string-path fret collision, not only the legacy post-output burst. The
    /// contact-disabled lesion deliberately keeps `click_post`, so a pass here
    /// proves the old burst alone no longer satisfies the identity oracle.
    #[test]
    fn slap_pop_identity_depends_on_fret_collision() {
        let sr = 44100.0;
        for (name, preset, key) in [("SLAP", &SLAP, 28u8), ("SLAP_POP", &SLAP_POP, 40)] {
            let no_contact = PluckPreset {
                fret_contact: None,
                ..*preset
            };
            let with = render_pluck(preset, key, 114, 0.16, 0x1600 + key as u32);
            let without = render_pluck(&no_contact, key, 114, 0.16, 0x1600 + key as u32);
            let residual: Vec<f32> = with.iter().zip(&without).map(|(&a, &b)| a - b).collect();

            let legacy_burst = hp_rms(segment(&without, sr, 0.0, 0.003), sr, 3000.0);
            assert!(
                legacy_burst > 1.0e-4,
                "{name}: lesion accidentally removed the legacy post-output burst"
            );

            let attack_contact = hp_rms(segment(&residual, sr, 0.006, 0.030), sr, 2400.0);
            let attack_body = hp_rms(segment(&with, sr, 0.006, 0.030), sr, 2400.0);
            assert!(
                attack_contact > 0.18 * attack_body.max(1e-9),
                "{name}: fret contact does not carry the slap/pop attack identity: \
                 residual {attack_contact:.6} vs body {attack_body:.6}"
            );

            let settled = segment(&with, sr, 0.080, 0.140);
            let f0 = key_freq(key);
            let pitch = peak_locate(settled, sr, f0 * 0.82, f0 * 1.18);
            assert!(
                (pitch / f0 - 1.0).abs() < 0.045,
                "{name}: fret collision moved settled pitch to {pitch:.2} Hz, expected {f0:.2}"
            );
        }
    }

    /// The retained post-output click may add a small acoustic detail, but it
    /// must not remain the identity carrier after the string-path collision
    /// exists. This is the level-matched lesion the original KILN-00016 recovery
    /// was missing: remove only `click`, keep `fret_contact`, and prove the
    /// contact-only voice still reads as slap/pop while the removed burst is small.
    #[test]
    fn slap_pop_post_click_is_secondary_to_fret_collision() {
        let sr = 44100.0;
        let attack = (0.055 * sr) as usize;
        let distance = |a: &[f32], b: &[f32]| {
            let ar = rms(a).max(1e-12);
            let br = rms(b).max(1e-12);
            let residual: Vec<f32> = a.iter().zip(b).map(|(&x, &y)| x / ar - y / br).collect();
            rms(&residual)
        };

        for (name, preset, key) in [("SLAP", &SLAP, 28u8), ("SLAP_POP", &SLAP_POP, 40)] {
            let contact_only = PluckPreset {
                click: 0.0,
                ..*preset
            };
            let plain = PluckPreset {
                click: 0.0,
                fret_contact: None,
                ..*preset
            };
            let seed = 0x16_5000 + key as u32;
            let full = render_pluck(preset, key, 114, 0.18, seed);
            let no_click = render_pluck(&contact_only, key, 114, 0.18, seed);
            let no_contact = render_pluck(&plain, key, 114, 0.18, seed);
            let finger = render_pluck(&BASS, key, 114, 0.18, seed);

            let click_residual: Vec<f32> =
                full.iter().zip(&no_click).map(|(&x, &y)| x - y).collect();
            let contact_residual: Vec<f32> = no_click
                .iter()
                .zip(&no_contact)
                .map(|(&x, &y)| x - y)
                .collect();
            let click_hf = hp_rms(segment(&click_residual, sr, 0.0, 0.003), sr, 3000.0);
            let contact_hf = hp_rms(segment(&contact_residual, sr, 0.0, 0.030), sr, 2400.0);
            let click_energy = click_hf * click_hf * 0.003;
            let contact_energy = contact_hf * contact_hf * 0.030;
            assert!(
                click_energy < 0.35 * contact_energy.max(1e-12),
                "{name}: post-output click is still too large relative to string contact: \
                 click {click_energy:.8}, contact {contact_energy:.8}"
            );

            let contact_identity = distance(&no_click[..attack], &finger[..attack]);
            let click_shift = distance(&full[..attack], &no_click[..attack]);
            assert!(
                contact_identity > 0.35 && click_shift < 0.45 * contact_identity,
                "{name}: contact-only identity is not dominant after level matching: \
                 contact/finger {contact_identity:.3}, full/no-click {click_shift:.3}"
            );
        }
    }

    /// The fret-collision layer is a thresholded physical contact: soft notes
    /// should not chatter, hard notes should get disproportionately more contact
    /// energy, and the contact must be bounded to the attack interval.
    #[test]
    fn slap_pop_fret_collision_scales_and_dies() {
        let sr = 44100.0;
        for (name, preset, key) in [("SLAP", &SLAP, 28u8), ("SLAP_POP", &SLAP_POP, 40)] {
            let no_contact = PluckPreset {
                fret_contact: None,
                ..*preset
            };
            let contact = |vel: u8, a: f32, b: f32| {
                let seed = 0x6100 + key as u32 + vel as u32;
                let with = render_pluck(preset, key, vel, 0.18, seed);
                let without = render_pluck(&no_contact, key, vel, 0.18, seed);
                let residual: Vec<f32> = with.iter().zip(&without).map(|(&x, &y)| x - y).collect();
                hp_rms(segment(&residual, sr, a, b), sr, 2400.0)
            };
            let soft = contact(34, 0.006, 0.032);
            let mid = contact(84, 0.006, 0.032);
            let hard = contact(124, 0.006, 0.032);
            assert!(
                soft < 0.12 * hard.max(1e-9),
                "{name}: soft contact chatters too much: soft {soft:.6}, hard {hard:.6}"
            );
            assert!(
                hard > 1.8 * mid.max(1e-9),
                "{name}: contact does not grow superlinearly with velocity: \
                 soft {soft:.6}, mid {mid:.6}, hard {hard:.6}"
            );
            let late = contact(124, 0.075, 0.135);
            assert!(
                late < 0.20 * hard.max(1e-9),
                "{name}: fret contact leaves a sustained buzz tail: late {late:.6}, \
                 hard attack {hard:.6}"
            );
        }
    }

    #[test]
    fn slap_fret_collision_map_is_passive_and_attack_bounded() {
        let sr = 44100.0;
        for (name, spec) in [
            ("SLAP", SLAP.fret_contact.unwrap()),
            ("SLAP_POP", SLAP_POP.fret_contact.unwrap()),
        ] {
            assert!(
                FretContact::new(&spec, spec.vel_floor * 0.95, sr, spec.vert).is_none(),
                "{name}: below-threshold velocity armed fret contact"
            );

            let mut contact =
                FretContact::new(&spec, 1.0, sr, spec.vert).expect("hard note arms contact");
            let until = (spec.duration_s * sr) as usize;
            let mut changed = 0usize;
            for i in 0..(until + 64) {
                let s = if i % 4 < 2 { -0.8 } else { 0.45 };
                let y = contact.process(s);
                assert!(
                    y.abs() <= s.abs() + 1e-6,
                    "{name}: fret reflection increased sample magnitude: {y} from {s}"
                );
                if i < until && y.to_bits() != s.to_bits() {
                    changed += 1;
                }
                if i >= until {
                    assert_eq!(
                        y.to_bits(),
                        s.to_bits(),
                        "{name}: fret contact did not become exact pass-through after its attack window"
                    );
                }
            }
            assert!(changed > 0, "{name}: hard contact never touched the signal");
        }
    }

    /// The complete MM-BUG-KILN-00016 acceptance grid: slap, pop, and fingered
    /// bass stay level-matched but timbrally distinct across the useful register
    /// and performance range; hard contact stays pitched, deterministic, finite,
    /// attack-only, and the released voices still reap.
    #[test]
    fn slap_pop_identity_holds_across_register_and_lifecycle() {
        let sr = 44100.0;
        let distance = |a: &[f32], b: &[f32]| {
            let ar = rms(a).max(1e-12);
            let br = rms(b).max(1e-12);
            let residual: Vec<f32> = a.iter().zip(b).map(|(&x, &y)| x / ar - y / br).collect();
            rms(&residual)
        };

        for key in [28u8, 40, 52] {
            for vel in [64u8, 96, 124] {
                let seed = 0x16_0000 + ((key as u32) << 8) + vel as u32;
                let slap = render_pluck(&SLAP, key, vel, 0.16, seed);
                let pop = render_pluck(&SLAP_POP, key, vel, 0.16, seed);
                let finger = render_pluck(&BASS, key, vel, 0.16, seed);
                assert!(
                    slap.iter().chain(&pop).all(|x| x.is_finite()),
                    "key {key} vel {vel}: slap/pop produced non-finite output"
                );
                assert_eq!(
                    slap,
                    render_pluck(&SLAP, key, vel, 0.16, seed),
                    "key {key} vel {vel}: slap render is not deterministic"
                );
                assert_eq!(
                    pop,
                    render_pluck(&SLAP_POP, key, vel, 0.16, seed),
                    "key {key} vel {vel}: pop render is not deterministic"
                );

                let attack = (0.055 * sr) as usize;
                let sf = distance(&slap[..attack], &finger[..attack]);
                let pf = distance(&pop[..attack], &finger[..attack]);
                let sp = distance(&slap[..attack], &pop[..attack]);
                assert!(
                    sf > 0.35 && pf > 0.35 && sp > 0.20,
                    "key {key} vel {vel}: level-matched attack identities collapsed \
                     (slap/finger {sf:.3}, pop/finger {pf:.3}, slap/pop {sp:.3})"
                );

                if vel == 124 {
                    let settled = segment(&slap, sr, 0.080, 0.150);
                    let f0 = key_freq(key);
                    let pitch = peak_locate(settled, sr, f0 * 0.82, f0 * 1.18);
                    assert!(
                        (pitch / f0 - 1.0).abs() < 0.045,
                        "key {key}: hard slap settled at {pitch:.2} Hz, expected {f0:.2}"
                    );
                }
            }
        }

        for (name, preset) in [("SLAP", &SLAP), ("SLAP_POP", &SLAP_POP)] {
            let mut voice = Pluck::new(preset, 40, 124, sr, 0x16_FF);
            let mut attack = vec![0.0; (0.080 * sr) as usize];
            voice.render(&mut attack);
            assert!(
                voice.horiz.fret.is_none() && voice.vert.fret.is_none(),
                "{name}: expired fret-contact runtime was not retired"
            );
            voice.note_off();
            let mut block = [0.0f32; 256];
            let mut alive = true;
            for _ in 0..((5.0 * sr) as usize / block.len() + 1) {
                block.fill(0.0);
                alive = voice.render(&mut block);
                assert!(
                    block.iter().all(|x| x.is_finite()),
                    "{name}: release produced non-finite output"
                );
                if !alive {
                    break;
                }
            }
            assert!(!alive, "{name}: voice did not reap within five seconds");
        }
    }

    /// Oracle 9 (§5): FRETLESS finger noise — onset >2 kHz energy above the
    /// no-noise baseline, dying within ~8 ms.
    #[test]
    fn finger_noise_speaks_then_dies() {
        let sr = 44100.0;
        let with = render_pluck(&FRETLESS, 31, 80, 0.1, 7);
        let without = render_pluck(
            &PluckPreset {
                attack_noise: 0.0,
                ..FRETLESS
            },
            31,
            80,
            0.1,
            7,
        );
        let hf = |s: &[f32], a: f32, b: f32| {
            crate::testutil::hp_rms(&s[(a * sr) as usize..(b * sr) as usize], sr, 2000.0)
        };
        assert!(
            hf(&with, 0.0, 0.008) > 1.5 * hf(&without, 0.0, 0.008),
            "finger noise: {} vs {}",
            hf(&with, 0.0, 0.008),
            hf(&without, 0.0, 0.008)
        );
        // the NOISE dies within ~8 ms — measure its energy excess over the
        // noiseless build per window (the string itself is still ramping up)
        let excess =
            |a: f32, b: f32| (hf(&with, a, b).powi(2) - hf(&without, a, b).powi(2)).max(0.0);
        assert!(
            excess(0.012, 0.020) < 0.35 * excess(0.0, 0.008),
            "finger noise rings too long: late {} vs early {}",
            excess(0.012, 0.020),
            excess(0.0, 0.008)
        );
    }

    #[test]
    fn fretless_bass_35_mwah_blooms() {
        let sr = 44100.0;
        let vel = 96;
        let spec = FRETLESS.mwah.expect("FRETLESS must carry the mwah spec");
        let no_mwah = PluckPreset {
            mwah: None,
            ..FRETLESS
        };

        assert_eq!(make(35, 31, vel, sr, 7, false).kind(), "FRETLESS");

        for key in [31u8, 38] {
            let seed = 0x35_00u32 + key as u32;
            let with = render_program(35, key, vel, 0.55, seed);
            // SYMMETRIZE THE PAIR. `render_program` goes through `make()`, which
            // applies the `VEL_LEVEL_EXP` correction; `render_pluck` builds the model
            // directly and does not. Without matching them, the residual carries a
            // slice of the WHOLE voice (-4.4 % at GM35/v96), not just the mwah, and the
            // formant clauses measure that leak instead of the feature under test.
            let comp = ScaledVoice::gain(vel, VEL_LEVEL_EXP[35]);
            let without: Vec<f32> = render_pluck(&no_mwah, key, vel, 0.55, seed)
                .into_iter()
                .map(|s| s * comp)
                .collect();
            let residual: Vec<f32> = with.iter().zip(&without).map(|(a, b)| a - b).collect();
            let band = |s: &[f32], a: f32, b: f32, hz: f32| {
                let lo = (a * sr) as usize;
                let hi = (b * sr) as usize;
                crate::testutil::band_rms(&s[lo..hi], sr, hz, spec.q)
            };

            let early_low = band(&residual, 0.035, 0.070, spec.start_hz);
            let early_high = band(&residual, 0.035, 0.070, spec.bloom_hz);
            let bloom_low = band(&residual, 0.105, 0.155, spec.start_hz);
            let bloom_high = band(&residual, 0.105, 0.155, spec.bloom_hz);
            let late_low = band(&residual, 0.280, 0.420, spec.start_hz);
            let late_high = band(&residual, 0.280, 0.420, spec.bloom_hz);

            let early_mid = early_low + early_high;
            let bloom_mid = bloom_low + bloom_high;
            let late_mid = late_low + late_high;
            assert!(
                early_low > 1.35 * early_high.max(1e-9),
                "key {key}: mwah does not start as a low-mid formant: early low {early_low}, early high {early_high}"
            );
            assert!(
                early_low > 0.02 * bloom_mid,
                "key {key}: mwah low-mid onset is too small to prove the opening shape: early low {early_low}, bloom mid {bloom_mid}"
            );
            assert!(
                bloom_mid > 2.0 * early_mid.max(1e-8),
                "key {key}: mwah bloom is not delayed: bloom {bloom_mid} early {early_mid}"
            );
            assert!(
                bloom_mid > 1.6 * late_mid.max(1e-8),
                "key {key}: mwah bloom does not decay: bloom {bloom_mid} late {late_mid}"
            );

            let early_ratio = early_high / early_low.max(1e-9);
            let bloom_ratio = bloom_high / bloom_low.max(1e-9);
            assert!(
                bloom_ratio > 1.25 * early_ratio
                    && bloom_ratio > 0.4
                    && bloom_high > 6.0 * early_high.max(1e-9),
                "key {key}: mwah formant does not open upward: early ratio {early_ratio}, bloom ratio {bloom_ratio}, bloom high {bloom_high}, early high {early_high}"
            );

            let f0 = key_freq(key);
            let body = &with[(0.080 * sr) as usize..(0.420 * sr) as usize];
            let peak = crate::testutil::peak_locate(body, sr, f0 * 0.85, f0 * 1.15);
            assert!(
                (peak / f0 - 1.0).abs() < 0.05,
                "key {key}: mwah moved perceived pitch to {peak} Hz, expected {f0}"
            );
            let fund = crate::testutil::mag_at(body, sr, f0);
            let h2 = crate::testutil::mag_at(body, sr, 2.0 * f0);
            let h3 = crate::testutil::mag_at(body, sr, 3.0 * f0);
            assert!(
                fund > 0.55 * h2.max(h3),
                "key {key}: mwah upper harmonics dominate f0: f0 {fund}, h2 {h2}, h3 {h3}"
            );
        }
    }

    /// Oracle 10 (§5): the stop thump fires on note_off (LF bump vs a
    /// thump-disabled build) and NEVER on a natural end (bit-identical).
    #[test]
    fn stop_thump_on_note_off_only() {
        let sr = 44100.0;
        // Isolate the thump MECHANISM from BASS's (now very large) sub + kick,
        // which live in the same sub-250 Hz band as the 250 Hz-lowpassed thump
        // and mask it completely in the full voice (measurably ~0 contribution
        // at the muffled-flatwound sub weight of 0.72). We still test BASS's own
        // stop_thump VALUE (2.2), just with the masking layers switched off so
        // the burst is observable — the mechanism is what this oracle guards.
        let base = PluckPreset {
            sub: 0.0,
            kick: 0.0,
            ..BASS
        };
        let no_thump = PluckPreset {
            stop_thump: 0.0,
            ..base
        };
        let run = |p: &PluckPreset, off: bool| {
            let mut v = Pluck::new(p, 33, 100, sr, 7);
            let mut a = vec![0f32; (0.3 * sr) as usize];
            v.render(&mut a);
            if off {
                v.note_off();
            }
            let mut b = vec![0f32; (0.12 * sr) as usize];
            v.render(&mut b);
            (a, b)
        };
        let (_, tail_with) = run(&base, true);
        let (_, tail_without) = run(&no_thump, true);
        let lf = |s: &[f32]| crate::testutil::band_rms(s, sr, 150.0, 0.7);
        // The thump adds ~19% LF here (1.19x); the note's own harmonics (55 Hz
        // key with body-EQ'd low) share the band, so the burst can't swamp it.
        // >1.10 pins that the note_off thud fires while leaving deterministic
        // margin (fixed seed 7).
        assert!(
            lf(&tail_with) > 1.10 * lf(&tail_without),
            "thump missing: {} vs {}",
            lf(&tail_with),
            lf(&tail_without)
        );
        // natural end: the armed-but-untriggered burst must change nothing
        let (a1, b1) = run(&base, false);
        let (a2, b2) = run(&no_thump, false);
        assert!(
            a1.iter().zip(&a2).all(|(x, y)| x.to_bits() == y.to_bits())
                && b1.iter().zip(&b2).all(|(x, y)| x.to_bits() == y.to_bits()),
            "un-triggered thump altered the render"
        );
    }

    /// Oracle 39 (MUTED grit + sub enrichment, §5.1): the palm chug's thud
    /// carries 2f/3f, and the soft-clip grit changes the string's output.
    #[test]
    fn muted_grit_and_rich_thud() {
        let sr = 44100.0;
        let plain_sub = PluckPreset {
            sub_shape: (0.0, 0.0),
            ..MUTED
        };
        let rich = render_pluck(&MUTED, 40, 110, 0.3, 7);
        let plain = render_pluck(&plain_sub, 40, 110, 0.3, 7);
        let f = key_freq(40);
        let h23 = |s: &[f32]| {
            crate::testutil::mag_at(s, sr, 2.0 * f) + crate::testutil::mag_at(s, sr, 3.0 * f)
        };
        assert!(
            h23(&rich) > 1.2 * h23(&plain),
            "sub enrichment missing: {} vs {}",
            h23(&rich),
            h23(&plain)
        );
        let no_grit = PluckPreset {
            grit: false,
            ..MUTED
        };
        let gritless = render_pluck(&no_grit, 40, 110, 0.3, 7);
        assert!(
            rich.iter().zip(&gritless).any(|(x, y)| x != y),
            "grit clip is not in the path"
        );
    }

    /// Round-3 U1 bug A (plan §3.3, hand-verified): CLAVINET sets `click_post`
    /// AND `attack_noise`, but the `onset_post` if/else-if lets the slap-pop
    /// branch shadow the tangent scrape — `attack_noise: 0.22` was dead code
    /// (renders were byte-identical with it zeroed, the RED observation).
    /// Two clauses: (a) the shipped preset carries the scrape in its path;
    /// (b) at its shipped level the scrape is audible on its own — asserted
    /// on a click-free lesion, because next to the gain-2.0 slap click a
    /// with/without band-energy read drowns in the click's rng realization
    /// (the two bursts interleave draws from the shared voice rng).
    #[test]
    fn clavinet_tangent_scrape_speaks() {
        let sr = 44100.0;
        let no_scrape = PluckPreset {
            attack_noise: 0.0,
            ..CLAVINET
        };
        let with = render_pluck(&CLAVINET, 60, 110, 0.25, 7);
        let without = render_pluck(&no_scrape, 60, 110, 0.25, 7);
        assert!(
            with.iter().zip(&without).any(|(x, y)| x != y),
            "attack_noise is dead code on CLAVINET (click_post shadows it)"
        );
        let solo = PluckPreset {
            click: 0.0,
            ..CLAVINET
        };
        let solo_off = PluckPreset {
            click: 0.0,
            attack_noise: 0.0,
            ..CLAVINET
        };
        let s_on = render_pluck(&solo, 60, 110, 0.25, 7);
        let s_off = render_pluck(&solo_off, 60, 110, 0.25, 7);
        // With the click gone, NOTHING else draws the voice rng while the
        // scrape burst lives, so the waveform difference IS the scrape.
        // Assert it speaks at its designed level: ≥ −24 dB under the onset
        // over the burst's own 10 ms life (the shared burst formula caps its
        // gain at min(v), so a band-energy contest against the string is
        // unwinnable by construction — presence at level is the honest
        // clause; the exact amount is a round-3 EAR-A/B item).
        let n10 = (0.010 * sr) as usize;
        let diff: Vec<f32> = s_on[..n10]
            .iter()
            .zip(&s_off[..n10])
            .map(|(&x, &y)| x - y)
            .collect();
        let ratio = crate::testutil::rms(&diff) / crate::testutil::rms(&s_on[..n10]).max(1e-9);
        assert!(
            ratio >= 0.06,
            "tangent scrape below its designed level: diff/onset {ratio:.4} < 0.06"
        );
    }

    /// Round-3 U1 bug B (plan §3.3): the memoryless grit tanh is near-linear
    /// at sustain amplitude, so the clavinet's metallic buzz died with the
    /// onset — the same refuted property whose sitar instance was replaced by
    /// the in-loop jawari. Measured HF fractions (>2.8 kHz share, key 48
    /// vel 110) BEFORE the contact-gated buzz landed:
    ///   [.05-.15] 0.374  [.15-.30] 0.134  [.30-.50] 0.063  [.45-.60] 0.050
    /// — a 7.5× collapse down the ring. AFTER:
    ///   [.05-.15] 0.461  [.15-.30] 0.276  [.30-.50] 0.171  [.45-.60] 0.160
    /// Three clauses: the sustain buzz is audible (≥0.12 ≈ −18 dB HF share,
    /// RED at 0.063), it PERSISTS through the ring (late ≥ half of mid, RED
    /// at 0.37×), and it is the buzz stage doing it (differential). All
    /// windows start past the attack — the strike transient's brightness is
    /// the click/scrape's axis, not this oracle's.
    #[test]
    fn clavinet_buzz_survives_into_the_sustain() {
        let sr = 44100.0;
        let buf = render_pluck(&CLAVINET, 48, 110, 0.7, 7);
        let hf_frac = |b: &[f32], lo: f32, hi: f32| {
            let seg = segment(b, sr, lo, hi);
            crate::testutil::hp_rms(seg, sr, 2800.0) / crate::testutil::rms(seg).max(1e-9)
        };
        let sustain = hf_frac(&buf, 0.30, 0.50);
        assert!(
            sustain >= 0.12,
            "clavinet sustain buzz inaudible: HF fraction {sustain:.4} < 0.12"
        );
        let (mid, late) = (hf_frac(&buf, 0.15, 0.30), hf_frac(&buf, 0.45, 0.60));
        assert!(
            late >= 0.5 * mid,
            "clavinet buzz still dies down the ring: late {late:.4} < half of mid {mid:.4}"
        );
        let no_buzz = PluckPreset {
            buzz: 0.0,
            ..CLAVINET
        };
        let plain = render_pluck(&no_buzz, 48, 110, 0.7, 7);
        assert!(
            hf_frac(&buf, 0.30, 0.50) > 1.5 * hf_frac(&plain, 0.30, 0.50),
            "the buzz stage is not what carries the sustain HF: {} vs {}",
            hf_frac(&buf, 0.30, 0.50),
            hf_frac(&plain, 0.30, 0.50)
        );
    }

    /// GM 1 Bright Acoustic uses the brighter `bright_acoustic_piano` MODEL (the 2026.07.18
    /// re-voicing gave GM 1 the Kawai recording, whose attack is darker than GM 0's upright,
    /// so GM 1's brightness now lives in the model, not the sample). Measured MODEL-ONLY so
    /// the sample layer can't mask it: GM 1's HF fraction over [0, 0.4 s] must exceed GM 0's.
    /// This is also what keeps GM 0/GM 1 distinct in a modeled-only build.
    #[test]
    fn gm1_bright_model_is_brighter_than_gm0() {
        let sr = 44100.0;
        for key in [48u8, 60] {
            let hf_frac = |prog: u8| {
                let mut v = make(prog, key, 100, sr, 7, false); // model only
                let mut buf = vec![0f32; (0.45 * sr) as usize];
                v.render(&mut buf);
                let span = &buf[..(0.40 * sr) as usize];
                crate::testutil::hp_rms(span, sr, 2500.0) / rms(span).max(1e-9)
            };
            let (r0, r1) = (hf_frac(0), hf_frac(1));
            assert!(
                r1 > 1.1 * r0,
                "key {key}: GM1 bright model not brighter than GM0: GM1 {r1:.4} vs GM0 {r0:.4}"
            );
        }
    }

    /// Round-3 U3 (plan §3.1): GM 3's honky-tonk beat must begin AT THE
    /// ONSET — round 2 put the wide trichord detune in the model, which the
    /// shared-sample crossfade discards until 0.85 s, so the first (and for
    /// short notes, only) 0.8 s of a honky note was a plain grand. Metric:
    /// detrended envelope ripple of the f0-band signal over [0.05, 0.9] —
    /// the beat is periodic f0-band AM (the same anti-flange axis as the
    /// perceptual oracle's D5; key 72 is T4's load-bearing beat probe, where
    /// ±0.7 % reads sit ~3.7/7.3 Hz apart). RED at HEAD.
    #[test]
    fn honky_tonk_beats_from_the_onset() {
        if !crate::embedded_samples_available() {
            return;
        }
        let sr = 44100.0;
        // The honky signature, asserted DIRECTLY in the spectrum: the f0
        // line SPLITS into side lines at f0·(1±0.007) — at key 72 they sit
        // ±3.7 Hz off center, resolvable in a 0.85 s Hann-windowed Goertzel
        // (Hann keeps the center line's leakage ~−31 dB at that offset).
        // Three envelope-domain estimator drafts were measured and REJECTED:
        // a moving-average detrend ate the 3.7 Hz beat line itself (4× low);
        // a linear detrend of the raw envelope left decay curvature in the
        // sub-2 Hz bins (GM0 control read 0.197 at key 60); and total
        // f0-band ripple is a soup of sample-vs-model crossfade interference
        // that the side reads actually SMOOTH (GM0 3.8 dB, GM3 3.2). The
        // line-split ratio is monotone in the mix and is the physics. Keys
        // 72/79 per T4 (a key-48-class probe splits by ~0.9 Hz —
        // unresolvable in this window); GM0 — same estimator, no trichord —
        // is the running control for the recorded upright's own unisons.
        let side_ratio = |prog: u8, key: u8| {
            let mut v = make(prog, key, 100, sr, 7, true);
            let mut buf = vec![0f32; (0.95 * sr) as usize];
            v.render(&mut buf);
            let f0 = key_freq(key);
            let seg = &buf[(0.05 * sr) as usize..(0.90 * sr) as usize];
            let n = seg.len();
            let w: Vec<f32> = seg
                .iter()
                .enumerate()
                .map(|(i, &x)| {
                    let h = 0.5 - 0.5 * (std::f32::consts::TAU * i as f32 / (n - 1) as f32).cos();
                    x * h
                })
                .collect();
            let m = |f: f32| crate::testutil::mag_at(&w, sr, f);
            (m(f0 * 1.007) + m(f0 * 0.993)) / m(f0).max(1e-9)
        };
        for key in [72u8, 79] {
            let (r0, r3) = (side_ratio(0, key), side_ratio(3, key));
            println!("honky split key {key}: GM3 {r3:.3} vs GM0 {r0:.3}");
            assert!(
                r3 >= 2.0 * r0,
                "key {key}: honky-tonk f0 line does not split: GM3 side-line \
                 ratio {r3:.3} vs GM0 control {r0:.3}"
            );
        }
    }

    /// Round-3 U4 (plan §3.3): the harpsichord must JANGLE — persistent
    /// post-onset brightness — and carry its 4′ octave rank. Clause (a):
    /// sustain-window centroid ≥ 1.6× the GM1 upright control. (The control was
    /// GM 0 at 1.75× when GM 0 was the VSCO upright; GM 0 is now the Salamander
    /// grand — brighter and 2f0-rich — so it is no longer a plain-piano
    /// reference. The control moved to GM 1, the same upright, which carries a
    /// +5 dB bright shelf and so reads a touch brighter than the old bare
    /// control; the bar drops to 1.6× to match, measured 1.76×/1.68× at keys
    /// 55/67.) Clause (b): 4′ choir energy, 2f0/f0 ≥ 2× the control's (measured
    /// 3–14× — the strong discriminator; the plan's original §3.3 choir clause,
    /// live because the rank is now built).
    ///
    /// What delivers it (each measured): the in-loop damper opened
    /// 6200→11000 (the 07.14 lesson — the damper's HF magnitude rules
    /// treble decay, and no excitation survives it), the thin-soundboard
    /// body sheen, and the 4′ rank on the existing course loop. The plan's
    /// proposed QUILL-PULSE excitation was built and REFUTED by
    /// measurement, then removed: with `vel_sense: 0.15` flattening the
    /// velocity laws, the noise burst's pick_lp is already open at every
    /// velocity, so the "spectrally flat" pulse changed neither the attack
    /// share (0.293 vs 0.355 — it read DARKER) nor the sustain share
    /// (0.0341 vs 0.0334) — the same premise-false pattern as the shelved
    /// bass sub-octave (lessons 2026.07.15).
    #[test]
    fn harpsichord_jangles_with_a_four_foot_choir() {
        let sr = 44100.0;
        for key in [55u8, 67] {
            let f0 = key_freq(key);
            let stats = |prog: u8| {
                let mut v = make(prog, key, 100, sr, 7, true);
                let mut buf = vec![0f32; (0.5 * sr) as usize];
                v.render(&mut buf);
                let seg = &buf[(0.20 * sr) as usize..(0.45 * sr) as usize];
                let choir = crate::testutil::mag_at(seg, sr, 2.0 * f0)
                    / crate::testutil::mag_at(seg, sr, f0).max(1e-9);
                (crate::testutil::centroid(seg, sr), choir)
            };
            // GM0's upright envelope is deliberately under active calibration. Keep
            // this unrelated harpsichord oracle on the stable GM1 acoustic-piano
            // control; its measured centroid ratios are 1.76×/1.68× at keys 55/67.
            let (c6, ch6) = stats(6);
            let (c1, ch1) = stats(1);
            println!("harpsi key {key}: cent {c6:.0} vs GM1 {c1:.0}; 2f0/f0 {ch6:.2} vs {ch1:.2}");
            // Encodes "much brighter sustain than an acoustic piano"; the 4′-choir
            // clause below is the strong discriminator.
            assert!(
                c6 >= 1.6 * c1,
                "key {key}: harpsichord sustain does not jangle: centroid {c6:.0} Hz \
                 vs GM1 acoustic-piano control {c1:.0} Hz"
            );
            assert!(
                ch6 >= 2.0 * ch1,
                "key {key}: no 4′ choir over the control: 2f0/f0 {ch6:.2} vs GM1 {ch1:.2}"
            );
        }
    }

    /// Oracle 40 (§5.3, three clauses): the prog-31 flageolet suppresses the
    /// notated fundamental, actually rings at the touched harmonic, and
    /// holds both under an active pitch modulator (V4/INT-2).
    #[test]
    fn harmonic_flageolet_suppresses_fundamental() {
        let sr = 44100.0;
        let f = key_freq(52); // E3 ≈ 164.8 Hz, below the E4 split → 2f
        let buf = render_pluck(&HARMONIC, 52, 100, 0.8, 7);
        let strongest = crate::testutil::peak_locate(&buf, sr, f * 0.8, f * 3.5);
        assert!(
            (strongest / (2.0 * f) - 1.0).abs() < 0.03,
            "strongest partial at {strongest} Hz, expected ~{}",
            2.0 * f
        );
        let db = |m: f32| 20.0 * m.max(1e-12).log10();
        let sup = db(crate::testutil::mag_at(&buf, sr, f))
            - db(crate::testutil::mag_at(&buf, sr, strongest));
        assert!(sup <= -12.0, "fundamental only {sup:.1} dB down");
        // clause (c): a +2-semitone bend must move the flageolet, not
        // collapse it back to the fundamental
        let mut v = Pluck::new(&HARMONIC, 52, 100, sr, 7);
        let mut head = vec![0f32; (0.25 * sr) as usize];
        v.render(&mut head);
        let bend = 2f32.powf(2.0 / 12.0);
        v.set_pitch(bend);
        let mut tail = vec![0f32; (0.6 * sr) as usize];
        v.render(&mut tail);
        let late = &tail[(0.2 * sr) as usize..];
        let target = 2.0 * f * bend;
        let p = crate::testutil::peak_locate(late, sr, f * 0.8, f * 3.5);
        assert!(
            (p / target - 1.0).abs() < 0.04,
            "bent flageolet at {p} Hz, expected ~{target}"
        );
        let sup_bent = db(crate::testutil::mag_at(late, sr, f * bend))
            - db(crate::testutil::mag_at(late, sr, p));
        assert!(
            sup_bent <= -12.0,
            "bent fundamental only {sup_bent:.1} dB down"
        );
    }

    /// MM-BUG-KILN-00037: retuning a broadband pluck does not make a
    /// flageolet. After the short touch transient, the sounding harmonic must
    /// carry a near-sine ring rather than an ordinary pluck's upper-partial
    /// ladder. Check both sides of the shipped 2f/3f split.
    #[test]
    fn harmonic_flageolet_ring_is_spectrally_thin() {
        let sr = 44100.0;
        let peak_around = |seg: &[f32], f: f32| {
            [0.996, 0.998, 1.0, 1.002, 1.004]
                .into_iter()
                .map(|ratio| crate::testutil::mag_at(seg, sr, f * ratio))
                .fold(0.0f32, f32::max)
        };
        for (key, multiple) in [(52u8, 2.0f32), (64, 3.0)] {
            let buf = render_pluck(&HARMONIC, key, 100, 0.5, 7);
            let ring = &buf[(0.020 * sr) as usize..(0.250 * sr) as usize];
            let sounding = key_freq(key) * multiple;
            let h1 = peak_around(ring, sounding);
            let upper = (2..=8)
                .map(|harmonic| peak_around(ring, sounding * harmonic as f32).powi(2))
                .sum::<f32>()
                .sqrt();
            let upper_db = 20.0 * (upper / h1.max(1e-12)).max(1e-12).log10();
            let ring_rms = crate::testutil::rms(ring);
            let tone_fraction = h1 / (2.0f32.sqrt() * ring_rms).max(1e-12);
            println!(
                "flageolet key {key}: h2..h8/h1 {upper_db:.1} dB, \
                 h1 energy fraction {tone_fraction:.3}, rms {ring_rms:.4}"
            );
            assert!(
                ring_rms > 1e-4,
                "key {key}: spectrally thin flageolet became silent"
            );
            assert!(
                tone_fraction >= 0.5,
                "key {key}: sounding harmonic carries only {tone_fraction:.3} of \
                 the ring energy; off-lattice noise can fake a thin harmonic ladder"
            );
            assert!(
                upper_db <= -9.0,
                "key {key}: flageolet upper-partial energy is {upper_db:.1} dB \
                 relative to the sounding harmonic; expected a near-sine ring"
            );
        }
    }

    /// Oracle 12 (B2): the three bass articulations are genuinely distinct —
    /// pick brighter than fingers, upright woodier and shorter, with its
    /// 110 Hz body mode in the shipped table.
    #[test]
    fn bass_articulations_distinct() {
        let sr = 44100.0;
        let cent = |p: &PluckPreset| {
            let buf = render_pluck(p, 30, 100, 0.3, 7); // F#1: partials avoid 110 Hz
            crate::testutil::centroid(&buf, sr)
        };
        assert!(
            cent(&PICK) > 1.1 * cent(&BASS),
            "PICK {} not brighter than BASS {}",
            cent(&PICK),
            cent(&BASS)
        );
        assert!(
            UPRIGHT.body.iter().any(|&(f, _, g)| f == 110.0 && g > 0.0),
            "UPRIGHT 110 Hz body mode missing from the shipped table"
        );
        let (u, b) = (
            std::hint::black_box(UPRIGHT.t60),
            std::hint::black_box(BASS.t60),
        );
        assert!(u < b, "upright should decay faster: {u} vs {b}");
    }

    /// MM-BUG-KILN-00045: the default GM bass family must stay within the same
    /// held-body level bracket as the reference modules. This measures the
    /// original calibration grid's bass register and excludes the first 200 ms so
    /// slap/pick/onset differences cannot hide a collapsed or over-hot sustain.
    #[test]
    fn default_bass_family_held_levels_stay_together() {
        let sr = 44100.0;
        let keys = [24u8, 29, 34, 39, 44, 49];
        let velocities = [72u8, 110];
        let mut levels = Vec::new();

        for program in 32u8..=39 {
            let mut energy = 0.0f64;
            let mut samples = 0usize;
            for &key in &keys {
                for &vel in &velocities {
                    let buf = render_program(program, key, vel, 1.3, 0x45_0000 + program as u32);
                    let body = segment(&buf, sr, 0.20, 1.20);
                    energy += body.iter().map(|&x| (x as f64) * (x as f64)).sum::<f64>();
                    samples += body.len();
                }
            }
            let level = 20.0 * ((energy / samples as f64).sqrt().max(1e-12)).log10() as f32;
            eprintln!("GM{program} held bass-family level {level:.2} dB");
            levels.push((program, level));
        }

        let (low_program, low) = levels
            .iter()
            .copied()
            .min_by(|a, b| a.1.total_cmp(&b.1))
            .unwrap();
        let (high_program, high) = levels
            .iter()
            .copied()
            .max_by(|a, b| a.1.total_cmp(&b.1))
            .unwrap();
        let spread = high - low;
        assert!(
            spread <= 9.25,
            "GM32-39 held-body spread is {spread:.2} dB (GM{low_program} {low:.2}, \
             GM{high_program} {high:.2}); reference modules sit around 9 dB"
        );
    }

    /// GM046 harp must SHIMMER — its sustained tone carries upper-partial energy,
    /// not just a low-mid soundboard thud. Round-2: pick_lp 1800 dulled the attack
    /// and the loop-damper `bright` sat at the DEFAULTS 3000, so the ring damped
    /// everything above ~3 kHz and the centroid sat near the fundamental ("needs
    /// work" / dark). `bright` is the shimmer lever (it sets the KS loop damper).
    /// Fail-first at bright=3000/pick_lp=1800.
    #[test]
    fn harp_46_shimmers() {
        let sr = 44100.0;
        let buf = render_pluck(&HARP, 60, 96, 0.6, 7);
        let sus = segment(&buf, sr, 0.10, 0.45);
        let c = spectral_centroid(sus, sr, 100.0, 9000.0);
        println!("harp shimmer centroid: {c:.0} Hz");
        // Threshold calibrated between the dark original (432 Hz) and the brightened
        // voice (641 Hz) — a ~40% shimmer lift with margin either side. The absolute
        // brightness is Arthur's ear to fine-tune; this only pins "not dark again".
        assert!(
            c > 580.0,
            "harp too dark: sustain centroid {c:.0} Hz (need > 580)"
        );
    }

    /// Round-3 harp octave-outlier guard (graduates the deep-dive diagnosis into a
    /// permanent oracle). The initial pluck burst has a Rayleigh-random h1; pre-fix, a
    /// weak-h1 draw let the undamped low-mid octave dominate by up to +23 dB at G3-C4 —
    /// the intermittent "an-octave-up" harp notes. `HARP.h1_floor` tops the fundamental up.
    /// Across many seeds, NO note in the susceptible register may show a hot octave; SC-55
    /// is a clean −6..−10 dB re f0 everywhere. Band-integrated (the two KS loops smear h2).
    #[test]
    fn harp_octave_outliers_are_floored() {
        let sr = 44100.0;
        let band = |buf: &[f32], f: f32| -> f32 {
            // sustain window ≥ the 1.47 s two-loop beat period, band-integrated (both
            // detuned partials) — the perceptual "an-octave-up" lives in the ring, not
            // the transient attack.
            let seg = &buf[(0.3 * sr) as usize..(2.0 * sr) as usize];
            [0.985f32, 1.0, 1.015]
                .iter()
                .map(|m| mag_at(seg, sr, f * m).powi(2))
                .sum::<f32>()
        };
        for key in [55u8, 57, 59, 60] {
            // G3, A3, B3, C4 — the octave-susceptible band
            let f0 = key_freq(key);
            let mut worst = f32::NEG_INFINITY;
            for seed in 0..24u32 {
                let buf = render_pluck(&HARP, key, 96, 2.2, seed);
                let db = 10.0 * (band(&buf, 2.0 * f0) / band(&buf, f0).max(1e-12)).log10();
                worst = worst.max(db);
            }
            eprintln!("harp octave key {key}: worst h2/h1 over 24 seeds = {worst:.1} dB");
            // Pre-fix this reached +23 dB (grossly octave-up); the h1 floor caps the worst
            // seed at ~4 dB (median is a healthy −5..−8, mid-SC-55). ≤5 guards the regression
            // with margin; the exact residual + floor depth are Arthur's ear-in-the-loop call.
            assert!(
                worst <= 6.0,
                "harp key {key}: worst h2/h1 over 24 seeds = {worst:.1} dB — octave outlier (need ≤ 6)"
            );
        }
    }

    /// The initial-pluck h1 floor is OFF by default (every non-harp pluck byte-identical)
    /// and ON for the harp. Byte-identity of the others is proven by the render-diff.
    #[test]
    fn h1_floor_is_off_by_default() {
        assert_eq!(DEFAULTS.h1_floor, 0.0);
        assert_ne!(HARP.h1_floor, 0.0, "harp must set h1_floor");
        for p in [&STEEL, &NYLON, &JAZZ, &HARPSICHORD] {
            assert_eq!(p.h1_floor, 0.0, "{} must inherit h1_floor = 0", p.name);
        }
    }

    #[test]
    fn harp_46_has_soundboard_and_harp_wound_law() {
        assert!(
            HARP.body.iter().any(|&(f, _, g)| f < 120.0 && g > 0.0),
            "HARP should have a low soundboard mode"
        );
        assert!(
            HARP.body
                .iter()
                .any(|&(f, _, g)| (150.0..=250.0).contains(&f) && g > 0.0),
            "HARP should have a low-mid soundboard mode"
        );
        assert!(
            HARP.body
                .iter()
                .any(|&(f, _, g)| (350.0..=500.0).contains(&f) && g > 0.0),
            "HARP should have a warm upper soundboard mode"
        );
        assert!(
            !std::hint::black_box(HARP.wound_key_split),
            "HARP should not inherit the guitar key-split wound law"
        );
        assert_eq!(wound_factor(true, true, 70), 1.0);
        assert_eq!(wound_factor(false, true, 60), 0.0);
        assert!(wound_factor(false, true, 45) > 0.3);
        assert_eq!(wound_factor(false, false, 31), 0.0);

        let sr = 44100.0;
        let bodyless = PluckPreset { body: &[], ..HARP };
        let old_split = PluckPreset {
            wound_key_split: true,
            ..HARP
        };

        for (key, bands) in [(45u8, [90.0, 180.0, 400.0]), (52u8, [180.0, 400.0, 90.0])] {
            let full = render_pluck(&HARP, key, 104, 0.7, 0x4600 + key as u32);
            let dry = render_pluck(&bodyless, key, 104, 0.7, 0x4600 + key as u32);
            let full_body = segment(&full, sr, 0.04, 0.42);
            let dry_body = segment(&dry, sr, 0.04, 0.42);
            for f in bands {
                let lift =
                    band_rms(full_body, sr, f, 1.0) / band_rms(dry_body, sr, f, 1.0).max(1e-9);
                assert!(
                    lift > 1.08,
                    "key {key}: HARP body mode {f} Hz did not lift enough versus bodyless clone: {lift:.3}"
                );
            }
        }

        let new_harp = render_pluck(&HARP, 45, 104, 0.7, 0x46_4510);
        let old_harp = render_pluck(&old_split, 45, 104, 0.7, 0x46_4510);
        let new_body = segment(&new_harp, sr, 0.04, 0.42);
        let old_body = segment(&old_harp, sr, 0.04, 0.42);
        let new_centroid = centroid(new_body, sr);
        let old_centroid = centroid(old_body, sr);
        assert!(
            new_centroid > old_centroid * 1.04,
            "new harp should be less guitar-wound/dark in bass register: {new_centroid:.1} vs {old_centroid:.1}"
        );
        let new_hf = hp_rms(new_body, sr, 1200.0);
        let old_hf = hp_rms(old_body, sr, 1200.0);
        assert!(
            new_hf > old_hf * 1.06,
            "new harp should retain more high-frequency pluck energy than guitar-split clone: {new_hf:.5} vs {old_hf:.5}"
        );
    }

    /// Oracle 15 (K3, §5.3 differential): the polarization coupling is
    /// audible (same seed, k on vs off differ) and unconditionally bounded
    /// on the worst case — a long low DRIVE note at high loop gain.
    #[test]
    fn coupling_audible_and_bounded() {
        let sr = 44100.0;
        let run = |k: f32, secs: f32| {
            let mut v = Pluck::new(&DRIVE, 28, 110, sr, 7);
            v.k_couple = k;
            let mut buf = vec![0f32; (secs * sr) as usize];
            v.render(&mut buf);
            buf
        };
        let with = run(K_COUPLE, 2.0);
        let without = run(0.0, 2.0);
        let d: Vec<f32> = with.iter().zip(&without).map(|(a, b)| a - b).collect();
        assert!(
            crate::testutil::rms(&d) > 0.05 * crate::testutil::rms(&with),
            "coupling inaudible: diff {} vs signal {}",
            crate::testutil::rms(&d),
            crate::testutil::rms(&with)
        );
        let long = run(K_COUPLE, 10.0);
        let peak = long.iter().fold(0f32, |m, &x| m.max(x.abs()));
        // Bound re-pinned 1.5 → 3.2 when round 2 raised DRIVE.amp 0.7 → 1.5
        // (the raw voice scales ×2.14; the engine's Drive tanh bounds the
        // mixed signal). Measured 1.57 post-raise — same ~2× margin as the
        // 0.73-vs-1.5 original capture; runaway feedback still lands far
        // outside.
        assert!(
            long.iter().all(|x| x.is_finite()) && peak < 3.2,
            "peak {peak}"
        );
    }

    /// Oracle 18 (G6, §5.3 time-matched differential): a released string
    /// dulls faster than a held one — same seed, same absolute window.
    #[test]
    fn release_darkens_the_string() {
        let sr = 44100.0;
        let run = |release: bool| {
            let mut v = Pluck::new(&CLEAN, 64, 110, sr, 7);
            let mut head = vec![0f32; (0.3 * sr) as usize];
            v.render(&mut head);
            if release {
                v.note_off();
            }
            let mut tail = vec![0f32; (0.3 * sr) as usize];
            v.render(&mut tail);
            tail[(0.1 * sr) as usize..].to_vec()
        };
        let rel = crate::testutil::centroid(&run(true), sr);
        let held = crate::testutil::centroid(&run(false), sr);
        assert!(
            rel < 0.8 * held,
            "release not darkening: released {rel} vs held {held}"
        );
    }

    /// Oracle 41 (K4 Stage 1, §5.3): wound-ness is real — the factor splits
    /// the registers, and a fully-wound build of the same note reads darker.
    ///
    /// Phase-2 (Shaped excitation + click reshape, 2026.07.20): the audio clause now
    /// measures the centroid over the BODY window [0.05, 0.3] s at key 50, not the
    /// whole render at key 57. Two reasons: (1) the wound law is a STRING property
    /// (`bright`/`pick_lp`, which also feeds the Shaped backbone's P(k·f0)) that
    /// lives in the sustain, so excluding the pick click removes a confound rather
    /// than adds one — the Fable click de-impulsify band-limited the click, and its
    /// residual >5 kHz fizz had been inflating the full-window gap; (2) key 50 has a
    /// strong `wound_factor` (> 0.3) where the darkening is robust (body gap ~12 %),
    /// vs the marginal ramp region at key 57. The 0.92 bar (≥ 8 % darker) trips
    /// clearly if a regression ever flattens the wound law (gap → 0). The register
    /// SPLIT itself is still pinned by the structural asserts above.
    #[test]
    fn wound_strings_darker() {
        // structural: bass full-range, guitars split around G3
        assert_eq!(wound_factor(true, true, 70), 1.0);
        assert_eq!(wound_factor(false, true, 60), 0.0);
        assert!(wound_factor(false, true, 45) > 0.3);
        assert!(wound_factor(false, true, 31) >= 1.0);
        assert_eq!(wound_factor(false, false, 31), 0.0);
        // audio: the same key, wound vs plain construction. Measured over the BODY
        // window [0.05, 0.3] s (after the pick click has died, t60 ≤ 10 ms) so the
        // centroid reflects the STRING's wound darkening, not the click transient —
        // the wound law lives in `bright`/`pick_lp`, a sustain property. Key 50 sits
        // where `wound_factor` is strong enough (> 0.3) for a robust gap.
        let sr = 44100.0;
        let wound_steel = PluckPreset {
            wound_all: true,
            ..STEEL
        };
        let body = |s: &[f32]| crate::testutil::centroid(&s[(0.05 * sr) as usize..], sr);
        let cp = body(&render_pluck(&STEEL, 50, 100, 0.3, 7));
        let cw = body(&render_pluck(&wound_steel, 50, 100, 0.3, 7));
        assert!(
            cw < 0.92 * cp,
            "wound {cw:.0} not darker than plain {cp:.0}"
        );
    }

    /// Oracle 43 (V4/INT-4): a range-24 full-down bend pitch-limits at the
    /// delay line's capacity instead of silently wrapping into garbage.
    #[test]
    fn extreme_downbend_stays_finite() {
        let sr = 44100.0;
        let mut v = Pluck::new(&BASS, 28, 110, sr, 7);
        v.set_pitch(2f32.powf(-24.0 / 12.0)); // RPN range 24, wheel floored
        let mut buf = vec![0f32; sr as usize];
        v.render(&mut buf);
        assert!(buf.iter().all(|x| x.is_finite()), "non-finite output");
        let peak = buf.iter().fold(0f32, |m, &x| m.max(x.abs()));
        assert!(peak < 2.0, "wrapped ring buffer: peak {peak}");
    }

    /// Oracle 11 (B5, §5.3): the bass sub carries a real 2nd harmonic
    /// (differential vs a shaper-disabled build) with no DC, and its start
    /// phase varies with the seed.
    #[test]
    fn bass_sub_shaped_and_phase_random() {
        let sr = 44100.0;
        let plain = PluckPreset {
            sub_shape: (0.0, 0.0),
            ..BASS
        };
        let with = render_pluck(&BASS, 28, 100, 0.4, 7);
        let without = render_pluck(&plain, 28, 100, 0.4, 7);
        let f = key_freq(28);
        let h2 = |s: &[f32]| crate::testutil::mag_at(s, sr, 2.0 * f);
        assert!(
            h2(&with) > 1.1 * h2(&without),
            "sub 2f missing: {} vs {}",
            h2(&with),
            h2(&without)
        );
        // DC clause, differential: an unwindowed mean of a 41 Hz note reads
        // fundamental partial-cycle residue (~A/2πn), so compare the SAME
        // seed with the shaper on vs off — sin²−½ = −½cos2x must add none
        let mean = |s: &[f32]| s.iter().map(|&x| x as f64).sum::<f64>() / s.len() as f64;
        let added_dc = (mean(&with) - mean(&without)).abs();
        assert!(added_dc < 1e-3, "sub shaper leaked DC: {added_dc}");
        // seed-dependent sub phase: the LF starts differently across seeds
        let a = render_pluck(&BASS, 28, 100, 0.05, 7);
        let b = render_pluck(&BASS, 28, 100, 0.05, 8);
        let lf = |s: &[f32]| {
            let mut lp = OnePole::lowpass(60.0, sr);
            s.iter().map(|&x| lp.process(x)).collect::<Vec<f32>>()
        };
        assert!(
            crate::testutil::inter_corr(&lf(&a), &lf(&b)).abs() < 0.98,
            "sub phase identical across seeds"
        );
    }

    /// Oracle 13 (B4 + §5.3 pitch clause): SynthBass holds a steady sustain,
    /// its filter envelope sweeps the brightness down after the attack, and
    /// set_pitch actually bends it (V4/INT-5).
    #[test]
    fn synthbass_class_and_pitch() {
        let sr = 44100.0;
        let mut v = SynthBass::new(38, 40, 100, sr, 7);
        let mut buf = vec![0f32; (1.0 * sr) as usize];
        v.render(&mut buf);
        let rms_a = crate::testutil::rms(&buf[(0.2 * sr) as usize..(0.5 * sr) as usize]);
        let rms_b = crate::testutil::rms(&buf[(0.5 * sr) as usize..(0.8 * sr) as usize]);
        let ratio = rms_a.max(rms_b) / rms_a.min(rms_b).max(1e-9);
        assert!(ratio < 1.3, "sustain not steady: {ratio}");
        let c_early = crate::testutil::centroid(&buf[..(0.15 * sr) as usize], sr);
        let c_late = crate::testutil::centroid(&buf[(0.5 * sr) as usize..(0.8 * sr) as usize], sr);
        assert!(
            c_early > 1.15 * c_late,
            "filter env not sweeping: early {c_early} late {c_late}"
        );
        // pitch clause: +2 semitones must sound at the bent pitch
        let mut vb = SynthBass::new(38, 40, 100, sr, 7);
        vb.set_pitch(2f32.powf(2.0 / 12.0));
        let mut bent = vec![0f32; (0.6 * sr) as usize];
        vb.render(&mut bent);
        let want = key_freq(40) * 2f32.powf(2.0 / 12.0);
        let p =
            crate::testutil::peak_locate(&bent[(0.2 * sr) as usize..], sr, want * 0.9, want * 1.1);
        assert!((p / want - 1.0).abs() < 0.04, "bent pitch {p} vs {want}");
    }

    /// A plucked A4 should oscillate near 440 Hz (count zero crossings).
    #[test]
    fn pluck_pitch_a4() {
        let sr = 44100.0;
        let mut v = Pluck::new(&STEEL, 69, 100, sr, 7);
        let mut buf = vec![0f32; 22050];
        v.render(&mut buf);
        // Goertzel peak instead of zero crossings: the K1 cubic tap keeps
        // the 2nd harmonic ringing, which over-counts crossings even after
        // a 500 Hz lowpass — the fundamental itself is what this test pins
        let hz = crate::testutil::peak_locate(&buf[4410..], sr, 396.0, 484.0);
        assert!((hz - 440.0).abs() < 6.0, "measured {hz} Hz");
    }

